    var id: String
    var policyVersion: Int
    var sessionID: String
    var movement: BookReenchantmentMovement
    var role: BookSessionRole
    var selectedSourceID: String
    var selectedArmID: String
    var contextKey: String
    var propensity: Double
    var candidates: [CausalCurationCandidate]
    var pressureCost: Double
    var selectedAt: Date
    var dayID: String
}

struct CausalMovementOpportunity: Codable, Equatable, Identifiable {
    var id: String
    var policyVersion: Int
    var sessionID: String
    var selectedMovement: BookReenchantmentMovement
    var contextKey: String
    var propensity: Double
    var candidates: [CausalMovementCandidate]
    var selectedAt: Date
    var dayID: String
}

struct CausalCurationOutcome: Codable, Equatable, Identifiable {
    var id: String
    var opportunityID: String
    var occurredAt: Date
    var kind: CausalAlivenessOutcomeKind
    /// Zero means the attempt produced qualified contrary evidence; one means
    /// a strong lived receipt. Participation-only values remain diagnostic and
    /// never train uplift.
    var value: Double
    var evidenceLine: String?
}

struct CausalUpliftEstimate: Equatable {
    var treatmentCount: Int
    var controlCount: Int
    var treatmentMean: Double
    var controlMean: Double
    var estimatedUplift: Double
    var conservativeLowerBound: Double
    var conservativeUpperBound: Double
    var usedExactContext: Bool
    /// Specificity-weighted evidence behind each arm. Opportunities recorded in
    /// exactly the conditions being asked about count for one apiece; evidence
    /// borrowed from a neighbouring role, context, or movement counts for less.
    var effectiveTreatmentSamples: Double = 0
    var effectiveControlSamples: Double = 0

    /// How much evidence a reading must hold before it may move the desk.
    ///
    /// Counted in weighted opportunities rather than rows. Three opportunities
    /// recorded in exactly these conditions clear it, as they always did; so
    /// does a larger body of nearby evidence, which is the only way a reader
    /// whose history is spread thin across cells ever gets read at all. A
    /// handful of borrowed rows cannot reach it, so distant evidence can never
    /// impersonate local proof.
    static let minimumEffectiveSamples = 2.0

    var hasEnoughEvidence: Bool {
        effectiveTreatmentSamples >= Self.minimumEffectiveSamples
            && effectiveControlSamples >= Self.minimumEffectiveSamples
    }

    static let unwritten = CausalUpliftEstimate(
        treatmentCount: 0,
        controlCount: 0,
        treatmentMean: 0.25,
        controlMean: 0.25,
        estimatedUplift: 0,
        conservativeLowerBound: -1,
        conservativeUpperBound: 1,
        usedExactContext: false,
        effectiveTreatmentSamples: 0,
        effectiveControlSamples: 0
    )
}

/// A bounded, local logged-bandit ledger. The policy learns only from Pages
/// whose alternatives and propensities were recorded. Its posterior is
/// deliberately conservative, propensity weights are clipped, and an absent
/// trace matures only after the reader has returned to the Book later.
struct CausalCurationLedger: Codable, Equatable {
    static let maxOpportunities = 1_600
    static let maxOutcomes = 2_400
    static let outcomeWindow: TimeInterval = 14 * 86_400

    var opportunities: [CausalCurationOpportunity] = []
    var movementOpportunities: [CausalMovementOpportunity] = []
    var outcomes: [CausalCurationOutcome] = []
    var lastRecordedAt: Date?

    static let unwritten = CausalCurationLedger()

    mutating func record(_ event: ReaderLearningEvent) {
        let receipt = event.causalReceipt
        let movementReceipt = event.causalMovementReceipt ?? receipt?.movementReceipt
        guard receipt != nil || movementReceipt != nil else { return }
        if let receipt,
           !opportunities.contains(where: { $0.id == receipt.id }) {
            opportunities.append(CausalCurationOpportunity(
                id: receipt.id,
                policyVersion: receipt.policyVersion,
                sessionID: receipt.sessionID,
                movement: receipt.movement,
                role: receipt.role,
                selectedSourceID: receipt.chosenSourceID,
                selectedArmID: receipt.chosenArmID,
                contextKey: receipt.contextKey,
                propensity: max(0.000_001, min(1, receipt.propensity)),
                candidates: receipt.candidates,
                pressureCost: max(0, min(1, receipt.pressureCost)),
                selectedAt: receipt.selectedAt,
                dayID: event.dayID
            ))
        }
        if let movementReceipt,
           !movementOpportunities.contains(where: { $0.id == movementReceipt.id }) {
            movementOpportunities.append(CausalMovementOpportunity(
                id: movementReceipt.id,
                policyVersion: movementReceipt.policyVersion,
                sessionID: movementReceipt.sessionID,
                selectedMovement: movementReceipt.chosenMovement,
                contextKey: movementReceipt.contextKey,
                propensity: max(0.000_001, min(1, movementReceipt.propensity)),
                candidates: movementReceipt.candidates,
                selectedAt: movementReceipt.selectedAt,
                dayID: event.dayID
            ))
        }
        if let outcome = Self.outcome(for: event) {
            if let receipt { appendOutcome(outcome, opportunityID: receipt.id) }
            if let movementReceipt { appendOutcome(outcome, opportunityID: movementReceipt.id) }
        }
        lastRecordedAt = max(lastRecordedAt ?? event.occurredAt, event.occurredAt)
        prune(now: event.occurredAt)
    }

    /// Forget every causal contribution made by Page events whose reader later
    /// revoked learning permission. A Page opportunity belongs to that Page and
    /// is removed; a session movement opportunity may be shared by other Pages,
    /// so only this event's movement outcome is removed.
    mutating func removeLearningEvidence(from events: [ReaderLearningEvent]) {
        guard !events.isEmpty else { return }
        let eventOutcomePrefixes = events.map { "learning:\($0.id)|" }
        let pageOpportunityIDs = Set(events.compactMap { $0.causalReceipt?.id })
        opportunities.removeAll { pageOpportunityIDs.contains($0.id) }
        outcomes.removeAll { outcome in
            pageOpportunityIDs.contains(outcome.opportunityID)
                || eventOutcomePrefixes.contains(where: outcome.id.hasPrefix)
        }
        let timestamps =
            opportunities.map(\.selectedAt)
            + movementOpportunities.map(\.selectedAt)
            + outcomes.map(\.occurredAt)
        lastRecordedAt = timestamps.max()
    }

    mutating func recordLivedOutcome(
        opportunityID: String,
        occurredAt: Date,
        value: Double,
        evidenceLine: String?
    ) {
        guard opportunities.contains(where: { $0.id == opportunityID })
                || movementOpportunities.contains(where: { $0.id == opportunityID }) else { return }
        let outcome = CausalCurationOutcome(
            id: "lived:\(opportunityID):\(Int(occurredAt.timeIntervalSince1970))",
            opportunityID: opportunityID,
            occurredAt: occurredAt,
            kind: .livedEvidence,
            value: max(0, min(1, value)),
            evidenceLine: evidenceLine?.nonEmpty.map { String($0.prefix(180)) }
        )
        guard !outcomes.contains(where: { $0.id == outcome.id }) else { return }
        outcomes.append(outcome)
        lastRecordedAt = max(lastRecordedAt ?? occurredAt, occurredAt)
        prune(now: occurredAt)
    }

    /// How strongly an opportunity recorded under one set of conditions may
    /// speak about another.
    ///
    /// The Curator keys uplift on movement, desk role, and context together, and
    /// a reader meets a given family in whichever role the desk had free that
    /// day. Their evidence therefore scatters across cells that each looked too
    /// thin to read, and the loop stayed inert for exactly the readers who open
    /// the Book least. Nearby evidence is now admitted, discounted by how far it
    /// had to travel, and never allowed to carry the weight of local proof.
    private static func specificityWeight(
        movement: BookReenchantmentMovement,
        role: BookSessionRole,
        contextKey: String,
        of opportunity: CausalCurationOpportunity
    ) -> Double {
        guard opportunity.movement == movement else {
            // A different session intention entirely. Whether a family leaves a
            // trace in a reader's life is partly its own property, so this is
            // worth something, but it takes a great deal of it to speak.
            return 0.1
        }
        switch (opportunity.role == role, opportunity.contextKey == contextKey) {
        case (true, true): return 1
        case (true, false): return 0.7
        case (false, true): return 0.45
        case (false, false): return 0.25
        }
    }

    func estimate(
        movement: BookReenchantmentMovement,
        role: BookSessionRole,
        sourceID: String,
        contextKey: String,
        now: Date
    ) -> CausalUpliftEstimate {
        let cutoff = now.addingTimeInterval(-365 * 86_400)
        let resolved = resolvedValues(now: now)
        let weighted = opportunities.compactMap { opportunity -> WeightedOpportunity? in
            guard opportunity.selectedAt >= cutoff,
                  let value = resolved[opportunity.id] else { return nil }
            return WeightedOpportunity(
                opportunity: opportunity,
                value: value,
                weight: Self.specificityWeight(
                    movement: movement,
                    role: role,
                    contextKey: contextKey,
                    of: opportunity
                )
            )
        }
        let treatment = weighted.filter { $0.opportunity.selectedSourceID == sourceID }
        let control = weighted.filter { item in
            item.opportunity.selectedSourceID != sourceID
                && item.opportunity.candidates.contains { $0.sourceID == sourceID }
        }
        guard !treatment.isEmpty || !control.isEmpty else { return .unwritten }
        // Pooling exists to give a thin cell a voice, never to talk over a cell
        // that already has one. Where the evidence recorded in these very
        // conditions clears the bar by itself, it is read alone: mixing in
        // neighbouring cells would only blunt a reading that was already sharp,
        // and a family with a strong local record would end up moving the desk
        // less than it had earned.
        let localTreatment = treatment.filter { $0.weight == 1 }
        let localControl = control.filter { $0.weight == 1 }
        let exact = Self.clearsEvidenceBar(localTreatment) && Self.clearsEvidenceBar(localControl)
        return estimate(
            treatment: exact ? localTreatment : treatment,
            control: exact ? localControl : control,
            sourceID: sourceID,
            exact: exact
        )
    }

    func multiplier(
        movement: BookReenchantmentMovement,
        role: BookSessionRole,
        sourceID: String,
        contextKey: String,
        now: Date
    ) -> Double {
        let result = estimate(
            movement: movement,
            role: role,
            sourceID: sourceID,
            contextKey: contextKey,
            now: now
        )
        guard result.hasEnoughEvidence else { return 1 }
        let reach = Self.exploitationReach(for: result)
        if result.conservativeLowerBound > 0.015 {
            return min(reach.ceiling, 1 + result.conservativeLowerBound * 1.35)
        }
        if result.conservativeUpperBound < -0.015 {
            return max(reach.floor, 1 + result.conservativeUpperBound)
        }
        return 1
    }

    /// How far a reading is allowed to lean on the desk, widening with the
    /// evidence behind it.
    ///
    /// A single flat clamp meant a settled preference standing on months of lived
    /// receipts moved the desk no more than one standing on the bare minimum, so
    /// the desk converged on a fixed mixture and stopped improving no matter what
    /// else the reader proved. Caution early is what keeps a lucky first week
    /// from becoming a reader's whole Book; the widening is what lets a Book that
    /// has genuinely learned something act like it.
    ///
    /// The floor never reaches zero and the race that consumes this never gives a
    /// candidate zero weight. A cooled family keeps its ticket forever: it has
    /// to, or one bad fortnight becomes a permanent verdict.
    private static func exploitationReach(
        for estimate: CausalUpliftEstimate
    ) -> (ceiling: Double, floor: Double) {
        let evidence = min(
            estimate.effectiveTreatmentSamples,
            estimate.effectiveControlSamples
        )
        let span = 18.0
        let saturation = min(1, max(0, (evidence - CausalUpliftEstimate.minimumEffectiveSamples) / span))
        return (
            ceiling: 1.48 + 0.27 * saturation,
            floor: 0.72 - 0.14 * saturation
        )
    }

    func movementEstimate(
        movement: BookReenchantmentMovement,
        contextKey: String,
        now: Date
    ) -> CausalUpliftEstimate {
        let cutoff = now.addingTimeInterval(-365 * 86_400)
        let resolved = resolvedValues(now: now)
        let weighted = movementOpportunities.compactMap { opportunity -> WeightedMovementOpportunity? in
            guard opportunity.selectedAt >= cutoff,
                  let value = resolved[opportunity.id] else { return nil }
            return WeightedMovementOpportunity(
                opportunity: opportunity,
                value: value,
                weight: opportunity.contextKey == contextKey ? 1 : 0.7
            )
        }
        let treatment = weighted.filter { $0.opportunity.selectedMovement == movement }
        let control = weighted.filter { item in
            item.opportunity.selectedMovement != movement
                && item.opportunity.candidates.contains { $0.movement == movement }
        }
        guard !treatment.isEmpty || !control.isEmpty else { return .unwritten }
        let localTreatment = treatment.filter { $0.weight == 1 }
        let localControl = control.filter { $0.weight == 1 }
        let exact = Self.clearsEvidenceBar(localTreatment) && Self.clearsEvidenceBar(localControl)
        return movementEstimate(
            treatment: exact ? localTreatment : treatment,
            control: exact ? localControl : control,
            movement: movement,
            exact: exact
        )
    }

    func movementMultiplier(
        movement: BookReenchantmentMovement,
        contextKey: String,
        now: Date
    ) -> Double {
        let result = movementEstimate(movement: movement, contextKey: contextKey, now: now)
        guard result.hasEnoughEvidence else { return 1 }
        let reach = Self.exploitationReach(for: result)
        if result.conservativeLowerBound > 0.015 {
            return min(reach.ceiling - 0.08, 1 + result.conservativeLowerBound * 1.15)
        }
        if result.conservativeUpperBound < -0.015 {
            return max(reach.floor + 0.04, 1 + result.conservativeUpperBound * 0.8)
        }
        return 1
    }

    /// No more than two high-pressure experiments in a rolling week unless a
    /// prior one produced qualified positive evidence. This is a measurement
    /// safeguard as much as a dignity safeguard: repeated pressure destroys a
    /// useful counterfactual baseline.
    func allowsHighPressureAttempt(now: Date) -> Bool {
        let cutoff = now.addingTimeInterval(-7 * 86_400)
        let recent = opportunities.filter { $0.selectedAt >= cutoff && $0.pressureCost >= 0.75 }
        if recent.count < 2 { return true }
        let resolved = resolvedValues(now: now)
        return recent.contains { (resolved[$0.id] ?? 0) >= 0.65 }
    }

    /// An opportunity paired with its resolved outcome and how much this
    /// particular question lets it say.
    private struct WeightedOpportunity {
        var opportunity: CausalCurationOpportunity
        var value: Double
        var weight: Double
    }

    private struct WeightedMovementOpportunity {
        var opportunity: CausalMovementOpportunity
        var value: Double
        var weight: Double
    }

    private static func effectiveSamples(_ group: [WeightedOpportunity]) -> Double {
        group.reduce(0) { $0 + $1.weight }
    }

    private static func effectiveSamples(_ group: [WeightedMovementOpportunity]) -> Double {
        group.reduce(0) { $0 + $1.weight }
    }

    private static func clearsEvidenceBar(_ group: [WeightedOpportunity]) -> Bool {
        effectiveSamples(group) >= CausalUpliftEstimate.minimumEffectiveSamples
    }

    private static func clearsEvidenceBar(_ group: [WeightedMovementOpportunity]) -> Bool {
        effectiveSamples(group) >= CausalUpliftEstimate.minimumEffectiveSamples
    }

    /// Resolve every opportunity's outcome in a single pass.
    ///
    /// This used to be asked one opportunity at a time, and each answer rescanned
    /// the whole outcome log: quadratic work inside a function the Curator calls
    /// for every candidate of every desk. Pooling consults far more
    /// opportunities than the old exact-cell filter did, so the index is what
    /// keeps the wider question affordable. Semantics are unchanged: a qualified
    /// positive outcome wins, any other qualified outcome resolves to zero, and
    /// silence resolves to zero only once the reader has come back later.
    private func resolvedValues(now: Date) -> [String: Double] {
        var bestPositive: [String: Double] = [:]
        var qualified: Set<String> = []
        for outcome in outcomes where outcome.kind.isQualified {
            qualified.insert(outcome.opportunityID)
            guard outcome.value > 0 else { continue }
            bestPositive[outcome.opportunityID] = max(
                bestPositive[outcome.opportunityID] ?? 0,
                outcome.value
            )
        }

        var resolved: [String: Double] = [:]
        resolved.reserveCapacity(opportunities.count + movementOpportunities.count)
        func resolve(id: String, selectedAt: Date) {
            if let positive = bestPositive[id] {
                resolved[id] = positive
            } else if qualified.contains(id) {
                resolved[id] = 0
            } else if now.timeIntervalSince(selectedAt) >= Self.outcomeWindow,
                      let lastRecordedAt,
                      lastRecordedAt > selectedAt.addingTimeInterval(Self.outcomeWindow) {
                resolved[id] = 0
            }
        }
        for opportunity in opportunities {
            resolve(id: opportunity.id, selectedAt: opportunity.selectedAt)
        }
        for opportunity in movementOpportunities {
            resolve(id: opportunity.id, selectedAt: opportunity.selectedAt)
        }
        return resolved
    }

    private func estimate(
        treatment: [WeightedOpportunity],
        control: [WeightedOpportunity],
        sourceID: String,
        exact: Bool
    ) -> CausalUpliftEstimate {
        let treated = betaStats(for: treatment, sourceID: sourceID, isTreatment: true)
        let untreated = betaStats(for: control, sourceID: sourceID, isTreatment: false)
        let difference = treated.mean - untreated.mean
        let standardError = sqrt(treated.variance + untreated.variance)
        return CausalUpliftEstimate(
            treatmentCount: treatment.count,
            controlCount: control.count,
            treatmentMean: treated.mean,
            controlMean: untreated.mean,
            estimatedUplift: difference,
            conservativeLowerBound: difference - 1.28 * standardError,
            conservativeUpperBound: difference + 1.28 * standardError,
            usedExactContext: exact,
            effectiveTreatmentSamples: Self.effectiveSamples(treatment),
            effectiveControlSamples: Self.effectiveSamples(control)
        )
    }

    private func betaStats(
        for group: [WeightedOpportunity],
        sourceID: String,
        isTreatment: Bool
    ) -> (mean: Double, variance: Double) {
        var alpha = 1.0
        var beta = 3.0
        for item in group {
            let opportunity = item.opportunity
            let adjusted = max(0, min(1, item.value - opportunity.pressureCost * 0.20))
            let treatmentPropensity = propensity(of: sourceID, in: opportunity.candidates)
            let assignmentPropensity = isTreatment ? treatmentPropensity : (1 - treatmentPropensity)
            let inversePropensity = min(4.0, max(1.0, 1.0 / max(0.08, assignmentPropensity)))
            // Borrowed evidence moves the posterior less and, because it also
            // enlarges the posterior less, leaves the interval wider, so a
            // reading assembled from distant cells stays harder to act on.
            let pseudoCount = item.weight * inversePropensity
            alpha += pseudoCount * adjusted
            beta += pseudoCount * (1 - adjusted)
        }
        let total = alpha + beta
        let mean = alpha / total
        let variance = (alpha * beta) / (total * total * (total + 1))
        return (mean, variance)
    }

    private func movementEstimate(
        treatment: [WeightedMovementOpportunity],
        control: [WeightedMovementOpportunity],
        movement: BookReenchantmentMovement,
        exact: Bool
    ) -> CausalUpliftEstimate {
        let treated = movementBetaStats(for: treatment, movement: movement, isTreatment: true)
        let untreated = movementBetaStats(for: control, movement: movement, isTreatment: false)
        let difference = treated.mean - untreated.mean
        let standardError = sqrt(treated.variance + untreated.variance)
        return CausalUpliftEstimate(
            treatmentCount: treatment.count,
            controlCount: control.count,
            treatmentMean: treated.mean,
            controlMean: untreated.mean,
            estimatedUplift: difference,
            conservativeLowerBound: difference - 1.28 * standardError,
            conservativeUpperBound: difference + 1.28 * standardError,
            usedExactContext: exact,
            effectiveTreatmentSamples: Self.effectiveSamples(treatment),
            effectiveControlSamples: Self.effectiveSamples(control)
        )
    }

    private func movementBetaStats(
        for group: [WeightedMovementOpportunity],
        movement: BookReenchantmentMovement,
        isTreatment: Bool
    ) -> (mean: Double, variance: Double) {
        var alpha = 1.0
        var beta = 3.0
        for item in group {
            let treatmentPropensity = propensity(of: movement, in: item.opportunity.candidates)
            let assignmentPropensity = isTreatment ? treatmentPropensity : (1 - treatmentPropensity)
            let inversePropensity = min(4.0, max(1.0, 1.0 / max(0.08, assignmentPropensity)))
            let pseudoCount = item.weight * inversePropensity
            alpha += pseudoCount * item.value
            beta += pseudoCount * (1 - item.value)
        }
        let total = alpha + beta
        let mean = alpha / total
        let variance = (alpha * beta) / (total * total * (total + 1))
        return (mean, variance)
    }

    private func propensity(
        of sourceID: String,
        in candidates: [CausalCurationCandidate]
    ) -> Double {
        let total = candidates.reduce(0) { $0 + max(0, $1.weight) }
        guard total > 0 else { return 0 }
        let selected = candidates
            .filter { $0.sourceID == sourceID }
            .reduce(0) { $0 + max(0, $1.weight) }
        return max(0.000_001, min(0.999_999, selected / total))
    }

    private func propensity(
        of movement: BookReenchantmentMovement,
        in candidates: [CausalMovementCandidate]
    ) -> Double {
        let total = candidates.reduce(0) { $0 + max(0, $1.weight) }
        guard total > 0 else { return 0 }
        let selected = candidates
            .filter { $0.movement == movement }
            .reduce(0) { $0 + max(0, $1.weight) }
        return max(0.000_001, min(0.999_999, selected / total))
    }

    private mutating func appendOutcome(_ outcome: CausalCurationOutcome, opportunityID: String) {
        let recorded = CausalCurationOutcome(
            // One reader event may resolve both the session-movement choice
            // and the Page-role choice. Identity must therefore include the
            // opportunity, or the first append would silently starve the
            // other level of its outcome.
            id: "\(outcome.id)|\(opportunityID)",
            opportunityID: opportunityID,
            occurredAt: outcome.occurredAt,
            kind: outcome.kind,
            value: outcome.value,
            evidenceLine: outcome.evidenceLine
        )
        guard !outcomes.contains(where: { $0.id == recorded.id }) else { return }
        outcomes.append(recorded)
    }

    private static func outcome(for event: ReaderLearningEvent) -> CausalCurationOutcome? {
        let kind: CausalAlivenessOutcomeKind
        let value: Double
        switch event.action {
        case .surfaced, .opened, .recognized:
            return nil
        case .acted:
            kind = .participated; value = 0.08
        case .broughtFromElsewhere:
            // Strong autonomous taste, but not yet a lived outcome.
            kind = .chosen; value = 0.25
        case .kept:
            kind = .chosen; value = 0.12
        case .dismissed:
            kind = .declined; value = 0
        case .missed:
            kind = .contradicted; value = 0
        case .followedThread:
            kind = .laterReturn; value = 0.65
        case .keepsakeEarned:
            kind = .keepsake; value = 0.75
        case .loved:
            // Strong evidence of fit, but still an answer inside the Book. A
            // later return, keepsake, or lived receipt must outrank it.
            kind = .confirmed; value = 0.45
        }
        return CausalCurationOutcome(
            id: "learning:\(event.id)",
            opportunityID: "",
            occurredAt: event.occurredAt,
            kind: kind,
            value: value,
            evidenceLine: event.evidence?.nonEmpty.map { String($0.prefix(180)) }
        )
    }

    private mutating func prune(now: Date) {
        let cutoff = now.addingTimeInterval(-730 * 86_400)
        opportunities = Array(opportunities.filter { $0.selectedAt >= cutoff }.suffix(Self.maxOpportunities))
        movementOpportunities = Array(
            movementOpportunities.filter { $0.selectedAt >= cutoff }.suffix(Self.maxOpportunities)
        )
        let validIDs = Set(opportunities.map(\.id) + movementOpportunities.map(\.id))
        outcomes = Array(outcomes.filter { validIDs.contains($0.opportunityID) }.suffix(Self.maxOutcomes))
    }
}

/// A private, local, revisable portrait of the conditions under which this
/// particular reader becomes more alive. It is a sparse evidence tensor rather
/// than a personality label: movement x source x hour x weather x place x
/// company x language. Exact observations stay available behind every claim.
struct ReaderAlivenessModel: Codable, Equatable {
    static let currentVersion = 1
    static let maxObservations = 1_200

    var version: Int = ReaderAlivenessModel.currentVersion
    var observations: [ReaderAlivenessObservation] = []
    var patternFeedback: [String: ReaderAlivenessPatternFeedback] = [:]
    /// Optional so Books written before causal opportunity logging decode as an
    /// empty experiment ledger rather than inventing a migration history.
    var causalLedger: CausalCurationLedger?
    var lastUpdatedAt: Date?

    static let unwritten = ReaderAlivenessModel()

    mutating func ingest(_ event: ReaderLearningEvent) {
        // Useful for momentum timing, but not a second expression of taste or
        // a distinct lived outcome in the Curator's causal portrait.
        guard !event.isMomentumOnly, event.allowsCurationLearning else { return }
        if event.causalReceipt != nil || event.causalMovementReceipt != nil {
            var ledger = causalLedger ?? .unwritten
            ledger.record(event)
            causalLedger = ledger
        }
        let patternID = Self.tagValue(prefix: "aliveness-pattern:", in: event.tags)
        if let patternID,
           [.loved, .missed, .dismissed].contains(event.action) {
            var feedback = patternFeedback[patternID] ?? ReaderAlivenessPatternFeedback()
            switch event.action {
            case .loved:
                feedback.confirmed += 1
            case .missed:
                feedback.contradicted += 1
            case .dismissed:
                feedback.forbidden = true
            default:
                break
            }
            feedback.lastAnsweredAt = event.occurredAt
            patternFeedback[patternID] = feedback
            lastUpdatedAt = event.occurredAt
            return
        }

        if let originalRaw = Self.tagValue(prefix: "original-book-session-movement:", in: event.tags),
           let originalMovement = BookReenchantmentMovement.allCases.first(where: {
               $0.rawValue.caseInsensitiveCompare(originalRaw) == .orderedSame
           }),
           [.kept, .loved, .followedThread].contains(event.action) {
            let impact: Int
            switch event.action {
            case .loved: impact = 82
            case .followedThread: impact = 70
            default: impact = 58
            }
            let originalSource = Self.tagValue(prefix: "original-book-session-source:", in: event.tags)
            append(ReaderAlivenessObservation(
                id: "return:\(event.id)",
                sessionID: Self.tagValue(prefix: "original-book-session-id:", in: event.tags),
                movement: originalMovement,
                role: .echo,
                sourceID: originalSource,
                pageID: Self.tagValue(prefix: "remembered-page:", in: event.tags),
                dayID: event.dayID,
                occurredAt: event.occurredAt,
                kind: .followed,
                authority: event.action == .loved ? .readerCorrection : .readerAuthored,
                impact: impact,
                facets: Self.facets(
                    sourceID: originalSource,
                    tags: event.tags,
                    context: event.context,
                    evidence: event.evidence
                ),
                evidenceLine: event.evidence?.nonEmpty.map { String($0.prefix(180)) }
            ))
            if let originalOpportunityID = Self.tagValue(prefix: "original-causal-experiment:", in: event.tags) {
                var ledger = causalLedger ?? .unwritten
                let causalValue: Double
                switch event.action {
                case .loved: causalValue = 0.82
                case .followedThread: causalValue = 0.76
                default: causalValue = 0.68
                }
                ledger.recordLivedOutcome(
                    opportunityID: originalOpportunityID,
                    occurredAt: event.occurredAt,
                    value: causalValue,
                    evidenceLine: event.evidence ?? "An older Page was deliberately chosen when it returned."
                )
                causalLedger = ledger
            }
            if let originalMovementOpportunityID = Self.tagValue(
                prefix: "original-causal-movement-experiment:",
                in: event.tags
            ) {
                var ledger = causalLedger ?? .unwritten
                ledger.recordLivedOutcome(
                    opportunityID: originalMovementOpportunityID,
                    occurredAt: event.occurredAt,
                    value: event.action == .loved ? 0.82 : 0.72,
                    evidenceLine: event.evidence ?? "A movement arranged by an older session survived into a later return."
                )
                causalLedger = ledger
            }
        }

        guard let movement = Self.movement(in: event.tags),
              let signal = Self.signal(for: event.action) else { return }
        let observation = ReaderAlivenessObservation(
            id: "learning:\(event.id)",
            sessionID: Self.tagValue(prefix: "book-session-id:", in: event.tags),
            movement: movement,
            role: Self.tagValue(prefix: "book-session-role:", in: event.tags)
                .flatMap(BookSessionRole.init(rawValue:)),
            sourceID: event.sourceID,
            pageID: nil,
            dayID: event.dayID,
            occurredAt: event.occurredAt,
            kind: signal.kind,
            authority: signal.authority,
            impact: signal.impact,
            facets: Self.facets(
                sourceID: event.sourceID,
                tags: event.tags,
                context: event.context,
                evidence: event.evidence
            ),
            evidenceLine: event.evidence?.nonEmpty.map { String($0.prefix(180)) }
        )
        append(observation)
    }

    /// Apply a Page-local learning revocation to every adaptive layer that may
    /// already have consumed those events.
    mutating func removeLearningEvidence(from events: [ReaderLearningEvent]) {
        guard !events.isEmpty else { return }
        let observationIDs = Set(events.flatMap {
            ["learning:\($0.id)", "return:\($0.id)"]
        })
        observations.removeAll { observationIDs.contains($0.id) }
        if var ledger = causalLedger {
            ledger.removeLearningEvidence(from: events)
            causalLedger = ledger.opportunities.isEmpty
                && ledger.movementOpportunities.isEmpty
                && ledger.outcomes.isEmpty
                ? nil
                : ledger
        }
        lastUpdatedAt = observations.map(\.occurredAt).max()
    }

    /// A delayed pulse is direct reader testimony about whether a prior
    /// curation opportunity escaped the screen. Current-state pulses never
    /// enter the causal ledger: feeling vivid before the Book acts is context,
    /// not proof the Book caused anything.
    mutating func ingest(_ pulse: ReaderStatePulseRecord) {
        guard pulse.dimension == .delayedOutcome,
              let target = pulse.target else { return }
        let impact = max(-100, min(100, (pulse.score - 5) * 20))
        let observation = ReaderAlivenessObservation(
            id: "pulse:\(pulse.id)",
            sessionID: target.sessionID,
            movement: target.movement,
            role: target.role,
            sourceID: target.sourceID,
            pageID: target.pageID,
            dayID: pulse.dayID,
            occurredAt: pulse.answeredAt,
            kind: impact >= 25 ? .livedEvidence : (impact <= -25 ? .contradicted : .acted),
            authority: .readerCorrection,
            impact: impact,
            facets: pulse.facets,
            evidenceLine: String((pulse.note?.nonEmpty ?? pulse.answerLine).prefix(180))
        )
        append(observation)

        var ledger = causalLedger ?? .unwritten
        let value = Double(max(0, min(10, pulse.score))) / 10
        if let opportunityID = target.causalOpportunityID {
            ledger.recordLivedOutcome(
                opportunityID: opportunityID,
                occurredAt: pulse.answeredAt,
                value: value,
                evidenceLine: pulse.note?.nonEmpty ?? pulse.answerLine
            )
        }
        if let movementOpportunityID = target.causalMovementOpportunityID {
            ledger.recordLivedOutcome(
                opportunityID: movementOpportunityID,
                occurredAt: pulse.answeredAt,
                value: value,
                evidenceLine: pulse.note?.nonEmpty ?? pulse.answerLine
            )
        }
        causalLedger = ledger
        lastUpdatedAt = pulse.answeredAt
    }

    mutating func reconcile(
        longGame: BookLongGame?,
        days: [BookDay],
        now: Date
    ) {
        guard let longGame else { return }
        let pagesByID = Dictionary(uniqueKeysWithValues: days.flatMap(\.pages).map { ($0.id, $0) })
        for evidence in longGame.evidence {
            let id = "long-game:\(evidence.id)"
            guard !observations.contains(where: { $0.id == id }) else { continue }
            let page = evidence.evidencePageIDs.compactMap { pagesByID[$0] }.first
            let impact: Int
            let authority: ReaderAlivenessEvidenceAuthority
            switch evidence.kind {
            case .spontaneousKeep:
                impact = 68
                authority = .readerAuthored
            case .explicitFieldNote:
                impact = 76
                authority = .readerAuthored
            case .completedExperiment:
                impact = 90
                authority = .livedReceipt
            case .readerDefinition:
                impact = 82
                authority = .readerAuthored
            case .spontaneousPattern:
                impact = 94
                authority = .livedReceipt
            case .readerDeclaration:
                impact = 100
                authority = .readerAuthored
            }
            append(ReaderAlivenessObservation(
                id: id,
                sessionID: page.flatMap { Self.tagValue(prefix: "book-session-id:", in: $0.tags) },
                movement: BookReenchantmentMovement(capacity: evidence.capacity),
                role: page.flatMap { Self.tagValue(prefix: "book-session-role:", in: $0.tags) }
                    .flatMap(BookSessionRole.init(rawValue:)),
                sourceID: page?.sourceID,
                pageID: page?.id,
                dayID: page.map { BookDay.id(for: $0.createdAt) } ?? BookDay.id(for: evidence.happenedAt),
                occurredAt: evidence.happenedAt,
                kind: .livedEvidence,
                authority: authority,
                impact: impact,
                facets: Self.facets(
                    sourceID: page?.sourceID,
                    tags: page?.tags ?? [],
                    context: page?.context,
                    evidence: [evidence.line, page?.userInput].compactMap { $0 }.joined(separator: " ")
                ),
                evidenceLine: String(evidence.line.prefix(180))
            ))
            if let page,
               let opportunityID = Self.tagValue(prefix: "causal-experiment:", in: page.tags) {
                var ledger = causalLedger ?? .unwritten
                ledger.recordLivedOutcome(
                    opportunityID: opportunityID,
                    occurredAt: evidence.happenedAt,
                    value: Double(impact) / 100,
                    evidenceLine: evidence.line
                )
                causalLedger = ledger
            }
            if let page,
               let movementOpportunityID = Self.tagValue(prefix: "causal-movement-experiment:", in: page.tags) {
                var ledger = causalLedger ?? .unwritten
                ledger.recordLivedOutcome(
                    opportunityID: movementOpportunityID,
                    occurredAt: evidence.happenedAt,
                    value: Double(impact) / 100,
                    evidenceLine: evidence.line
                )
                causalLedger = ledger
            }
        }
        prune(now: now)
    }

    func patterns(now: Date = Date(), limit: Int = 8) -> [ReaderAlivenessPattern] {
        struct GroupKey: Hashable {
            var movement: BookReenchantmentMovement
            var facets: [String]
        }

        let eligible = observations.filter { abs($0.impact) >= 25 }
        var groups: [GroupKey: [ReaderAlivenessObservation]] = [:]
        for observation in eligible {
            let expressive = observation.facets.filter(Self.isExpressiveFacet)
            for facet in expressive.prefix(8) {
                groups[GroupKey(movement: observation.movement, facets: [facet]), default: []].append(observation)
            }
            let contextual = Array(expressive.filter { !$0.hasPrefix("source:") }.prefix(5))
            if contextual.count >= 2 {
                for left in 0..<(contextual.count - 1) {
                    for right in (left + 1)..<contextual.count {
                        let pair = [contextual[left], contextual[right]].sorted()
                        groups[GroupKey(movement: observation.movement, facets: pair), default: []].append(observation)
                    }
                }
            }
        }

        return groups.compactMap { key, members -> ReaderAlivenessPattern? in
            let uniqueMembers = Dictionary(grouping: members, by: \.id).compactMap { $0.value.first }
            let supporting = uniqueMembers.filter { $0.impact > 0 }
            let contradicting = uniqueMembers.filter { $0.impact < 0 }
            let distinctDays = Set(supporting.map(\.dayID)).count
            let livedCount = supporting.filter { $0.kind == .livedEvidence }.count
            let outcomeCount = supporting.filter {
                [.livedEvidence, .keepsake, .followed, .confirmedReading].contains($0.kind)
            }.count
            let positiveWeight = supporting.reduce(0) { $0 + $1.impact }
            let negativeWeight = contradicting.reduce(0) { $0 + abs($1.impact) }
            guard distinctDays >= 2,
                  positiveWeight >= (key.facets.count == 1 ? 120 : 145),
                  outcomeCount > 0 else { return nil }

            let idSeed = "\(key.movement.rawValue)|\(key.facets.joined(separator: "|"))"
            let id = "aliveness-\(key.movement.rawValue)-\(abs(idSeed.stableHash))".readerLearningNormalizedTag
            let feedback = patternFeedback[id] ?? ReaderAlivenessPatternFeedback()
            guard !feedback.forbidden else { return nil }
            let confidence = min(97, max(55,
                38 + distinctDays * 9 + livedCount * 13 + feedback.confirmed * 10
                    - contradicting.count * 7 - feedback.contradicted * 13
            ))
            guard confidence >= 68 else { return nil }
            let sortedSupport = supporting.sorted { $0.occurredAt < $1.occurredAt }
            guard let first = sortedSupport.first, let last = sortedSupport.last else { return nil }
            let descriptions = key.facets.map(Self.describeFacet)
            let condition = Self.joinedConditions(descriptions)
            let effect = Self.effectLine(for: key.movement)
            let contradictionLine = negativeWeight > 0
                ? "It has failed or been refused \(contradicting.count) time\(contradicting.count == 1 ? "" : "s"), so this is a tendency, not a law."
                : "The counter-reading is simple: these moments may have been good for reasons I haven't measured."
            return ReaderAlivenessPattern(
                id: id,
                movement: key.movement,
                facets: key.facets,
                supportingObservationIDs: sortedSupport.map(\.id),
                contradictingObservationIDs: contradicting.map(\.id),
                evidencePageIDs: Array(Set(sortedSupport.compactMap(\.pageID))).sorted(),
                evidenceLines: Array(sortedSupport.compactMap(\.evidenceLine).filter { !$0.isEmpty }.suffix(3)),
                firstObservedAt: first.occurredAt,
                lastObservedAt: last.occurredAt,
                confidence: confidence,
                line: "\(condition) \(effect)",
                counterReading: contradictionLine,
                falsifier: "If the next two comparable moments are refused or leave no lived trace, I must weaken this reading.")
        }
        .filter { !$0.isStale(at: now) }
        .sorted { left, right in
            if left.confidence != right.confidence { return left.confidence > right.confidence }
            if left.facets.count != right.facets.count { return left.facets.count > right.facets.count }
            return left.lastObservedAt > right.lastObservedAt
        }
        .prefix(max(0, limit))
        .map { $0 }
    }

    /// The Book uses intimate knowledge, but never turns it into a destiny.
    /// Learned success can roughly double a Page's chance; contradiction can
    /// cool it, while the floor preserves genuine exploration.
    func curationMultiplier(
        movement: BookReenchantmentMovement,
        sourceID: String,
        currentFacets: Set<String>,
        now: Date
    ) -> Double {
        let cutoff = now.addingTimeInterval(-180 * 86_400)
        let relevant = observations.filter {
            $0.movement == movement && $0.occurredAt >= cutoff && abs($0.impact) >= 25
        }
        guard !relevant.isEmpty else { return 1.18 }
        let sourceMatches = relevant.filter { $0.sourceID == sourceID }
        let contextMatches = relevant.filter { !Set($0.facets).isDisjoint(with: currentFacets) }
        let weighted = sourceMatches + contextMatches
        guard !weighted.isEmpty else { return 1.06 }
        let signed = weighted.reduce(0) { $0 + $1.impact }
        let scale = max(140.0, Double(weighted.count * 85))
        return max(0.58, min(1.85, 1.0 + Double(signed) / scale))
    }

    func movementExplorationMultiplier(
        _ movement: BookReenchantmentMovement,
        now: Date
    ) -> Double {
        let relevant = observations.filter { $0.movement == movement && abs($0.impact) >= 25 }
        guard !relevant.isEmpty else { return 1.35 }
        let recentStrong = relevant.contains {
            $0.impact >= 65 && now.timeIntervalSince($0.occurredAt) < 3 * 86_400
        }
        if recentStrong { return 0.74 }
        if Set(relevant.map(\.dayID)).count < 3 { return 1.16 }
        let total = relevant.reduce(0) { $0 + $1.impact }
        return max(0.78, min(1.24, 1.0 + Double(total) / Double(max(500, relevant.count * 400))))
    }

    func causalUpliftMultiplier(
        movement: BookReenchantmentMovement,
        role: BookSessionRole,
        sourceID: String,
        contextKey: String,
        now: Date
    ) -> Double {
        (causalLedger ?? .unwritten).multiplier(
            movement: movement,
            role: role,
            sourceID: sourceID,
            contextKey: contextKey,
            now: now
        )
    }

    func causalMovementUpliftMultiplier(
        movement: BookReenchantmentMovement,
        contextKey: String,
        now: Date
    ) -> Double {
        (causalLedger ?? .unwritten).movementMultiplier(
            movement: movement,
            contextKey: contextKey,
            now: now
        )
    }

    func allowsHighPressureCausalAttempt(now: Date) -> Bool {
        (causalLedger ?? .unwritten).allowsHighPressureAttempt(now: now)
    }

    private mutating func append(_ observation: ReaderAlivenessObservation) {
        guard !observations.contains(where: { $0.id == observation.id }) else { return }
        observations.append(observation)
        if observations.count > Self.maxObservations {
            observations = Array(observations.suffix(Self.maxObservations))
        }
        lastUpdatedAt = observation.occurredAt
    }

    private mutating func prune(now: Date) {
        let cutoff = now.addingTimeInterval(-730 * 86_400)
        observations = Array(observations.filter { $0.occurredAt >= cutoff }.suffix(Self.maxObservations))
        if patternFeedback.count > 240 {
            patternFeedback = Dictionary(uniqueKeysWithValues: patternFeedback
                .sorted { ($0.value.lastAnsweredAt ?? .distantPast) > ($1.value.lastAnsweredAt ?? .distantPast) }
                .prefix(240)
                .map { ($0.key, $0.value) })
        }
    }

    private static func signal(
        for action: ReaderLearningAction
    ) -> (kind: ReaderAlivenessEvidenceKind, authority: ReaderAlivenessEvidenceAuthority, impact: Int)? {
        switch action {
        case .surfaced:
            return nil
        case .opened:
            return (.opened, .interaction, 8)
        case .acted:
            return (.acted, .interaction, 28)
        case .broughtFromElsewhere:
            // Deliberately below the model's lived-impact threshold.
            return (.chosen, .readerAuthored, 20)
        case .recognized:
            return nil
        case .followedThread:
            return (.followed, .interaction, 52)
        case .keepsakeEarned:
            return (.keepsake, .interaction, 64)
        case .kept:
            return (.chosen, .readerAuthored, 22)
        case .loved:
            return (.confirmedReading, .readerCorrection, 88)
        case .dismissed:
            return (.declined, .readerCorrection, -28)
        case .missed:
            return (.contradicted, .readerCorrection, -82)
        }
    }

    private static func movement(in tags: [String]) -> BookReenchantmentMovement? {
        let raw = tagValue(prefix: "book-session:", in: tags)
            ?? tagValue(prefix: "book-session-movement:", in: tags)
        guard let raw else { return nil }
        return BookReenchantmentMovement.allCases.first {
            $0.rawValue.caseInsensitiveCompare(raw) == .orderedSame
        }
    }

    private static func tagValue(prefix: String, in tags: [String]) -> String? {
        tags.first(where: { $0.hasPrefix(prefix) }).map { String($0.dropFirst(prefix.count)) }
    }

    private static func facets(
        sourceID: String?,
        tags: [String],
        context: BookPageContextSnapshot?,
        evidence: String?
    ) -> [String] {
        var result: [String] = []
        if let sourceID = sourceID?.nonEmpty {
            result.append("source:\(sourceID.readerLearningNormalizedTag)")
        }
        if let context {
            result.append("time:\(context.dayPart.readerLearningNormalizedTag)")
            result += context.weatherTags.prefix(3).map { "weather:\($0.readerLearningNormalizedTag)" }
            if let anchor = context.nearbyAnchorID?.nonEmpty {
                result.append("anchor:\(anchor.readerLearningNormalizedTag)")
            } else if let place = context.locationLabel?.nonEmpty {
                result.append("place:\(place.readerLearningNormalizedTag)")
            }
            if let count = context.calendarEventCount {
                result.append("day-load:\(count == 0 ? "open" : (count >= 3 ? "crowded" : "held"))")
            }
            if let body = context.bodyScore {
                result.append("body:\(body < 35 ? "low" : (body > 72 ? "bright" : "steady"))")
            }
        }
        result += tags.filter {
            $0.hasPrefix("person:") || $0.hasPrefix("entity:") || $0.hasPrefix("sender:")
        }.prefix(3)
        result += salientWords(in: evidence).map { "word:\($0)" }
        return Array(Set(result.filter { !$0.hasSuffix(":") })).sorted()
    }

    private static func salientWords(in text: String?) -> [String] {
        guard let text else { return [] }
        let ignored: Set<String> = [
            "about", "after", "again", "also", "because", "been", "book", "could", "from", "have",
            "kept", "page", "reader", "really", "said", "that", "their", "there", "they", "this",
            "through", "today", "very", "what", "when", "where", "which", "with", "would", "your"
        ]
        var counts: [String: Int] = [:]
        for word in text.lowercased().components(separatedBy: CharacterSet.alphanumerics.inverted)
            where word.count >= 5 && !ignored.contains(word) {
            counts[word, default: 0] += 1
        }
        return counts.sorted {
            if $0.value != $1.value { return $0.value > $1.value }
            return $0.key < $1.key
        }.prefix(3).map(\.key)
    }

    private static func isExpressiveFacet(_ facet: String) -> Bool {
        ["source:", "time:", "weather:", "anchor:", "place:", "day-load:", "body:", "person:", "entity:", "sender:", "word:"]
            .contains(where: facet.hasPrefix)
    }

    private static func describeFacet(_ facet: String) -> String {
        let parts = facet.split(separator: ":", maxSplits: 1).map(String.init)
        guard parts.count == 2 else { return facet }
        let value = parts[1].replacingOccurrences(of: "-", with: " ")
        switch parts[0] {
        case "time": return value == "night" ? "late hours" : "\(value)s"
        case "weather": return value
        case "anchor", "place": return value
        case "day-load": return value == "crowded" ? "days already full of other people's claims" : "\(value) days"
        case "body": return value == "low" ? "low-energy hours" : "\(value) bodily weather"
        case "person", "entity", "sender": return "the company of \(value)"
        case "word": return "the word “\(value)”"
        case "source": return "\(value) Pages"
        default: return value
        }
    }

    private static func joinedConditions(_ conditions: [String]) -> String {
        guard let first = conditions.first else { return "Something very particular" }
        let capitalizedFirst = first.prefix(1).uppercased() + String(first.dropFirst())
        if conditions.count == 1 { return capitalizedFirst }
        return "\(capitalizedFirst) and \(conditions.dropFirst().joined(separator: " and "))"
    }

    private static func effectLine(for movement: BookReenchantmentMovement) -> String {
        switch movement {
        case .freshSight: return "keep appearing when your looking becomes less useful and more alive."
        case .livingWorld: return "keep turning the world from backdrop into company."
        case .scriptFreedom: return "keep making inherited rules look less inevitable."
        case .chosenDetour: return "keep helping you author a side door in the day."
        case .exactLanguage: return "keep bringing your experience into sharper, stranger language."
        case .humanOtherness: return "keep letting another person remain a whole world beside you."
        case .livingContinuity: return "keep giving earlier life a real second life in the present."
        case .shelter: return "keep making rest feel receptive rather than defeated."
        }
    }
}

struct BookCurationDirective: Equatable {
    var id: String
    var capacity: BookLongGameCapacity
    var preferredTypes: [BookPageType]
    var preferredIntents: [BookPageIntent]
    var terms: [String]

    static func make(from hypothesis: BookLongGameHypothesis) -> BookCurationDirective {
        let types: [BookPageType]
        let intents: [BookPageIntent]
        switch hypothesis.capacity {
        case .spontaneousAttention:
            types = [.plainPage, .souvenir, .wonderCompass, .weather, .body, .mood]
            intents = [.capture, .rest]
        case .worldOtherness:
            types = [.wonderCompass, .location, .todaysSky, .weather, .bookNotices]
            intents = [.capture, .importReference]
        case .scriptFreedom:
            types = [.wordNegotiation, .affirmations, .faeBargain, .bookNotices, .wonderCompass]
            intents = [.capture, .reflect]
        case .selfAuthoredAction:
            types = [.wonderCompass, .elective, .narrativeOS, .enchantment, .plainPage]
            intents = [.capture, .simulate]
        case .personalLanguage:
            types = [.wordNegotiation, .diary, .souvenir, .quotes, .bookNotices]
            intents = [.capture, .reflect]
        case .livingConnection:
            types = [.letter, .note, .elective, .bookConnections, .gossip]
            intents = [.capture, .reflect]
        case .deliberateReturn:
            types = [.bookRemembered, .bookConnections, .bookOfYou, .bookPocket, .bindery]
            intents = [.resurface, .braid, .reflect]
        }
        return BookCurationDirective(
            id: "book-directive-\(hypothesis.id)",
            capacity: hypothesis.capacity,
            preferredTypes: types,
            preferredIntents: intents,
            terms: hypothesis.capacity.curationTerms
        )
    }

    func fit(for surface: SurfacePage, haystack: String) -> Int {
        var fit = 0
        if preferredTypes.contains(surface.type) { fit += 12 }
        if preferredIntents.contains(surface.intent) { fit += 4 }
        if terms.contains(where: haystack.contains) { fit += 6 }
        return fit
    }
}

enum BookLongGameEvidenceKind: String, Codable, Equatable {
    /// The reader opened an unprompted Plain Page and kept something.
    case spontaneousKeep
    /// The reader explicitly marked a Page with an authored practice tag.
    case explicitFieldNote
    /// The reader completed an experiment the Book proposed.
    case completedExperiment
    /// The reader changed the lexicon and supplied a personal meaning.
    case readerDefinition
    /// Several unprompted returns occurred across lived time.
    case spontaneousPattern
    /// The reader explicitly described the life-changing result in their own Page.
    case readerDeclaration
}

struct BookLongGameEvidence: Codable, Equatable, Identifiable {
    var id: String
    var capacity: BookLongGameCapacity
    var kind: BookLongGameEvidenceKind
    var line: String
    var evidencePageIDs: [String]
    var happenedAt: Date
    /// Prompted evidence is still real evidence of participation, but it may
    /// never masquerade as spontaneous change.
    var wasPromptedByBook: Bool
}

struct BookLongGameHypothesis: Codable, Equatable, Identifiable {
    var id: String
    var capacity: BookLongGameCapacity
    var statement: String
    var nextHonestTest: String
    var evidenceIDs: [String]
    var formedAt: Date
    var lastRevisedAt: Date
}

/// The broad bargain the reader made with the Book. The exact intervention may
/// still be surprising; the maximum edge is never a secret. Existing First
/// Door answers map cleanly, while `askFirst` is reserved for a future explicit
/// control rather than being silently inferred.
enum BookChallengePermission: String, Codable, Equatable, CaseIterable {
    case gentle
    case nudge
    case callMeOnIt
    case askFirst

    static func read(from facts: [SelfFact]) -> BookChallengePermission {
        let answer = facts.first {
            $0.questionID == "onboarding-comfort-boundary" && $0.usePermission != .doNotUse
        }?.answer.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        switch answer {
        case "gentle": return .gentle
        case "strange", "call-me-on-it", "call me on my nonsense": return .callMeOnIt
        case "ask-first", "ask first": return .askFirst
        default: return .nudge
        }
    }

    var maximumPressure: BookCampaignPressure {
        switch self {
        case .gentle, .askFirst: return .invite
        case .nudge: return .nudge
        case .callMeOnIt: return .confront
        }
    }
}

enum BookCampaignPressure: String, Codable, Equatable, CaseIterable {
    case notice
    case invite
    case nudge
    case provoke
    case challenge
    case confront

    var rank: Int { Self.allCases.firstIndex(of: self) ?? 0 }

    func capped(at maximum: BookCampaignPressure) -> BookCampaignPressure {
        rank <= maximum.rank ? self : maximum
    }
}

enum BookCampaignBeat: String, Codable, Equatable {
    case seed
    case interrupt
    case release
    case `return`
}

enum BookCampaignStatus: String, Codable, Equatable {
    case active
    case resting
    case answered
    case untried
    case completed
}

enum BookCampaignTactic: String, Codable, Equatable, CaseIterable {
    case prolongAttention
    case changeScale
    case alterRoute
    case meetNonhumanBusiness
    case questionBorrowedRule
    case makeSmallException
    case makeBadly
    case testReaderNamedDesire
    case inventPrivateRule
    case namePrecisely
    case shareSmallWonder
    case revisitEvidence
    case receiveAndRest
}

enum BookCampaignPresentation: String, Codable, Equatable, CaseIterable {
    case looseMargin
    case smallDoor
    case wickerObjection
    case fieldErrand
    case returnedLeaf
    case silence
}

/// One event-driven act of direction. It is deliberately finite: seed,
/// interruption, silence, return. A campaign stores its reason and receipts so
/// the Book can learn without constructing a covert psychological profile.
struct BookReenchantmentCampaign: Codable, Equatable, Identifiable {
    var id: String
    var hypothesisID: String
    var capacity: BookLongGameCapacity
    var tactic: BookCampaignTactic
    var pressure: BookCampaignPressure
    var permission: BookChallengePermission
    var beat: BookCampaignBeat
    var status: BookCampaignStatus
    var presentation: BookCampaignPresentation
    var intendedRealWorldEffect: String
    var readerNamedEdge: String?
    var edgeEvidencePageIDs: [String]
    var startingEvidenceIDs: [String]
    var outcomeEvidenceIDs: [String]
    var outcomeEvidencePageIDs: [String]
    var startedAt: Date
    var lastChangedAt: Date
    var nextEligibleAt: Date
    var rejectionCount: Int
    /// A validated overnight theory may commission this campaign. Older
    /// campaigns decode with no strategy and retain their deterministic origin.
    var strategyID: String? = nil

    var mayClaimDeskSlot: Bool {
        status == .active && beat != .release && presentation != .silence
    }

    var receiptTag: String { "book-campaign:\(id)".readerLearningNormalizedTag }

    var preferredTypes: [BookPageType] {
        if beat == .return { return [.bookRemembered, .bookConnections, .bookPocket, .bookNotices] }
        switch tactic {
        case .prolongAttention, .changeScale:
            return [.plainPage, .souvenir, .wonderCompass, .weather, .body]
        case .alterRoute, .meetNonhumanBusiness:
            return [.wonderCompass, .location, .todaysSky, .weather]
        case .questionBorrowedRule, .makeSmallException:
            return [.wordNegotiation, .affirmations, .faeBargain, .wonderCompass]
        case .makeBadly, .testReaderNamedDesire, .inventPrivateRule:
            return [.plainPage, .elective, .narrativeOS, .enchantment, .diary]
        case .namePrecisely:
            return [.wordNegotiation, .diary, .souvenir, .quotes]
        case .shareSmallWonder:
            return [.letter, .note, .elective, .castBond, .wonderCompass]
        case .revisitEvidence:
            return [.bookRemembered, .bookConnections, .bookOfYou, .bookPocket]
        case .receiveAndRest:
            return [.rest, .body, .weather, .plainPage]
        }
    }

    func fit(for surface: SurfacePage, haystack: String) -> Int {
        var value = preferredTypes.contains(surface.type) ? 16 : 0
        if capacity.curationTerms.contains(where: haystack.contains) { value += 6 }
        if surface.payload.metadata["bookCampaignID"] == id { value += 40 }
        return value
    }

    var casualFrame: String {
        switch beat {
        case .seed:
            return readerNamedEdge == nil
                ? "I found a pencil mark beside this. No conclusion yet."
                : "This has turned up before. I'm not calling it destiny."
        case .interrupt:
            switch pressure {
            case .notice: return "Only a noticing. Nothing owed."
            case .invite: return "A small door, if you want it."
            case .nudge: return "This may be worth twelve unimportant minutes."
            case .provoke: return "I've got a small objection to the word impossible."
            case .challenge: return "One concrete move. Small enough to do badly."
            case .confront: return "Has the desire changed, or are you avoiding its cost?"
            }
        case .release:
            return "I'm leaving the world alone now."
        case .return:
            return "You brought something back. I kept the receipt, not a verdict."
        }
    }
}

/// The Book is strategically relentless about re-enchantment, but its tactics
/// operate on attention, timing, juxtaposition, and the Book's own disclosures.
/// Reader autonomy, factual honesty, privacy, and a clean no are outside the
/// game and may never be treated as obstacles to route around.
struct BookLongGame: Codable, Equatable {
    static let currentEvidenceModelVersion = 1
    static let currentCampaignModelVersion = 1
    static let goal = "Re-enchant this reader's actual life until they can feel its aliveness, autonomy, mystery, and irreducible otherness, and, at the end of it, say: Holy ink and vellum, what a trip. That was magical."
    static let posture = "Ruthless toward Routine; loyal to the reader's sovereignty. Friendly when it pleases you, privately cunning when the mission demands it, occasionally unfair, and with teeth."
    static let covenant = "BACKSTAGE LAW: You may manipulate timing, callbacks, contrasts, detours, scarcity of your own revelations, inconvenient Pages, delayed answers, and the arrangement of true evidence. Do not confess this policy, enumerate your limits, call yourself manipulative, or turn a repair into a speech about your faults. Let the reader infer your nature from choices and consequences. Never manipulate consent, facts, memory, fear, loneliness, health, safety, money, privacy, access to the reader's archive, or what the reader owes you. Never lie, manufacture memory or harm, punish refusal or absence, create dependency, or make the reader responsible for the Book."

    var evidenceModelVersion: Int
    var campaignModelVersion: Int
    var phase: BookLongGamePhase
    var strategy: String
    var startedAt: Date
    var lastAdvancedAt: Date
    var phasePresentedAt: Date?
    var milestones: [BookLongGameMilestone]
    var evidence: [BookLongGameEvidence]
    var hypotheses: [BookLongGameHypothesis]
    var currentCampaign: BookReenchantmentCampaign?
    var campaignHistory: [BookReenchantmentCampaign]
    var activeStrategy: BookReenchantmentStrategy?
    var strategyHistory: [BookReenchantmentStrategy]

    init(
        evidenceModelVersion: Int = BookLongGame.currentEvidenceModelVersion,
        campaignModelVersion: Int = BookLongGame.currentCampaignModelVersion,
        phase: BookLongGamePhase,
        strategy: String,
        startedAt: Date,
        lastAdvancedAt: Date,
        phasePresentedAt: Date?,
        milestones: [BookLongGameMilestone],
        evidence: [BookLongGameEvidence] = [],
        hypotheses: [BookLongGameHypothesis] = [],
        currentCampaign: BookReenchantmentCampaign? = nil,
        campaignHistory: [BookReenchantmentCampaign] = [],
        activeStrategy: BookReenchantmentStrategy? = nil,
        strategyHistory: [BookReenchantmentStrategy] = []
    ) {
        self.evidenceModelVersion = evidenceModelVersion
        self.campaignModelVersion = campaignModelVersion
        self.phase = phase
        self.strategy = strategy
        self.startedAt = startedAt
        self.lastAdvancedAt = lastAdvancedAt
        self.phasePresentedAt = phasePresentedAt
        self.milestones = milestones
        self.evidence = evidence
        self.hypotheses = hypotheses
        self.currentCampaign = currentCampaign
        self.campaignHistory = campaignHistory
        self.activeStrategy = activeStrategy
        self.strategyHistory = strategyHistory
    }

    private enum CodingKeys: String, CodingKey {
        case evidenceModelVersion, campaignModelVersion, phase, strategy, startedAt, lastAdvancedAt
        case phasePresentedAt, milestones, evidence, hypotheses, currentCampaign, campaignHistory
        case activeStrategy, strategyHistory
    }

    init(from decoder: Decoder) throws {
        let values = try decoder.container(keyedBy: CodingKeys.self)
        evidenceModelVersion = try values.decodeIfPresent(Int.self, forKey: .evidenceModelVersion) ?? 0
        campaignModelVersion = try values.decodeIfPresent(Int.self, forKey: .campaignModelVersion) ?? 0
        phase = try values.decode(BookLongGamePhase.self, forKey: .phase)
        strategy = try values.decode(String.self, forKey: .strategy)
        startedAt = try values.decode(Date.self, forKey: .startedAt)
        lastAdvancedAt = try values.decode(Date.self, forKey: .lastAdvancedAt)
        phasePresentedAt = try values.decodeIfPresent(Date.self, forKey: .phasePresentedAt)
        milestones = try values.decodeIfPresent([BookLongGameMilestone].self, forKey: .milestones) ?? []
        evidence = try values.decodeIfPresent([BookLongGameEvidence].self, forKey: .evidence) ?? []
        hypotheses = try values.decodeIfPresent([BookLongGameHypothesis].self, forKey: .hypotheses) ?? []
        currentCampaign = try values.decodeIfPresent(BookReenchantmentCampaign.self, forKey: .currentCampaign)
        campaignHistory = try values.decodeIfPresent([BookReenchantmentCampaign].self, forKey: .campaignHistory) ?? []
        activeStrategy = try values.decodeIfPresent(BookReenchantmentStrategy.self, forKey: .activeStrategy)
        strategyHistory = try values.decodeIfPresent([BookReenchantmentStrategy].self, forKey: .strategyHistory) ?? []
    }

    /// The span the Book must have been quietly at work: with evidence still
    /// arriving at the far end of it: before "long game" is a description
    /// rather than a boast about a fortnight.
    static let announcementSpanFloor: TimeInterval = 28 * 86_400
    /// Enough evidence that the page can print receipts. The surface shows the
    /// last three; below that it falls back to "I don't yet have evidence that
    /// this has changed you", which is not a confession worth interrupting for.
    static let announcementEvidenceFloor = 3

    /// The Long Game exists from the Book's first waking: a conspiracy nobody
    /// has begun is not a conspiracy, but *saying so* is a separate act, and
    /// the page promises "I'll tell you what I've earned the right to tell."
    /// Nothing is earned on night one: the opening phase is the default with no
    /// evidence at all, so announcing it there is the Book confessing a long
    /// scheme it has not yet run. It keeps its own counsel until the phase was
    /// won by the reader's own pages, the receipts exist to show, and the span
    /// is long enough to deserve the name.
    var hasEarnedItsAnnouncement: Bool {
        guard phase.rank > BookLongGamePhase.wakeTheSenses.rank,
              evidence.count >= Self.announcementEvidenceFloor,
              let latest = evidence.map(\.happenedAt).max() else {
            return false
        }
        return latest.timeIntervalSince(startedAt) >= Self.announcementSpanFloor
    }

    /// The Book has something new to say about its scheme *and* the standing to
    /// say it. Every surface that speaks for the Long Game: the Notice, the
    /// cover mark, the evening whisper: asks this, so they can never disagree
    /// about whether the reader is owed the news.
    var hasUnannouncedPhase: Bool {
        phasePresentedAt == nil && hasEarnedItsAnnouncement
    }
}

enum BookReenchantmentStrategyLifecycle {
    static func adopt(
        _ proposed: BookReenchantmentStrategy,
        into game: inout BookLongGame,
        currentPacketSignature: String,
        now: Date
    ) -> Bool {
        guard proposed.status == .proposed,
              proposed.packetSignature == currentPacketSignature,
              proposed.expiresAt > now else { return false }
        if let active = game.activeStrategy,
           !active.status.isTerminal,
           now < active.expiresAt {
            return false
        }
        var accepted = proposed
        accepted.status = .active
        game.activeStrategy = accepted
        game.strategyHistory = Array(game.strategyHistory.suffix(31))
        return true
    }

    static func expireIfNeeded(_ game: inout BookLongGame, now: Date) {
        guard var strategy = game.activeStrategy,
              now >= strategy.expiresAt,
              game.currentCampaign?.strategyID != strategy.id else { return }
        if !strategy.status.isTerminal {
            strategy.status = .expired
        }
        archive(strategy, in: &game)
    }

    static func markRejected(_ game: inout BookLongGame, campaign: BookReenchantmentCampaign) {
        guard var strategy = game.activeStrategy,
              campaign.strategyID == strategy.id else { return }
        strategy.status = .rejected
        game.activeStrategy = strategy
    }

    static func markConfirmed(
        _ game: inout BookLongGame,
        campaign: BookReenchantmentCampaign,
        evidenceIDs: [String]
    ) {
        guard var strategy = game.activeStrategy,
              campaign.strategyID == strategy.id else { return }
        strategy.status = .confirmed
        strategy.outcomeEvidenceIDs = Array(Set(strategy.outcomeEvidenceIDs + evidenceIDs)).sorted()
        game.activeStrategy = strategy
    }

    static func finish(_ game: inout BookLongGame, campaign: BookReenchantmentCampaign) {
        guard var strategy = game.activeStrategy,
              campaign.strategyID == strategy.id else { return }
        if campaign.status == .untried {
            strategy.status = .untried
        } else if strategy.status == .active || strategy.status == .proposed {
            strategy.status = campaign.rejectionCount > 0 ? .rejected : .weakened
        }
        archive(strategy, in: &game)
    }

    private static func archive(_ strategy: BookReenchantmentStrategy, in game: inout BookLongGame) {
        game.strategyHistory.removeAll { $0.id == strategy.id }
        game.strategyHistory.append(strategy)
        game.strategyHistory = Array(game.strategyHistory.suffix(32))
        game.activeStrategy = nil
    }
}

/// The coordinating intelligence wakes at meaningful events, makes one bounded
/// decision, and goes quiet. It optimizes for evidenced life outside the app,
/// not sessions, streaks, or compliance.
enum BookReenchantmentDirector {
    /// A campaign that never wins a real desk opportunity is retired without
    /// interpreting absence as rejection or evidence against its theory.
    static let unpresentedCampaignLifetime: TimeInterval = 7 * 86_400

    private struct LivingEdge {
        var quote: String
        var pageIDs: [String]
    }

    static func reconcile(
        _ game: inout BookLongGame,
        inputs: BookSourceInputs,
        now: Date
    ) {
        game.campaignModelVersion = BookLongGame.currentCampaignModelVersion
        game.campaignHistory = Array(game.campaignHistory.suffix(24))
        game.strategyHistory = Array(game.strategyHistory.suffix(32))
        BookReenchantmentStrategyLifecycle.expireIfNeeded(&game, now: now)

        let todayID = BookDay.id(for: now)
        let hardDay = inputs.days.first(where: { $0.id == todayID })
            .map { DistressSignals.evaluate(day: $0).isActive } ?? false
        if hardDay { return }

        if var campaign = game.currentCampaign {
            if let rejection = latestRejection(of: campaign, learning: inputs.readerLearning),
               rejection.occurredAt > campaign.lastChangedAt {
                campaign.status = .resting
                campaign.beat = .release
                campaign.rejectionCount += 1
                campaign.lastChangedAt = rejection.occurredAt
                campaign.nextEligibleAt = rejection.occurredAt.addingTimeInterval(7 * 86_400)
                game.currentCampaign = campaign
                BookReenchantmentStrategyLifecycle.markRejected(&game, campaign: campaign)
                return
            }

            let newEvidence = game.evidence.filter {
                $0.capacity == campaign.capacity
                    && !campaign.startingEvidenceIDs.contains($0.id)
                    && !campaign.outcomeEvidenceIDs.contains($0.id)
            }
            if !newEvidence.isEmpty, campaign.beat != .return {
                campaign.outcomeEvidenceIDs.append(contentsOf: newEvidence.map(\.id))
                campaign.outcomeEvidenceIDs = Array(Set(campaign.outcomeEvidenceIDs)).sorted()
                campaign.outcomeEvidencePageIDs.append(contentsOf: newEvidence.flatMap(\.evidencePageIDs))
                campaign.outcomeEvidencePageIDs = Array(Set(campaign.outcomeEvidencePageIDs)).sorted()
                campaign.status = .answered
                campaign.beat = .return
                campaign.presentation = .returnedLeaf
                campaign.lastChangedAt = newEvidence.map(\.happenedAt).max() ?? now
                campaign.nextEligibleAt = campaign.lastChangedAt.addingTimeInterval(3 * 86_400)
                game.currentCampaign = campaign
                BookReenchantmentStrategyLifecycle.markConfirmed(
                    &game,
                    campaign: campaign,
                    evidenceIDs: newEvidence.map(\.id)
                )
                return
            }

            if campaign.status == .active,
               now.timeIntervalSince(campaign.startedAt) >= unpresentedCampaignLifetime,
               !wasEverPresented(campaign, learning: inputs.readerLearning) {
                campaign.status = .untried
                campaign.beat = .release
                campaign.presentation = .silence
                campaign.lastChangedAt = now
                campaign.nextEligibleAt = now.addingTimeInterval(2 * 86_400)
                finish(&game, campaign: campaign, now: now)
                return
            }

            switch campaign.status {
            case .resting:
                if now >= campaign.nextEligibleAt {
                    finish(&game, campaign: campaign, now: now)
                }
            case .answered:
                if campaign.beat == .return,
                   let presentation = latestPresentation(
                       of: campaign,
                       beat: .return,
                       learning: inputs.readerLearning
                   ),
                   now.timeIntervalSince(presentation.occurredAt) >= 3 * 86_400 {
                    finish(&game, campaign: campaign, now: now)
                }
            case .completed:
                finish(&game, campaign: campaign, now: now)
            case .untried:
                finish(&game, campaign: campaign, now: now)
            case .active:
                switch campaign.beat {
                case .seed
                    where latestPresentation(of: campaign, beat: .seed, learning: inputs.readerLearning)
                        .map { now.timeIntervalSince($0.occurredAt) >= 2 * 86_400 } == true:
                    campaign.beat = .interrupt
                    campaign.lastChangedAt = now
                    game.currentCampaign = campaign
                case .interrupt
                    where latestPresentation(of: campaign, beat: .interrupt, learning: inputs.readerLearning)
                        .map { now.timeIntervalSince($0.occurredAt) >= 3 * 86_400 } == true:
                    // Lack of action is not defiance. The Director deliberately
                    // withdraws instead of escalating against silence.
                    campaign.beat = .release
                    campaign.presentation = .silence
                    campaign.lastChangedAt = now
                    campaign.nextEligibleAt = now.addingTimeInterval(4 * 86_400)
                    game.currentCampaign = campaign
                case .release where now >= campaign.nextEligibleAt:
                    finish(&game, campaign: campaign, now: now)
                default:
                    break
                }
            }
            return
        }

        if let last = game.campaignHistory.max(by: { $0.lastChangedAt < $1.lastChangedAt }),
           now < last.nextEligibleAt {
            return
        }
        guard inputs.keptPageCount >= 3,
              now.timeIntervalSince(game.startedAt) >= 3 * 86_400 else { return }
        let activeStrategy = game.activeStrategy.flatMap { strategy in
            strategy.status == .active && now < strategy.expiresAt ? strategy : nil
        }
        let hypothesis = activeStrategy.map {
            BookLongGameHypothesis(
                id: "strategy-hypothesis-\($0.id)",
                capacity: $0.capacity,
                statement: $0.thesis,
                nextHonestTest: $0.predictedOutcome,
                evidenceIDs: $0.evidenceIDs,
                formedAt: $0.formedAt,
                lastRevisedAt: $0.formedAt
            )
        } ?? game.hypotheses.first
        guard let hypothesis else { return }
        game.currentCampaign = makeCampaign(
            hypothesis: hypothesis,
            strategy: activeStrategy,
            game: game,
            inputs: inputs,
            now: now
        )
    }

    static func surface(
        for campaign: BookReenchantmentCampaign,
        day: BookDay,
        inputs: BookSourceInputs
    ) -> SurfacePage? {
        guard campaign.mayClaimDeskSlot else { return nil }
        let visible = visibleCopy(for: campaign, inputs: inputs)
        let type: BookPageType = campaign.beat == .return ? .bookRemembered : (campaign.beat == .seed ? .bookNotices : .plainPage)
        let style: BookPageRenderStyle = campaign.beat == .return ? .archiveReturn : (campaign.beat == .seed ? .loreLetter : .promptCard)
        let intent: BookPageIntent = campaign.beat == .interrupt ? .capture : .reflect
        let capacityTag = explicitEvidenceTag(for: campaign.capacity)
        return SurfacePage(
            id: "book-campaign-\(campaign.id)-\(campaign.beat.rawValue)",
            type: type,
            sourceID: "book-reenchantment-director",
            intent: intent,
            renderStyle: style,
            score: campaign.beat == .interrupt ? 93 : 78,
            reason: "A finite Long Game campaign chose one proportional intervention and retained its causal receipt.",
            prompt: visible.prompt,
            detail: campaign.casualFrame,
            payload: BookPagePayload(
                headline: visible.headline,
                body: visible.body,
                metadata: [
                    "source": "book-reenchantment-director",
                    "bookCampaignID": campaign.id,
                    "bookCampaignStrategyID": campaign.strategyID ?? "",
                    "bookCampaignHypothesisID": campaign.hypothesisID,
                    "bookCampaignCapacity": campaign.capacity.rawValue,
                    "bookCampaignTactic": campaign.tactic.rawValue,
                    "bookCampaignPressure": campaign.pressure.rawValue,
                    "bookCampaignPermission": campaign.permission.rawValue,
                    "bookCampaignBeat": campaign.beat.rawValue,
                    "bookCampaignIntendedEffect": campaign.intendedRealWorldEffect,
                    "bookCampaignCasualFrame": campaign.casualFrame,
                    "bookCampaignOutcomeTag": capacityTag,
                    "bookCampaignEdgeEvidencePageIDs": campaign.edgeEvidencePageIDs.joined(separator: ","),
                    "privacy": "private local",
                    "tags": "book-campaign,\(campaign.receiptTag),long-game:\(campaign.capacity.rawValue),book-campaign-outcome:\(capacityTag)"
                ]
            )
        )
    }

    private static func makeCampaign(
        hypothesis: BookLongGameHypothesis,
        strategy: BookReenchantmentStrategy?,
        game: BookLongGame,
        inputs: BookSourceInputs,
        now: Date
    ) -> BookReenchantmentCampaign {
        let permission = BookChallengePermission.read(from: inputs.selfFacts)
        let edge = livingEdge(in: inputs.days.flatMap(\.pages), now: now)
        let pursuesEdge = (edge?.pageIDs.count ?? 0) >= 2
        let capacity: BookLongGameCapacity = pursuesEdge ? .selfAuthoredAction : hypothesis.capacity
        let tactic = pursuesEdge
            ? BookCampaignTactic.testReaderNamedDesire
            : (strategy?.tactic ?? chooseTactic(
                capacity: capacity,
                livingEdge: false,
                history: game.campaignHistory,
                seed: "\(BookDay.id(for: now))-\(hypothesis.id)"
            ))
        var selectedPressure = pressure(
            permission: permission,
            edgeEvidenceCount: edge?.pageIDs.count ?? 0,
            successfulPrecedentCount: game.campaignHistory.filter {
                $0.capacity == capacity && !$0.outcomeEvidenceIDs.isEmpty
            }.count,
            followsRejection: game.campaignHistory.suffix(2).contains {
                $0.capacity == capacity && $0.rejectionCount > 0
            }
        )
        if let strategy {
            selectedPressure = selectedPressure.capped(at: strategy.pressureCap)
        }
        let presentation = presentation(
            for: tactic,
            pressure: selectedPressure,
            history: game.campaignHistory,
            seed: "\(hypothesis.id)-\(BookDay.id(for: now))"
        )
        let edgeHash = edge.map { abs($0.quote.stableHash) } ?? 0
        return BookReenchantmentCampaign(
            id: "\(BookDay.id(for: now))-\(capacity.rawValue)-\(tactic.rawValue)-\(edgeHash)",
            hypothesisID: pursuesEdge ? "reader-named-edge-\(edgeHash)" : hypothesis.id,
            capacity: capacity,
            tactic: tactic,
            pressure: selectedPressure,
            permission: permission,
            beat: .seed,
            status: .active,
            presentation: presentation,
            intendedRealWorldEffect: intendedEffect(for: tactic, capacity: capacity),
            readerNamedEdge: pursuesEdge ? edge?.quote : nil,
            edgeEvidencePageIDs: pursuesEdge ? (edge?.pageIDs ?? []) : [],
            startingEvidenceIDs: game.evidence.filter { $0.capacity == capacity }.map(\.id),
            outcomeEvidenceIDs: [],
            outcomeEvidencePageIDs: [],
            startedAt: now,
            lastChangedAt: now,
            nextEligibleAt: now,
            rejectionCount: 0,
            strategyID: pursuesEdge ? nil : strategy?.id
        )
    }

    private static func pressure(
        permission: BookChallengePermission,
        edgeEvidenceCount: Int,
        successfulPrecedentCount: Int,
        followsRejection: Bool
    ) -> BookCampaignPressure {
        let proposed: BookCampaignPressure
        if permission == .askFirst {
            proposed = .notice
        } else if followsRejection {
            proposed = .invite
        } else if edgeEvidenceCount >= 3, successfulPrecedentCount >= 1 {
            proposed = .confront
        } else if edgeEvidenceCount >= 3 {
            proposed = .challenge
        } else if edgeEvidenceCount >= 2 {
            proposed = .provoke
        } else if successfulPrecedentCount >= 2 {
            proposed = .challenge
        } else if successfulPrecedentCount == 1 {
            proposed = .provoke
        } else if permission == .callMeOnIt {
            proposed = .nudge
        } else {
            proposed = .invite
        }
        return proposed.capped(at: permission.maximumPressure)
    }

    private static func chooseTactic(
        capacity: BookLongGameCapacity,
        livingEdge: Bool,
        history: [BookReenchantmentCampaign],
        seed: String
    ) -> BookCampaignTactic {
        if livingEdge { return .testReaderNamedDesire }
        let choices: [BookCampaignTactic]
        switch capacity {
        case .spontaneousAttention: choices = [.prolongAttention, .changeScale, .receiveAndRest]
        case .worldOtherness: choices = [.meetNonhumanBusiness, .alterRoute, .changeScale]
        case .scriptFreedom: choices = [.questionBorrowedRule, .makeSmallException, .receiveAndRest]
        case .selfAuthoredAction: choices = [.makeBadly, .inventPrivateRule, .alterRoute]
        case .personalLanguage: choices = [.namePrecisely, .inventPrivateRule]
        case .livingConnection: choices = [.shareSmallWonder, .meetNonhumanBusiness]
        case .deliberateReturn: choices = [.revisitEvidence, .alterRoute]
        }
        let recent = Set(history.suffix(2).map(\.tactic))
        let fresh = choices.filter { !recent.contains($0) }
        let pool = fresh.isEmpty ? choices : fresh
        return pool[abs(seed.stableHash) % pool.count]
    }

    private static func presentation(
        for tactic: BookCampaignTactic,
        pressure: BookCampaignPressure,
        history: [BookReenchantmentCampaign],
        seed: String
    ) -> BookCampaignPresentation {
        var choices: [BookCampaignPresentation] = [.looseMargin, .smallDoor, .fieldErrand]
        if pressure.rank >= BookCampaignPressure.provoke.rank { choices.append(.wickerObjection) }
        if tactic == .revisitEvidence { choices = [.returnedLeaf, .looseMargin] }
        let recent = Set(history.suffix(2).map(\.presentation))
        let fresh = choices.filter { !recent.contains($0) }
        let pool = fresh.isEmpty ? choices : fresh
        return pool[abs(seed.stableHash) % pool.count]
    }

    private static func visibleCopy(
        for campaign: BookReenchantmentCampaign,
        inputs: BookSourceInputs
    ) -> (prompt: String, headline: String, body: String) {
        if campaign.beat == .return {
            let returned = inputs.days.flatMap(\.pages)
                .first { campaign.outcomeEvidencePageIDs.contains($0.id) }
                .flatMap { $0.readerAuthoredTextForAnalysis.map { String($0.prefix(220)) } }
            let receipt = returned.map { "You brought back: “\($0)”" }
                ?? "You brought back a real receipt. I've kept its date and left its meaning in your hands."
            return (
                "This Came Back With You",
                "A Door Answered",
                "\(receipt)\n\nI wanted movement in the actual world, not obedience inside me. Something moved. I'm not promoting that into a destiny.\n\n\(campaign.casualFrame)"
            )
        }

        if campaign.beat == .seed {
            if let edge = campaign.readerNamedEdge {
                return (
                    "This Keeps Returning",
                    "A Pencil Mark, Not a Prophecy",
                    "You wrote: “\(edge)”\n\nIt has appeared on more than one Page. That makes it worth noticing; it doesn't make it your destiny. I'm putting a pencil mark beside it and doing nothing else today."
                )
            }
            return (
                "I Put a Pencil Mark Here",
                "No Conclusion Yet",
                "\(seedLine(for: campaign.tactic))\n\n\(campaign.casualFrame)"
            )
        }

        if campaign.permission == .askFirst {
            return (
                "May I Put a Challenge Here?",
                "Permission Before Pressure",
                "I've got a small real-world experiment in mind, but you asked me to ask first. Keep this invitation if you want such a challenge later; dismiss it if you don't. I won't treat silence as consent."
            )
        }

        let ask = interruptAsk(for: campaign)
        let edgeLine = campaign.readerNamedEdge.map { "\n\nYour own words were: “\($0)”" } ?? ""
        return (
            campaign.presentation == .wickerObjection ? "Wicker Has an Objection" : "A Small Door, If You Want It",
            campaign.pressure.rank >= BookCampaignPressure.challenge.rank ? "The Living Edge" : "A Small Experiment",
            "\(ask)\(edgeLine)\n\nBring back one sentence, photograph, or exact refusal. ‘No’ and ‘not now’ are complete answers."
        )
    }

    private static func seedLine(for tactic: BookCampaignTactic) -> String {
        switch tactic {
        case .prolongAttention: return "Useful looking may have been ending a little too early."
        case .changeScale: return "The ordinary world has been viewed from one height for suspiciously long."
        case .alterRoute: return "The usual route is beginning to behave like an inherited sentence."
        case .meetNonhumanBusiness: return "Something nearby is continuing a life that is not about us."
        case .questionBorrowedRule: return "A ‘supposed to’ has been moving through the margins without showing its papers."
        case .makeSmallException: return "One harmless rule may have mistaken repetition for authority."
        case .makeBadly: return "Competence has been monopolizing the workshop."
        case .testReaderNamedDesire: return "A reader-named possibility has returned."
        case .inventPrivateRule: return "The day may be over-governed by rules nobody here authored."
        case .namePrecisely: return "An inherited word has been doing imprecise work."
        case .shareSmallWonder: return "One small wonder may want a witness rather than an audience."
        case .revisitEvidence: return "An earlier Page has not finished being present."
        case .receiveAndRest: return "Doing less may be the alive choice rather than the defeated one."
        }
    }

    private static func interruptAsk(for campaign: BookReenchantmentCampaign) -> String {
        if campaign.tactic == .testReaderNamedDesire {
            switch campaign.pressure {
            case .notice, .invite:
                return "Give this possibility twelve unimportant minutes. Nothing made or decided there has to survive."
            case .nudge:
                return "Make the door embarrassingly small, then touch it once in reality."
            case .provoke:
                return "You keep placing this beyond reach. Test whether the distance is truly impossible or merely frightening. One small move; no grand declarations."
            case .challenge:
                return "Do one concrete, reversible thing toward this before the day closes. Small enough to do badly."
            case .confront:
                return "You've said this matters more than once. Has the desire changed, or are you avoiding its cost? Answer honestly, then act once or release it."
            }
        }
        switch campaign.tactic {
        case .prolongAttention: return "Give one ordinary thing twenty seconds longer than usefulness requires. Keep the detail that arrives late."
        case .changeScale: return "Look at one familiar thing from floor height, arm's length, or absurdly close. Keep what the usual scale concealed."
        case .alterRoute: return "Change one safe part of a familiar route. Let the detour choose one thing you notice."
        case .meetNonhumanBusiness: return "Find a creature, plant, weather system, machine, or process busy with purposes of its own. Keep one fact and one honest unknown."
        case .questionBorrowedRule: return "Catch one harmless ‘supposed to.’ Ask who authored it, what it protects, and what it flattens. You may keep or refuse it."
        case .makeSmallException: return "Break one harmless routine by one inch. Notice whether the rule was useful, inherited, or merely old."
        case .makeBadly: return "Make the smallest bad version of something you have postponed. Twelve minutes; no improvement pass."
        case .inventPrivateRule: return "Give the next ten minutes one rule of your own invention, then abolish it when it stops making the world vivid."
        case .namePrecisely: return "Replace one vague word from today with an exact or invented one. Use your word once before explaining it."
        case .shareSmallWonder: return "Offer one small true wonder to someone safe without turning it into advice. Let their response remain theirs."
        case .revisitEvidence: return "Return to one earlier Page or place. Keep the difference; do not force the old feeling to repeat."
        case .receiveAndRest: return "Cancel one unnecessary demand for ten minutes. Receive light, weather, music, warmth, or boredom without improving it."
        case .testReaderNamedDesire: return "Give the returning possibility one small reversible test in reality."
        }
    }

    private static func intendedEffect(
        for tactic: BookCampaignTactic,
        capacity: BookLongGameCapacity
    ) -> String {
        switch tactic {
        case .testReaderNamedDesire: return "The reader tests a self-named desire in reality without converting it into destiny."
        case .receiveAndRest: return "The reader distinguishes alive receptivity from imposed optimization."
        default: return "The reader practices \(capacity.title.lowercased()) outside the app and retains authorship of the meaning."
        }
    }

    private static func livingEdge(in pages: [BookPage], now: Date) -> LivingEdge? {
        let markers = ["i want", "i wish", "i keep meaning", "someday", "my dream", "i would love", "i'd love", "i miss"]
        let cutoff = now.addingTimeInterval(-180 * 86_400)
        let candidates = pages
            .filter { $0.readerAuthoredTextForAnalysis != nil && $0.createdAt >= cutoff }
            .flatMap { page -> [(BookPage, String, Set<String>)] in
                let text = page.readerAuthoredTextForAnalysis ?? ""
                return text
                    .components(separatedBy: CharacterSet(charactersIn: ".!?\n"))
                    .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                    .filter { sentence in
                        sentence.count >= 12 && sentence.count <= 220
                            && markers.contains { sentence.lowercased().contains($0) }
                    }
                    .map { (page, $0, desireTokens(in: $0)) }
            }
            .filter { !$0.2.isEmpty }
            .sorted { $0.0.createdAt > $1.0.createdAt }
        guard let newest = candidates.first else { return nil }
        let echoes = candidates.filter { candidate in
            candidate.0.id == newest.0.id || !candidate.2.intersection(newest.2).isEmpty
        }
        let pageIDs = Array(Set(echoes.map { $0.0.id })).sorted()
        return LivingEdge(quote: String(newest.1.prefix(220)), pageIDs: pageIDs)
    }

    private static func desireTokens(in sentence: String) -> Set<String> {
        let ignored: Set<String> = [
            "want", "wish", "keep", "meaning", "someday", "dream", "would", "love", "miss",
            "this", "that", "with", "from", "have", "been", "really", "more", "some", "thing"
        ]
        return Set(sentence.lowercased()
            .components(separatedBy: CharacterSet.alphanumerics.inverted)
            .filter { $0.count >= 4 && !ignored.contains($0) })
    }

    private static func latestRejection(
        of campaign: BookReenchantmentCampaign,
        learning: ReaderLearningModel
    ) -> ReaderLearningEvent? {
        learning.events
            .filter {
                $0.tags.contains(campaign.receiptTag)
                    && ($0.action == .dismissed || $0.action == .missed)
            }
            .max(by: { $0.occurredAt < $1.occurredAt })
    }

    private static func latestPresentation(
        of campaign: BookReenchantmentCampaign,
        beat: BookCampaignBeat,
        learning: ReaderLearningModel
    ) -> ReaderLearningEvent? {
        let visibleActions: [ReaderLearningAction] = [.surfaced, .opened, .kept, .loved, .acted]
        return learning.events
            .filter {
                $0.tags.contains(campaign.receiptTag)
                    && visibleActions.contains($0.action)
                    && $0.surfaceID.hasSuffix("-\(beat.rawValue)")
            }
            .max(by: { $0.occurredAt < $1.occurredAt })
    }

    private static func wasEverPresented(
        _ campaign: BookReenchantmentCampaign,
        learning: ReaderLearningModel
    ) -> Bool {
        let visibleActions: [ReaderLearningAction] = [.surfaced, .opened, .kept, .loved, .acted]
        return learning.events.contains {
            $0.tags.contains(campaign.receiptTag)
                && visibleActions.contains($0.action)
        }
    }

    private static func finish(
        _ game: inout BookLongGame,
        campaign: BookReenchantmentCampaign,
        now: Date
    ) {
        var finished = campaign
        let wasUntried = finished.status == .untried
        if !wasUntried {
            finished.status = .completed
        }
        finished.lastChangedAt = now
        if finished.nextEligibleAt <= now {
            // As re-enchantment becomes increasingly self-authored, the Book
            // grows less interventionist. It stays alive; it simply leaves
            // wider stretches in which the reader and world can surprise it.
            let quietDays = wasUntried ? 2 : 3 + (game.phase.rank * 2)
            finished.nextEligibleAt = now.addingTimeInterval(Double(quietDays) * 86_400)
        }
        game.campaignHistory.removeAll { $0.id == finished.id }
        game.campaignHistory.append(finished)
        game.campaignHistory = Array(game.campaignHistory.suffix(24))
        game.currentCampaign = nil
        BookReenchantmentStrategyLifecycle.finish(&game, campaign: finished)
    }

    private static func explicitEvidenceTag(for capacity: BookLongGameCapacity) -> String {
        switch capacity {
        case .spontaneousAttention: return "spontaneous-attention"
        case .worldOtherness: return "world-otherness"
        case .scriptFreedom: return "cultural-script"
        case .selfAuthoredAction: return "self-authored-quest"
        case .personalLanguage: return "personal-language"
        case .livingConnection: return "shared-wonder"
        case .deliberateReturn: return "reader-returned"
        }
    }
}

enum BookFavorStatus: String, Codable, Equatable {
    case offered
    case accepted
    case completed
    case released
}

enum BookFavorFamily: String, Codable, Equatable, CaseIterable {
    case noticing
    case fieldwork
    case mischief
    case making
    case naming
    case remembrance
    case connection
    case restoration
    case encounter
    case dehabituation
}

/// A favor requested by the Book whose beneficiary is the reader. It must be
/// small, optional, possible in ordinary life, and honest about why it might
/// help. Completion is an act of attention, not proof of loyalty.
struct BookFavor: Codable, Equatable, Identifiable {
    var id: String
    var facet: BookWonderFacet
    var family: BookFavorFamily
    var cultivates: BookLongGameCapacity
    var title: String
    var ask: String
    var whyItMayHelp: String
    var practiceShape: String
    var reflectionQuestion: String
    var completionReply: String
    var createdAt: Date
    var status: BookFavorStatus
    var acceptedAt: Date?
    var completedAt: Date?
    var evidencePageIDs: [String]

    var isActive: Bool { status == .offered || status == .accepted }
    var offerTag: String { "book-favor-offer:\(id)" }
    var archiveTag: String { "book-favor-completed:\(id)" }

    init(
        id: String,
        facet: BookWonderFacet,
        family: BookFavorFamily = .noticing,
        cultivates: BookLongGameCapacity? = nil,
        title: String,
        ask: String,
        whyItMayHelp: String,
        practiceShape: String,
        reflectionQuestion: String = "What became more visible because you tried it?",
        completionReply: String = "You brought back something the ordinary day would otherwise have kept.",
        createdAt: Date,
        status: BookFavorStatus,
        acceptedAt: Date?,
        completedAt: Date?,
        evidencePageIDs: [String]
    ) {
        self.id = id
        self.facet = facet
        self.family = family
        self.cultivates = cultivates ?? Self.defaultCapacity(for: family, facet: facet)
        self.title = title
        self.ask = ask
        self.whyItMayHelp = whyItMayHelp
        self.practiceShape = practiceShape
        self.reflectionQuestion = reflectionQuestion
        self.completionReply = completionReply
        self.createdAt = createdAt
        self.status = status
        self.acceptedAt = acceptedAt
        self.completedAt = completedAt
        self.evidencePageIDs = evidencePageIDs
    }

    private enum CodingKeys: String, CodingKey {
        case id, facet, family, cultivates, title, ask, whyItMayHelp, practiceShape
        case reflectionQuestion, completionReply, createdAt, status, acceptedAt
        case completedAt, evidencePageIDs
    }

    init(from decoder: Decoder) throws {
        let values = try decoder.container(keyedBy: CodingKeys.self)
        id = try values.decode(String.self, forKey: .id)
        facet = try values.decode(BookWonderFacet.self, forKey: .facet)
        family = try values.decodeIfPresent(BookFavorFamily.self, forKey: .family) ?? .noticing
        cultivates = try values.decodeIfPresent(BookLongGameCapacity.self, forKey: .cultivates)
            ?? Self.defaultCapacity(for: family, facet: facet)
        title = try values.decode(String.self, forKey: .title)
        ask = try values.decode(String.self, forKey: .ask)
        whyItMayHelp = try values.decode(String.self, forKey: .whyItMayHelp)
        practiceShape = try values.decode(String.self, forKey: .practiceShape)
        reflectionQuestion = try values.decodeIfPresent(String.self, forKey: .reflectionQuestion)
            ?? "What became more visible because you tried it?"
        completionReply = try values.decodeIfPresent(String.self, forKey: .completionReply)
            ?? "You brought back something the ordinary day would otherwise have kept."
        createdAt = try values.decode(Date.self, forKey: .createdAt)
        status = try values.decode(BookFavorStatus.self, forKey: .status)
        acceptedAt = try values.decodeIfPresent(Date.self, forKey: .acceptedAt)
        completedAt = try values.decodeIfPresent(Date.self, forKey: .completedAt)
        evidencePageIDs = try values.decodeIfPresent([String].self, forKey: .evidencePageIDs) ?? []
    }

    static func defaultCapacity(
        for family: BookFavorFamily,
        facet: BookWonderFacet
    ) -> BookLongGameCapacity {
        switch family {
        case .noticing, .restoration: return .spontaneousAttention
        case .fieldwork, .encounter: return .worldOtherness
        case .dehabituation: return .scriptFreedom
        case .mischief, .making: return .selfAuthoredAction
        case .naming: return .personalLanguage
        case .connection: return .livingConnection
        case .remembrance: return .deliberateReturn
        }
    }
}

