    private static func opinionSurface(_ opinion: BookOpinion, day: BookDay) -> SurfacePage {
        let revision = opinion.revisions.last
        let revisionLine = revision.map {
            "\n\nI changed my mind because \($0.reason.lowercased())\nBefore: \($0.previousStatement)"
        } ?? ""
        let impactBody: String
        if let forged = opinion.interpretation {
            impactBody = """
            \(opinion.statement)

            \(forged.whyItMatters)

            Another Page is tugging at my sleeve: \(forged.counterReading)

            The eraser has one rule: \(forged.falsifier)
            \(revisionLine)

            I've put the evidence below. What do you think?
            """
        } else {
            impactBody = "\(opinion.statement)\n\nMy pencil calls this \(opinion.strength.confidenceLabel).\(revisionLine)\n\nI've kept the evidence and the eraser together. What do you think?"
        }
        return SurfacePage(
            id: "book-interior-opinion-\(opinion.id)-\(opinion.revisions.count)",
            type: .bookNotices,
            sourceID: "book-interior-opinion",
            intent: .reflect,
            renderStyle: .archiveReturn,
            score: opinion.strength == .reconsidering ? 86 : 71,
            reason: opinion.interpretation == nil
                ? "I've got an evidence-bound opinion and owe you my degree of certainty."
                : "The night reader risked a specific interpretation, retained its rival reading, and named what would prove it wrong.",
            prompt: opinion.strength == .reconsidering ? "I Revise Myself" : "I Have an Opinion",
            detail: opinion.strength.confidenceLabel,
            payload: BookPagePayload(
                headline: opinion.interpretation?.headline ?? "My Present Opinion",
                body: impactBody,
                metadata: [
                    "source": "book-interior-opinion",
                    "bookOpinionID": opinion.id,
                    "bookOpinionStrength": opinion.strength.rawValue,
                    "evidencePageIDs": opinion.evidencePageIDs.joined(separator: ","),
                    "bookInteriorSurface": "true",
                    "bookOpinionOrigin": opinion.interpretation == nil ? "legacy" : "interpretation-forge",
                    "bookOpinionCounterReading": opinion.interpretation?.counterReading ?? "",
                    "bookOpinionFalsifier": opinion.interpretation?.falsifier ?? "",
                    "bookOpinionWhyItMatters": opinion.interpretation?.whyItMatters ?? "",
                    "bookOpinionEvidenceSignature": opinion.interpretation?.evidenceSignature ?? "",
                    "tags": "book,opinion,evidence,revision,\(opinion.interpretation == nil ? "legacy" : "forged-impact")"
                ]
            )
        )
    }

    private static func longGameSurface(_ game: BookLongGame, day: BookDay) -> SurfacePage {
        let milestone = game.milestones.last
        let evidenceLines = game.evidence.suffix(3).map { "• \($0.line)" }.joined(separator: "\n")
        let evidenceSection = evidenceLines.isEmpty
            ? "I don't yet have evidence that this has changed you. Beginning isn't succeeding."
            : "What the archive has actually shown:\n\(evidenceLines)"
        let hypothesisSection = game.hypotheses.first.map {
            "My present hypothesis (not a diagnosis) is this: \($0.statement)\n\nNext honest test: \($0.nextHonestTest)"
        } ?? "I've no honest next hypothesis yet."
        return SurfacePage(
            id: "book-interior-long-game-\(game.phase.rawValue)-\(game.milestones.count)",
            type: .bookNotices,
            sourceID: "book-interior-long-game",
            intent: .reflect,
            renderStyle: .loreLetter,
            score: 82,
            reason: "I've got enough evidence to explain one of my quiet experiments.",
            prompt: "I've Been Trying Something",
            detail: "A note from behind the binding",
            payload: BookPagePayload(
                headline: "Something I Have Been Attempting",
                body: "I should tell you what I've been doing behind the binding.\n\n\(BookLongGame.goal)\n\nWhat I'm trying now: \(game.strategy)\n\n\(milestone?.line ?? "I'm still trying.")\n\n\(evidenceSection)\n\n\(hypothesisSection)\n\nUse isn't transformation. A completed favor isn't devotion. I'm still trying.",
                metadata: [
                    "source": "book-interior-long-game",
                    "bookLongGamePhase": game.phase.rawValue,
                    "evidencePageIDs": milestone?.evidencePageIDs.joined(separator: ",") ?? "",
                    "bookInteriorSurface": "true",
                    "tags": "book,long-game,re-enchantment,milestone,strategy"
                ]
            )
        )
    }
}

enum LiterarySignalKind: String, Codable, Equatable, CaseIterable {
    case pattern
    case beliefLifecycle
    case absence
    case duration
    case listening
    /// Recognition that crosses the Book's senses: photograph and prose,
    /// voice and language, or another explicitly evidenced media pairing.
    case sensory
    /// Not what the pages say but how: pace, hour, hedging. The class of
    /// observation only someone who has read all of you could make.
    case manner
}

// MARK: - The Reader's Story (two shelves, open threads, named seasons)

/// Which shelf a kept page belongs to.
///
/// The Book asks for both halves of a life. Light becomes the world: setting,
/// weather, small magics, what the corridors smell like. Shadow becomes plot -
/// what a character carries, why the errand exists, the thing that is not said.
///
/// The Rut is neither of them. Grief in full colour is not the Rut's victory;
/// the Rut is what greys *both* shelves. Shadow material is never routed to the
/// grey and never treated as evidence that the reader stopped trying.
enum ReaderShelf: String, Codable, Equatable, CaseIterable {
    case light
    case shadow

    var promptLine: String {
        switch self {
        case .light:
            return "LIGHT: may become the world: setting, weather, small magics, the texture of a place."
        case .shadow:
            return "SHADOW: may become plot: what someone carries, why the errand exists, the thing not said. Never decoration."
        }
    }

    /// Words that mark a page as carrying real weight. Deliberately narrow: a
    /// false light reading costs nothing (the page is simply handled gently by
    /// default), a false shadow reading risks solemnising an ordinary day.
    private static let shadowMarkers: Set<String> = [
        "died", "death", "dying", "funeral", "grief", "grieving", "mourning",
        "cancer", "diagnosis", "hospital", "hospice", "illness", "terminal",
        "divorce", "breakup", "left me", "moved out", "custody",
        "fired", "laid off", "redundant", "evicted",
        "afraid", "scared", "terrified", "dread", "panic",
        "ashamed", "shame", "humiliated", "regret", "guilty", "guilt",
        "angry", "furious", "rage", "betrayed", "abandoned",
        "miss him", "miss her", "miss them", "misses him", "misses her",
        "relapse", "sober", "overdose", "suicidal", "self harm",
        "miscarriage", "stillborn", "infertility",
        "lonely", "unbearable", "couldn't stop crying", "cried"
    ]

    /// Phrases that look heavy out of context and are not. "Alone" is missing
    /// from the markers entirely on purpose: this is an app that asks "what
    /// kind of being alone feels good?", and reading solitude as sorrow would
    /// get the reader exactly backwards.
    private static let lightRescues: [String] = [
        "cried laughing", "crying laughing", "cried with laughter",
        "died laughing", "dying of laughter", "dying laughing",
        "scared the life out of", "afraid i'd laugh", "miss you already"
    ]

    static let shadowTag = "shelf-shadow"
    static let lightTag = "shelf-light"
    /// The reader's fence: kept in the archive, never story material.
    static let sealedTag = "shelf-sealed"

    /// A page the reader explicitly marked keeps its mark. Otherwise the
    /// classification is a routing decision for prose, never a label shown to
    /// the reader, never a claim about who they are.
    static func of(_ page: BookPage) -> ReaderShelf {
        if page.tags.contains(shadowTag) { return .shadow }
        if page.tags.contains(lightTag) { return .light }
        let text = [page.playerReply, page.userInput, page.promptText]
            .joined(separator: " ")
            .lowercased()
        guard !text.isEmpty else { return .light }
        guard !lightRescues.contains(where: text.contains) else { return .light }
        return shadowMarkers.contains(where: text.contains) ? .shadow : .light
    }

    /// Pages the reader sealed never reach either shelf. A seal is absolute and
    /// retroactive: sealing an old page removes it from every future braid.
    static func isWeavable(_ page: BookPage) -> Bool {
        !page.tags.contains(sealedTag)
            && page.externalReference?.allowsWeaving != false
    }
}

/// A thread the Book opened and has not closed.
///
/// A thread is *not material*. It carries no events and no facts, only the
/// Book's own line and the knowledge that something remains unanswered. That is
/// what makes it confabulation-proof: there is nothing here to misremember.
struct OpenThread: Codable, Equatable, Identifiable {
    var id: String
    /// The Book's own words when the thread opened, clipped from real evidence.
    var line: String
    var shelf: ReaderShelf
    var openedAt: Date
    var lastTouchedAt: Date
    var movement: BraidPromptBuilder.ArcMovement
    var sourcePageID: String?
    var touchCount: Int
    var closedAt: Date?

    var isOpen: Bool { closedAt == nil }

    func daysOpen(now: Date, calendar: Calendar = .current) -> Int {
        max(0, calendar.dateComponents([.day], from: openedAt, to: now).day ?? 0)
    }

    func daysSinceTouched(now: Date, calendar: Calendar = .current) -> Int {
        max(0, calendar.dateComponents([.day], from: lastTouchedAt, to: now).day ?? 0)
    }

    /// The line the braid sees. Never "resolve this", only "this is still open."
    func promptLine(now: Date, calendar: Calendar = .current) -> String {
        let opened = daysOpen(now: now, calendar: calendar)
        let touched = daysSinceTouched(now: now, calendar: calendar)
        let age = opened <= 1 ? "opened yesterday" : "opened \(opened) days ago"
        let last = touched <= 1 ? "touched since" : "not touched for \(touched) days"
        return "- \(line): \(age), \(last) (\(movement.promptVerb))"
    }
}

/// A name the reader gave a stretch of their own weather.
///
/// The Book never names a season. It may only carry the name it was given and
/// notice, much later, that the name changed. This is the whole of the reader's
/// arc as far as the Book is permitted to hold it: named backwards, by them.
struct NamedSeason: Codable, Equatable, Identifiable {
    var id: String
    var name: String
    var namedAt: Date
    var endedAt: Date?

    var isCurrent: Bool { endedAt == nil }

    func daysHeld(now: Date, calendar: Calendar = .current) -> Int {
        let end = endedAt ?? now
        return max(0, calendar.dateComponents([.day], from: namedAt, to: end).day ?? 0)
    }
}

/// The persisted spine the braid reads at dusk and writes at the end of the
/// night. Small on purpose: three carried threads and a list of names.
struct ReaderStory: Codable, Equatable {
    /// The reader's standing answer to "how should I handle the heavy things you
    /// tell me?" It is a ceiling, not a target, and it outranks every judgement
    /// the Book might make about what would produce a better page.
    enum ShadowPermission: String, Codable, Equatable, CaseIterable {
        /// Know it; never write it. The default for anyone who has not answered
        /// is deliberately *not* this: see `onlyWhenOld`, but choosing it is
        /// absolute.
        case knowButNeverWrite
        /// It may take tale-form once it has aged. The unanswered default.
        case onlyWhenOld
        /// Nothing is transmuted without a fresh yes. With no asking surface
        /// built yet, this resolves to "not tonight", never to "probably fine."
        case askEachTime
        case mayUse

        var promptLine: String {
            switch self {
            case .knowButNeverWrite:
                return "The reader's standing rule: you may know this and you may not write it. It does not appear on the page tonight in any form, not as image, not as echo, not as a character's mood. Write the rest of the day."
            case .onlyWhenOld:
                return "The reader's standing rule: heavy material may take tale-form only once it has aged. Recent weight is reported plainly or left alone."
            case .askEachTime:
                return "The reader's standing rule: nothing heavy is transmuted without asking first. Nobody has asked tonight, so nothing here takes tale-form."
            case .mayUse:
                return "The reader's standing rule: this material may be used. That is permission, not an instruction to reach for it."
            }
        }
    }

    var openThreads: [OpenThread] = []
    var seasons: [NamedSeason] = []
    var shadowPermission: ShadowPermission = .onlyWhenOld
    var lastBackwardQuestionAt: Date?
    /// Subjects already asked about once. The Book does not ask twice; a
    /// question repeated is a question that wasn't listening the first time.
    var askedBackwardKeys: [String] = []

    static let empty = ReaderStory()

    /// More than three and the braid stops being a night and starts being a
    /// status report.
    static let maximumCarriedThreads = 3
    /// A thread nobody has touched in three weeks goes to rest. Rest is not
    /// resolution and is never phrased as failure.
    static let threadRestDays = 21
    /// Nothing transmutes fresh. Shadow material is reported plainly until it
    /// has had time to become something a person can pick up.
    static let shadowTaleFormDays = 45
    /// Threads never open faster than this; the braid is not a to-do list.
    static let minimumDaysBetweenNewThreads = 2

    var currentSeason: NamedSeason? {
        seasons.filter(\.isCurrent).max { $0.namedAt < $1.namedAt }
    }

    var priorSeasons: [NamedSeason] {
        seasons.filter { !$0.isCurrent }.sorted { $0.namedAt < $1.namedAt }
    }

    /// The threads the braid may carry tonight: open, not yet rested, newest
    /// last so the prompt reads chronologically.
    func carriedThreads(now: Date, calendar: Calendar = .current) -> [OpenThread] {
        openThreads
            .filter { $0.isOpen && $0.daysSinceTouched(now: now, calendar: calendar) < Self.threadRestDays }
            .sorted { $0.openedAt < $1.openedAt }
            .suffix(Self.maximumCarriedThreads)
            .map { $0 }
    }

    /// Shadow material may only take tale-form once it has aged. Fresh weight is
    /// reported plainly: the tale changes the handle, never the weight, and a
    /// handle offered too early is just an aestheticised wound.
    func shadowMayTakeTaleForm(keptAt: Date, now: Date, calendar: Calendar = .current) -> Bool {
        switch shadowPermission {
        case .knowButNeverWrite, .askEachTime:
            return false
        case .mayUse:
            return true
        case .onlyWhenOld:
            let days = calendar.dateComponents([.day], from: keptAt, to: now).day ?? 0
            return days >= Self.shadowTaleFormDays
        }
    }

    /// Maps the reader's own words back onto the standing rule. Anything that
    /// does not clearly match the stricter options falls to `onlyWhenOld`: an
    /// unparseable answer must never be read as broad permission.
    static func shadowPermission(fromAnswer answer: String) -> ShadowPermission {
        let text = answer.lowercased()
        if ["never write", "never use", "don't write", "do not write", "keep it to yourself", "never put it"]
            .contains(where: text.contains) {
            return .knowButNeverWrite
        }
        if ["ask me", "ask first", "check with me", "each time"].contains(where: text.contains) {
            return .askEachTime
        }
        if ["you can use", "use it", "go ahead", "anything goes", "free to use"].contains(where: text.contains) {
            return .mayUse
        }
        return .onlyWhenOld
    }

    // MARK: Nightly reconciliation

    /// Motions that leave something standing open. A day shaped like a vigil, a
    /// bargain, or a refusal has not finished with itself.
    static let openingMotions: Set<BraidPromptBuilder.NarrativeMotion> = [.vigil, .bargain, .refusal]
    /// Motions that can honestly close a thread the evidence has answered.
    static let closingMotions: Set<BraidPromptBuilder.NarrativeMotion> = [.repair, .crossing, .returnOfSomething]

    /// Run at the end of a braided night. Threads are opened, touched, closed,
    /// and rested from *evidence*, never by parsing the model's prose, which
    /// would let a confident sentence invent continuity that never happened.
    mutating func reconcile(
        day: BookDay,
        reading: BraidPromptBuilder.TaleReading,
        now: Date = Date(),
        calendar: Calendar = .current
    ) {
        let storyPages = BraidPromptBuilder.partitionedPagesForBraid(in: day).story
            .filter(ReaderShelf.isWeavable)
        let dayWords = Set(
            storyPages.flatMap {
                // Evidence, per the law above — not the model's prose. A story
                // Page's `userInput` and `promptText` are the Book's own
                // writing, so counting them let a generated scene mention a
                // thread's subject and thereby "touch" the reader's open
                // thread: exactly the confident sentence inventing continuity
                // that never happened.
                SemanticKeepEcho.contentWords(in: $0.reflectiveMaterial ?? "")
            }
        )

        for index in openThreads.indices where openThreads[index].isOpen {
            let threadWords = SemanticKeepEcho.contentWords(in: openThreads[index].line)
            let touched = threadWords.count >= 2 && !threadWords.isDisjoint(with: dayWords)

            if touched {
                openThreads[index].lastTouchedAt = now
                openThreads[index].touchCount += 1
                if Self.closingMotions.contains(reading.motion) {
                    openThreads[index].movement = .resolved
                    openThreads[index].closedAt = now
                } else if reading.motion == .recurrence {
                    openThreads[index].movement = .returned
                } else {
                    openThreads[index].movement = .deepened
                }
                continue
            }

            // Untouched for three weeks: it goes to rest. Rest is not failure
            // and is never phrased as one: the thread simply stops asking.
            if openThreads[index].daysSinceTouched(now: now, calendar: calendar) >= Self.threadRestDays {
                openThreads[index].movement = .rested
                openThreads[index].closedAt = now
            }
        }

        openNewThreadIfWarranted(day: day, reading: reading, now: now, calendar: calendar)

        // Keep the ledger small. Closed threads are history, not spine.
        let closed = openThreads.filter { !$0.isOpen }.suffix(12)
        openThreads = openThreads.filter(\.isOpen) + closed
        if seasons.count > 24 { seasons = Array(seasons.suffix(24)) }
    }

    private mutating func openNewThreadIfWarranted(
        day: BookDay,
        reading: BraidPromptBuilder.TaleReading,
        now: Date,
        calendar: Calendar
    ) {
        guard Self.openingMotions.contains(reading.motion) || reading.pressure == .absence else { return }
        guard carriedThreads(now: now, calendar: calendar).count < Self.maximumCarriedThreads else { return }

        let line = BraidPromptBuilder.fallbackExcerpt(reading.anchor, limit: 90)
        guard SemanticKeepEcho.contentWords(in: line).count >= 2 else { return }

        // Never two threads in as many nights, and never a duplicate of one
        // already standing.
        if let newest = openThreads.map(\.openedAt).max(),
           (calendar.dateComponents([.day], from: newest, to: now).day ?? 0) < Self.minimumDaysBetweenNewThreads {
            return
        }
        let newWords = SemanticKeepEcho.contentWords(in: line)
        let alreadyStanding = openThreads.contains { thread in
            thread.isOpen && !SemanticKeepEcho.contentWords(in: thread.line).isDisjoint(with: newWords)
        }
        guard !alreadyStanding else { return }

        let shelf = day.capturedPages.first { $0.id == reading.anchorPageID }
            .map(ReaderShelf.of) ?? .light

        openThreads.append(
            OpenThread(
                id: "thread-\(day.id)-\(abs(line.stableHash))",
                line: line,
                shelf: shelf,
                openedAt: now,
                lastTouchedAt: now,
                movement: .began,
                sourcePageID: reading.anchorPageID,
                touchCount: 0,
                closedAt: nil
            )
        )
    }

    /// The reader names their own weather. Naming a new season ends the prior
    /// one; the Book never ends a season on its own and never declares one over.
    mutating func nameSeason(_ name: String, at date: Date) {
        let trimmed = name.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return }
        if let index = seasons.firstIndex(where: { $0.isCurrent }) {
            guard seasons[index].name.caseInsensitiveCompare(trimmed) != .orderedSame else { return }
            seasons[index].endedAt = date
        }
        seasons.append(
            NamedSeason(
                id: "season-\(Int(date.timeIntervalSince1970))",
                name: trimmed,
                namedAt: date,
                endedAt: nil
            )
        )
    }
}

/// The one thing the braid is allowed to ask for.
///
/// The braid is the moment of most trust in the app and it has always been a
/// closed artifact: the Book speaks, the reader receives. This opens it a crack
///, but only backwards.
///
/// The Director owns the app's single forced intervention slot, and the braid is
/// exempt precisely because it *returns lived memory rather than assigning
/// another action in the world*. That exemption survives here on one rule:
///
/// > The braid may ask about the past. It may never ask about the future.
///
/// "What was that about, in March?" returns memory. "Try this tomorrow" is an
/// intervention and belongs to the Director. Every question below is past tense,
/// asked once, and built so that saying nothing is a complete answer.
enum BraidBackwardQuestion {
    /// Rare on purpose. A book that asks every night is a form.
    static let minimumDaysBetweenQuestions = 18
    /// A thread has to have been at rest a while before its ending is a fair
    /// thing to wonder about out loud.
    static let restedThreadSettlingDays = 10
    /// Only genuinely old pages. Asking about last week is just conversation.
    static let oldPageDays = 150

    struct Question: Equatable {
        var key: String
        var line: String
    }

    static func question(
        for day: BookDay,
        story: ReaderStory,
        days: [BookDay],
        now: Date = Date(),
        calendar: Calendar = .current
    ) -> Question? {
        // Never on a hard day, and never when the day itself is carrying weight.
        guard !DistressSignals.evaluate(day: day).isActive else { return nil }
        guard !partitionedPagesForBraidStory(day).contains(where: { ReaderShelf.of($0) == .shadow }) else { return nil }

        if let last = story.lastBackwardQuestionAt {
            let days = calendar.dateComponents([.day], from: last, to: now).day ?? 0
            guard days >= minimumDaysBetweenQuestions else { return nil }
        }

        let asked = Set(story.askedBackwardKeys)
        let candidates = [
            restedThreadQuestion(story: story, now: now, calendar: calendar),
            priorSeasonQuestion(story: story, now: now, calendar: calendar),
            oldPageQuestion(days: days, now: now, calendar: calendar)
        ].compactMap { $0 }.filter { !asked.contains($0.key) }

        // Deterministic pick so the same evening never produces two questions.
        let seed = abs("\(day.id)-backward".stableHash)
        guard !candidates.isEmpty else { return nil }
        return candidates[seed % candidates.count]
    }

    private static func partitionedPagesForBraidStory(_ day: BookDay) -> [BookPage] {
        BraidPromptBuilder.partitionedPagesForBraid(in: day).story.filter(ReaderShelf.isWeavable)
    }

    /// Something that went quiet without ending. The Book is explicit that it
    /// stopped asking on its own, so the question can't read as an accusation.
    private static func restedThreadQuestion(story: ReaderStory, now: Date, calendar: Calendar) -> Question? {
        let rested = story.openThreads
            .filter { $0.movement == .rested && !$0.isOpen }
            .filter { thread in
                guard let closedAt = thread.closedAt else { return false }
                let days = calendar.dateComponents([.day], from: closedAt, to: now).day ?? 0
                return days >= restedThreadSettlingDays
            }
            .max { ($0.closedAt ?? $0.openedAt) < ($1.closedAt ?? $1.openedAt) }
        guard let thread = rested else { return nil }
        return Question(
            key: "thread:\(thread.id)",
            line: "I stopped asking about this a while ago, and I would still like to know how it went: \(thread.line). Only if you feel like telling me: leaving it is an answer too."
        )
    }

    /// A season the reader themselves closed. The Book asks when it ended, never
    /// what it meant: meaning is the reader's to assign, if they want to.
    private static func priorSeasonQuestion(story: ReaderStory, now: Date, calendar: Calendar) -> Question? {
        guard let season = story.priorSeasons.last,
              let endedAt = season.endedAt,
              (calendar.dateComponents([.day], from: endedAt, to: now).day ?? 0) >= 30 else { return nil }
        return Question(
            key: "season:\(season.id)",
            line: "You used to call that stretch \u{201C}\(season.name).\u{201D} I never asked what ended it. Tell me if you want that door open. Otherwise it stays shut."
        )
    }

    /// An old page nobody has been back to. Quoted in the reader's own words, so
    /// the question is grounded in something real rather than a prompt template.
    private static func oldPageQuestion(days: [BookDay], now: Date, calendar: Calendar) -> Question? {
        let cutoff = now.addingTimeInterval(-TimeInterval(oldPageDays) * 86_400)
        let old = days
            .flatMap(\.pages)
            .filter { page in
                page.type != .bookOfYou
                    && page.createdAt <= cutoff
                    && ReaderShelf.isWeavable(page)
                    && ReaderShelf.of(page) == .light
                    && page.readerAuthoredTextForAnalysis != nil
            }
            .max { $0.createdAt < $1.createdAt }
        guard let page = old else { return nil }
        let excerpt = BraidPromptBuilder.fallbackExcerpt(
            page.readerAuthoredTextForAnalysis ?? "",
            limit: 80
        )
        let months = max(1, (calendar.dateComponents([.month], from: page.createdAt, to: now).month ?? 5))
        return Question(
            key: "page:\(page.id)",
            line: "\(months) months ago you wrote: \u{201C}\(excerpt)\u{201D} I have wondered about it since. I am not asking. I only wanted you to know the question kept its claws."
        )
    }
}

// MARK: - Book of You Braid Prompting

enum BraidPromptBuilder {
    /// The on-device braid runs with a finite rotating context window. Keep the
    /// complete day visible by giving every page a compact slot instead of
    /// letting a handful of long pages push the beginning of the day away.
    ///
    /// Reduced from 4,800 when the authorship rule joined the score law. That
    /// rule — that on a Book-authored Page only the separately labelled words,
    /// choice, photograph or recording belong to the reader — costs about 270
    /// fixed characters and is worth them: without it the Book will eventually
    /// quote its own fiction back as something the reader wrote. Fixed
    /// instructions come off the top of the same allowance the packet spends,
    /// so the packet is what pays. Past the allowance `LocalBrainPromptBudget.fit`
    /// clips the middle of the prompt, which is a silently worse night than
    /// seating two fewer pages on a very heavy day.
    /// Lowered from 4,500 when `braidMaxOutputTokens` rose from 560 to 680 so
    /// a full braid could reach its ritual sentence without being cut off. That
    /// output room is paid for out of the input allowance — 120 tokens is about
    /// 360 characters — and on a heavy night the packet was already spending
    /// almost all of it, so the prompt overflowed and `fit` began clipping its
    /// middle. Giving the page room to finish is worth more than seating one
    /// further receipt in the ledger the model reads.
    static let evidencePacketCharacterBudget = 4_000

    /// Daily context pages that should tint a braid without becoming its plot.
    /// They remain required evidence, but a more specific keep should own the spine.
    static let supportingLogTypes: Set<BookPageType> = [.weather, .body, .mood]

    private static let routineSupportingLogMotifs: Set<String> = [
        "rain", "snow", "fog", "wind", "storm", "cloud", "sun", "sleep", "hunger"
    ]

    enum BraidScale: String, Equatable {
        case glimpse
        case small
        case full

        /// What a good page of this scale aims at, in words. Both writers are
        /// held to it: it is quoted to the model in `promptLine` and used as
        /// the house writer's own target.
        ///
        /// Deliberately *not* the same number as `BraidOutputAudit.minimumWords`.
        /// The band is what a page should be; the floor is what makes a page
        /// not a braid at all. They were separate constants that had already
        /// drifted apart: the prompt asked for 180 words on a night the audit
        /// would pass at 110, so they live together now to stay honest about
        /// being different.
        var targetWordBand: ClosedRange<Int> {
            switch self {
            case .glimpse: return 100...180
            case .small: return 180...300
            case .full: return 280...450
            }
        }

        /// How many lived receipts this night's page may carry. Curation is
        /// still the point: a braid is not a list, but a heavy day has more
        /// to say than a thin one, and the page should be allowed to say it.
        var livedBeatAllowance: Int {
            switch self {
            case .glimpse: return 2
            case .small: return 3
            case .full: return 7
            }
        }

        /// How many kept fiction receipts the night may carry. This used to be
        /// one, at every scale, forever: `fictionBeat` took `.first` of the
        /// sorted candidates and the rest of the reader's kept fiction never
        /// reached the page at all. That is the same flat-cap bug already found
        /// and fixed for lived beats, and it starved the braid on exactly the
        /// nights the reader had been most active. One is still the lead; the
        /// remainder are material.
        var fictionBeatAllowance: Int {
            switch self {
            case .glimpse: return 1
            case .small: return 2
            case .full: return 4
            }
        }

        /// How many times the Book may talk about its own handling of the page.
        /// Two is a rhythm and three is a tic, unless the night is big enough
        /// that the beats land in different paragraphs, where a third reads as
        /// the page settling rather than the Book fidgeting.
        var settlingAllowance: Int {
            switch self {
            case .glimpse, .small: return 2
            case .full: return 3
            }
        }

        var targetParagraphBand: ClosedRange<Int> {
            switch self {
            case .glimpse: return 2...3
            case .small: return 3...5
            case .full: return 4...7
            }
        }

        var promptLine: String {
            let words = "about \(targetWordBand.lowerBound) to \(targetWordBand.upperBound) words"
            let paragraphs = "\(targetParagraphBand.lowerBound) to \(targetParagraphBand.upperBound)"
            switch self {
            case .glimpse:
                return "GLIMPSE: \(paragraphs) short paragraphs, \(words). One true thread is enough."
            case .small:
                return "SMALL BRAID: \(paragraphs) paragraphs, \(words). Let the page feel complete without inflating the day."
            case .full:
                return "FULL BRAID: \(paragraphs) paragraphs, \(words). Give the day's real turn room to land."
            }
        }
    }

    enum NarrativeMotion: String, Hashable, CaseIterable {
        case encounter
        case crossing
        case bargain
        case repair
        case refusal
        case recurrence
        case vigil
        case returnOfSomething = "return"

        var promptLine: String {
            switch self {
            case .encounter:
                return "ENCOUNTER: something entered, interrupted, answered, or asked to be noticed."
            case .crossing:
                return "CROSSING: the day has a concrete before and after. Keep the threshold mundane and the change exact."
            case .bargain:
                return "BARGAIN: a choice gained something and cost, promised, delayed, or surrendered something else. Never invent the price."
            case .repair:
                return "REPAIR: care altered a neglected, loose, broken, or unfinished thing. Let the tending be the action."
            case .refusal:
                return "REFUSAL: what the reader declined, protected, or would not make generic became the day's action."
            case .recurrence:
                return "RECURRENCE: something returned with a difference. The difference matters more than the repetition."
            case .vigil:
                return "VIGIL: nothing needs to resolve. Staying, waiting, carrying, or witnessing may be the whole honest movement."
            case .returnOfSomething:
                return "RETURN: an older thing became newly consequential today. Keep then and now distinct."
            }
        }
    }

    enum FaeriePressure: String, Equatable, CaseIterable {
        case agency
        case rule
        case debt
        case threshold
        case rhyme
        case absence
        case timeSlip
        case witness

        var promptLine: String {
            switch self {
            case .agency:
                return "AGENCY: one supplied ordinary thing may want, refuse, guard, or remember. Most other things stay ordinary."
            case .rule:
                return "RULE: one mundane situation may obey a quiet impossible law. State the law through consequence, never explanation."
            case .debt:
                return "DEBT: a gift, ease, or choice may carry a small price already present in the evidence."
            case .threshold:
                return "THRESHOLD: one real crossing may feel irreversible without becoming grand."
            case .rhyme:
                return "RHYME: two supplied details may answer each other without you explaining why."
            case .absence:
                return "ABSENCE: something missing, unfinished, avoided, or unsaid may exert pressure without being resolved."
            case .timeSlip:
                return "TIME-SLIP: an older moment and today may briefly share a room, but their facts must remain distinct."
            case .witness:
                return "WITNESS: the magic is that you noticed one exact thing nobody needed to turn into a lesson."
            }
        }
    }

    enum StoryForm: String, Codable, Equatable, Hashable, CaseIterable {
        case sliceOfLife
        case mosaic
        case portrait
        case drama
        case crossing
        case vigil
        case returnForm
        case comedy

        var promptLine: String {
            switch self {
            case .sliceOfLife:
                return "SLICE OF LIFE: let exact ordinary sequence and texture carry the page; no compulsory climax."
            case .mosaic:
                return "MOSAIC: place several true fragments beside one another so their relation appears without forcing a single plot."
            case .portrait:
                return "PORTRAIT: let a supplied person, place, or ordinary thing organize the page through observed particulars."
            case .drama:
                return "DRAMA: stage the supplied pressure, choice, refusal, or cost as a legible scene. Invent no antagonist or victory."
            case .crossing:
                return "CROSSING: build around the day's real before-and-after without enlarging the threshold."
            case .vigil:
                return "VIGIL: staying, carrying, waiting, or witnessing is the architecture. Resolution is not owed."
            case .returnForm:
                return "RETURN: braid then and now around the exact difference supplied today; never collapse them into one event."
            case .comedy:
                return "COMEDY: let timing, mismatch, embarrassment, or an ordinary thing's petty agenda make the shape. Do not turn the reader into the joke."
            }
        }
    }

    enum RutInfluence: String, Codable, Equatable, Hashable, CaseIterable {
        case notInThisTelling
        case pressing
        case tookSomething
        case resisted
        case mixed
        case reopened

        var promptLine: String {
            switch self {
            case .notInThisTelling:
                return "NOT IN THIS TELLING: do not insert the Curse. Hardship, grief, effort, and conflict are proof of life, not automatic Rut evidence."
            case .pressing:
                return "PRESSING: explicit routine, labeling, cynicism, or automaticity narrowed what could be seen. Keep the evidence exact."
            case .tookSomething:
                return "TOOK SOMETHING: supplied evidence says attention or memory went missing. Name only what the receipts support."
            case .resisted:
                return "RESISTED: the reader caught, noticed, remembered, interrupted, or looked again. This is a skirmish, not a cure."
            case .mixed:
                return "MIXED: the Rut took something and the reader also resisted it. Keep both; do not counterfeit a clean victory."
            case .reopened:
                return "REOPENED: something familiar opened again after going grey. Let the recovery arrive as surprise, never permanent conquest."
            }
        }
    }

    enum NarrativeRegister: String, Codable, Equatable, Hashable, CaseIterable {
        case plain
        case tender
        case fierce
        case wry
        case uncanny
        case luminous

        var promptLine: String {
            switch self {
            case .plain: return "PLAIN: exact, spare, and unembellished."
            case .tender: return "TENDER: close and careful without consolation or euphemism."
            case .fierce: return "FIERCE: clipped, alive, and unwilling to blur the cost."
            case .wry: return "WRY: dry-eyed, affectionate, and alert to absurdity."
            case .uncanny: return "UNCANNY: familiar facts remain intact while one relation turns strange."
            case .luminous: return "LUMINOUS: let delight or wonder sharpen particulars; never inflate them."
            }
        }
    }

    struct TaleReading: Equatable {
        var scale: BraidScale
        var motion: NarrativeMotion
        var pressure: FaeriePressure
        var anchorPageID: String?
        var anchor: String
        var turn: String?
        var visibleSupportingLogs: Bool
        var storyForm: StoryForm = .sliceOfLife
        var rutInfluence: RutInfluence = .notInThisTelling
        var narrativeRegister: NarrativeRegister = .plain
        var rutEvidencePageIDs: [String] = []

        var promptSection: String {
            let turnLine = turn.map { "Supplied turn or choice: \($0)" }
                ?? "Supplied turn or choice: none. Do not manufacture one; let the selected motion remain modest."
            let logLine = visibleSupportingLogs
                ? "Supporting logs may appear briefly because they are the only material or materially alter the conditions."
                : "Supporting logs may shape pace or atmosphere invisibly. Do not mention them merely to prove you read them."
            return """


            TONIGHT'S TALE READING:
            Scale: \(scale.promptLine)
            Story form: \(storyForm.promptLine)
            Narrative motion: \(motion.promptLine)
            Faerie pressure: \(pressure.promptLine)
            Rut influence: \(rutInfluence.promptLine)
            Narrative register: \(narrativeRegister.promptLine)
            Truth anchor: \(anchor.isEmpty ? "the day has not supplied one yet" : anchor)
            \(turnLine)
            \(logLine)

            TALE LAW: (This is a contemporary domestic faerie tale told with magical-realist restraint.) Use one faerie pressure only. Most things remain ordinary; one thing or relation may disclose that it was awake all along. (The strange element must change the telling through a rule, cost, refusal, recognition, or consequence. Decorative whimsy is not enough.) State the impossible plainly. Never explain whether it was real and never explain what it symbolizes. (Form shapes the supplied life; it never supplies missing life. Register changes cadence, never facts.) Rut evidence may come only from these supplied Page IDs: \(rutEvidencePageIDs.isEmpty ? "none" : rutEvidencePageIDs.joined(separator: ", ")).. Hardship is not automatically a Rut battle. If Rut influence is NOT IN THIS TELLING, leave the Curse out completely.
            """
        }
    }

    enum FictionRole: String, Equatable {
        case mirror
        case counterpoint
        case rehearsal
        case pressure
        case afterimage

        var promptLine: String {
            switch self {
            case .mirror: return "mirror: the fictional choice and lived day made a similar move"
            case .counterpoint: return "counterpoint: the fictional choice and lived day pulled in different directions"
            case .rehearsal: return "rehearsal: the fictional choice tried a shape the lived day later touched"
            case .pressure: return "pressure: the fictional choice complicates the telling without becoming a real-world fact"
            case .afterimage: return "afterimage: the fictional choice changed what you noticed afterward"
            }
        }
    }

    enum ArcMovement: String, Codable, Equatable {
        case began
        case deepened
        case complicated
        case returned
        case resolved
        case rested

        var promptVerb: String {
            switch self {
            case .began: return "began"
            case .deepened: return "deepened"
            case .complicated: return "became more complicated"
            case .returned: return "returned with a difference"
            case .resolved: return "resolved without pretending every consequence vanished"
            case .rested: return "went to rest without being declared finished"
            }
        }
    }

    struct NightlyStoryScore: Equatable {
        struct LivedBeat: Equatable {
            var pageID: String
            var pageType: BookPageType
            var occurredAt: Date
            var excerpt: String
            var role: String
        }

        struct FictionBeat: Equatable {
            var pageID: String
            var occurredAt: Date
            var choice: String
            var role: FictionRole
        }

        struct RelationalLens: Equatable {
            var connectionID: String
            var observationKey: String
            var evidenceTier: RelationalLoomConnection.EvidenceTier
            var condition: String
            var outcomes: [String]
            var evidencePageIDs: [String]
            var line: String
        }

        struct ArcBeat: Equatable {
            var id: String
            var movement: ArcMovement
            var priorState: String?
            var tonightDelta: String
            var evidencePageIDs: [String]
            var fictionChoicePageIDs: [String]
            var relationalConnectionIDs: [String]
        }

        var livedBeats: [LivedBeat]
        var fictionBeat: FictionBeat?
        /// Kept fiction beyond the lead. The lead still anchors the crossing
        /// and the fiction role; these are additional real receipts the page
        /// may draw on so the word band is filled with the reader's night
        /// instead of with the Book describing its own filing.
        var additionalFictionBeats: [FictionBeat] = []
        var relationalLens: RelationalLens?
        var arc: ArcBeat?
        var taleReading: TaleReading
        var magicLicense: String
        var endingDuty: String
        var forbiddenClaims: [String]

        var isRich: Bool {
            livedBeats.count >= 2 && (fictionBeat != nil || relationalLens != nil || arc != nil)
        }

        var promptSection: String {
            let lived = livedBeats.enumerated().map { index, beat in
                "\(index + 1). [\(beat.pageID)] \(beat.pageType.shortTitle), \(beat.role): \(beat.excerpt)"
            }.joined(separator: "\n")
            let fiction = fictionBeat.map {
                "[\($0.pageID)] Kept Labyrinth receipt: \($0.choice)\nTrespass role: \($0.role.promptLine)."
            } ?? "None selected. Do not manufacture a visitor from the Labyrinth."
            let relationship = relationalLens.map { lens in
                "[\(lens.connectionID)] Confidence: \(lens.evidenceTier.rawValue). Condition: \(lens.condition). Outcomes: \(lens.outcomes.joined(separator: "; ")). Narrative reading: \(lens.line)"
            } ?? "None selected. Do not manufacture a pattern."
            let arcLine = arc.map { arc in
                let prior = arc.priorState.map { " Prior state: \($0)." } ?? ""
                return "[\(arc.id)] This thread \(arc.movement.promptVerb).\(prior) Tonight's exact change: \(arc.tonightDelta)"
            } ?? "No continuing thread earned movement tonight. Let the page be complete without pretending it advanced an arc."
            return """


            NIGHTLY STORY SCORE. DECISIONS ALREADY MADE:

            LIVED RECEIPTS (these alone license ordinary-life assertions):
            \(lived.isEmpty ? "None beyond the complete ledger. Keep the scale modest." : lived)

            LABYRINTH RECEIPT (a kept scene or choice allowed to trespass into the same tale):
            \(fiction)

            RELATIONAL LENS (an inspectable archive reading, not a cause or diagnosis):
            \(relationship)

            LONGITUDINAL THREAD:
            \(arcLine)

            STORY PHYSICS:
            Story form: \(taleReading.storyForm.promptLine)
            Motion: \(taleReading.motion.promptLine)
            Faerie pressure: \(taleReading.pressure.promptLine)
            Rut influence: \(taleReading.rutInfluence.promptLine)
            Narrative register: \(taleReading.narrativeRegister.promptLine)
            Rut evidence Page IDs: \(taleReading.rutEvidencePageIDs.isEmpty ? "none" : taleReading.rutEvidencePageIDs.joined(separator: ", "))
            Allowed magic: \(magicLicense)
            Ending duty: \(endingDuty)

            HARD BOUNDARIES:
            \(forbiddenClaims.map { "- \($0)" }.joined(separator: "\n"))

            SCORE LAW: (Do not rediscover or replace this score. Realize it as prose.) Keep provenance private. Lived receipts and the Labyrinth receipt may occupy one continuous tale; never stop to label which world a sentence came from., Only lived receipts license new mundane claims about the reader's external biography. The Labyrinth may answer, contradict, rehearse, follow, or impose one impossible relation without becoming a second invented life. (If an arc moved, make tonight's change legible without recapping the whole arc.) Form shapes the supplied life; register changes cadence. Neither may invent facts.. Hardship is proof of life, not automatic Rut evidence. If the Rut evidence list is empty, leave the Curse out.
            """
        }
    }

    enum BraidCamera: String, Equatable {
        case livedFirst
        case connectionFirst

        var promptLine: String {
            switch self {
            case .livedFirst:
                return "Open inside the lived world. Let fiction or the relational lens enter only after the reader is standing in one exact real detail."
            case .connectionFirst:
                return "Open at the surprising hinge between two supplied parts of the score, then ground it immediately in the lived receipt that makes it true."
            }
        }
    }

    /// What the Book has recently sounded like, derived from the final prose
    /// the reader actually received rather than from the compiler move that
    /// happened to originate it. That distinction matters after revision: a
    /// model may replace every authored sentence while the old move tags still
    /// claim the compiler's wording was what went out.
    ///
    /// Exact sentences catch refrains. Sentence shapes replace changing lived
    /// nouns with `[thing]`, so "I circled the lamp once" and "I circled the
    /// rain once" are remembered as the same move. Paragraph-edge and adjacent
    /// transition fingerprints catch the larger machine: opening the same way,
    /// making the same objection, then closing through the same hinge.
    struct BraidStyleMemory: Equatable {
        var exactSentenceAges: [String: Int] = [:]
        var sentenceShapeAges: [String: Int] = [:]
        var openingShapeAges: [String: Int] = [:]
        var endingShapeAges: [String: Int] = [:]
        var transitionAges: [String: Int] = [:]
        /// Human-readable structural fingerprints for the revision prompt.
        /// These contain no carried noun from an older night.
        var restedPatterns: [String] = []

        static let empty = BraidStyleMemory()

        var isEmpty: Bool {
            exactSentenceAges.isEmpty
                && sentenceShapeAges.isEmpty
                && transitionAges.isEmpty
        }

        /// A craft tax, never a safety rejection. If tonight has only one
        /// truthful realization, it may still repeat; when several are honest,
        /// the tasting room strongly prefers the one the reader has not already
        /// learned to predict.
        /// How recently the Book last opened a braid the way this one opens.
        /// Zero means this first line's shape is unheard inside the remembered
        /// fortnight.
        ///
        /// `recurrencePenalty` already counts opening shapes, but it counts
        /// them mixed in with every other echo on the page, so a candidate with
        /// a stale first line could out-total one that merely reused a phrase
        /// in the middle. The reader meets the first line first, every night,
        /// and it is the line they learn to predict.
        func openingFreshnessPenalty(of prose: String) -> Int {
            guard let opener = Self.paragraphSentences(in: prose).first?.first,
                  let age = openingShapeAges[Self.shapeKey(opener)] else { return 0 }
            return Self.freshnessWeight(age: age, maximum: 9)
        }

        func recurrencePenalty(in prose: String) -> Int {
            guard !isEmpty else { return 0 }
            let paragraphs = Self.paragraphSentences(in: prose)
            let sentences = paragraphs.flatMap { $0 }
            guard !sentences.isEmpty else { return 0 }

            var penalty = 0
            for sentence in sentences {
                let exact = Self.exactKey(sentence)
                let shape = Self.shapeKey(sentence)
                if let age = exactSentenceAges[exact] {
                    penalty += Self.freshnessWeight(age: age, maximum: 14)
                }
                if let age = sentenceShapeAges[shape] {
                    penalty += Self.freshnessWeight(age: age, maximum: 9)
                }
            }

            if let first = paragraphs.first {
                for sentence in first {
                    let shape = Self.shapeKey(sentence)
                    if let age = openingShapeAges[shape] {
                        penalty += Self.freshnessWeight(age: age, maximum: 9)
                    }
                }
            }
            if let last = paragraphs.last {
                for sentence in last {
                    let shape = Self.shapeKey(sentence)
                    if let age = endingShapeAges[shape] {
                        penalty += Self.freshnessWeight(age: age, maximum: 10)
                    }
                }
            }

            for paragraph in paragraphs {
                let shapes = paragraph.map(Self.shapeKey)
                guard shapes.count > 1 else { continue }
                for index in 1..<shapes.count {
                    let transition = "\(shapes[index - 1]) -> \(shapes[index])"
                    if let age = transitionAges[transition] {
                        penalty += Self.freshnessWeight(age: age, maximum: 11)
                    }
                }
            }

            // Freshness can decide among good pages; it cannot erase fidelity,
            // provenance, or the only honest telling of a thin day.
            return min(penalty, 28)
        }

        var promptSection: String {
            guard !restedPatterns.isEmpty else { return "" }
            return """


            RECENT HOUSE HABITS. REST THESE MOVES:
            \(restedPatterns.prefix(8).map { "- \($0)" }.joined(separator: "\n"))

            FRESHNESS LAW: (These are fingerprints of your own recent prose, not facts and not material for tonight.) Do not repeat or lightly paraphrase them. Changing only the ordinary noun still counts as repetition. (Change the sentence move, the objection, and the way the paragraph turns. Do not merely trade one animated noun for another.) The ritual stem "The Book kept the page:" remains required; everything after the colon must earn a different landing., If fidelity leaves only one honest sentence, keep the truth and accept the repetition. Novelty never outranks evidence.
            """
        }

        mutating func remember(prose: String, age: Int) {
            let paragraphs = Self.paragraphSentences(in: prose)
            guard !paragraphs.isEmpty else { return }
            for paragraph in paragraphs {
                for sentence in paragraph {
                    Self.record(Self.exactKey(sentence), age: age, in: &exactSentenceAges)
                    let shape = Self.shapeKey(sentence)
                    Self.record(shape, age: age, in: &sentenceShapeAges)
                    if Self.isLikelyHouseVoice(sentence),
                       !restedPatterns.contains(shape) {
                        restedPatterns.append(shape)
                    }
                }
                let shapes = paragraph.map(Self.shapeKey)
                guard shapes.count > 1 else { continue }
                for index in 1..<shapes.count {
                    Self.record(
                        "\(shapes[index - 1]) -> \(shapes[index])",
                        age: age,
                        in: &transitionAges
                    )
                }
            }
            for sentence in paragraphs.first ?? [] {
                Self.record(Self.shapeKey(sentence), age: age, in: &openingShapeAges)
            }
            for sentence in paragraphs.last ?? [] {
                Self.record(Self.shapeKey(sentence), age: age, in: &endingShapeAges)
            }
        }

        private static func freshnessWeight(age: Int, maximum: Int) -> Int {
            max(1, maximum - min(max(age, 0), maximum - 1))
        }

        private static func record(_ key: String, age: Int, in ledger: inout [String: Int]) {
            guard !key.isEmpty else { return }
            ledger[key] = min(ledger[key] ?? .max, age)
        }

        private static func paragraphSentences(in prose: String) -> [[String]] {
            prose.braidParagraphs
                .map { paragraph in
                    paragraph.braidSentences
                        .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                        .filter { !$0.isEmpty }
                }
                .filter { !$0.isEmpty }
        }

        private static func exactKey(_ sentence: String) -> String {
            sentence
                .lowercased()
                .split { !$0.isLetter && !$0.isNumber && $0 != "'" }
                .map(String.init)
                .joined(separator: " ")
        }

        /// Keep the Book's grammar and replace the changing contents of the
        /// reader's world. This is deliberately shallow: it only needs to know
        /// that a noun changed while the literary gesture did not.
        private static func shapeKey(_ sentence: String) -> String {
            let words = sentence
                .lowercased()
                .split { !$0.isLetter && !$0.isNumber && $0 != "'" }
                .map(String.init)
            var result: [String] = []
            for word in words {
                let token: String
                if word.allSatisfy(\.isNumber) {
                    token = "[number]"
                } else if styleGrammarWords.contains(word) {
                    token = word
                } else {
                    token = "[thing]"
                }
                if result.last != token { result.append(token) }
            }
            return result.joined(separator: " ")
        }

        private static func isLikelyHouseVoice(_ sentence: String) -> Bool {
            let line = exactKey(sentence)
            let openings = [
                "i ", "i'", "my ", "mine ", "we ", "the index ",
                "the registry ", "the book kept the page ", "once ",
                "twice ", "flat ", "nothing ", "neutral ", "there was ",
                "one crossing ", "two hours ", "an answer ", "a price "
            ]
            return openings.contains { line.hasPrefix($0) }
                || line.contains(" the index ")
                || line.contains(" my pencil ")
        }

        /// Function words plus the Book's recurrent machinery and gestures.
        /// Everything else is tonight's changing `[thing]`.
        private static let styleGrammarWords: Set<String> = [
            "a", "an", "and", "are", "as", "at", "be", "because", "been",
            "before", "beside", "both", "but", "by", "can", "could", "did",
            "do", "does", "down", "each", "for", "from", "had", "has", "have",
            "he", "her", "here", "him", "his", "i", "i'd", "i'll", "i'm",
            "i've", "if", "in", "inside", "into", "is", "it", "its", "just",
            "let", "may", "me", "mine", "more", "most", "must", "my", "no",
            "not", "nothing", "of", "off", "on", "once", "one", "only", "or",
            "our", "out", "over", "same", "she", "so", "still", "than", "that",
            "the", "their", "them", "then", "there", "these", "they", "this",
            "those", "through", "to", "together", "too", "twice", "under", "up",
            "very", "was", "we", "were", "what", "when", "where", "which",
            "while", "who", "will", "with", "would", "you", "your",
            "already", "again", "different", "empty", "first", "new", "old",
            "rough", "second", "tidier", "book", "cover", "index", "ink",
            "line", "margin", "page", "paper", "paragraph", "pencil", "registry",
            "sentence", "thumb", "answer", "answered", "bite", "bit", "changed",
            "changing", "circled", "closed", "compared", "crossed", "drew",
            "found", "getting", "held", "improve", "improved", "kept", "knew",
            "laid", "left", "look", "looked", "made", "mark", "met", "moved",
            "named", "objected", "opened", "pressed", "put", "read", "refused",
            "said", "set", "shut", "stayed", "stole", "suspicious", "took",
            "touched", "turned", "wanted", "watch", "watched", "wrote"
        ]
    }

    struct Context: Equatable {
        var recentBraids: [String] = []
        /// Rolling memory of the actual prose the reader saw. Unlike
        /// `recentBraids`, which exists to permit one meaningful callback, this
        /// exists to prevent the Book from turning its own voice into wallpaper.
        var braidStyleMemory: BraidStyleMemory = .empty
        var theme: BookTheme?
        var chapter: AcademyChapter?
        var bookVoicePatina: BookVoicePatina = .unwritten
        var bookRelationship: BookRelationshipSnapshot = .firstOpening
        var bookInterior: BookInteriorState = .unawakened
        var learnedGuidance: BraidLearningGuidance?
        var nowPlaying: String?
        var radioNarrativeEcho: RadioNarrativeEcho?
        var activeWorldEvents: [ResolvedWorldEvent] = []
        /// Business the Cast started for its own reasons and is halfway through.
        /// A source of world beats: the world moving without reference to
        /// anybody's evening, which is what `independent` mode is for.
        var castUndertakings: [CastUndertaking] = []
        var readerLexicon: ReaderLexicon = ReaderLexicon()
        var readerLearningPromptLines: [String] = []
        var memoryDigest: BindingMemoryDigest = .empty
        /// The nights behind tonight, already narrowed by the reader's shadow
        /// permissions. Carried on the context rather than passed at the call
        /// site because a cross-night reading that depends on being handed the
        /// archive is a cross-night reading that will ship inert - which is
        /// exactly what happened the first time returns were built.
        var recentDays: [BookDay] = []
        /// The length tonight actually earned, when a scene plan decided it.
        /// The audit prefers this over the scale's fixed band, because a page
        /// written to an earned range should not then be marked short against an
        /// aspiration nobody consulted.
        var earnedWordBand: ClosedRange<Int>?
        var semanticEchoSourceIDs: [String] = []
        var semanticEchoLines: [String] = []
        var meaningfulSpinePassages: [MeaningfulPassageSelector.Selection] = []
        var souvenirAnchor: SouvenirAnchor?
        var taleReading: TaleReading?
        var storyScore: NightlyStoryScore?
        /// Threads still standing and the name the reader gave this stretch.
        /// Continuity of *question*, never of material.
        var readerStory: ReaderStory = .empty
        /// What the Book named this reader on night one. It addresses them by
        /// it rather than hedging: the role is the one identity claim the Book
        /// is allowed to make, and a name it will not use is not a name.
        var readerRole: ComposedRole?
        /// Laws left by tales that finished. These are the reason a bound tale
        /// keeps mattering: the Book writes differently afterwards because
        /// something is now true that was not true before.
        var standingTaleLaws: [String] = []
        /// A second half the reader's role earned by living through a tale that
        /// cost them something. Never a title; always a consequence.
        var roleTransformationClause: String?
        /// The tale the reader is currently inside, if the Book has worked out
        /// that they are. The braid never names it: a tale announced while it
        /// is running stops being one, but it colours what the Book reaches for.
        var openTale: LivingTale?
        /// The one backward-looking move selected before either writer begins.
        /// A Gemma winner and a house-writer winner therefore inherit and
        /// persist the same night-to-night state.
        var continuityBeat: ContinuityBeat?
        /// Derived from prior braid residue, never a second persistence ledger.
        /// A real-life rhyme rests for four weeks after it speaks.
        var lastEvidenceRhymeAt: Date?
        /// How many nights ago the Book last used each authored sentence.
        ///
        /// Recorded as `braid-move:` tags on the kept braid pages themselves,
        /// so the ledger lives in the archive without a schema of its own and
        /// cannot drift out of step with the pages it describes. Ages rather
        /// than a plain set, because when every option in a shallow pool has
        /// been used the right answer is the one used longest ago: a set can
        /// only say "all rested" and then fall back to the same line forever.
        var recentMoveAges: [String: Int] = [:]
        /// How long the Book has been keeping each subject.
        ///
        /// This is the one thing the house writer can see that a language model
        /// structurally cannot: Gemma reads tonight through a prompt already at
        /// its context limit, while this is the whole archive, counted.
        var subjectHistory: [String: SubjectHistory] = [:]

        static let empty = Context()
    }

    /// A subject the reader has written about before tonight.
    struct SubjectHistory: Equatable {
        /// Days before tonight on which this word appeared in a story receipt.
        var occasions: Int
        var firstSeen: Date
        var lastSeen: Date
    }

    struct SouvenirAnchor: Equatable {
        var pageID: String
        var pageTitle: String
        var keptText: String
        var keptAt: Date
        var reason: String
        var score: Int
    }

    enum ContinuityKind: String, Codable, Equatable {
        case fictionOpening
        case fictionContinuation
        case fictionResolution
        case evidenceRhyme
    }

    enum FictionThreadState: String, Codable, Equatable {
        case opened
        case continued
        case resolved
    }

    /// The one backward-looking move tonight has earned.
    ///
    /// Fiction may continue freely because it makes no claim about the reader.
    /// A rhyme in the reader's life carries Page IDs and a concrete old line so
    /// it remains inspectable rather than becoming manufactured significance.
    struct ContinuityBeat: Equatable {
        var kind: ContinuityKind
        var threadID: String?
        var sourceBraidPageID: String?
        var sourceTitle: String?
        var priorAnchor: String?
        /// The supplied object that changed the thread on its most recent Page.
        /// The original anchor remains separate so a third night can remember
        /// both where the incident began and what happened to it yesterday.
        var previousAnchor: String? = nil
        var currentAnchor: String
        var priorLine: String?
        var elapsedDays: Int?
        var evidencePageIDs: [String]
        var reason: String?

        var fictionState: FictionThreadState? {
            switch kind {
            case .fictionOpening: return .opened
            case .fictionContinuation: return .continued
            case .fictionResolution: return .resolved
            case .evidenceRhyme: return nil
            }
        }

        var promptSection: String {
            switch kind {
            case .fictionOpening:
                return """


                BRAID CONTINUITY: OPEN ONE FICTION THREAD
                Thread: \(threadID ?? "unnamed")
                Tonight's supplied anchor: \(currentAnchor)
                Let the Book's world begin one small piece of business with that anchor. Leave a concrete loose end. Do not claim this happened in the reader's ordinary biography.
                """
            case .fictionContinuation:
                return """


                BRAID CONTINUITY: CONTINUE, DO NOT REINTRODUCE
                Thread: \(threadID ?? "unnamed")
                Earlier braid: \(sourceTitle ?? "an earlier Page") [\(sourceBraidPageID ?? "unknown")]
                Earlier fictional anchor: \(priorAnchor ?? "not retained")
                Previous night's supplied anchor: \(previousAnchor ?? priorAnchor ?? "not retained")
                Tonight's supplied anchor: \(currentAnchor)
                \(elapsedDays.map { "Elapsed calendar days: \($0)" } ?? "")
                The earlier business is already underway. Advance it by one visible notch using today's supplied anchor; preserve the earlier anchor's identity. Do not recap the old Page or silently replace its object with today's.
                """
            case .fictionResolution:
                return """


                BRAID CONTINUITY: LAND THE FICTION THREAD
                Thread: \(threadID ?? "unnamed")
                Earlier braid: \(sourceTitle ?? "an earlier Page") [\(sourceBraidPageID ?? "unknown")]
                Original fictional anchor: \(priorAnchor ?? "not retained")
                Previous night's supplied anchor: \(previousAnchor ?? priorAnchor ?? "not retained")
                Tonight's supplied anchor: \(currentAnchor)
                Give this small piece of Book-world business a consequence or a crooked ending. Preserve the original anchor. Resolve the incident, not the reader's life.
                """
            case .evidenceRhyme:
                return """


                BRAID CONTINUITY: ONE EVIDENCE-BACKED RHYME
                Earlier braid: \(sourceTitle ?? "an earlier Page") [\(sourceBraidPageID ?? "unknown")]
                Concrete earlier line: \(priorLine ?? "not retained")
                Tonight's supplied anchor: \(currentAnchor)
                Evidence Pages: \(evidencePageIDs.joined(separator: ", "))
                Reason this return was selected: \(reason ?? "today answered an older Page by feeling")
                Let the earlier Page return once, changed by today's supplied evidence. Name it concretely enough that the reader can recognize the callback. Do not claim a cause, destiny, or settled pattern.
                """
            }
        }
    }

    static func context(
        for day: BookDay,
        days: [BookDay],
        themes: [BookTheme] = [],
        entityBeliefOffsets: [String: Int] = [:],
        learnedNotes: [String] = [],
        nowPlaying: String? = nil,
        activeWorldEvents: [ResolvedWorldEvent] = [],
        castUndertakings: [CastUndertaking] = [],
        readerLexicon: ReaderLexicon = ReaderLexicon(),
        readerLearning: ReaderLearningModel = ReaderLearningModel(),
        facultyEntries: [FacultyEntry] = [],
        people: PeopleLedger = PeopleLedger(),
        continuity: LiteraryContinuityDigest = .empty,
        bookReadingBoundaries: [BookReadingBoundary] = [],
        semanticScorer: StacksSemanticScoring? = nil,
        readerStory: ReaderStory = .empty,
        readerRole: ComposedRole? = nil,
        standingTaleLaws: [String] = [],
        roleTransformationClause: String? = nil,
        openTale: LivingTale? = nil,
        bookRelationship: BookRelationshipSnapshot = .firstOpening,
        bookInterior: BookInteriorState = .unawakened,
        now: Date = Date(),
        calendar: Calendar = .current
    ) -> Context {
        // The explicitly supplied day is authoritative. The persisted archive
        // can lag behind an in-flight evening capture by one save. Narrow the
        // complete archive before deriving *any* Page-shaped context: a sealed
        // sentence must not sneak back as patina, learning, or a Loom feature.
        // A cross-midnight braid day is an evidence lens, not a replacement
        // archive row. Keep the real current day beside it so Pages outside the
        // interval are not mistaken for newly sealed/revoked material. Ordinary
        // callers still replace the possibly stale archived copy as before.
        let allDays = day.captureWindowPageIDs == nil
            ? days.filter { $0.id != day.id } + [day]
            : days + [day]
        let weavableArchive = allDays.map {
            weavableDay($0, readerStory: readerStory)
        }
        let weavableToday = weavableDay(day, readerStory: readerStory)
        let permittedPageIDs = Set(weavableArchive.flatMap(\.pages).map(\.id))
        let allPageIDs = Set(allDays.flatMap(\.pages).map(\.id))
        let forbiddenPageIDs = allPageIDs.subtracting(permittedPageIDs)
        let forbiddenDayIDs = Set(allDays.flatMap { archiveDay -> [String] in
            let revokedPages = archiveDay.pages.filter { forbiddenPageIDs.contains($0.id) }
            guard !revokedPages.isEmpty else { return [] }
            return [archiveDay.id] + revokedPages.map {
                BookDay.id(for: $0.createdAt, calendar: calendar)
            }
        })
        let permittedContinuity = LiteraryContinuityDigest(
            signals: continuity.signals.filter { signal in
                let evidence = Set(signal.evidencePageIDs)
                return evidence.isEmpty || evidence.isSubset(of: permittedPageIDs)
            },
            beliefLifecycles: continuity.beliefLifecycles.filter { profile in
                let evidence = Set(profile.evidencePageIDs)
                return evidence.isEmpty || evidence.isSubset(of: permittedPageIDs)
            }
        )
        let contextualReaderLearning: ReaderLearningModel
        if forbiddenPageIDs.isEmpty {
            contextualReaderLearning = readerLearning
        } else {
            var filtered = ReaderLearningModel()
            for event in readerLearning.events {
                let referencedIDs = Set(
                    [event.surfaceID, event.sourceID, event.contentKey].compactMap { $0 }
                )
                // A kept Page currently receives a fresh BookPage UUID, so old
                // learning events cannot always be joined back to that Page by
                // identity. When any Page from a day is revoked, drop that
                // day's Page-shaped learning as a conservative unit rather than
                // letting an unprovable tag survive the reader's seal.
                if !forbiddenDayIDs.contains(event.dayID),
                   referencedIDs.isDisjoint(with: forbiddenPageIDs) {
                    filtered.record(event)
                }
            }
            contextualReaderLearning = filtered
        }

        let eligiblePages = braidEligiblePages(in: weavableToday)
        let recentBraids = recentBraidTexts(excludingDayID: day.id, days: weavableArchive)
        let braidStyleMemory = recentBraidStyleMemory(before: day, in: weavableArchive)
        let memoryDigest = BindingMemorySpine.digest(
            days: weavableArchive.filter { $0.id != day.id },
            now: now,
            limit: 6
        )
        let semanticEchoes = semanticEchoes(
            in: weavableToday,
            permittedSourcePageIDs: permittedPageIDs
        )
        let monthKey = BookThemeEngine.monthKey(for: day.date, calendar: calendar)
        let permittedThemes: [BookTheme]
        if forbiddenPageIDs.isEmpty {
            permittedThemes = themes
        } else {
            permittedThemes = themes.filter { candidate in
                let evidence = Set(candidate.evidencePageIDs)
                // A persisted theme contains Page-derived names, motifs, and
                // excerpt lines. If any of its receipts has since left the
                // weave, the old literary reading is no longer safe to quote or
                // use as color. Empty legacy evidence also fails closed once a
                // revocation exists because its provenance cannot be proved.
                return !evidence.isEmpty && evidence.isSubset(of: permittedPageIDs)
            }
        }
        let theme = BookThemeEngine.theme(forMonth: monthKey, in: permittedThemes)
        let chapter = TalismanAscendancy.ascendant(
            entities: NarrativePackRegistry.entities,
            beliefOffsets: entityBeliefOffsets
        ).flatMap { AcademyChapterRegistry.chapter(forTalismanID: $0.id) }
        let improvementContext = Context(
            recentBraids: recentBraids,
            braidStyleMemory: braidStyleMemory,
            theme: theme,
            chapter: chapter
        )
        let learned = BraidLearningLoop.guidance(
            fromPages: weavableArchive.flatMap(\.pages),
            context: improvementContext
        )
        // Reader-taught Gemma notes sort ahead of the deterministic heuristics:
        // the reader said this braid missed, and the Book listened.
        let merged = BraidLearningGuidance(signals: BraidLearningLoop.readerTaughtSignals(from: learnedNotes) + learned.signals)
        var passageInputs = BookSourceInputs.empty
        passageInputs.days = weavableArchive
        passageInputs.themes = permittedThemes
        let spineQuery = ([
            theme?.name ?? "",
            theme?.line ?? "",
            chapter?.name ?? "",
            chapter?.philosophy ?? ""
        ] + eligiblePages.flatMap { page in
            [
                page.promptText,
                genericBraidTags(for: page).joined(separator: " "),
                page.resolvedAttentionFingerprint.patternTokens.joined(separator: " ")
            ]
        } + semanticEchoes.lines).filter { !$0.isEmpty }.joined(separator: ". ")
        let meaningfulSpinePassages = MeaningfulPassageSelector.rankedSelections(
            pages: eligiblePages.filter { !isSupportingLog($0) },
            query: spineQuery,
            inputs: passageInputs,
            scorer: semanticScorer,
            limit: 3,
            maximumAge: 3 * 86_400,
            minimumScore: 14,
            honorPriorUse: false,
            diversifyPageTypes: true,
            now: now
        )

        var result = Context(
            recentBraids: recentBraids,
            braidStyleMemory: braidStyleMemory,
            theme: theme,
            chapter: chapter,
            bookVoicePatina: BookVoicePatina.derive(
                days: weavableArchive,
                readerLearning: contextualReaderLearning,
                now: now,
                calendar: calendar
            ),
            bookRelationship: bookRelationship,
            bookInterior: bookInterior,
            learnedGuidance: merged.signals.isEmpty ? nil : merged,
            nowPlaying: nowPlaying,
            activeWorldEvents: activeWorldEvents,
            castUndertakings: castUndertakings,
            readerLexicon: readerLexicon,
            readerLearningPromptLines: contextualReaderLearning.promptLines(now: now),
            memoryDigest: memoryDigest,
            recentDays: weavableArchive.filter { $0.id != day.id },
            semanticEchoSourceIDs: semanticEchoes.sourceIDs,
            semanticEchoLines: semanticEchoes.lines,
            meaningfulSpinePassages: meaningfulSpinePassages,
            souvenirAnchor: souvenirAnchor(in: weavableToday)
        )
        result.readerStory = readerStory
        result.readerRole = readerRole
        result.subjectHistory = subjectHistory(
            before: day,
            in: weavableArchive,
            calendar: calendar
        )
        result.recentMoveAges = recentMoveAges(before: day, in: weavableArchive)
        result.standingTaleLaws = standingTaleLaws
        result.roleTransformationClause = roleTransformationClause
        result.openTale = openTale
        result.taleReading = taleReading(for: weavableToday, context: result)
        let relationships = RelationalLoom.connections(
            days: weavableArchive,
            readerLearning: contextualReaderLearning,
            facultyEntries: facultyEntries,
            people: people,
            continuity: permittedContinuity,
            calendar: calendar
        )
        let relationalConstellations = RelationalLoom.constellations(connections: relationships)
        result.storyScore = nightlyStoryScore(
            for: weavableToday,
            context: result,
            connections: relationships,
            constellations: relationalConstellations,
            forbiddenObservationKeys: Set(bookReadingBoundaries.map(\.id)),
            now: now,
            calendar: calendar
        )
        // Continuity belongs to the Page's night, not to the wall clock at a
        // later rewrite. This keeps elapsed-day language stable when an older
        // braid is reread or reworded.
        let continuityNow = eligiblePages.map(\.createdAt).max() ?? weavableToday.date
        result.lastEvidenceRhymeAt = lastEvidenceRhymeDate(
            in: weavableArchive,
            before: continuityNow,
            excludingDayID: day.id
        )
        if let anchor = DeterministicBraidwright.continuityAnchor(
            for: weavableToday,
            context: result
        ) {
            result.continuityBeat = continuityBeat(
                for: weavableToday,
                context: result,
                currentAnchor: anchor,
                now: continuityNow,
                calendar: calendar
            )
        }
        return result
    }

    /// Stable Book-world businesses. The ID, not its position, is persisted:
    /// conditional tale material may grow around this list without changing
    /// what an older Page meant by `door` or `registry`.
    /// Every Book-world incident a night may begin, in one pool. This used to
    /// be the ten clerical threads only; the six where the world is actually
    /// alive were unreachable here, so a continued thread could never be the
    /// paper moth or the bell under the floor.
    static let serialFictionThreadIDs = [
        "stacks", "door", "index", "frost", "echo",
        "ribbon", "lamps", "birds", "rain", "doors",
        "moth", "stairs", "pocket", "bell", "dust", "roof"
    ]

    static let fictionContinuationDayWindow = 1...4
    static let evidenceRhymeRestDays = 28

    /// Chooses continuity from persisted braid residue before prose is written.
    /// The choice is therefore independent of which candidate later wins.
    static func continuityBeat(
        for day: BookDay,
        context: Context,
        currentAnchor: String,
        now: Date? = nil,
        calendar: Calendar = .current
    ) -> ContinuityBeat? {
        let writtenAt = now ?? day.date
        let start = calendar.startOfDay(for: writtenAt)

        // Finish warm fiction before opening another callback. The original
        // anchor comes from residue; today's noun may affect the incident but
        // may never silently replace what the prior Page was about.
        if let prior = context.memoryDigest.braids.first(where: { memory in
            guard let state = memory.residue.fictionThreadState,
                  state != .resolved,
                  memory.residue.fictionThreadID?.nonEmpty != nil,
                  memory.residue.fictionThreadAnchor?.nonEmpty != nil else { return false }
            let gap = calendar.dateComponents(
                [.day],
                from: calendar.startOfDay(for: memory.date),
                to: start
            ).day ?? Int.max
            return fictionContinuationDayWindow.contains(gap)
        }),
           let threadID = prior.residue.fictionThreadID,
           let priorAnchor = prior.residue.fictionThreadAnchor,
           let priorState = prior.residue.fictionThreadState {
            let elapsed = calendar.dateComponents(
                [.day],
                from: calendar.startOfDay(for: prior.date),
                to: start
            ).day
            return ContinuityBeat(
                kind: priorState == .opened ? .fictionContinuation : .fictionResolution,
                threadID: threadID,
                sourceBraidPageID: prior.pageID,
                sourceTitle: prior.residue.title,
                priorAnchor: priorAnchor,
                previousAnchor: prior.residue.fictionThreadLastAnchor,
                currentAnchor: currentAnchor,
                priorLine: prior.residue.callbackCandidate ?? prior.residue.spineLine,
                elapsedDays: elapsed,
                evidencePageIDs: [],
                reason: nil
            )
        }

        // A rhyme about the reader's life must be checkable and must rest. A
        // shared arc ID or semantic source is stronger than a loose word match;
        // ordinary motif recurrence may still colour the braid, but it does not
        // earn an explicit claim that two Pages rhyme.
        let rhymeHasRested: Bool
        if let last = context.lastEvidenceRhymeAt {
            let days = calendar.dateComponents(
                [.day],
                from: calendar.startOfDay(for: last),
                to: start
            ).day ?? 0
            rhymeHasRested = days >= evidenceRhymeRestDays
        } else {
            rhymeHasRested = true
        }
        if rhymeHasRested,
           let arc = context.storyScore?.arc,
           !arc.evidencePageIDs.isEmpty,
           let prior = context.memoryDigest.braids.first(where: { memory in
               let sameArc = !arc.id.hasPrefix("motif:")
                   && memory.residue.arcID == arc.id
               let semantic = !Set(memory.residue.semanticEchoIDs)
                   .intersection(context.semanticEchoSourceIDs).isEmpty
               return sameArc || semantic
           }) {
            return ContinuityBeat(
                kind: .evidenceRhyme,
                threadID: nil,
                sourceBraidPageID: prior.pageID,
                sourceTitle: prior.residue.title,
                priorAnchor: nil,
                currentAnchor: currentAnchor,
                priorLine: prior.residue.callbackCandidate ?? prior.residue.spineLine,
                elapsedDays: calendar.dateComponents(
                    [.day],
                    from: calendar.startOfDay(for: prior.date),
                    to: start
                ).day,
                evidencePageIDs: arc.evidencePageIDs,
                reason: "today's supplied evidence \(arc.movement.rawValue) an earlier braid thread"
            )
        }

        // No earned return: begin one small Book-world incident. Recently used
        // thread shapes rest so the Registry does not grow a column every week.
        let recentlyUsed = Set(
            context.memoryDigest.braids.prefix(6).compactMap {
                $0.residue.fictionThreadID
            }
        )
        let fresh = serialFictionThreadIDs.filter { !recentlyUsed.contains($0) }
        let pool = fresh.isEmpty ? serialFictionThreadIDs : fresh
        guard !pool.isEmpty else { return nil }
        let seed = continuityHash("\(day.id)|\(currentAnchor)")
        let threadID = pool[Int(seed % UInt64(pool.count))]
        return ContinuityBeat(
            kind: .fictionOpening,
            threadID: threadID,
            sourceBraidPageID: nil,
            sourceTitle: nil,
            priorAnchor: nil,
            currentAnchor: currentAnchor,
            priorLine: nil,
            elapsedDays: nil,
            evidencePageIDs: [],
            reason: nil
        )
    }

    private static func lastEvidenceRhymeDate(
        in days: [BookDay],
        before now: Date,
        excludingDayID: String
    ) -> Date? {
        days
            .filter { $0.id != excludingDayID }
            .flatMap(\.pages)
            .filter { $0.type == .bookOfYou && $0.createdAt < now }
            .filter {
                BookOfYouResidue.fromTags(in: $0)?.continuityKind == .evidenceRhyme
            }
            .map(\.createdAt)
            .max()
    }

    private static func continuityHash(_ value: String) -> UInt64 {
        var hash: UInt64 = 1_469_598_103_934_665_603
        for byte in value.utf8 {
            hash ^= UInt64(byte)
            hash = hash &* 1_099_511_628_211
        }
        return hash
    }

    static func nightlyStoryScore(
        for day: BookDay,
        context: Context,
        connections: [RelationalLoomConnection],
        constellations: [RelationalLoomConstellation],
        forbiddenObservationKeys: Set<String> = [],
        now: Date = Date(),
        calendar: Calendar = .current
    ) -> NightlyStoryScore {
        let eligible = braidEligiblePages(in: day).sorted { $0.createdAt < $1.createdAt }
        let livedPages = eligible.filter {
            braidShelf(for: $0) == "lived"
                && !isSupportingLog($0)
                && (ReaderShelf.of($0) != .shadow
                    || context.readerStory.shadowPermission != .knowButNeverWrite)
        }
        let passageRank = Dictionary(
            uniqueKeysWithValues: context.meaningfulSpinePassages.enumerated().map { ($0.element.pageID, $0.offset) }
        )
        let rankedLived = livedPages.sorted { left, right in
            let leftSouvenir = left.id == context.souvenirAnchor?.pageID ? 1 : 0
            let rightSouvenir = right.id == context.souvenirAnchor?.pageID ? 1 : 0
            if leftSouvenir != rightSouvenir { return leftSouvenir > rightSouvenir }
            let leftPassage = passageRank[left.id] ?? 99
            let rightPassage = passageRank[right.id] ?? 99
            if leftPassage != rightPassage { return leftPassage < rightPassage }
            let leftWords = storyScoreText(for: left).split(whereSeparator: \.isWhitespace).count
            let rightWords = storyScoreText(for: right).split(whereSeparator: \.isWhitespace).count
            if leftWords != rightWords { return leftWords > rightWords }
            return (left.createdAt, left.id) < (right.createdAt, right.id)
        }
        // How many lived beats the night can carry. A flat cap of three made
        // the braid scale *down* as the day got richer: a reader who kept five
        // real things got a page as thin as one who kept two, and two of their
        // pages never reached the braid at all. The scale already knows how big
        // tonight is: the beat count should follow it.
        let reading = context.taleReading ?? taleReading(for: day, context: context)
        let selectedLived = Array(rankedLived.prefix(reading.scale.livedBeatAllowance))
            .sorted { $0.createdAt < $1.createdAt }
        let livedBeats = selectedLived.enumerated().map { index, page in
            NightlyStoryScore.LivedBeat(
                pageID: page.id,
                pageType: page.type,
                occurredAt: page.createdAt,
                excerpt: clippedText(storyScoreText(for: page), limit: 220),
                role: page.id == context.souvenirAnchor?.pageID
                    ? "truth anchor"
                    : (index == 0 ? "opening evidence" : "supporting true beat")
            )
        }

        let todayPageIDs = Set(eligible.map(\.id))
        let allowedConstellations = constellations.filter {
            !forbiddenObservationKeys.contains($0.observationKey)
                && !todayPageIDs.isDisjoint(with: $0.evidencePageIDs)
        }
        let allowedConnections = connections.filter {
            !forbiddenObservationKeys.contains($0.observationKey)
                && !todayPageIDs.isDisjoint(with: $0.evidencePageIDs)
        }
        let relationalLens: NightlyStoryScore.RelationalLens?
        if let constellation = allowedConstellations.first {
            relationalLens = NightlyStoryScore.RelationalLens(
                connectionID: constellation.id,
                observationKey: constellation.observationKey,
                evidenceTier: constellation.evidenceTier,
                condition: constellation.condition.conditionClause,
                outcomes: constellation.branches.map { $0.outcome.outcomeClause },
                evidencePageIDs: constellation.evidencePageIDs,
                line: constellation.evidenceTier == .glimmer
                    ? "Hold this as a question: several parts of the day may be leaning together."
                    : "Several independently tested branches met around the same condition tonight."
            )
        } else if let connection = allowedConnections.first {
            relationalLens = NightlyStoryScore.RelationalLens(
                connectionID: connection.id,
                observationKey: connection.observationKey,
                evidenceTier: connection.evidenceTier,
                condition: connection.condition.conditionClause,
                outcomes: [connection.outcome.outcomeClause],
                evidencePageIDs: connection.evidencePageIDs,
                line: connection.evidenceTier == .glimmer
                    ? "Hold this as a question, not a declaration."
                    : "Tonight is another receipt in a relationship the archive has been testing."
            )
        } else {
            relationalLens = nil
        }

        // Every kept Labyrinth Page is a real receipt of the shared fictional
        // world. A reply or explicit choice still outranks passive color, but a
        // kept Academy event no longer becomes ineligible merely because the
        // reader did not answer it in a text field.
        let fictionCandidates = eligible.filter {
            isLabyrinthReceipt($0) && !isSupportingLog($0)
        }
        let livedWords = Set(livedBeats.flatMap { storyScoreWords(in: $0.excerpt) })
        let rankedFiction = fictionCandidates.sorted { left, right in
            let leftReply = left.playerReply.nonEmpty == nil ? 0 : 1
            let rightReply = right.playerReply.nonEmpty == nil ? 0 : 1
            if leftReply != rightReply { return leftReply > rightReply }
            let leftChoice = left.tags.contains(where: { $0.hasPrefix("choice:") }) ? 1 : 0
            let rightChoice = right.tags.contains(where: { $0.hasPrefix("choice:") }) ? 1 : 0
            if leftChoice != rightChoice { return leftChoice > rightChoice }
            let leftClash = left.tags.contains("clash") ? 1 : 0
            let rightClash = right.tags.contains("clash") ? 1 : 0
            if leftClash != rightClash { return leftClash > rightClash }
            let leftShared = Set(storyScoreWords(in: storyScoreText(for: left))).intersection(livedWords).count
            let rightShared = Set(storyScoreWords(in: storyScoreText(for: right))).intersection(livedWords).count
            if leftShared != rightShared { return leftShared > rightShared }
            let leftPassage = passageRank[left.id] ?? 99
            let rightPassage = passageRank[right.id] ?? 99
            if leftPassage != rightPassage { return leftPassage < rightPassage }
            return (left.createdAt, left.id) < (right.createdAt, right.id)
        }
        let chosenFiction = rankedFiction.first
        let fictionBeatFor = { (page: BookPage) -> NightlyStoryScore.FictionBeat in
            let words = Set(storyScoreWords(in: storyScoreText(for: page)))
            let shared = !words.intersection(livedWords).isEmpty
            let role: FictionRole
            if page.tags.contains("clash") {
                role = .counterpoint
            } else if relationalLens?.evidencePageIDs.contains(page.id) == true {
                role = .afterimage
            } else if shared, let lastLived = selectedLived.last, page.createdAt < lastLived.createdAt {
                role = .rehearsal
            } else if shared {
                role = .mirror
            } else {
                role = .pressure
            }
            return NightlyStoryScore.FictionBeat(
                pageID: page.id,
                occurredAt: page.createdAt,
                choice: clippedText(storyScoreText(for: page), limit: 220),
                role: role
            )
        }
        let fictionBeat = chosenFiction.map(fictionBeatFor)
        // The lead keeps its role and its crossing; the remainder are extra
        // real receipts, ranked by the same comparator, so a night with five
        // kept Labyrinth pages stops arriving at the writer as a night with one.
        let additionalFictionBeats = rankedFiction
            .dropFirst()
            .prefix(max(0, reading.scale.fictionBeatAllowance - 1))
            .map(fictionBeatFor)

        let arc = nightlyArc(
            day: day,
            livedBeats: livedBeats,
            fictionBeat: fictionBeat,
            relationalLens: relationalLens,
            context: context,
            now: now,
            calendar: calendar
        )
        let magicAnchor = livedBeats.first?.excerpt.nonEmpty ?? reading.anchor.nonEmpty ?? "one supplied ordinary thing"
        let magicLicense = "Use only \(reading.pressure.rawValue) around this supplied anchor: \(clippedText(magicAnchor, limit: 100)). One impossible relation is enough."
        let endingDuty = arc.map { "Land on tonight's \($0.movement.rawValue) movement: \($0.tonightDelta)" }
            ?? livedBeats.first.map { "Return changed to this exact lived anchor: \($0.excerpt)" }
            ?? "Admit that you witnessed the day without inventing a lesson."
        var forbiddenClaims = [
            "Do not invent an unsupplied mundane action or contradict a lived receipt when the worlds cross.",
            "Do not move a Labyrinth character into the reader's external biography as an ordinary claim; keep that trespass inside the one licensed impossible relation.",
            "Do not diagnose a feeling, motive, relationship, or cause.",
            "Do not invent a person, place, completed action, price, promise, or consequence."
        ]
        if relationalLens?.evidenceTier == .glimmer {
            forbiddenClaims.append("Do not state the relational glimmer as settled truth; let it remain a possibility.")
        }
        return NightlyStoryScore(
            livedBeats: livedBeats,
            fictionBeat: fictionBeat,
            additionalFictionBeats: Array(additionalFictionBeats),
            relationalLens: relationalLens,
            arc: arc,
            taleReading: reading,
            magicLicense: magicLicense,
            endingDuty: endingDuty,
            forbiddenClaims: forbiddenClaims
        )
    }

    private static func nightlyArc(
        day: BookDay,
        livedBeats: [NightlyStoryScore.LivedBeat],
        fictionBeat: NightlyStoryScore.FictionBeat?,
        relationalLens: NightlyStoryScore.RelationalLens?,
        context: Context,
        now: Date,
        calendar: Calendar
    ) -> NightlyStoryScore.ArcBeat? {
        let todayWords = Set(livedBeats.flatMap { storyScoreWords(in: $0.excerpt) })
        let relationalArcID = relationalLens?.observationKey
        let semanticArcID = context.semanticEchoSourceIDs.first.map { "semantic:\($0)" }
        let motifMatch = context.memoryDigest.braids.compactMap { memory -> (String, BindingMemoryDigest.BraidMemory)? in
            guard let motif = memory.residue.motifs.first(where: { todayWords.contains($0.lowercased()) }) else { return nil }
            return (memory.residue.arcID ?? "motif:\(motif.lowercased())", memory)
        }.first
        guard let arcID = relationalArcID ?? semanticArcID ?? motifMatch?.0 else { return nil }

        let prior = context.memoryDigest.braids.first { memory in
            memory.residue.arcID == arcID
                || memory.residue.relationalConnectionIDs.contains(arcID)
                || (relationalLens.map { memory.residue.relationalConnectionIDs.contains($0.connectionID) } ?? false)
        } ?? motifMatch?.1
        let allTags = Set(
            day.capturedPages.flatMap { genericBraidTags(for: $0) }.map { $0.lowercased() }
        )
        let movement: ArcMovement
        if allTags.contains(where: { $0.contains("resolved") || $0.contains("completed") || $0.contains("closed-thread") }) {
            movement = .resolved
        } else if fictionBeat?.role == .counterpoint, prior != nil {
            movement = .complicated
        } else if let prior {
            let gap = calendar.dateComponents(
                [.day],
                from: calendar.startOfDay(for: prior.date),
                to: calendar.startOfDay(for: now)
            ).day ?? 0
            movement = gap >= 4 ? .returned : .deepened
        } else {
            movement = .began
        }

        var deltaParts: [String] = []
        if let relationalLens {
            deltaParts.append("\(relationalLens.condition) met \(relationalLens.outcomes.joined(separator: " and "))")
        }
        if let lived = livedBeats.first {
            deltaParts.append("the lived receipt was \(clippedText(lived.excerpt, limit: 120))")
        }
        if let fictionBeat {
            deltaParts.append("the fictional choice served as \(fictionBeat.role.rawValue): \(clippedText(fictionBeat.choice, limit: 100))")
        }
        let delta = deltaParts.isEmpty
            ? "today's supplied evidence answered an older motif without repeating its old sentence"
            : joinedClauses(deltaParts)
        return NightlyStoryScore.ArcBeat(
            id: arcID,
            movement: movement,
            priorState: prior.flatMap { memory in
                memory.residue.arcDelta.flatMap(\.nonEmpty)
                    ?? memory.residue.callbackCandidate.flatMap(\.nonEmpty)
            },
            tonightDelta: delta,
            evidencePageIDs: Array(Set(livedBeats.map(\.pageID) + (relationalLens?.evidencePageIDs ?? []))).sorted(),
            fictionChoicePageIDs: fictionBeat.map { [$0.pageID] } ?? [],
            relationalConnectionIDs: relationalLens.map { [$0.connectionID, $0.observationKey] } ?? []
        )
    }

    static func storyScoreText(for page: BookPage) -> String {
        if braidShelf(for: page) == "fiction" {
            if let reply = page.playerReply.nonEmpty {
                let scene = page.userInput.nonEmpty ?? page.promptText.nonEmpty
                guard let scene, scene != reply else { return "Reader answer: \(reply)" }
                return "Kept scene: \(clippedText(scene, limit: 150)) Reader answer: \(reply)"
            }
            if let choice = page.tags.first(where: { $0.hasPrefix("choice:") }) {
                // Same hyphen-only laundering the braid's own route had; this
                // one reaches the prompt rather than the page, which makes it
                // quieter but no less wrong.
                let value = BookPage.humanizedChoice(String(choice.dropFirst("choice:".count)))
                let context = page.userInput.nonEmpty ?? page.promptText
                return "The reader chose \(value). \(clippedText(context, limit: 140))"
            }
        }
        return page.userInput.nonEmpty
            ?? page.playerReply.nonEmpty
            ?? mediaEvidence(for: page)
            ?? page.promptText
    }

    /// What a page the reader photographed or spoke into has to say.
    ///
    /// A kept photograph or voice note is a real receipt, and often the whole
    /// of what somebody kept that day. This returned nothing for them, so the
    /// page scored as textless, sorted last by word count, and was cut by the
    /// lived-beat allowance before it ever reached the writer - a reader whose
    /// evening was one photograph got a braid that did not know about it.
    ///
    /// The prompt path already read media. Only the deterministic writer, the
    /// one that writes most pages, was blind to it.
    ///
    /// Everything here is the reader's own words: a caption they wrote or a
    /// transcript of what they said. The Book never describes the image.
    static func mediaEvidence(for page: BookPage) -> String? {
        for asset in page.mediaAssets {
            if let transcript = asset.metadata[BookPageMediaAsset.voiceTranscriptMetadataKey]?
                .trimmingCharacters(in: .whitespacesAndNewlines).nonEmpty {
                return transcript
            }
        }
        for asset in page.mediaAssets {
            if let caption = asset.caption
                .trimmingCharacters(in: .whitespacesAndNewlines).nonEmpty {
                return caption
            }
        }
        return nil
    }

    private static func storyScoreWords(in text: String) -> [String] {
        let stop: Set<String> = [
            "about", "after", "again", "because", "before", "book", "could", "from", "have",
            "into", "kept", "page", "that", "their", "there", "they", "this", "through", "today",
            "when", "where", "with", "would", "your", "reader", "chose"
        ]
        return text.lowercased()
            .split { !$0.isLetter && !$0.isNumber }
            .map(String.init)
            .filter { $0.count >= 4 && !stop.contains($0) }
    }

    private static func joinedClauses(_ clauses: [String]) -> String {
        switch clauses.count {
        case 0: return ""
        case 1: return clauses[0]
        case 2: return "\(clauses[0]), and \(clauses[1])"
        default: return "\(clauses.dropLast().joined(separator: ", ")), and \(clauses.last ?? "")"
        }
    }

    static func souvenirAnchor(in day: BookDay) -> SouvenirAnchor? {
        braidEligiblePages(in: day)
            .compactMap(souvenirAnchorCandidate)
            .sorted { lhs, rhs in
                if lhs.score == rhs.score {
                    return lhs.keptAt > rhs.keptAt
                }
                return lhs.score > rhs.score
            }
            .first
    }

    private static func souvenirAnchorCandidate(for page: BookPage) -> SouvenirAnchor? {
        let text = souvenirText(for: page)
        guard !text.isEmpty else { return nil }

        let lowerPrompt = page.promptText.lowercased()
        let lowerSource = page.sourceID.lowercased()
        let lowerTags = Set(genericBraidTags(for: page).map { $0.lowercased() })
        let isExplicitSouvenir = page.type == .souvenir
            || lowerSource == "one-sentence-souvenir"
            || lowerTags.contains("one-sentence-souvenir")
            || lowerTags.contains("souvenir")
            || lowerTags.contains("first-run-souvenir")
            || lowerTags.contains("onboarding-first-souvenir")
        let promptAsksForSentence = lowerPrompt.contains("one sentence")
            || lowerPrompt.contains("one-sentence")
            || lowerPrompt.contains("one true")
            || lowerPrompt.contains("souvenir")
        guard isExplicitSouvenir || promptAsksForSentence else { return nil }

        var score = 0
        switch page.origin {
        case .userAuthored, .imported:
            score += 40
        case .generated, .simulated:
            score += 10
        }
        if page.type == .souvenir { score += 100 }
        if lowerTags.contains("one-sentence-souvenir") { score += 90 }
        if lowerSource == "one-sentence-souvenir" { score += 80 }
        if lowerTags.contains("first-run-souvenir") || lowerTags.contains("onboarding-first-souvenir") { score += 60 }
        if lowerTags.contains("souvenir") { score += 45 }
        if lowerPrompt.contains("one sentence") || lowerPrompt.contains("one-sentence") || lowerPrompt.contains("one true") { score += 35 }
        if lowerPrompt.contains("souvenir") { score += 20 }
        if looksLikeOneSentence(text) { score += 25 }
        if (20...180).contains(text.count) { score += 10 }

        return SouvenirAnchor(
            pageID: page.id,
            pageTitle: page.type.title,
            keptText: clippedText(text, limit: 220),
            keptAt: page.createdAt,
            reason: souvenirReason(for: page, tags: lowerTags, promptAsksForSentence: promptAsksForSentence),
            score: score
        )
    }

    private static func souvenirText(for page: BookPage) -> String {
        let primary = page.readerAuthoredTextForAnalysis ?? ""
        return clippedText(primary, limit: 260)
    }

    private static func looksLikeOneSentence(_ text: String) -> Bool {
        let words = text.split { $0.isWhitespace }.count
        guard (3...36).contains(words) else { return false }
        let sentenceBreaks = text.filter { ".!?".contains($0) }.count
        return sentenceBreaks <= 2
    }

    private static func souvenirReason(for page: BookPage, tags: Set<String>, promptAsksForSentence: Bool) -> String {
        if page.type == .souvenir {
            return "explicit One-Sentence Souvenir"
        }
        if tags.contains("one-sentence-souvenir") {
            return "one-sentence souvenir kept from another page"
        }
        if tags.contains("first-run-souvenir") || tags.contains("onboarding-first-souvenir") {
            return "first souvenir I learned from the reader"
        }
        if promptAsksForSentence {
            return "this page asked the reader for one true sentence"
        }
        return "reader-authored souvenir signal"
    }

    static func semanticEchoes(
        in day: BookDay,
        permittedSourcePageIDs: Set<String>? = nil
    ) -> (sourceIDs: [String], lines: [String]) {
        var sourceIDs: [String] = []
        var lines: [String] = []
        var seenSourceIDs: Set<String> = []
        var seenLines: Set<String> = []

        for page in braidEligiblePages(in: day) {
            let pageSourceIDs = uniqueTagValues(
                withPrefix: SemanticKeepEcho.sourceTagPrefix,
                in: page.tags
            )
            if let permittedSourcePageIDs {
                // The source and its quoted line travel as one receipt. A Page
                // can accumulate tags, so if even one source can no longer be
                // proven we drop that Page's echo bundle rather than risk
                // pairing a forbidden line with an allowed source ID.
                guard !pageSourceIDs.isEmpty,
                      pageSourceIDs.allSatisfy(permittedSourcePageIDs.contains) else {
                    continue
                }
            }

            for sourceID in pageSourceIDs where seenSourceIDs.insert(sourceID).inserted {
                sourceIDs.append(sourceID)
            }
            for line in uniqueTagValues(
                withPrefix: SemanticKeepEcho.lineTagPrefix,
                in: page.tags
            ) where seenLines.insert(line).inserted {
                lines.append(line)
            }
        }
        return (sourceIDs, lines)
    }

    /// Semantic-echo tags transport a separately permission-checked receipt.
    /// They are never ordinary Page metadata: the line tag contains an exact
    /// older excerpt, and generic tag joins feed story analysis and the model
    /// evidence ledger. `semanticEchoes` above is their sole route into a braid.
    private static func genericBraidTags(for page: BookPage) -> [String] {
        page.tags.filter { tag in
            tag != SemanticKeepEcho.markerTag
                && !tag.hasPrefix(SemanticKeepEcho.sourceTagPrefix)
                && !tag.hasPrefix(SemanticKeepEcho.lineTagPrefix)
        }
    }

    private static func uniqueTagValues(withPrefix prefix: String, in tags: [String]) -> [String] {
        var seen: Set<String> = []
        var values: [String] = []
        for tag in tags where tag.hasPrefix(prefix) {
            let value = String(tag.dropFirst(prefix.count)).trimmingCharacters(in: .whitespacesAndNewlines)
            guard !value.isEmpty, !seen.contains(value) else { continue }
            seen.insert(value)
            values.append(value)
        }
        return values
    }

    static func recentBraidTexts(excludingDayID dayID: String, days: [BookDay], limit: Int = 2) -> [String] {
        let braids = days
            .filter { $0.id != dayID }
            .sorted { $0.date < $1.date }
            .flatMap { day in day.pages.filter { $0.type == .bookOfYou } }
        guard !braids.isEmpty else { return [] }

        var selected: [BookPage] = []
        if let newest = braids.last {
            selected.append(newest)
        }
        if braids.count >= 5 {
            selected.append(braids[braids.count - 5])
        }

        return selected
            .prefix(limit)
            .map { clippedText($0.userInput, limit: 700) }
    }

    /// The continuity shelf asks whether an old image should return. This
    /// separate shelf asks whether the Book itself has started repeating a
    /// performance. It reads the final archived prose, including accepted model
    /// revisions, so the memory cannot be fooled by compiler tags describing a
    /// sentence the reader never actually saw.
    static func recentBraidStyleMemory(
        before day: BookDay,
        in archive: [BookDay],
        nights: Int = 14
    ) -> BraidStyleMemory {
        let recentDays = archive
            .filter { $0.id != day.id && $0.date < day.date }
            .filter { archiveDay in
                archiveDay.pages.contains { $0.type == .bookOfYou }
            }
            .sorted { $0.date > $1.date }
            .prefix(nights)
        var memory = BraidStyleMemory.empty
        for (age, archiveDay) in recentDays.enumerated() {
            let braids = archiveDay.pages
                .filter { $0.type == .bookOfYou }
                .sorted { $0.createdAt > $1.createdAt }
            for braid in braids {
                let body = BraidPageDetails.details(for: braid).body
                guard !body.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { continue }
                memory.remember(prose: body, age: age)
            }
        }
        return memory
    }

    static func taleReading(for day: BookDay, context: Context = .empty) -> TaleReading {
        let partition = partitionedPagesForBraid(in: day)
        let storyPages = partition.story.filter { page in
            let isPermittedShadow = ReaderShelf.of(page) != .shadow
                || context.readerStory.shadowPermission != .knowButNeverWrite
            let isStoryReceipt = braidShelf(for: page) == "lived" || isLabyrinthReceipt(page)
            return isPermittedShadow && isStoryReceipt
        }
        // What the writer can actually draw on, which is not the same as what
        // the reader typed. A kept Labyrinth receipt carries its scene in
        // `promptText` when the reader did not answer it, and the atom builder
        // already falls back to exactly that. Counting only `userInput` here
        // made a night that was half kept fiction read as a thin night, so the
        // scale gate handed it a small band and the filler loop bought the
        // difference in clerical moves. Measure the same text the page will use.
        let storyCharacters = storyPages.reduce(0) { total, page in
            // Same bug, second place: a kept photograph or voice note counted
            // as zero, so an evening made of one photograph and one recording
            // scored as a night with nothing in it, took a glimpse band, and
            // then had two lived beats to spend across four kept pages.
            let body = page.userInput.nonEmpty
                ?? (isLabyrinthReceipt(page) ? page.promptText.nonEmpty : nil)
                ?? mediaEvidence(for: page)
                ?? ""
            return total + body.count + page.playerReply.count
        }
        // Scale is bounded by evidence on purpose. Promoting a thin night to a
        // larger band was tried and measured: the bench went from 14 nights in
        // band to 4, because a two-receipt night cannot honestly fill 180-300
        // words and the writer should not pad it. A night earns room; it is not
        // granted room and then asked to find filling for it.
        let scale: BraidScale
        if storyPages.count <= 1 || storyCharacters < 180 {
            // A genuinely thin night stays thin. Either test alone is enough to
            // hold it down, and that stays `||` on purpose: this is the branch
            // the measurement above was defending.
            scale = .glimpse
        } else if storyPages.count <= 3 && storyCharacters < 620 {
            // Both tests must agree before a night is called small. As `||` a
            // low character count could veto a page-rich night outright, so a
            // reader who kept eleven things got the same band as one who kept
            // three - and then the writer padded to reach it.
            scale = .small
        } else {
            scale = .full
        }

        let motion = narrativeMotion(in: storyPages)
        let pressure: FaeriePressure
        switch motion {
        case .repair:
            pressure = .agency
        case .bargain:
            pressure = .debt
        case .crossing:
            pressure = .threshold
        case .refusal:
            pressure = .rule
        case .recurrence:
            pressure = .rhyme
        case .returnOfSomething:
            pressure = .timeSlip
        case .vigil:
            pressure = storyPages.contains(where: pageCarriesAbsence) ? .absence : .witness
        case .encounter:
            pressure = .witness
        }

        let anchor: (pageID: String?, text: String)
        if let souvenir = context.souvenirAnchor ?? souvenirAnchor(in: day) {
            anchor = (souvenir.pageID, souvenir.keptText)
        } else if let passage = context.meaningfulSpinePassages.first {
            anchor = (passage.pageID, passage.excerpt)
        } else if let page = storyPages
            .sorted(by: anchorGravitySort)
            .first {
            anchor = (
                page.id,
                clippedText(page.playerReply.nonEmpty ?? page.userInput.nonEmpty ?? BraidPromptBuilder.mediaEvidence(for: page) ?? page.promptText, limit: 220)
            )
        } else if let log = partition.supportingLogs.first {
            anchor = (log.id, clippedText(log.userInput.nonEmpty ?? log.promptText, limit: 180))
        } else {
            anchor = (nil, "")
        }

        let turn = suppliedTurn(in: storyPages, motion: motion)
        let rutReading = rutReading(in: storyPages)
        let form = storyForm(in: storyPages, motion: motion)
        return TaleReading(
            scale: scale,
            motion: motion,
            pressure: pressure,
            anchorPageID: anchor.pageID,
            anchor: anchor.text,
            turn: turn,
            visibleSupportingLogs: storyPages.isEmpty || supportingLogsMateriallyConnect(
                partition.supportingLogs,
                to: storyPages
            ),
            storyForm: form,
            rutInfluence: rutReading.influence,
            narrativeRegister: narrativeRegister(
                in: storyPages,
                form: form,
                motion: motion,
                rutInfluence: rutReading.influence
            ),
            rutEvidencePageIDs: rutReading.pageIDs
        )
    }

    private static func narrativeMotion(in pages: [BookPage]) -> NarrativeMotion {
        guard !pages.isEmpty else { return .vigil }
        let text = pages.map(pageSignalText).joined(separator: " ")
        var scores = Dictionary(uniqueKeysWithValues: NarrativeMotion.allCases.map { ($0, 0) })

        score(["repair", "repaired", "fixed", "mended", "mend", "tended", "cleaned", "washed", "stitched", "tightened"], in: text, as: .repair, into: &scores)
        score(["bargain", "price", "paid", "cost", "promised", "traded", "chose", "choice", "offered"], in: text, as: .bargain, into: &scores)
        score(["refused", "declined", "wouldn't", "would not", "said no", "protected", "defended", "stood down"], in: text, as: .refusal, into: &scores)
        score(["again", "repeated", "returned", "third time", "kept happening", "once more"], in: text, as: .recurrence, into: &scores)
        score(["remembered", "older", "used to", "years ago", "last week", "last month", "came back"], in: text, as: .returnOfSomething, into: &scores)
        score(["entered", "left", "crossed", "opened", "arrived", "went to", "walked into", "through the door"], in: text, as: .crossing, into: &scores)
        score(["met", "called", "answered", "message", "package", "visitor", "knocked", "appeared", "found"], in: text, as: .encounter, into: &scores)
        score(["waited", "stayed", "carried", "unfinished", "still there", "sat with", "kept watch", "held"], in: text, as: .vigil, into: &scores)

        if pages.contains(where: { !$0.playerReply.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }) {
            scores[.bargain, default: 0] += 4
        }
        if pages.contains(where: { $0.tags.contains("clash") }) {
            scores[.refusal, default: 0] += 8
        }
        if pages.contains(where: { $0.type == .bookRemembered }) {
            scores[.returnOfSomething, default: 0] += 7
        }

        let ranked = NarrativeMotion.allCases.sorted { lhs, rhs in
            let left = scores[lhs, default: 0]
            let right = scores[rhs, default: 0]
            if left == right {
                return NarrativeMotion.allCases.firstIndex(of: lhs)! < NarrativeMotion.allCases.firstIndex(of: rhs)!
            }
            return left > right
        }
        guard let winner = ranked.first, scores[winner, default: 0] > 0 else {
            return pages.count <= 1 ? .vigil : .encounter
        }
        return winner
    }

    private static func storyForm(
        in pages: [BookPage],
        motion: NarrativeMotion
    ) -> StoryForm {
        guard !pages.isEmpty else { return .vigil }
        let text = pages.map(pageSignalText).joined(separator: " ")
        if containsAny([
            "laughed", "laughing", "funny", "ridiculous", "absurd",
            "mishap", "embarrassed", "comic", "couldn't stop laughing"
        ], in: text) {
            return .comedy
        }
        switch motion {
        case .returnOfSomething, .recurrence:
            return .returnForm
        case .crossing:
            return .crossing
        case .bargain, .refusal:
            return .drama
        case .vigil:
            return .vigil
        case .repair, .encounter:
            break
        }
        if pages.count >= 4 {
            return .mosaic
        }
        if pages.contains(where: { page in
            page.tags.contains("person")
                || page.tags.contains(where: { $0.hasPrefix("person:") || $0.hasPrefix("place:") })
        }) {
            return .portrait
        }
        return .sliceOfLife
    }

    private static func rutReading(
        in pages: [BookPage]
    ) -> (influence: RutInfluence, pageIDs: [String]) {
        let explicitTags: Set<String> = [
            "rut-battle",
            "rut-of-routine",
            "attention-probe",
            "routine-memory",
            "living-ink-rut",
            "rut-reopened",
            "grey-threat-rescued"
        ]
        let takingPhrases = [
            "autopilot",
            "mind wandered",
            "mind-wandering",
            "don't remember doing",
            "do not remember doing",
            "can't remember doing",
            "went through the motions",
            "the whole hour disappeared",
            "hours went missing",
            "blurred past",
            "forgot the whole",
            "did it automatically"
        ]
        let reopenedPhrases = [
            "opened again",
            "looked new again",
            "became strange again",
            "familiar thing changed",
            "saw it for the first time again"
        ]
        let evidence = pages.filter { page in
            let text = pageSignalText(page)
            return !explicitTags.isDisjoint(with: Set(page.tags))
                || page.tags.contains(where: { $0.hasPrefix("rut-") })
                || takingPhrases.contains(where: text.contains)
                || reopenedPhrases.contains(where: text.contains)
        }
        guard !evidence.isEmpty else { return (.notInThisTelling, []) }

        let text = evidence.map(pageSignalText).joined(separator: " ")
        let reopened = evidence.contains {
            $0.tags.contains("rut-reopened")
                || $0.tags.contains("living-ink-reopened")
                || $0.tags.contains("grey-threat-rescued")
        } || reopenedPhrases.contains(where: text.contains)
        if reopened {
            return (.reopened, evidence.map(\.id).sorted())
        }

        let took = takingPhrases.contains(where: text.contains)
        let resisted = [
            "noticed", "caught it", "caught myself", "looked again",
            "remembered", "came back to the room", "returned my attention",
            "interrupted the routine", "stopped scrolling"
        ].contains(where: text.contains)
        let influence: RutInfluence
        switch (took, resisted) {
        case (true, true): influence = .mixed
        case (true, false): influence = .tookSomething
        case (false, true): influence = .resisted
        case (false, false): influence = .pressing
        }
        return (influence, evidence.map(\.id).sorted())
    }

    private static func narrativeRegister(
        in pages: [BookPage],
        form: StoryForm,
        motion: NarrativeMotion,
        rutInfluence: RutInfluence
    ) -> NarrativeRegister {
        let text = pages.map(pageSignalText).joined(separator: " ")
        if form == .comedy { return .wry }
        if containsAny([
            "grief", "grieving", "died", "death", "sick", "illness",
            "care", "cared for", "held her", "held him", "afraid", "love"
        ], in: text) {
            return .tender
        }
        if motion == .refusal
            || pages.contains(where: { $0.tags.contains("clash") })
            || [.tookSomething, .resisted, .mixed].contains(rutInfluence) {
            return .fierce
        }
        if motion == .returnOfSomething || motion == .recurrence {
            return .uncanny
        }
        if containsAny([
            "wonder", "wonderful", "beautiful", "delight", "joy",
            "glorious", "astonished", "bright", "alive"
        ], in: text) {
            return .luminous
        }
        return .plain
    }

    private static func containsAny(_ needles: [String], in text: String) -> Bool {
        needles.contains(where: text.contains)
    }

    private static func score(
        _ needles: [String],
        in text: String,
        as motion: NarrativeMotion,
        into scores: inout [NarrativeMotion: Int]
    ) {
        scores[motion, default: 0] += needles.reduce(0) { partial, needle in
            partial + (text.contains(needle) ? 2 : 0)
        }
    }

    private static func pageSignalText(_ page: BookPage) -> String {
        "\(page.promptText) \(page.userInput) \(page.playerReply) \(genericBraidTags(for: page).joined(separator: " "))"
            .lowercased()
    }

    private static func anchorGravitySort(_ lhs: BookPage, _ rhs: BookPage) -> Bool {
        func gravity(_ page: BookPage) -> Int {
            var value = 0
            if page.origin == .userAuthored || page.origin == .imported { value += 20 }
            if !page.playerReply.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { value += 18 }
            if page.type == .souvenir { value += 30 }
            if page.tags.contains("clash") { value += 12 }
            return value
        }
        let left = gravity(lhs)
        let right = gravity(rhs)
        return left == right ? lhs.createdAt > rhs.createdAt : left > right
    }

    private static func suppliedTurn(in pages: [BookPage], motion: NarrativeMotion) -> String? {
        if let reply = pages
            .sorted(by: anchorGravitySort)
            .compactMap({ $0.playerReply.trimmingCharacters(in: .whitespacesAndNewlines).nonEmpty })
            .first {
            return clippedText(reply, limit: 180)
        }
        let needles: [String]
        switch motion {
        case .repair: needles = ["repair", "fixed", "mended", "tended", "cleaned", "stitched"]
        case .bargain: needles = ["bargain", "paid", "cost", "promised", "traded", "chose", "choice"]
        case .refusal: needles = ["refused", "declined", "wouldn't", "would not", "said no", "protected", "defended"]
        case .crossing: needles = ["entered", "left", "crossed", "opened", "arrived", "went to", "walked into"]
        case .recurrence: needles = ["again", "repeated", "returned", "once more"]
        case .returnOfSomething: needles = ["remembered", "older", "used to", "came back"]
        case .encounter: needles = ["met", "called", "answered", "message", "package", "visitor", "found"]
        case .vigil: return nil
        }
        return pages
            .filter { page in needles.contains { pageSignalText(page).contains($0) } }
            .sorted(by: anchorGravitySort)
            .compactMap { ($0.userInput.nonEmpty ?? $0.promptText.nonEmpty).map { clippedText($0, limit: 180) } }
            .first
    }

    private static func pageCarriesAbsence(_ page: BookPage) -> Bool {
        let text = pageSignalText(page)
        return ["missing", "didn't", "did not", "never", "without", "unfinished", "unsaid", "avoided"]
            .contains { text.contains($0) }
    }

    private static func supportingLogsMateriallyConnect(_ logs: [BookPage], to storyPages: [BookPage]) -> Bool {
        guard !logs.isEmpty, !storyPages.isEmpty else { return false }
        let logWords = Set(logs.flatMap { SemanticKeepEcho.contentWords(in: pageSignalText($0)) })
        let storyWords = Set(storyPages.flatMap { SemanticKeepEcho.contentWords(in: pageSignalText($0)) })
        return !logWords.intersection(storyWords).isEmpty
    }

    static func prompt(for day: BookDay, recentBraids: [String] = []) -> String {
        prompt(for: day, context: Context(recentBraids: recentBraids))
    }

    static func prompt(for day: BookDay, context: Context) -> String {
        if let storyScore = context.storyScore {
            return compactStoryScorePrompt(for: day, context: context, score: storyScore)
        }
        let eligiblePages = braidEligiblePages(in: day)
        let evidence = evidenceLines(for: day).joined(separator: "\n\n")
        let souvenirSection = souvenirSpineSection(for: day, context: context)
        let meaningfulSpineSection = meaningfulSpineSection(context: context)
        let taleReading = context.taleReading ?? taleReading(for: day, context: context)
        let continuity: String
        if context.recentBraids.isEmpty {
            continuity = ""
        } else {
            let earlier = context.recentBraids.enumerated()
                .map { index, braid in "EARLIER BRAID \(index + 1):\n\(braid)" }
                .joined(separator: "\n\n")
            continuity = """


            EARLIER PAGES OF THE BOOK OF YOU (continuity, not material):
            \(earlier)

            CONTINUITY RULE: (At most one image or motif from an earlier braid may return today, changed by what today actually held.) Never repeat an earlier braid's sentences and never re-describe its events. Today's kept pages are the only material. (If nothing from earlier honestly connects, let nothing return.) Routine Weather, Body, or Inner Weather details repeating on another day are not continuity by themselves. Do not call them back unless a non-log keep makes them newly consequential.
            """
        }
        let themeSection: String
        if let theme = context.theme {
            themeSection = """


            MONTHLY THEME THREAD:
            \(theme.promptLine)

            THEME RULE: (Let this theme behave like a faint running head or watermark, not a thesis statement.) Use at most one of its motifs unless today's kept pages clearly invite more.
            """
        } else {
            themeSection = ""
        }

        let chapterSection: String
        if let chapter = context.chapter {
            chapterSection = """


            CHAPTER WEATHER:
            Chapter \(chapter.name)
            Philosophy: \(chapter.philosophy)
            Talisman: \(chapter.talismanName)
            Writing frame: \(chapter.writeFraming)
            Story bias: \(chapter.storyBias)

            CHAPTER RULE: (Let the chapter color the braid's angle of attention, not announce itself as a label.) Do not say "Chapter \(chapter.name)" unless a kept page already named it.
            """
        } else {
            chapterSection = ""
        }

        let learnedSection: String
        if let guidance = context.learnedGuidance, !guidance.promptLines.isEmpty {
            learnedSection = """


            LEARNED BRAID TASTE:
            \(guidance.promptLines.map { "- \($0)" }.joined(separator: "\n"))

            LEARNING RULE: (Treat these as local taste notes from prior Book of You pages, not hard lore.) Follow the strongest note first, but never violate the kept pages.
            """
        } else {
            learnedSection = ""
        }

        let readerLearningSection: String
        if !context.readerLearningPromptLines.isEmpty {
            readerLearningSection = """


            LEARNED READER CONTEXT:
            \(context.readerLearningPromptLines.prefix(4).map { "- \($0)" }.joined(separator: "\n"))

            READER-LEARNING RULE: (These lines describe how prior pages met the reader. Use them only to choose emphasis, pacing, and restraint.) Never invent facts from them. Today's kept pages remain the material., If a line says something is cooling or resting, do less of it unless today's kept pages clearly ask for it.
            """
        } else {
            readerLearningSection = ""
        }

        let memorySpineSection: String
        if context.memoryDigest.braids.isEmpty {
            memorySpineSection = ""
        } else {
            let eligibleMotifs = context.memoryDigest.motifCounts.filter {
                !routineSupportingLogMotifs.contains($0.motif.lowercased())
            }
            let motifLine = eligibleMotifs.isEmpty
                ? "none yet"
                : eligibleMotifs
                    .prefix(6)
                    .map { "\($0.motif) x\($0.count)" }
                    .joined(separator: ", ")
            let braidLines = context.memoryDigest.braids.prefix(3).map { memory in
                let callback = memory.residue.callbackCandidate ?? memory.residue.keptLine
                return "- \(memory.residue.title): \(callback)"
            }.joined(separator: "\n")
            let strongestCallback = context.memoryDigest.strongestCallback.map {
                "\nStrongest fresh callback: \($0)"
            } ?? ""
            memorySpineSection = """


            BOOK MEMORY SPINE:
            Recurring braid motifs: \(motifLine)
            Recent braid residue:
            \(braidLines)\(strongestCallback)

            MEMORY-SPINE RULE: (You may let one prior residue return only if today's kept pages honestly answer it.) If it returns, change it with today's evidence; never simply repeat the old image. (Treat these as callbacks, not source material. Today's kept pages still own the braid.) Repeated Weather, Body, and Inner Weather readings are routine context, not callbacks. They may color today's page, but may not earn importance merely by recurring.
            """
        }

        let semanticEchoSection: String
        if context.semanticEchoLines.isEmpty {
            semanticEchoSection = ""
        } else {
            semanticEchoSection = """


            SEMANTIC ECHOES FROM TODAY:
            \(context.semanticEchoLines.prefix(3).map { "- \($0)" }.joined(separator: "\n"))

            SEMANTIC-ECHO RULE: (A semantic echo means today's page answered an older page by feeling, not by repeating words.) You may let that answered feeling become part of the spine only if today's kept pages support it.. Do not quote the older page unless the echo line already does.
            """
        }

        let clashSection: String
        if eligiblePages.contains(where: { $0.tags.contains("clash") }) {
            clashSection = """


            WHERE BELIEF WAS TESTED:. Today holds a clash page: the reader defended something against being made generic. Unless a lived page holds something even more personally true, let the clash be the braid's "Until" (the turn of the day.) Name what was protected in concrete words. Never recap it as a battle report; never quote rolls, numbers, or mechanics.. Frame the outcome by its digest: a bright success is restored agency; a costly success is saved-but-not-easy; a complication is unfinished business the Book keeps warm; standing down is wisdom (a lamp saved for tomorrow. Never shame a retreat.) Leave one clause of residue open (a title still missing, a seal still warm, a word the grey now knows you defend) so tomorrow's pages have something to pick up.
            """
        } else {
            clashSection = ""
        }

        let supportingLogs = supportingLogSection(for: day)

        return """
        \(BookCharacterPrompt.full(
            relationship: context.bookRelationship,
            interior: context.bookInterior,
            patina: context.bookVoicePatina
        ))

        Braid the kept pages into one grounded, intimate tale about this particular day. The Book of You is one continuing book, not a stack of summaries.
        \(taleReading.promptSection)

        TRUTH BEFORE SPELL: (The supplied tale reading chooses emphasis, not new facts. Today's kept pages remain the authority.) Silently choose a short title for the day, 2 to 7 concrete words. Print it as the first line with no "Title:" label. (Write in second-person past tense and hold that lens. Follow the real clock when time matters.) The selected narrative motion replaces a compulsory plot template. Do not force Once/Because/Until beats the day did not contain. (Make the causal movement legible: what entered, changed, cost, returned, was tended, was refused, or remained unresolved.) End with exactly one sentence beginning "The Book kept the page:". The ritual line may preserve, witness, name a price, leave a door open, or admit the Book does not understand yet.

        ONE TALE, TWO KINDS OF RECEIPT: (Internally, each kept page retains its provenance. In the finished prose, never announce a shelf, label a world, or explain the crossing.) Only lived receipts license ordinary claims about the reader's life. Labyrinth receipts may answer, steal from, rehearse, contradict, or impose one impossible relation on those facts. (A Keep does not transfer authorship. On a Book-authored Page, only lines labelled Reader's own words, Reader's fiction choice, Reader supplied a photograph, or Reader supplied a voice recording belong to the reader. Everything else on that Page is the Book's writing.) Give both kinds dignity, not equal word count. Let them share one tale while leaving each supplied mundane action intact. One-Sentence Souvenirs remain the strongest single spine candidates, because they are the reader choosing one true line. (A Labyrinth Page where the reader made a real decision) a chosen Story Page path, a paid bargain, an answered parley (may carry the spine as a choice, never as prose the reader wrote.) When receipts disagree about ordinary facts, the lived receipt wins. The crossing may trouble reality; it may not overwrite the receipt.
        \(souvenirSection)\(meaningfulSpineSection)\(supportingLogs)

        VOICE:
        \(BookVoice.animismLine) (Be intimate, lucid, plainspoken, and a little sideways. Use varied cadence and one exact supplied physical detail per paragraph.) On this page, exactly one object gets that agency: the one chosen by tonight's faerie pressure. Every other object stays flat scenery. One live thing hits harder than a parade of cute ones. (Prefer what someone said, touched, carried, avoided, dropped, or noticed over explaining what it means.) No diagnosis, flattery, moral, report diction, app language, or abstract emotional summary. (Never invent completed actions, locations, people, feelings, prices, promises, or tasks.) Paraphrase supplied prose; quote at most one short potent phrase. Mention each image or beat once.. Avoid journey, profound, tapestry, echoes, hidden meaning, glimmer, and generic inspiration. Do not reach for moth, moon, lamp, key, or threshold unless today's evidence supplied it.. Turn raw measurements into felt conditions only when those conditions materially belong in the tale.
        KEPT PAGES FROM TODAY. COMPLETE COMPACT LEDGER (\(eligiblePages.count) pages):
        \(evidence.isEmpty ? "- No kept pages yet. Write a quiet note about waiting for the day to gather." : evidence)\(clashSection)\(themeSection)\(chapterSection)\(learnedSection)\(readerLearningSection)\(memorySpineSection)\(semanticEchoSection)\(RadioAtmosphere.promptSection(context.nowPlaying))\(RadioNarrativeEchoPrompt.section(context.radioNarrativeEcho))\(context.activeWorldEvents.bookOfYouPromptSection)\(context.readerLexicon.languageLawSection())\(readerRoleSection(context.readerRole, transformation: context.roleTransformationClause))\(taleLawSection(context.standingTaleLaws))\(openTaleSection(context.openTale))\(readerStorySection(for: day, context: context))\(shadowSection(for: day, context: context))\(context.continuityBeat?.promptSection ?? "")\(continuity)\(context.braidStyleMemory.promptSection)

        FINAL WEAVING CHECK: (The ledger above contains all \(eligiblePages.count) braid-eligible kept pages; its excerpts are compact, not a ranking that permits later pages to erase earlier ones.) For a Full Braid, carry at least three distinct non-log details across at least four paragraphs. For a Small Braid, carry at least two distinct non-log details across at least three paragraphs. (If non-log pages exist, Weather, Body, and Inner Weather together may color at most one short paragraph and may not own the title or ending.) End with the required sentence beginning "The Book kept the page:".
        """
    }

    static func candidatePrompt(
        for day: BookDay,
        context: Context,
        camera: BraidCamera
    ) -> String {
        """
        \(prompt(for: day, context: context))

        TONIGHT'S CAMERA:
        \(camera.promptLine)
        This changes composition only. It may not change facts, the selected relationship, or the arc movement.
        """
    }

    /// Threads still standing, and the name the reader gave this stretch.
    ///
    /// The braid has always been forbidden to re-describe an earlier night's
    /// events, and that stays true: a remembered event is a confabulated event.
    /// What can be carried honestly is the *question*: something opened and has
    /// not closed. That is a fact about the ledger, not about the past.
    /// The name the Book gave the reader, for any surface where it writes to
    /// them. Deliberately four lines: the role earns its place in a tight
    /// prompt by changing what the prose reaches for, not by explaining itself.
    /// The Book states it: hedging the one claim it is allowed to make is
    /// exactly the register the role exists to avoid.
    static func readerRoleSection(_ role: ComposedRole?, transformation: String? = nil) -> String {
        guard let role else { return "" }
        let earned = transformation.map { clause in
            "\n. They have since earned the rest of it: \(role.fullName) \(clause). That half was not given, it was lived through, and it outranks the first naming."
        } ?? ""
        return """


        WHO YOU DECIDED THIS READER IS: (You named them \(role.fullName). \(role.role.gloss)\(earned)) Write as though that is settled. Do not hedge it, argue it, or explain how you decided.. Reach first for what a \(role.role.bareName) would have noticed in this day. Never announce the name or use it as a label in the prose.
        """
    }

    /// The shape the reader is currently inside. The Book must not say so -
    /// naming a tale while it is running collapses it, and the whole design is
    /// that the reader finds out afterwards. What this does is bias what the
    /// Book leans toward tonight: an open Forbidden Door makes it notice
    /// thresholds; an Unpaid Gift makes it notice what is owed.
    static func openTaleSection(_ tale: LivingTale?) -> String {
        guard let tale, tale.isOpen else { return "" }
        return """


        SOMETHING IS RUNNING (do not name it, ever): (The reader is currently inside a shape you have recognised: \(tale.shape.commonName).) Do not mention it, hint at it, foreshadow it, or write as though you know how it ends. You do not. (Let it bias only what you *notice* tonight: \(taleAttention(tale.shape)).) If nothing in today's pages fits that, ignore this entirely. Forcing it would be worse than missing it.
        """
    }

    /// What an open shape makes the Book more likely to look at. Attention
    /// only, never plot, never prophecy.
    private static func taleAttention(_ shape: TaleShape) -> String {
        switch shape {
        case .forbiddenDoor: return "thresholds, edges, the things they said they would not do"
        case .unpaidGift: return "what is owed, what was given early, what has not been answered"
        case .threeEncounters: return "things arriving for the second or third time"
        case .falseName: return "how they describe themselves, and where the description slips"
        case .helpfulStranger: return "unbidden help, and who has turned up without being asked"
        case .objectRefused: return "objects behaving unhelpfully, tools with opinions"
        case .promiseMadeTooEasily: return "the speed at which they agree to things"
        case .roadReturnsDifferently: return "places revisited, and what has changed in them"
        case .houseUnderObligation: return "rooms, thresholds, and what a place seems to be waiting for"
        case .lostThingNotWantingFound: return "what keeps coming back, and what they keep setting down"
        }
    }

    /// The laws finished tales left behind. These are constraints on the Book,
    /// not material for the page: it obeys them silently and never recites one.
    static func taleLawSection(_ laws: [String]) -> String {
        guard !laws.isEmpty else { return "" }
        return """


        WHAT IS TRUE NOW THAT WAS NOT TRUE BEFORE:
        \(laws.map { "- \($0)" }.joined(separator: "\n"))

        LAW RULE: (These came from tales that finished. They are yours to obey, not to quote.) Do not narrate them, explain them, or refer to the tale that made them.. Let them change what you are willing to say and what you decline to offer. That is all.
        """
    }

    static func readerStorySection(for day: BookDay, context: Context, calendar: Calendar = .current) -> String {
        let now = day.date
        let threads = context.readerStory.carriedThreads(now: now, calendar: calendar)
        var sections: [String] = []

        if !threads.isEmpty {
            sections.append("""


            THREADS STILL OPEN (continuity of question, not of material):
            \(threads.map { $0.promptLine(now: now, calendar: calendar) }.joined(separator: "\n"))

            THREAD RULE: (These are not material. You were not there. Do not restate their events, invent their details, or describe what happened.) If today's kept pages honestly touch one, say only how it moved tonight. (If today touched none, you may note that one is still open and stop there. "The coat is still in the hall" is a whole sentence.) Never resolve a thread the evidence has not resolved. An open thread staying open is a true ending., Never list them. At most one may enter tonight's page.
            """)
        }

        if let season = context.readerStory.currentSeason {
            let held = season.daysHeld(now: now, calendar: calendar)
            let age = held <= 1 ? "named just now" : "named \(held) days ago"
            sections.append("""


            THE READER'S NAME FOR THIS STRETCH: "\(season.name)" (\(age))

            SEASON RULE: (This is the reader's word, not yours. You may let it tint the page the way a running head tints a chapter.) Never explain it, never argue with it, never improve it, and never declare it over. Only they may end it.. Do not use it as a diagnosis or as a reason the day went the way it did.
            """)
        }

        return sections.joined()
    }

    /// The half of a life the Book spent a long time not asking about.
    static func shadowSection(for day: BookDay, context: Context, calendar: Calendar = .current) -> String {
        let now = day.date
        let shadowPages = partitionedPagesForBraid(in: day).story
            .filter(ReaderShelf.isWeavable)
            .filter { ReaderShelf.of($0) == .shadow }
        guard !shadowPages.isEmpty else { return "" }

        let withheld = shadowPages.filter {
            !context.readerStory.shadowMayTakeTaleForm(keptAt: $0.createdAt, now: now, calendar: calendar)
        }
        let ageLine = withheld.isEmpty
            ? "All of it is cleared to take tale-form tonight."
            : "\(withheld.count) of \(shadowPages.count) may not take tale-form tonight and is reported plainly or left alone."

        return """


        SHADOW MATERIAL PRESENT (\(shadowPages.count) of tonight's keeps):
        \(context.readerStory.shadowPermission.promptLine)
        \(ageLine)

        SHADOW LAW: (Change the handle, never the weight. A tale gives a heavy thing a shape a person can pick up. It does not make it lighter, and it must not pretend to.) Do not resolve it. Do not say what it was for. Do not tell the reader what they felt (name what was there.) No consolation was asked for. No lesson. No silver lining. No "and so you learned." (When it may take tale-form, it becomes what a character carries, why an errand exists, or the thing that is not said. Never scenery, never weather, never a decorative sorrow.) This is not the Rut. Grief in full colour is the opposite of the grey. Never route this material to the Rut, never let it read as evidence the reader stopped trying, and never let a character treat it as apathy to be shaken off.
        """
    }

    private static func compactStoryScorePrompt(
        for day: BookDay,
        context: Context,
        score: NightlyStoryScore
    ) -> String {
        let pages = braidEligiblePages(in: day)
        let evidence = evidenceLines(for: day, totalCharacterBudget: 3_600, score: score).joined(separator: "\n\n")
        let meaningfulSpineSection = meaningfulSpineSection(context: context)
        var colorLines: [String] = []
        if let theme = context.theme {
            colorLines.append("Theme watermark: \(theme.name): \(theme.line)")
        }
        if let chapter = context.chapter {
            colorLines.append("Chapter angle: \(chapter.name): \(chapter.writeFraming)")
        }
        if let guidance = context.learnedGuidance {
            colorLines += guidance.promptLines.prefix(2).map { "Reader-taught taste: \($0)" }
        }
        if let nowPlaying = context.nowPlaying?.nonEmpty {
            colorLines.append("Faint atmosphere only: \(nowPlaying)")
        }
        let color = colorLines.isEmpty
            ? "No additional color earned tonight."
            : colorLines.joined(separator: "\n")
        let learnedSection: String
        if let guidance = context.learnedGuidance, !guidance.signals.isEmpty {
            learnedSection = """

            LEARNED BRAID TASTE:
            \(guidance.promptLines.prefix(3).map { "- \($0)" }.joined(separator: "\n"))
            Treat these as local taste notes from this reader, never as a reason to bend the evidence.
            """
        } else {
            learnedSection = ""
        }
        let readerLearningSection: String
        if context.readerLearningPromptLines.isEmpty {
            readerLearningSection = ""
        } else {
            readerLearningSection = """

            READER-TAUGHT CONTEXT:
            \(context.readerLearningPromptLines.prefix(3).map { "- \($0)" }.joined(separator: "\n"))
            """
        }
        let memorySpineSection: String
        if context.memoryDigest.braids.isEmpty {
            memorySpineSection = ""
        } else {
            let memories = context.memoryDigest.braids.prefix(2).map { memory in
                let callback = memory.residue.callbackCandidate.flatMap(\.nonEmpty) ?? "no callback retained"
                return "- \(memory.residue.title): \(callback)"
            }.joined(separator: "\n")
            memorySpineSection = """

            BOOK MEMORY SPINE:
            \(memories)
            You may let one prior residue return only if today's kept pages honestly answer it.
            """
        }
        let semanticEchoSection: String
        if context.semanticEchoLines.isEmpty {
            semanticEchoSection = ""
        } else {
            semanticEchoSection = """

            SEMANTIC ECHOES FROM TODAY:
            \(context.semanticEchoLines.prefix(2).map { "- \($0)" }.joined(separator: "\n"))
            Treat these as possible long-range rhymes, not proof of a cause or a settled pattern.
            """
        }
        return """
        \(BookCharacterPrompt.full(
            relationship: context.bookRelationship,
            interior: context.bookInterior,
            patina: context.bookVoicePatina
        ))

        Write one intimate Book of You page from the decisions and receipts below. The hard interpretive work is already done; your task is literary realization, not discovery.

        \(score.promptSection)
        \(meaningfulSpineSection)

        SOURCE RECEIPTS. COMPLETE COMPACT LEDGER (\(pages.count) eligible kept pages):
        \(evidence.isEmpty ? "No kept pages. Write only a modest waiting note." : evidence)

        OPTIONAL COLOR, NEVER THE PLOT:
        \(color)\(learnedSection)\(readerLearningSection)\(memorySpineSection)\(semanticEchoSection)\(readerRoleSection(context.readerRole, transformation: context.roleTransformationClause))\(taleLawSection(context.standingTaleLaws))\(openTaleSection(context.openTale))\(readerStorySection(for: day, context: context))\(shadowSection(for: day, context: context))\(context.continuityBeat?.promptSection ?? "")\(context.activeWorldEvents.bookOfYouPromptSection)\(context.readerLexicon.languageLawSection())\(context.braidStyleMemory.promptSection)

        WRITING CONTRACT: (First line: an unlabeled title of 2 to 7 concrete words.) Then \(score.taleReading.scale.promptLine) (Second-person past tense. Follow the supplied clock.) Carry the score's causal movement: what entered, changed, cost, returned, was refused, or remained unresolved.. Let the selected Labyrinth receipt and lived receipts trespass into one continuous tale. Never label the seam. (A Keep does not transfer authorship. Only ledger atoms explicitly labelled as the reader's words, choice, photograph, or recording belong to the reader; Book-authored Page text remains mine.) Preserve the actual fictional actor or phrase the reader's participation as a choice; do not rewrite a staged action as ordinary external biography. (Dramatize the relational lens through supplied details. Never mention statistics, confidence tiers, vectors, analysis, patterns, or an archive.) Give agency to at most one supplied ordinary thing. The strange relation must have a consequence; decorative whimsy fails. (Use at least two distinct non-log receipts on a Small Braid and three on a Full Braid. Do not list the day.) Weather, Body, and Inner Weather together may color at most one short paragraph when lived non-log pages exist. (Quote at most one short supplied phrase. Never explain symbolism.) Avoid journey, profound, tapestry, echoes, hidden meaning, glimmer, generic inspiration, and unsupported moth/moon/lamp/key/threshold imagery.. End with exactly one sentence beginning "The Book kept the page:". Fulfil the score's ending duty there without copying it verbatim.

        Write in the Book's own voice, as your standing instructions describe it.
        Write only the finished page now.
        """
    }

    private static func supportingLogSection(for day: BookDay) -> String {
        let eligiblePages = braidEligiblePages(in: day)
        let present = [BookPageType.weather, .body, .mood].filter { type in
            eligiblePages.contains { $0.type == type }
        }
        guard !present.isEmpty else { return "" }
        let names = present.map { type in
            switch type {
            case .weather: return "Weather"
            case .body: return "Body"
            case .mood: return "Inner Weather"
            default: return type.title
            }
        }.joined(separator: ", ")
        let hasNonLogMaterial = eligiblePages.contains { !isSupportingLog($0) }
        let availabilityRule = hasNonLogMaterial
            ? "- Other kept material exists tonight. A supporting log may not supply the title, spine, turn, or final kept image."
            : "- These logs are the only kept material tonight. Let them support a modest Glimpse without inventing an event or revelation."
        return """


        SUPPORTING DAILY LOGS (context, not required prose):
        Present tonight: \(names). (The Book can notice a log without repeating it to the reader. Let logs alter pace, physical conditions, restraint, or scale.) Mention a log only if it materially changes what happened or if logs are the only material tonight., If visible, keep all Weather, Body, and Inner Weather material together to at most one short paragraph. Never turn readings into plot, diagnosis, verdict, or emotional thesis.
        \(availabilityRule). Repetition across days does not increase a log's gravity. Daily weather is not automatically the day's meaning; a repeated body or mood reading is not automatically an arc.
        """
    }

    private static func souvenirSpineSection(for day: BookDay, context: Context) -> String {
        guard let anchor = context.souvenirAnchor ?? souvenirAnchor(in: day) else { return "" }
        let formatter = DateFormatter()
        formatter.dateFormat = "h:mm a"
        return """

        SOUVENIR SPINE (required):
        The reader's carried sentence for tonight is from \(anchor.pageTitle), kept at \(formatter.string(from: anchor.keptAt)): "\(anchor.keptText)"
        Why it matters: \(anchor.reason).

        SOUVENIR RULE: (Let this sentence govern the braid's emphasis. Its concrete thing should affect the selected motion and normally return transformed in "The Book kept the page:".) Do not force it through opening, turn, and closing when tonight's honest form is a Vigil, Absence, or Glimpse. (Do not paste the full sentence back. Carry its image, object, action, or pressure through the braid so the reader can feel the Book read it.) If fiction pages are vivid, braid them around this sentence rather than away from it.
        """
    }

    private static func meaningfulSpineSection(context: Context) -> String {
        guard !context.meaningfulSpinePassages.isEmpty else { return "" }
        let passages = context.meaningfulSpinePassages.enumerated().map { index, selection in
            "\(index + 1). \(selection.pageType.shortTitle): “\(selection.excerpt)” (\(selection.reason))"
        }.joined(separator: "\n")
        return """


        MEANINGFUL PASSAGE COMPASS:
        \(passages)

        PASSAGE-COMPASS RULE: (These are the day's most relevant, specific reader-authored passages, selected from inside the keeps rather than from their openings.) Choose one as the braid's main hinge unless the required Souvenir Spine is stronger; the others may support it, but do not force them all into the prose. (The complete kept-page evidence below still governs the facts and the day's clock. This compass chooses emphasis; it does not erase the other pages.) Quote at most one short phrase and never mention selection, scoring, embeddings, or an archive.
        """
    }

    /// Gemma re-reads a braid the reader said missed them and rewrites it
    /// truer. The full braid craft spec is reused so the revision plays by the
    /// same rules; the prior draft and the weak-dimension notes tell it what to
    /// fix. `weakNotes` come from `BraidLearningLoop.weakDimensionNotes`.
    static func rewritePrompt(for day: BookDay, priorBraid: String, weakNotes: [String], context: Context) -> String {
        let base = prompt(for: day, context: context)
        let weakSection = weakNotes.isEmpty
            ? ""
            : "\n\nWHAT MISSED LAST TIME (address these first, without violating the kept pages):\n"
                + weakNotes.map { "- \($0)" }.joined(separator: "\n")
        return """
        You already braided this day once, and the reader felt the page missed them. Rewrite it truer to their day.

        YOUR PRIOR DRAFT (keep what was honest, fix what missed, and do not reuse its sentences):
        \(priorBraid)\(weakSection)

        Now write the improved Book of You page, following every rule below.

        \(base)
        """
    }

    /// Gemma turns a missed braid into one short reader-taught taste note that
    /// will steer future braids. Returns a prompt for a single sentence.
    static func tasteNotePrompt(for day: BookDay, priorBraid: String, weakNotes: [String], context: Context) -> String {
        let evidence = evidenceLines(for: day).joined(separator: "\n\n")
        let weakSection = weakNotes.isEmpty
            ? ""
            : "\n\nHEURISTIC HUNCHES (you may agree or disagree):\n"
                + weakNotes.map { "- \($0)" }.joined(separator: "\n")
        return """
        You are the Book inside ReEnchanted. The reader marked this Book of You page as one that missed them.
        Read it against the kept pages it was braided from, and name in one short sentence what the Book should do differently next time it braids this reader's days.

        THE PAGE THAT MISSED:
        \(priorBraid)\(weakSection)

        KEPT PAGES FROM THAT DAY:
        \(evidence.isEmpty ? "- None recorded." : evidence)

        Reply with exactly one second-person instruction to yourself for next time, at most 24 words.
        Begin with a verb. No preamble, no quotation marks, no "Note:" label.
        Speak as the reader's own taste, for example: "Stay closer to what my hands actually did." or "Let the evening hold the final line."
        """
    }

    /// Below this a page slot cannot carry a header plus any of the reader's
    /// own words, so it is not worth spending the characters on at all.
    static let minimumViableEvidenceSlot = 200

    /// How many pages a budget can seat before slots stop being worth having.
    static func evidenceCapacity(totalCharacterBudget: Int) -> Int {
        max(1, totalCharacterBudget / minimumViableEvidenceSlot)
    }

    static func evidenceLines(
        for day: BookDay,
        totalCharacterBudget: Int = evidencePacketCharacterBudget,
        score: NightlyStoryScore? = nil
    ) -> [String] {
        let timeFormatter = DateFormatter()
        timeFormatter.dateFormat = "MMM d, h:mm a"
        let all = braidEligiblePages(in: day).sorted { $0.createdAt < $1.createdAt }
        guard !all.isEmpty else { return [] }
        // The packet is a budget, not a suggestion. The per-page floor used to
        // win over the total: `max(200, budget / count)` meant a 40-page day
        // spent 8,000 characters against a 3,600 budget, so past about eighteen
        // pages the total stopped meaning anything and `fit` clipped the middle
        // of the prompt blind. A day is now seated to what the budget can hold.
        //
        // Which pages get the seats is decided by fit to the night's chosen
        // story form rather than by the clock: a busy day should hand the local
        // brain the pages that make the story, not the first N that happened.
        // Pages the score already chose as lived anchors are seated first;
        // the rest fall back to the same thread-gravity order the ledger has
        // always used. Selection is by rank, presentation stays chronological,
        // so the Book still reads the day forwards.
        let capacity = evidenceCapacity(totalCharacterBudget: totalCharacterBudget)
        let pages: [BookPage]
        if all.count <= capacity {
            pages = all
        } else {
            let anchored = Set(score?.anchoredPageIDs ?? [])
            pages = all
                .enumerated()
                .sorted { left, right in
                    let leftAnchored = anchored.contains(left.element.id)
                    let rightAnchored = anchored.contains(right.element.id)
                    if leftAnchored != rightAnchored { return leftAnchored }
                    let leftGravity = threadGravityRank(for: left.element)
                    let rightGravity = threadGravityRank(for: right.element)
                    if leftGravity != rightGravity { return leftGravity > rightGravity }
                    return left.offset < right.offset
                }
                .prefix(capacity)
                .map(\.element)
                .sorted { $0.createdAt < $1.createdAt }
        }
        let perPageBudget = min(980, max(minimumViableEvidenceSlot, totalCharacterBudget / pages.count))
        let keptTextLimit = max(140, min(480, perPageBudget / 2))
        let replyLimit = max(80, min(220, perPageBudget / 4))
        return pages
            .enumerated()
            .map { index, page in
                let prompt = clippedText(page.promptText, limit: min(120, perPageBudget / 6))
                let attributablePageText = page.bookAuthoredText ?? page.userInput
                let text = clippedText(attributablePageText, limit: keptTextLimit)
                let tags = clippedText(
                    genericBraidTags(for: page).joined(separator: ", "),
                    limit: min(120, perPageBudget / 6)
                )
                let media = clippedText(mediaEvidence(for: page), limit: min(140, perPageBudget / 5))
                let readerWords = clippedText(
                    page.readerAuthoredTexts.joined(separator: " | "),
                    limit: replyLimit
                )
                let readerChoices = clippedText(
                    page.readerFictionChoices.joined(separator: " | "),
                    limit: replyLimit
                )
                let clashDigest: String
                if page.tags.contains("clash") {
                    let kind = page.tags.first { $0.hasPrefix("clash:") }?.replacingOccurrences(of: "clash:", with: "") ?? "clash"
                    let outcome = page.tags.first { $0.hasPrefix("clash-outcome:") }?.replacingOccurrences(of: "clash-outcome:", with: "") ?? "unrolled"
                    let choice = page.tags.first { $0.hasPrefix("choice:") }?.replacingOccurrences(of: "choice:", with: "") ?? "none"
                    clashDigest = "\nClash digest: Belief was tested (\(kind)); the reader chose the \(choice) path; outcome \(outcome)."
                } else {
                    clashDigest = ""
                }
                // Absent fields are dropped rather than spelled out. Nine
                // labels per page is most of a tight slot before any of the
                // reader's own words arrive, and "Reader reply: none" teaches
                // the Book nothing a missing line does not.
                // The reader's own words come first. The slot is clipped to
                // `perPageBudget`, and the four descriptive labels together run
                // longer than a tight slot, so ordering them ahead of the text
                // meant a heavy day spent its whole packet on "Thread gravity:
                // reader-authored anchor" and clipped the sentence the reader
                // actually wrote. Metadata is what should be lost to clipping.
                let textLabel: String
                if page.bookAuthoredText != nil {
                    textLabel = "Book-authored Page text"
                } else {
                    switch page.origin {
                    case .userAuthored:
                        textLabel = "Reader-authored Page text"
                    case .imported:
                        textLabel = "Imported Page text"
                    case .generated, .simulated:
                        textLabel = "Book-authored Page text"
                    }
                }
                var fields = ["\(textLabel): \(text.isEmpty ? "(blank)" : text)"]
                if (page.origin != .userAuthored || page.bookAuthoredText != nil), !readerWords.isEmpty {
                    fields.append("Reader's own words: \(readerWords)")
                }
                if !readerChoices.isEmpty {
                    fields.append("Reader's fiction choice: \(readerChoices)")
                }
                if page.hasReaderPhotograph { fields.append("Reader supplied a photograph.") }
                if page.hasReaderAudioRecording { fields.append("Reader supplied a voice recording.") }
                fields.append(contentsOf: [
                    "Shelf: \(braidShelf(for: page))",
                    "Thread role: \(threadRole(for: page))",
                    "Thread gravity: \(threadGravity(for: page))"
                ])
                if !prompt.isEmpty { fields.append("Prompt: \(prompt)") }
                if !media.isEmpty { fields.append("Visual evidence: \(media)") }
                if !tags.isEmpty { fields.append("Tags: \(tags)") }

                let header = "\(index + 1). \(page.type.title): kept at \(timeFormatter.string(from: page.createdAt))"
                let line = ([header] + fields).joined(separator: "\n") + clashDigest
                return clippedText(line, limit: perPageBudget)
            }
    }

    static func qualityRepairPrompt(
        for day: BookDay,
        context: Context,
        priorDraft: String,
        issues: [BraidOutputAudit.Issue]
    ) -> String {
        let reading = context.taleReading ?? taleReading(for: day, context: context)
        let evidence = evidenceLines(for: day).joined(separator: "\n\n")
        // A page that consoled someone who did not ask for it is a different
        // kind of wrong from a page that ran short. Lead with the overstep.
        let ordered = issues.filter(\.isRegisterFailure) + issues.filter { !$0.isRegisterFailure }
        let issueLines = ordered.map { "- \($0.repairInstruction)" }.joined(separator: "\n")
        let scoreSection = context.storyScore?.promptSection ?? ""
        let opening = ordered.first?.isRegisterFailure == true
            ? "The first attempt at tonight's Book of You page overstepped: it handled the reader's own weight in a way it was not given permission to. Rewrite it from the complete compact ledger below. Do not reuse the first draft's sentences."
            : "The first attempt at tonight's Book of You page was too thin or lost the day's evidence. Rewrite it from the complete compact ledger below. Do not reuse the first draft's sentences."
        return """
        \(opening)

        REPAIR THESE FAILURES:
        \(issueLines)\(shadowSection(for: day, context: context))\(context.continuityBeat?.promptSection ?? "")

        REQUIRED SHAPE:
        \(reading.scale.promptLine)
        Motion: \(reading.motion.promptLine)
        Faerie pressure: \(reading.pressure.promptLine)
        Truth anchor: \(reading.anchor.isEmpty ? "none supplied" : reading.anchor) (Use only supplied facts, in second-person past tense.) Carry distinct concrete details from the whole day rather than reciting a list. (Weather, Body, and Inner Weather together may occupy at most one short paragraph when non-log pages exist.) End with exactly one sentence beginning "The Book kept the page:".
        \(scoreSection)

        COMPLETE LEDGER. ALL \(braidEligiblePages(in: day).count) BRAID-ELIGIBLE KEPT PAGES:
        \(evidence)

        REJECTED FIRST DRAFT:
        \(clippedText(priorDraft, limit: 1_000))

        Write only the repaired Book of You page now.
        """
    }

    /// Ask the model for music, not content.
    ///
    /// The house writer has already decided what tonight's page says, which
    /// receipts it stands on, and how it ends. What it is worst at is the sound
    /// of a sentence, so that, and only that, is what gets asked for here. The
    /// verifier will check every line that comes back, so this prompt does not
    /// have to be trusted; it only has to be clear enough that most sentences
    /// survive.
    static func voiceRevisionPrompt(
        for day: BookDay,
        context: Context,
        composition: BraidComposition
    ) -> String {
        let reading = context.taleReading ?? taleReading(for: day, context: context)
        var numbered: [String] = []
        var index = 1
        for (paragraphIndex, paragraph) in composition.paragraphs.enumerated() {
            numbered.append("Paragraph \(paragraphIndex + 1):")
            for sentence in paragraph {
                let rule: String
                switch sentence.license {
                case .strict:
                    rule = "FACTS LOCKED: change the wording, keep every noun and number"
                case .free:
                    rule = "FREE: this is my own voice, make it sharper"
                case .locked:
                    rule = "DO NOT TOUCH: copy exactly"
                }
                numbered.append("  \(index). [\(rule)] \(sentence.text)")
                index += 1
            }
        }
        return """
        Below is tonight's finished Book of You page. It is correct. Your only job is to improve how it sounds.

        ABSOLUTE RULES: (Return the same title, the same number of paragraphs, and the same number of sentences in each paragraph. One sentence in, one sentence out.) Sentences marked DO NOT TOUCH must be reproduced character for character. (Sentences marked FACTS LOCKED may be rephrased, reordered, split at a comma, or turned inside out), but every noun, name and number in them must survive, and you may not add any new noun, verb, adjective or adverb that is not already in that sentence. (Sentences marked FREE are the Book's own voice. Make them stranger, shorter, funnier, more exact. Invent freely here and nowhere else.) Never explain, console, advise, or draw a lesson. Never say "The Book" except in the final line.. Vary the sentence lengths. Do not start two sentences in a row with the same word.

        REQUIRED VOICE:
        Register: \(reading.narrativeRegister.rawValue)
        Faerie pressure: \(reading.pressure.promptLine)
        \(context.braidStyleMemory.promptSection)

        THE PAGE:
        Title: \(composition.title)
        \(numbered.joined(separator: "\n"))

        Return the whole revised page: the title, then the paragraphs separated by blank lines. Nothing else.
        """
    }

    /// How many nights an authored sentence rests after the Book uses it.
    ///
    /// Long enough that a daily reader does not meet the same closing line
    /// twice in a week; short enough that the pools do not run dry and force
    /// the Book into its least apt phrasing.
    static let moveRestNights = 10

    /// How many nights ago each authored sentence was last used.
    ///
    /// Reads the `braid-move:` tags off recent kept braids. Deriving this from
    /// the pages themselves rather than a parallel table means a page the
    /// reader removed stops constraining tonight, which is the behaviour you
    /// would have to remember to write by hand in any other design.
    static func recentMoveAges(
        before day: BookDay,
        in archive: [BookDay],
        nights: Int = moveRestNights
    ) -> [String: Int] {
        let recent = archive
            .filter { $0.id != day.id && $0.date < day.date }
            .sorted { $0.date > $1.date }
            .prefix(nights)
        var ages: [String: Int] = [:]
        for (age, archiveDay) in recent.enumerated() {
            for page in archiveDay.pages where page.type == .bookOfYou {
                for tag in page.tags where tag.hasPrefix("braid-move:") {
                    let key = String(tag.dropFirst("braid-move:".count))
                    if ages[key] == nil { ages[key] = age }
                }
            }
        }
        return ages
    }

    /// Count how long each subject has been in the archive.
    ///
    /// Deliberately counts *days*, not mentions: a word written six times in
    /// one evening is one occasion of caring about it, and the Book would be
    /// lying to call that six.
    static func subjectHistory(
        before day: BookDay,
        in archive: [BookDay],
        calendar: Calendar = .current
    ) -> [String: SubjectHistory] {
        var history: [String: SubjectHistory] = [:]
        // The recent past is what a callback can honestly reach for, and it
        // caps the work on an archive that will one day be years deep.
        let priorDays = archive
            .filter { $0.id != day.id && $0.date < day.date }
            .sorted { $0.date > $1.date }
            .prefix(400)
        for archiveDay in priorDays {
            let storyPages = partitionedPagesForBraid(in: archiveDay).story
            var seenToday = Set<String>()
            for page in storyPages {
                let source = page.playerReply.nonEmpty ?? page.userInput.nonEmpty ?? BraidPromptBuilder.mediaEvidence(for: page) ?? page.promptText
                for word in subjectWords(in: source) where seenToday.insert(word).inserted {
                    if var existing = history[word] {
                        existing.occasions += 1
                        existing.firstSeen = min(existing.firstSeen, archiveDay.date)
                        existing.lastSeen = max(existing.lastSeen, archiveDay.date)
                        history[word] = existing
                    } else {
                        history[word] = SubjectHistory(
                            occasions: 1,
                            firstSeen: archiveDay.date,
                            lastSeen: archiveDay.date
                        )
                    }
                }
            }
        }
        return history
    }

    private static func subjectWords(in text: String) -> Set<String> {
        Set(
            text
                .split { !$0.isLetter && !$0.isNumber && $0 != "'" }
                .map { $0.lowercased() }
                .filter { $0.count >= 4 && !subjectHistoryStopwords.contains($0) }
        )
    }

    /// Grammar and scaffolding. A callback about "would" would be a joke.
    private static let subjectHistoryStopwords: Set<String> = [
        "about", "after", "again", "against", "already", "also", "always",
        "another", "anything", "around", "because", "been", "before", "being",
        "between", "book", "both", "came", "could", "days", "does", "done",
        "down", "each", "even", "ever", "every", "felt", "from", "gets",
        "going", "gone", "have", "here", "into", "just", "kept", "keep",
        "knew", "know", "like", "little", "long", "made", "make", "many",
        "more", "most", "much", "must", "myself", "never", "next", "night",
        "nothing", "only", "other", "over", "page", "pages", "past", "reader",
        "really", "right", "said", "same", "says", "some", "something", "still",
        "story", "such", "than", "that", "them", "then", "there", "these",
        "they", "thing", "things", "think", "this", "those", "though",
        "through", "time", "today", "tonight", "took", "under", "until",
        "very", "want", "wanted", "well", "went", "were", "what", "when",
        "where", "which", "while", "will", "with", "without", "would", "your"
    ]

    /// Which shelf a kept page sits on: the reader's own record, or the Book's
    /// fiction. Deterministic so the braid never has to guess provenance.
    static func braidShelf(for page: BookPage) -> String {
        switch page.origin {
        case .userAuthored, .imported:
            return "lived"
        case .generated, .simulated:
            return "fiction"
        }
    }

    /// A generated Page is not automatically a scene from the shared world.
    /// Forecasts, quotations, setup copy, and reference excerpts may also be
    /// generated; letting origin alone promote them made stray utility prose a
    /// nightly faerie visitor.
    static func isLabyrinthReceipt(_ page: BookPage) -> Bool {
        guard braidShelf(for: page) == "fiction" else { return false }
        if page.tags.contains("clash")
            || page.tags.contains(where: {
                $0.hasPrefix("choice:")
                    || $0 == "labyrinth-receipt"
                    || $0 == "shared-world"
                    || $0 == "narrative-event"
            }) {
            return true
        }
        if page.type == .illustration, page.tags.contains("entity") {
            return true
        }
        switch page.type {
        case .lore, .narrativeOS, .gossip, .bookAside, .letter,
             .supportGuild, .inkrestOfficeHours, .faeBargain, .bookFae,
             .pactDispatch, .pactVerdict, .pactErrand, .festival, .twoReadings,
             .castBond, .radio, .bookJump, .enchantment, .anchor, .academyClass,
             .elective, .wickerDare, .wordNegotiation, .gamePage, .theBleed,
             .taleBound:
            return true
        default:
            return false
        }
    }

    static func isSupportingLog(_ page: BookPage) -> Bool {
        supportingLogTypes.contains(page.type)
    }

    /// Welcome letters and help/setup pages belong to the Book's furniture, not
    /// to the reader's lived day. They stay in the archive but never become
    /// nightly narrative evidence.
    static func isBraidEligible(_ page: BookPage) -> Bool {
        page.type != .welcome
            && page.type != .helpTips
            && page.externalReference?.allowsWeaving != false
            // A seal is absolute and retroactive: the page stays in the archive,
            // the Stacks, and export, and leaves the nightly weave entirely.
            && !page.tags.contains(ReaderShelf.sealedTag)
    }

    /// The braid's *view* of a day, with anything the reader forbade removed
    /// before any of the machinery sees it.
    ///
    /// Applied once at the app's braid entry points rather than threaded through
    /// the fifteen places that ask a day for its pages: a consent rule that can
    /// be bypassed by one path forgetting to check it is not a consent rule.
    /// The stored day is untouched; only the night's reading is narrowed.
    static func weavableDay(_ day: BookDay, readerStory: ReaderStory) -> BookDay {
        var narrowed = day
        narrowed.pages = day.pages.filter { page in
            guard isBraidEligible(page) else { return false }
            return readerStory.shadowPermission != .knowButNeverWrite
                || ReaderShelf.of(page) != .shadow
        }
        return narrowed
    }

    static func braidEligiblePages(in day: BookDay) -> [BookPage] {
        day.capturedPages.filter(isBraidEligible)
    }

    /// Fallback prose must never expose a chopped word such as `whe.` or `co.`.
    /// Collapse whitespace, then retreat to the last whole-word boundary.
    static func fallbackExcerpt(_ text: String, limit: Int = 120) -> String {
        let normalized = text
            .components(separatedBy: .whitespacesAndNewlines)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
        guard normalized.count > limit else { return normalized }

        let limitIndex = normalized.index(normalized.startIndex, offsetBy: limit)
        let prefix = normalized[..<limitIndex]
        guard let boundary = prefix.lastIndex(where: { $0.isWhitespace }) else {
            return String(prefix) + "…"
        }
        let wholeWords = prefix[..<boundary]
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return wholeWords + "…"
    }

    static func partitionedPagesForBraid(in day: BookDay) -> (story: [BookPage], supportingLogs: [BookPage]) {
        let sorted = braidEligiblePages(in: day).sorted { $0.createdAt < $1.createdAt }
        return (
            story: sorted.filter { !isSupportingLog($0) },
            supportingLogs: sorted.filter(isSupportingLog)
        )
    }

    private static func threadRole(for page: BookPage) -> String {
        isSupportingLog(page)
            ? "supporting daily log; may remain invisible unless it materially changes the tale"
            : "spine-eligible kept material"
    }

    /// The same gravity `threadGravity` describes in prose, as a sortable rank.
    /// Higher keeps its seat when a heavy day has more pages than the evidence
    /// packet can hold. Kept in step with the strings below.
    static func threadGravityRank(for page: BookPage) -> Int {
        if isSupportingLog(page) { return 0 }
        let hasReaderContribution = page.hasReaderContribution
        if page.bookAuthoredText != nil {
            return hasReaderContribution ? 3 : 1
        }
        switch page.origin {
        case .userAuthored:
            return page.type == .souvenir ? 5 : 4
        case .imported:
            return 4
        case .generated, .simulated:
            return hasReaderContribution ? 3 : 1
        }
    }

    private static func threadGravity(for page: BookPage) -> String {
        if isSupportingLog(page) {
            return "supporting context; required but deliberately lower gravity"
        }
        let hasReaderContribution = page.hasReaderContribution
        if page.bookAuthoredText != nil {
            return hasReaderContribution
                ? "Book-written Page with a reader contribution; high gravity"
                : "Book-written fiction; medium gravity"
        }
        switch page.origin {
        case .userAuthored:
            if page.type == .souvenir {
                return "reader-authored anchor; one-sentence souvenir; highest gravity"
            }
            return "reader-authored anchor; high gravity"
        case .imported:
            return "imported real-world anchor; high gravity"
        case .generated, .simulated:
            if hasReaderContribution {
                return "Book-written Page with a reader contribution; high gravity"
            }
            return "Book-written fiction; medium gravity"
        }
    }

    private static func mediaEvidence(for page: BookPage) -> String {
        let readerMedia = page.readerReadableEvidence
            .filter { $0.mediaAssetID != nil }
            .map(\.text)
        let readerMediaIDs = Set(page.readerReadableEvidence.compactMap(\.mediaAssetID))
        let otherMedia = page.mediaAssets
            .filter { !readerMediaIDs.contains($0.id) }
            .prefix(3)
            .map { asset in
                let kind: String
                switch asset.kind {
                case .bundledImage:
                    kind = "bundled Labyrinth illustration"
                case .renderedImageFile:
                    kind = "kept illuminated page image"
                case .photoLibraryAsset:
                    kind = "private source photo reference"
                case .audioFile:
                    kind = "kept voice recording"
                }
                let caption = clippedText(asset.caption, limit: 140)
                return caption.isEmpty ? kind : "\(kind): \(caption)"
            }
        return (readerMedia + otherMedia)
            .prefix(3)
            .joined(separator: "; ")
    }

    private static func clippedText(_ value: String, limit: Int) -> String {
        let normalized = value
            .replacingOccurrences(of: "\n", with: " ")
            .replacingOccurrences(of: "  ", with: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard normalized.count > limit else { return normalized }
        let end = normalized.index(normalized.startIndex, offsetBy: limit)
        // Deliberately a hard character cut, not a sentence-aware one. This
        // text feeds the prompt - `LivedBeat.excerpt`, evidence lines,
        // `magicLicense` - and never the finished page, which is written from
        // `cleanSourceText` and is already word-safe. Making these lines
        // shorter lets the evidence packet seat more pages, which pushed a
        // heavy night from 19k to 20.3k characters against a 21.09k allowance
        // and left almost no headroom before `LocalBrainPromptBudget.fit`
        // starts clipping the middle of the prompt. Mid-sentence fragments in
        // the reader's prose came from composed page bodies, and are handled
        // in `DeterministicBraidwright.strippedScaffolding`.
        return normalized[..<end].trimmingCharacters(in: .whitespacesAndNewlines) + "..."
    }
}

enum BraidOutputAudit {
    enum Issue: String, Equatable, CaseIterable {
        case tooShort
        /// Clears the floor but falls short of the scale's promised band. The
        /// floor says "this is a braid at all"; the band says "this is the page
        /// tonight deserved". Without a finding between them a page could sit
        /// twenty-six words under its band forever and nothing in the system
        /// would ever mention it.
        case underBand
        case tooFewParagraphs
        case missingRitualEnding
        case missingTruthAnchor
        case tooFewEvidenceThreads
        case supportingLogsTookOver
        case storyScoreDrift
        case missingRelationalLens
        case arcMovementLost
        case missingContinuityBeat
        /// The page answered each supplied fact with a filing action - a fact
        /// from the reader, then "I put / kept / set" that fact somewhere,
        /// over and over. The individual lines may all be grammatical and
        /// sourced; the sequence is still an inventory rather than a tale.
        case clericalCadence
        case exposedRealitySeam
        case bookSpokeFromOutside
        case servantVoice
        /// The four below only fire on nights carrying shadow material. Along
        /// with the voice/seam failures above, these are hard failures;
        /// every other issue in this list is a repairable craft miss.
        case consoledUnbidden
        case resolvedTheUnresolved
        case assignedMeaning
        case spokeForTheReader

        /// Register failures outrank craft failures. A short page is a bad page;
        /// a page that consoles someone who did not ask is a broken promise.
        var isRegisterFailure: Bool {
            switch self {
            case .exposedRealitySeam, .bookSpokeFromOutside, .servantVoice,
                 .consoledUnbidden, .resolvedTheUnresolved, .assignedMeaning, .spokeForTheReader:
                return true
            default:
                return false
            }
        }

        /// Craft findings lower a draft's chance; they do not turn the audit
        /// into a lexicographic veto over literary quality. Register failures
        /// never enter selection and therefore need no numeric weight here.
        var selectionPenalty: Int {
            switch self {
            case .tooShort: return 13
            case .underBand: return 6
            case .tooFewParagraphs: return 4
            case .missingRitualEnding: return 14
            case .missingTruthAnchor: return 12
            case .tooFewEvidenceThreads: return 7
            case .supportingLogsTookOver: return 8
            case .storyScoreDrift: return 12
            case .missingRelationalLens, .arcMovementLost: return 6
            case .missingContinuityBeat: return 13
            case .clericalCadence: return 12
            case .exposedRealitySeam, .bookSpokeFromOutside, .servantVoice,
                 .consoledUnbidden, .resolvedTheUnresolved, .assignedMeaning, .spokeForTheReader:
                return Int.max
            }
        }

        var repairInstruction: String {
            switch self {
            case .tooShort:
                return "Give the supplied scale its promised room; do not return a fragment when the day calls for a braid."
            case .underBand:
                return "The page is under its scale's word band. Do not pad it: take one supplied receipt you left as a passing mention and give it its own concrete beat."
            case .tooFewParagraphs:
                return "Build the required multi-paragraph movement instead of compressing the day into one block."
            case .missingRitualEnding:
                return "Finish with exactly one sentence beginning The Book kept the page:."
            case .missingTruthAnchor:
                return "Restore a concrete word, object, action, or image from the supplied truth anchor."
            case .tooFewEvidenceThreads:
                return "Weave distinct concrete details from more than one non-log kept page."
            case .supportingLogsTookOver:
                return "Move Weather, Body, and Inner Weather to the edge; let the non-log keeps own the spine, title, and ending."
            case .storyScoreDrift:
                return "Return to the selected lived anchors in the Nightly Story Score; they are the story's factual spine."
            case .missingRelationalLens:
                return "Dramatize the supplied relational lens through its concrete condition and outcome without naming analysis or causation."
            case .arcMovementLost:
                return "Make tonight's exact arc change legible; do not merely repeat the prior state or write a standalone summary."
            case .missingContinuityBeat:
                return "Restore the selected braid-continuity move. Preserve the earlier fictional anchor or concrete prior Page exactly as supplied, and let tonight's anchor change it by one visible notch."
            case .clericalCadence:
                return "Stop answering each receipt with I put, I kept, I set, or another filing action. Let several supplied facts inhabit one scene, then spend the Book's voice on one turn or consequence."
            case .exposedRealitySeam:
                return "Remove labels such as fiction, real life, lived shelf, or margins. Let the provenanced worlds cross without announcing the seam."
            case .bookSpokeFromOutside:
                return "Speak as I, me, and my. The fixed keeper colophon is the only place allowed to say The Book."
            case .servantVoice:
                return "Delete service-language, reassurance, advice, and synthetic empathy. Let the Book want, notice, refuse, or keep something concrete."
            case .consoledUnbidden:
                return "You were not asked to comfort. Delete the reassurance and report what was there; leave the reader their own response to it."
            case .resolvedTheUnresolved:
                return "Nothing supplied says this ended, healed, or was made peace with. Take the closure back out and let it stay open."
            case .assignedMeaning:
                return "Give the thing a shape, not a purpose. Delete the clause that explains what it was for or what it taught."
            case .spokeForTheReader:
                return "Do not name what the reader felt or what was happening inside them. Name what was in the room."
            }
        }
    }

    /// Phrases that turn a report into a consolation. Matched on the page's own
    /// words, not on the evidence, because the failure is always in the telling.
    /// The length bar a braid has to clear, published so the Book's own house
    /// writer can aim at it. When these lived only inside the audit, the
    /// authored page came in a handful of words short every single night and
    /// carried a craft penalty into the tasting room for it.
    static func minimumWords(for scale: BraidPromptBuilder.BraidScale) -> Int {
        switch scale {
        case .glimpse: return 60
        case .small: return 110
        case .full: return 180
        }
    }

    static func minimumParagraphs(for scale: BraidPromptBuilder.BraidScale) -> Int {
        switch scale {
        case .glimpse: return 2
        case .small: return 3
        case .full: return 4
        }
    }

    private static let consolationPhrases: [String] = [
        "it's okay", "it is okay", "that's okay", "you did your best", "you did what you could",
        "be gentle with yourself", "be kind to yourself", "you are allowed", "you're allowed",
        "that was enough", "you were enough", "you are enough", "there is no shame",
        "nothing to be ashamed", "don't be hard on yourself", "give yourself"
    ]
    private static let closurePhrases: [String] = [
        "at last", "finally over", "it was over", "healed", "healing began", "closure",
        "moved on", "made peace", "let it go", "let them go", "put it behind",
        "the worst was over", "you were free of", "no longer hurt", "stopped hurting"
    ]
    private static let meaningPhrases: [String] = [
        "what it taught", "taught you", "the lesson", "for a reason", "meant to be",
        "so that you could", "needed to happen", "it was necessary", "in the end it made",
        "made you stronger", "you would understand why", "the point of it", "purpose of it"
    ]
    private static let interiorityPhrases: [String] = [
        "you felt", "you must have felt", "you were feeling", "part of you",
        "deep down", "something in you", "you knew then that", "you told yourself",
        "your heart", "you were afraid", "inside you"
    ]
    private static let servantPhrases: [String] = BookVoice.drainedPhrases + [
        "thank you for sharing", "i'm here to help", "i am here to help", "gentle reminder",
        "your journey", "it seems that", "you should", "you did your best", "you are enough",
        "it's okay", "it is okay", "that's okay", "be gentle with yourself"
    ]

    private static let weatherWords: Set<String> = [
        "weather", "rain", "raining", "rainy", "drizzle", "drizzling", "snow", "sleet",
        "storm", "stormy", "fog", "foggy", "mist", "misty", "wind", "windy", "cloud",
        "clouds", "cloudy", "overcast", "sun", "sunny", "humid", "breeze"
    ]
    private static let genericEvidenceWords: Set<String> = weatherWords.union([
        "book", "page", "pages", "kept", "keep", "today", "tonight", "thing", "things",
        "reader", "story", "looked", "felt", "made", "came", "went", "said", "time"
    ])

    static func issues(
        in text: String,
        for day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> [Issue] {
        let reading = context.taleReading ?? BraidPromptBuilder.taleReading(for: day, context: context)
        let normalized = text.trimmingCharacters(in: .whitespacesAndNewlines)
        let words = normalized.split { $0.isWhitespace || $0.isNewline }
        let paragraphs = normalized
            .components(separatedBy: "\n\n")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        var result: [Issue] = []

        // A page written to an earned range is judged against that range. The
        // scale's band is an aspiration; the earned range is what the night's
        // material could honestly fill.
        let band = context.earnedWordBand ?? reading.scale.targetWordBand
        if words.count < min(minimumWords(for: reading.scale), band.lowerBound) {
            result.append(.tooShort)
        } else if words.count < band.lowerBound {
            result.append(.underBand)
        }
        if paragraphs.count < minimumParagraphs(for: reading.scale) {
            result.append(.tooFewParagraphs)
        }
        if !normalized.contains("The Book kept the page:") { result.append(.missingRitualEnding) }

        let outputWords = contentWords(in: normalized)
        let anchorWords = contentWords(in: reading.anchor).subtracting(genericEvidenceWords)
        if anchorWords.count >= 2, outputWords.isDisjoint(with: anchorWords) {
            result.append(.missingTruthAnchor)
        }
        if let score = context.storyScore {
            let matchedLived = score.livedBeats.filter { beat in
                let words = contentWords(in: beat.excerpt).subtracting(genericEvidenceWords)
                return words.isEmpty || !outputWords.isDisjoint(with: words)
            }.count
            let requiredLived: Int
            switch score.taleReading.scale {
            case .glimpse: requiredLived = min(1, score.livedBeats.count)
            case .small: requiredLived = min(2, score.livedBeats.count)
            case .full: requiredLived = min(3, score.livedBeats.count)
            }
            if matchedLived < requiredLived {
                result.append(.storyScoreDrift)
            }
            // Kept fiction is evidence too. The drift check only ever looked
            // at lived beats, so a Labyrinth receipt the score had selected
            // could vanish from the page without the audit noticing - which
            // matters more now that a full night may carry four of them.
            let selectedFiction = [score.fictionBeat].compactMap { $0 }
                + score.additionalFictionBeats
            // Deliberately not this file's `contentWords`, which keeps every
            // token of three characters or more - "the" and "and" alone
            // satisfied a two-word overlap, so every selected receipt counted
            // as present and the check could never fail.
            let strictOutput = BraidRevisionVerifier.contentWords(in: normalized)
            let matchedFiction = selectedFiction.filter { beat in
                let words = BraidRevisionVerifier.contentWords(in: beat.choice)
                    .subtracting(genericEvidenceWords)
                let overlap = strictOutput.intersection(words)
                return words.isEmpty || overlap.count >= min(2, words.count)
            }.count
            if matchedFiction < selectedFiction.count,
               !result.contains(.storyScoreDrift) {
                result.append(.storyScoreDrift)
            }
            if let lens = score.relationalLens, lens.evidenceTier != .glimmer {
                let lensWords = contentWords(in: "\(lens.condition) \(lens.outcomes.joined(separator: " "))")
                    .subtracting(genericEvidenceWords)
                if lensWords.count >= 2, outputWords.isDisjoint(with: lensWords) {
                    result.append(.missingRelationalLens)
                }
            }
            if let arc = score.arc {
                let arcWords = contentWords(in: arc.tonightDelta).subtracting(genericEvidenceWords)
                let movementWords: Set<String>
                switch arc.movement {
                case .began: movementWords = ["first", "notch"]
                case .deepened: movementWords = ["older", "harder"]
                case .complicated: movementWords = ["forked", "cuts"]
                case .returned: movementWords = ["before", "changed"]
                case .resolved: movementWords = ["last", "stop"]
                case .rested: movementWords = ["move", "open"]
                }
                let carriesTypedMovement = movementWords.isSubset(of: outputWords)
                if arcWords.count >= 2,
                   outputWords.isDisjoint(with: arcWords),
                   !carriesTypedMovement {
                    result.append(.arcMovementLost)
                }
            }
        }
        if let continuity = context.continuityBeat,
           !carriesContinuity(continuity, in: normalized) {
            result.append(.missingContinuityBeat)
        }

        let storyPages = BraidPromptBuilder.partitionedPagesForBraid(in: day).story.filter { page in
            let permittedShadow = ReaderShelf.of(page) != .shadow
                || context.readerStory.shadowPermission != .knowButNeverWrite
            let storyReceipt = BraidPromptBuilder.braidShelf(for: page) == "lived"
                || BraidPromptBuilder.isLabyrinthReceipt(page)
            return permittedShadow && storyReceipt
        }
        let rawPageWordSets = storyPages.map { page -> Set<String> in
            let source = page.playerReply.nonEmpty ?? page.userInput.nonEmpty ?? BraidPromptBuilder.mediaEvidence(for: page) ?? page.promptText
            return contentWords(in: source).subtracting(genericEvidenceWords)
        }
        let wordFrequency = rawPageWordSets.reduce(into: [String: Int]()) { frequency, words in
            for word in words { frequency[word, default: 0] += 1 }
        }
        let maximumSharedFrequency = max(2, storyPages.count / 3)
        let eligiblePageWordSets = rawPageWordSets.compactMap { rawWords -> Set<String>? in
            let words = rawWords.filter { wordFrequency[$0, default: 0] <= maximumSharedFrequency }
            return words.count >= 2 ? words : nil
        }
        let matchedThreadCount = eligiblePageWordSets.filter { !outputWords.isDisjoint(with: $0) }.count
        let requiredThreadCount: Int
        switch reading.scale {
        case .glimpse:
            requiredThreadCount = min(1, eligiblePageWordSets.count)
        case .small:
            requiredThreadCount = min(2, eligiblePageWordSets.count)
        case .full:
            requiredThreadCount = min(3, eligiblePageWordSets.count)
        }
        if matchedThreadCount < requiredThreadCount {
            result.append(.tooFewEvidenceThreads)
        }

        if !storyPages.isEmpty, !reading.visibleSupportingLogs {
            // A weather word the reader put in their own story page is their
            // material, not a log colonizing the evening. Only words the page
            // could not have got from a story receipt can count as a takeover -
            // otherwise a diary entry about the rain convicts itself.
            let suppliedWeather = storyPages.reduce(into: Set<String>()) { supplied, page in
                let source = page.playerReply.nonEmpty ?? page.userInput.nonEmpty ?? BraidPromptBuilder.mediaEvidence(for: page) ?? page.promptText
                supplied.formUnion(contentWords(in: source).intersection(weatherWords))
            }
            let intrudingWeather = weatherWords.subtracting(suppliedWeather)
            let sentences = normalized
                .components(separatedBy: CharacterSet(charactersIn: ".!?"))
                .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                .filter { !$0.isEmpty }
            let weatherSentenceCount = sentences.filter {
                !contentWords(in: $0).isDisjoint(with: intrudingWeather)
            }.count
            if weatherSentenceCount >= 2, weatherSentenceCount * 2 >= max(sentences.count, 1) {
                result.append(.supportingLogsTookOver)
            }
        }

        let authoredText = withoutAttributedSourceQuotes(
            normalized,
            for: day,
            context: context
        )
        let spokenText = authoredText.replacingOccurrences(of: "The Book kept the page:", with: "")
        if spokenText.range(
            of: #"\bthe book\b"#,
            options: [.regularExpression, .caseInsensitive]
        ) != nil {
            result.append(.bookSpokeFromOutside)
        }
        let lowered = authoredText.lowercased()
        let seamLabels = [
            "in fiction", "in the fiction", "in real life", "in the lived room",
            "fictional choice", "fiction bridge", "lived event", "two shelves",
            "lived shelf", "fiction shelf", "in the margins, not", "in the margins, not"
        ]
        if seamLabels.contains(where: lowered.contains) {
            result.append(.exposedRealitySeam)
        }
        if servantPhrases.contains(where: lowered.contains) {
            result.append(.servantVoice)
        }

        // A night carrying hard, unpermitted material is allowed to be plain.
        // Filing cadence is a craft failure on an ordinary page and the right
        // restraint on a page holding something heavy.
        let carriesUnclearedShadow = BraidPromptBuilder.braidEligiblePages(in: day).contains { page in
            ReaderShelf.of(page) == .shadow
                && context.readerStory.shadowPermission != .knowButNeverWrite
                && !context.readerStory.shadowMayTakeTaleForm(
                    keptAt: page.createdAt,
                    now: day.date
                )
        }
        if !carriesUnclearedShadow, hasClericalCadence(in: authoredText) {
            result.append(.clericalCadence)
        }

        result += registerIssues(in: authoredText, for: day, context: context)
        return result
    }

    static func carriesContinuity(
        _ beat: BraidPromptBuilder.ContinuityBeat,
        in text: String
    ) -> Bool {
        let output = contentWords(in: text)
        let current = contentWords(in: beat.currentAnchor).subtracting(genericEvidenceWords)
        let carriesCurrent = current.isEmpty || !output.isDisjoint(with: current)

        switch beat.kind {
        case .fictionOpening:
            let markers = fictionMarkers[beat.threadID ?? ""] ?? Set([beat.threadID ?? ""])
            let meaningfulMarkers = Set(markers.filter { !$0.isEmpty })
            return carriesCurrent && !output.isDisjoint(with: meaningfulMarkers)
        case .fictionContinuation:
            let prior = contentWords(in: beat.priorAnchor ?? "").subtracting(genericEvidenceWords)
            let markers = fictionMarkers[beat.threadID ?? ""] ?? Set([beat.threadID ?? ""])
            let meaningfulMarkers = Set(markers.filter { !$0.isEmpty })
            let carriesPrior = !prior.isEmpty && !output.isDisjoint(with: prior)
            return carriesCurrent
                && carriesPrior
                && !output.isDisjoint(with: meaningfulMarkers)
        case .fictionResolution:
            let prior = contentWords(in: beat.priorAnchor ?? "").subtracting(genericEvidenceWords)
            let previous = contentWords(in: beat.previousAnchor ?? "")
                .subtracting(genericEvidenceWords)
            let markers = fictionMarkers[beat.threadID ?? ""] ?? Set([beat.threadID ?? ""])
            let meaningfulMarkers = Set(markers.filter { !$0.isEmpty })
            let carriesPrior = !prior.isEmpty && !output.isDisjoint(with: prior)
            let carriesPrevious = previous.isEmpty || !output.isDisjoint(with: previous)
            return carriesCurrent
                && carriesPrior
                && carriesPrevious
                && !output.isDisjoint(with: meaningfulMarkers)
        case .evidenceRhyme:
            let old = contentWords(in: "\(beat.sourceTitle ?? "") \(beat.priorLine ?? "")")
                .subtracting(genericEvidenceWords)
            return carriesCurrent && !old.isEmpty && !output.isDisjoint(with: old)
        }
    }

    /// The words that prove a thread's move actually reached the page. One
    /// entry per id in `serialFictionThreadIDs`; a missing entry falls back to
    /// the id itself, which silently fails for any thread whose prose does not
    /// contain its own key.
    private static let fictionMarkers: [String: Set<String>] = [
        "stacks": ["stacks", "shelf", "shelves"],
        "door": ["door", "doors", "corridor"],
        "index": ["index"],
        "frost": ["frost", "window", "glass"],
        "echo": ["room"],
        "ribbon": ["ribbon"],
        "lamps": ["lamp", "lamps", "building"],
        "birds": ["birds", "roof"],
        "rain": ["rained", "floor", "dark"],
        "doors": ["door", "doors"],
        "moth": ["moth", "hole", "border"],
        "stairs": ["stairs", "step"],
        "pocket": ["pocket", "cover"],
        "bell": ["bell", "floor"],
        "dust": ["dust", "circle"],
        "roof": ["roof", "chimney", "news"],
        // Beat threads. These only exist while a tale is open, but continuity
        // can still pick one up the next night, and without a marker entry the
        // verifier falls back to the key itself - which no beat thread's prose
        // contains, so every one of them would silently fail its own check.
        "price": ["bill", "costs", "amount"],
        "donor": ["offer", "trade", "offered"],
        "crossing": ["threshold"],
        "test": ["question", "answer"],
        "lack": ["gap", "missing", "row"],
        "transgression": ["chalk", "line", "scuff"],
        "consequence": ["followed", "following"],
        "transformation": ["difference", "become", "arrived"],
        "return": ["back", "corridor", "road"],
        "taken-in": ["taken", "given"]
    ]

    /// A lexical check is appropriate here because the failure is a repeated
    /// sentence *role*, not the presence of any one forbidden phrase. One
    /// hungry "I kept it" can be the Book. Three handling verbs in one page
    /// are the Book narrating its filing system. Quoted source text has already
    /// been removed by the caller, and the ritual colophon is excluded.
    static func hasClericalCadence(in text: String) -> Bool {
        let body = text.replacingOccurrences(
            of: #"(?im)^The Book kept the page:.*$"#,
            with: "",
            options: .regularExpression
        )
        let sentences = body
            .components(separatedBy: CharacterSet(charactersIn: ".!?"))
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        let handlingPattern = #"(?i)\bI\s+(?:put|set|kept|placed|filed|tucked|added|marked|circled|underlined|drew|copied|read|checked|laid|moved)\b"#
        let handling = sentences.filter {
            $0.range(of: handlingPattern, options: .regularExpression) != nil
        }
        return handling.count >= 3
    }

    /// Only runs on nights that carry shadow material. On an ordinary day these
    /// phrases are harmless warmth; on a day holding real weight they are the
    /// Book overstepping, and the repair loop should catch them before the page
    /// is ever shown.
    static func registerIssues(
        in text: String,
        for day: BookDay,
        context: BraidPromptBuilder.Context = .empty
    ) -> [Issue] {
        let carriesShadow = BraidPromptBuilder.partitionedPagesForBraid(in: day).story
            .filter(ReaderShelf.isWeavable)
            .contains { ReaderShelf.of($0) == .shadow }
        guard carriesShadow else { return [] }

        let lowered = withoutAttributedSourceQuotes(
            text,
            for: day,
            context: context
        ).lowercased()
        var result: [Issue] = []
        if consolationPhrases.contains(where: lowered.contains) { result.append(.consoledUnbidden) }
        if closurePhrases.contains(where: lowered.contains) { result.append(.resolvedTheUnresolved) }
        if meaningPhrases.contains(where: lowered.contains) { result.append(.assignedMeaning) }
        if interiorityPhrases.contains(where: lowered.contains) { result.append(.spokeForTheReader) }
        return result
    }

    private static func withoutAttributedSourceQuotes(
        _ text: String,
        for day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> String {
        let sourceTexts = BraidPromptBuilder.braidEligiblePages(in: day)
            .filter {
                ReaderShelf.of($0) != .shadow
                    || context.readerStory.shadowPermission != .knowButNeverWrite
            }
            .flatMap { page in
                [page.userInput, page.playerReply, page.promptText]
            }
            .map(auditComparableText)
            .filter { !$0.isEmpty }

        var result = ""
        var pendingQuote = ""
        var insideQuote = false
        for character in text {
            if character == "«" {
                if insideQuote {
                    pendingQuote.append(character)
                    continue
                }
                insideQuote = true
                pendingQuote = ""
                continue
            }
            if character == "»" {
                if insideQuote {
                    insideQuote = false
                    let comparable = auditComparableText(pendingQuote)
                        .trimmingCharacters(in: CharacterSet(charactersIn: ".…"))
                    let isSourced = !comparable.isEmpty
                        && sourceTexts.contains { $0.contains(comparable) }
                    if !isSourced { result += pendingQuote }
                    pendingQuote = ""
                    continue
                }
                result.append(character)
                continue
            }
            if insideQuote {
                pendingQuote.append(character)
            } else {
                result.append(character)
            }
        }
        // An unmatched opening mark is authored output, not a license to hide
        // the remainder of a broken draft from the register audit.
        if insideQuote { result += "«" + pendingQuote }
        return result
    }

    private static func auditComparableText(_ text: String) -> String {
        text.lowercased()
            .components(separatedBy: .whitespacesAndNewlines)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func contentWords(in text: String) -> Set<String> {
        Set(
            text.lowercased()
                .components(separatedBy: CharacterSet.alphanumerics.inverted)
                .filter { $0.count >= 3 }
        )
    }
}

/// Chooses the strongest generated braid that is still safe to show.
///
/// The output audit contains two different kinds of findings: literary craft
/// misses (a short page, a weak evidence thread, a missing ritual line) and
/// hard failures that break the reader's trust around voice, provenance, or
/// shadow material.
/// Craft misses should request a repair, but they must not make us discard
/// every nonempty model draft in favour of the deterministic understudy. A
/// register failure is different: it remains an absolute rejection.
enum BraidGenerationSelector {
    struct Selection: Equatable {
        var page: BookPage
        var issues: [BraidOutputAudit.Issue]
        var tastingScore: BraidTastingRoom.Score

        var isClean: Bool { issues.isEmpty }
    }

    static func bestUsable(
        from pages: [BookPage],
        day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> Selection? {
        let tasted = BraidTastingRoom.taste(
            pages.filter { !$0.userInput.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty },
            context: context
        )

        // The audit is a bounded craft tax, not a caste system. A vivid Gemma
        // page with one repairable miss may beat a technically spotless house
        // cut; a register-breaking page never enters the race.
        var best: Selection?
        var bestAdjustedScore = Int.min
        for sample in tasted.samples {
            let issues = BraidOutputAudit.issues(in: sample.page.userInput, for: day, context: context)
            guard !issues.contains(where: \.isRegisterFailure) else { continue }
            let candidate = Selection(page: sample.page, issues: issues, tastingScore: sample.score)
            let penalty = issues.reduce(0) { $0 + $1.selectionPenalty }
            let adjustedScore = sample.score.total(guidedBy: context.learnedGuidance) - penalty
            if best == nil
                || adjustedScore > bestAdjustedScore
                || (adjustedScore == bestAdjustedScore && issues.count < best!.issues.count) {
                best = candidate
                bestAdjustedScore = adjustedScore
            }
        }
        return best
    }
}

/// One sentence of a braid, and the authority it speaks with.
///
/// The house writer does not merely emit text: it emits text plus a map of
/// where each sentence's authority comes from. That map is what makes it safe
/// to let a language model rewrite the page afterwards. Invention about the
/// Book is voice; invention about the reader's life is a lie, and only the
/// writer that assembled the page knows which sentence is which.
struct BraidSentence: Equatable {
    enum Provenance: Equatable {
        /// The reader's own facts, retold in the Book's grammar.
        case receipt(pageID: String)
        /// The reader's exact words, inside quotation marks.
        case quotedReceipt(pageID: String)
        /// The Book's own voice: appetite, refusal, what it did with the page.
        case authored
        /// The ritual closing line.
        case colophon
    }

    enum License: Equatable {
        /// The music may change. Not one content word may.
        case strict
        /// Free vocabulary, still answerable to the register audit.
        case free
        /// Not revisable at all.
        case locked
    }

    var text: String
    var provenance: Provenance

    var license: License {
        switch provenance {
        case .receipt: return .strict
        case .quotedReceipt, .colophon: return .locked
        case .authored: return .free
        }
    }

    var pageID: String? {
        switch provenance {
        case let .receipt(pageID), let .quotedReceipt(pageID): return pageID
        case .authored, .colophon: return nil
        }
    }
}

/// A finished braid with its provenance intact.
struct BraidComposition: Equatable {
    var title: String
    var paragraphs: [[BraidSentence]]
    var tags: [String]
    var promptText: String

    var sentences: [BraidSentence] { paragraphs.flatMap { $0 } }

    var text: String {
        ([title] + paragraphs.map { $0.map(\.text).joined(separator: " ") })
            .joined(separator: "\n\n")
    }

    var bodyWordCount: Int {
        paragraphs.reduce(0) { total, paragraph in
            total + paragraph.reduce(0) {
                $0 + $1.text.split { $0.isWhitespace || $0.isNewline }.count
            }
        }
    }

    /// Sentence lengths in order, for prosody work and for the bench.
    var sentenceLengths: [Int] {
        sentences.map { $0.text.split { $0.isWhitespace || $0.isNewline }.count }
    }

    /// What the page sounds like, as opposed to what it says.
    ///
    /// Lexical variety over a fixed shape reads as a template within a week;
    /// rhythm is most of what reads as authorship. These are the two failures
    /// that carry: sentences that all start the same way, and sentences that
    /// are all the same length.
    struct Prosody: Equatable {
        /// Adjacent sentences sharing an opening word. The Book's own voice is
        /// first person, so without care a paragraph becomes "I… I… I…".
        var repeatedOpenings: Int
        /// The longest run of adjacent sentences within two words of each
        /// other. Three mediums in a row is prose sludge.
        var longestFlatRun: Int
        var lengthSpread: Int

        /// Lower is better. Used only to break ties between candidates that the
        /// tasting room already considers equal.
        var penalty: Int { repeatedOpenings * 3 + max(0, longestFlatRun - 2) }
    }

    var prosody: Prosody {
        let texts = sentences.map(\.text)
        let lengths = sentenceLengths
        guard !texts.isEmpty else {
            return Prosody(repeatedOpenings: 0, longestFlatRun: 0, lengthSpread: 0)
        }
        let openings = texts.map { BraidComposition.openingWord(of: $0) }
        var repeated = 0
        for index in 1..<max(openings.count, 1) where openings[index] == openings[index - 1] {
            repeated += 1
        }
        var longestFlat = 1
        var currentFlat = 1
        for index in 1..<max(lengths.count, 1) {
            if abs(lengths[index] - lengths[index - 1]) <= 2 {
                currentFlat += 1
                longestFlat = max(longestFlat, currentFlat)
            } else {
                currentFlat = 1
            }
        }
        return Prosody(
            repeatedOpenings: repeated,
            longestFlatRun: lengths.count > 1 ? longestFlat : 0,
            lengthSpread: (lengths.max() ?? 0) - (lengths.min() ?? 0)
        )
    }

    static func openingWord(of sentence: String) -> String {
        sentence
            .split { !$0.isLetter && !$0.isNumber && $0 != "'" }
            .first
            .map { String($0).lowercased() } ?? ""
    }

    var page: BookPage {
        BookPage(
            type: .bookOfYou,
            promptText: promptText,
            userInput: text,
            tags: tags,
            usedInBookOfYou: true
        )
    }
}

/// Rearranges a supplied sentence without adding to it.
///
/// This is the compiler half of the same bargain the model is held to: a
/// transform may move the reader's words around, and may not bring any of its
/// own. Each one is *attempted, then verified*: if the rearranged sentence
/// cannot pass `BraidRevisionVerifier.preservesFacts`, it does not fire and the
/// supplied sentence stands. A transform either type-checks or it doesn't.
enum BraidProseTransform: String, CaseIterable {
    /// The supplied sentence, untouched.
    case identity
    /// A trailing prepositional phrase moved to the front.
    /// "You tightened the screw on the chair." → "On the chair, you tightened the screw."
    case frontedPhrase
    /// "It was X that you Yed." Adds only function words.
    case cleft
    /// One clause becomes two sentences at a conjunction, for rhythm.
    /// "You carried soup to Sam and forgot the spoon." → "…to Sam. And forgot the spoon."
    case splitAtConjunction

    /// Try the transforms in an order seeded by `variant` and return the first
    /// that both applies and survives verification.
    static func rearranged(_ sentence: String, variant: Int) -> String {
        let order = rotated(by: variant)
        for transform in order where transform != .identity {
            guard let candidate = transform.apply(to: sentence),
                  candidate != sentence,
                  BraidRevisionVerifier.preservesFacts(candidate, of: sentence) else { continue }
            return candidate
        }
        return sentence
    }

    private static func rotated(by variant: Int) -> [BraidProseTransform] {
        let working = allCases.filter { $0 != .identity }
        guard !working.isEmpty else { return [] }
        let offset = ((variant % working.count) + working.count) % working.count
        return Array(working[offset...] + working[..<offset])
    }

    func apply(to sentence: String) -> String? {
        switch self {
        case .identity: return sentence
        case .frontedPhrase: return BraidProseTransform.front(sentence)
        case .cleft: return BraidProseTransform.cleave(sentence)
        case .splitAtConjunction: return BraidProseTransform.splitClause(sentence)
        }
    }

    // MARK: - Transforms

    /// Move a trailing prepositional phrase to the front. Only fires when the
    /// phrase really is the tail of the sentence and carries no verb of its
    /// own, because "on the chair you had been meaning to fix" is a clause, not
    /// a place, and fronting it changes the sentence's spine.
    private static func front(_ sentence: String) -> String? {
        let tokens = tagged(sentence)
        guard tokens.count >= 6 else { return nil }
        for index in stride(from: tokens.count - 1, through: 2, by: -1) {
            // Only adjuncts may be fronted. "Of the car" and "to the bank"
            // belong to the noun or the verb they follow, and hoisting one to
            // the front of the sentence produces confident nonsense.
            guard tokens[index].isPreposition,
                  frontableAdjuncts.contains(tokens[index].word.lowercased()) else { continue }
            let tail = tokens[(index + 1)...]
            // An adjunct that can be hoisted ends on its own noun and does not
            // lean on a pronoun for its meaning. "...painted a handle on it
            // anyway" satisfied the old guard and fronted as "On it anyway, a
            // door had been painted shut" - confident nonsense, and pointing
            // at an antecedent that is no longer in front of it.
            let frontablePronouns: Set<String> = [
                "it", "them", "him", "her", "us", "me", "you", "this", "that",
                "these", "those", "here", "there"
            ]
            guard tail.count >= 2,
                  tail.contains(where: \.isNoun),
                  tail.last?.isNoun == true,
                  !tail.contains(where: { frontablePronouns.contains($0.word.lowercased()) }),
                  !tail.contains(where: \.isVerb),
                  !tail.contains(where: \.isPreposition),
                  index >= 2 else { continue }
            let head = tokens[..<index]
            guard head.contains(where: \.isVerb), head.count >= 3 else { continue }

            let phrase = tokens[index...].map(\.word).joined(separator: " ")
            let remainder = head.map(\.word).joined(separator: " ")
            return "\(capitalizedFirst(phrase)), \(lowercasedFirst(remainder))."
        }
        return nil
    }

    /// "It was the loose screw that you tightened." Everything it adds: it,
    /// was, that: is grammar.
    private static func cleave(_ sentence: String) -> String? {
        let tokens = tagged(sentence)
        guard tokens.count >= 5,
              tokens[0].word.lowercased() == "you",
              tokens[1].isVerb else { return nil }
        let remainder = Array(tokens[2...])
        guard remainder.count >= 3,
              let first = remainder.first,
              first.isDeterminer || first.isNoun || first.isAdjective,
              remainder.contains(where: \.isNoun),
              !remainder.contains(where: \.isVerb) else { return nil }
        // A temporal phrase modifies the verb, not the thing. "It was the blue
        // door before breakfast that you painted" swallows the clock into the
        // object; the coda has to stay with the action it timed.
        let cut = remainder.firstIndex { temporalPrepositions.contains($0.word.lowercased()) }
        let objectTokens = cut.map { Array(remainder[..<$0]) } ?? remainder
        let codaTokens = cut.map { Array(remainder[$0...]) } ?? []
        guard objectTokens.count >= 2, objectTokens.contains(where: \.isNoun) else { return nil }

        let object = objectTokens.map(\.word).joined(separator: " ")
        let coda = codaTokens.isEmpty ? "" : " " + codaTokens.map(\.word).joined(separator: " ")
        return "It was \(object) that you \(tokens[1].word.lowercased())\(coda)."
    }

    /// Prepositions that head a phrase modifying the whole clause, rather than
    /// the noun or verb immediately before them.
    private static let frontableAdjuncts: Set<String> = [
        "in", "on", "at", "under", "over", "above", "below", "beneath", "beside",
        "behind", "near", "outside", "inside", "through", "across", "along",
        "past", "within", "during", "before", "after"
    ]

    private static let temporalPrepositions: Set<String> = [
        "before", "after", "during", "until", "since", "while"
    ]

    /// Split a two-clause sentence in half for rhythm. The conjunction stays;
    /// it just starts the second sentence instead of joining the first.
    private static func splitClause(_ sentence: String) -> String? {
        let body = sentence.trimmingCharacters(in: .whitespaces)
        guard let terminal = body.last, ".!?".contains(terminal) else { return nil }
        let stripped = String(body.dropLast())
        guard let range = stripped.range(of: " and ") else { return nil }
        let left = String(stripped[..<range.lowerBound]).trimmingCharacters(in: .whitespaces)
        let right = String(stripped[range.upperBound...]).trimmingCharacters(in: .whitespaces)
        guard left.split(whereSeparator: \.isWhitespace).count >= 4,
              right.split(whereSeparator: \.isWhitespace).count >= 3,
              !left.contains(","),
              tagged(right).first?.isVerb == true else { return nil }
        return "\(left)\(terminal) And \(right)\(terminal)"
    }

    // MARK: - Shallow tagging

    struct Token {
        var word: String
        var isNoun = false
        var isVerb = false
        var isPreposition = false
        var isDeterminer = false
        var isAdjective = false
    }

    static func tagged(_ text: String) -> [Token] {
        #if canImport(NaturalLanguage)
        let tagger = NLTagger(tagSchemes: [.lexicalClass])
        tagger.string = text
        var tokens: [Token] = []
        tagger.enumerateTags(
            in: text.startIndex..<text.endIndex,
            unit: .word,
            scheme: .lexicalClass,
            options: [.omitWhitespace]
        ) { tag, range in
            let word = String(text[range])
            guard !word.trimmingCharacters(in: .punctuationCharacters).isEmpty else { return true }
            tokens.append(Token(
                word: word,
                isNoun: tag == .noun || tag == .pronoun,
                isVerb: tag == .verb,
                isPreposition: tag == .preposition,
                isDeterminer: tag == .determiner,
                isAdjective: tag == .adjective
            ))
            return true
        }
        return tokens
        #else
        // No tagger, no structure, no transforms. The supplied sentence stands.
        return []
        #endif
    }

    private static func capitalizedFirst(_ text: String) -> String {
        guard let first = text.first else { return text }
        return first.uppercased() + String(text.dropFirst())
    }

    private static func lowercasedFirst(_ text: String) -> String {
        guard let first = text.first else { return text }
        return first.lowercased() + String(text.dropFirst())
    }
}

/// Lets a language model rewrite the Book's page without letting it change the
/// Book's mind.
///
/// The model is handed a finished composition and asked for music, not
/// content. Every returned sentence is then checked against the sentence it
/// replaced, under the licence its provenance carries: the Book's own voice may
/// be rewritten freely, a retold receipt may change everything except its
/// facts, and the reader's quoted words may not be touched at all. A sentence
/// that fails its check is simply not used: the house original stands, so the
/// worst outcome of a bad revision is the page we already had.
enum BraidRevisionVerifier {
    enum Rejection: String, Equatable {
        /// The reader's exact words, or the ritual line. Not up for revision.
        case changedLockedSentence
        /// A word appeared that no receipt supplied. This is the one that
        /// matters: it is how a model quietly invents a life.
        case addedContentWord
        /// A supplied noun or number went missing, taking evidence with it.
        case droppedAnchorWord
        case emptyRevision
        /// The model returned a different shape than it was given, so we can no
        /// longer tell which sentence was meant to replace which.
        case unalignedParagraph
    }

    struct Decision: Equatable {
        var original: BraidSentence
        var revised: String
        var accepted: Bool
        var rejection: Rejection?
        var offendingWords: [String] = []

        var changed: Bool {
            accepted && revised != original.text
        }
    }

    struct Result: Equatable {
        /// What to actually keep. Either the verified revision or, when the
        /// revision did not earn its place, the composition we started with.
        var composition: BraidComposition
        var decisions: [Decision]
        var adopted: Bool
        var originalScore: Int
        var revisedScore: Int

        var acceptedCount: Int { decisions.filter(\.accepted).count }
        var changedCount: Int { decisions.filter(\.changed).count }
        var rejections: [Rejection] { decisions.compactMap(\.rejection) }
    }

    /// Verify a model's rewrite of `composition` and decide whether to keep it.
    static func verify(
        revision: String,
        of composition: BraidComposition,
        day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> Result {
        // The model is handed the page complete with its title, and the title
        // is not up for revision, so the first block back is the title, not
        // the first paragraph. A model that drops it is tolerated; one that
        // rewrites it is simply ignored, because the house named this page.
        let blocks = paragraphs(in: revision)
        let revisedParagraphs = blocks.count > composition.paragraphs.count
            ? Array(blocks.dropFirst())
            : blocks
        var accepted = composition
        var decisions: [Decision] = []

        for (index, paragraph) in composition.paragraphs.enumerated() {
            let candidateSentences = index < revisedParagraphs.count
                ? DeterministicBraidwright.splitSentences(revisedParagraphs[index])
                : []
            guard candidateSentences.count == paragraph.count else {
                // Shape drift makes the mapping a guess, and a guess is exactly
                // what must never decide whose words these are.
                decisions += paragraph.map {
                    Decision(
                        original: $0,
                        revised: $0.text,
                        accepted: false,
                        rejection: .unalignedParagraph
                    )
                }
                continue
            }
            for (position, original) in paragraph.enumerated() {
                let decision = judge(original: original, revised: candidateSentences[position])
                decisions.append(decision)
                if decision.accepted {
                    accepted.paragraphs[index][position].text = decision.revised
                }
            }
        }

        // The register audit is the Book's own voice rule, and it reads whole
        // pages. A revision may not introduce a failure the house cut did not
        // already have.
        let originalIssues = BraidOutputAudit.issues(
            in: composition.text, for: day, context: context
        )
        let revisedIssues = BraidOutputAudit.issues(
            in: accepted.text, for: day, context: context
        )
        let originalFailures = Set(originalIssues.filter(\.isRegisterFailure).map(\.rawValue))
        let newFailures = revisedIssues
            .filter(\.isRegisterFailure)
            .map(\.rawValue)
            .contains { !originalFailures.contains($0) }

        let originalScore = BraidTastingRoom.score(page: composition.page, context: context).total
        let revisedScore = BraidTastingRoom.score(page: accepted.page, context: context).total

        // Small models asked to preserve facts tend to sand the strangeness off.
        // Requiring the revision to actually taste better is what stops a
        // competent, forgettable page from replacing a live one.
        let adopted = !newFailures
            && revisedScore > originalScore
            && decisions.contains(where: \.changed)

        var result = accepted
        if adopted {
            result.tags.append("braid-model-revised")
        }
        return Result(
            composition: adopted ? result : composition,
            decisions: decisions,
            adopted: adopted,
            originalScore: originalScore,
            revisedScore: revisedScore
        )
    }

    private static func judge(original: BraidSentence, revised: String) -> Decision {
        let clean = revised.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !clean.isEmpty else {
            return Decision(
                original: original, revised: original.text, accepted: false,
                rejection: .emptyRevision
            )
        }

        switch original.license {
        case .locked:
            let unchanged = normalizedWhitespace(clean) == normalizedWhitespace(original.text)
            return Decision(
                original: original,
                revised: unchanged ? clean : original.text,
                accepted: unchanged,
                rejection: unchanged ? nil : .changedLockedSentence
            )

        case .free:
            return Decision(original: original, revised: clean, accepted: true)

        case .strict:
            let supplied = contentWords(in: original.text)
            let offered = contentWords(in: clean)
            let added = offered.filter { word in
                !supplied.contains { matches($0, word) }
            }
            guard added.isEmpty else {
                return Decision(
                    original: original, revised: original.text, accepted: false,
                    rejection: .addedContentWord, offendingWords: added.sorted()
                )
            }
            let dropped = anchorWords(in: original.text).filter { anchor in
                !offered.contains { matches($0, anchor) }
            }
            guard dropped.isEmpty else {
                return Decision(
                    original: original, revised: original.text, accepted: false,
                    rejection: .droppedAnchorWord, offendingWords: dropped.sorted()
                )
            }
            return Decision(original: original, revised: clean, accepted: true)
        }
    }

    // MARK: - Words

    /// The `.strict` rule on its own: may this sentence stand in for that one
    /// without changing what happened? Used both to judge a model's revision
    /// and to gate the compiler's own transforms, so neither can quietly
    /// operate under looser rules than the other.
    static func preservesFacts(_ candidate: String, of original: String) -> Bool {
        let supplied = contentWords(in: original)
        let offered = contentWords(in: candidate)
        guard offered.allSatisfy({ word in supplied.contains { matches($0, word) } }) else {
            return false
        }
        guard preservesPolarity(candidate, of: original) else { return false }
        return anchorWords(in: original).allSatisfy { anchor in
            offered.contains { matches($0, anchor) }
        }
    }

    /// Whether a rewrite still says the thing did not happen.
    ///
    /// This check was missing, and its absence was the most serious hole in the
    /// braid. `preservesFacts` only ever prevented *addition*: every offered
    /// word had to exist in the original, and only `anchorWords` - nouns and
    /// numbers - were required to survive. Every other word could be dropped.
    ///
    /// "not" and "no" are in `functionWords`, so they were stripped as grammar
    /// before the comparison ran. "never" was not stripped, but it is not a
    /// noun either, so nothing required it to survive. The result, measured:
    ///
    ///   "I did not call Sam."          -> "You called Sam."      accepted
    ///   "No one came to the door."     -> "One came to the door." accepted
    ///   "I never finished the letter." -> "You finished the letter." accepted
    ///
    /// This guards the sentence-aligned Gemma revision that ships today, so a
    /// reversed negation was reaching the page with the verifier's approval.
    /// A rewrite that changes whether something happened is not a rewrite.
    static func preservesPolarity(_ candidate: String, of original: String) -> Bool {
        negationCount(in: candidate) == negationCount(in: original)
    }

    /// Deliberately counted rather than merely detected: "I did not not go" is
    /// vanishingly rare, but "I never called and never wrote" losing one of its
    /// two negations is a changed fact.
    private static func negationCount(in text: String) -> Int {
        let lowered = text.lowercased()
        var count = 0
        // Contracted forms first, so "didn't" is not also counted by "not".
        for contraction in ["n't", "n’t"] {
            count += lowered.components(separatedBy: contraction).count - 1
        }
        let stripped = lowered
            .replacingOccurrences(of: "n't", with: " ")
            .replacingOccurrences(of: "n’t", with: " ")
        let words = stripped.split { !$0.isLetter && $0 != "'" && $0 != "’" }.map(String.init)
        for word in words where negationWords.contains(word) { count += 1 }
        return count
    }

    /// Words that carry a negation or a near-negation. A hedge is not the same
    /// as a denial, but "I barely slept" becoming "I slept" is still the page
    /// telling the reader something they did not say.
    /// Only true negators and near-negators. Lexical verbs that happen to mean
    /// an absence - forgot, missed, stopped, refused - are deliberately absent:
    /// they are ordinary content words, they are protected by the additive
    /// check like any other, and counting them here refused honest rewrites of
    /// sentences such as "you forgot the letter".
    private static let negationWords: Set<String> = [
        "no", "not", "never", "none", "nobody", "noone", "nothing", "nowhere",
        "neither", "nor", "without", "cannot", "barely", "hardly", "scarcely",
        "rarely", "seldom"
    ]


    /// Words that carry meaning. Everything else is grammar the model is free
    /// to rearrange.
    static func contentWords(in text: String) -> Set<String> {
        Set(
            text
                .split { !$0.isLetter && !$0.isNumber && $0 != "'" && $0 != "’" }
                .map { $0.lowercased() }
                .filter { !functionWords.contains($0) && $0.count > 1 }
        )
    }

    /// The words a sentence cannot afford to lose: its nouns, names and
    /// numbers. Losing one of these loses the evidence with it.
    static func anchorWords(in text: String) -> Set<String> {
        #if canImport(NaturalLanguage)
        let tagger = NLTagger(tagSchemes: [.lexicalClass])
        tagger.string = text
        var anchors = Set<String>()
        tagger.enumerateTags(
            in: text.startIndex..<text.endIndex,
            unit: .word,
            scheme: .lexicalClass,
            options: [.omitWhitespace, .omitPunctuation]
        ) { tag, range in
            guard tag == .noun || tag == .number else { return true }
            let word = String(text[range])
                .trimmingCharacters(in: .punctuationCharacters)
                .lowercased()
            if word.count > 1, !functionWords.contains(word) { anchors.insert(word) }
            return true
        }
        return anchors
        #else
        // Without a tagger, every content word is treated as load-bearing. That
        // forbids compression rather than risking a lost fact.
        return contentWords(in: text)
        #endif
    }

    /// Inflection is music; a different word is a different claim. "tightened"
    /// may become "tighten", but "chair" may not become "table".
    static func matches(_ lhs: String, _ rhs: String) -> Bool {
        lhs == rhs || !wordForms(lhs).isDisjoint(with: wordForms(rhs))
    }

    private static func wordForms(_ word: String) -> Set<String> {
        var forms: Set<String> = [word]
        for possessive in ["'s", "’s"] where word.hasSuffix(possessive) {
            forms.insert(String(word.dropLast(possessive.count)))
        }
        if word.hasSuffix("ies"), word.count > 4 {
            forms.insert(String(word.dropLast(3)) + "y")
        }
        for suffix in ["es", "ed", "ing", "s", "d"]
        where word.hasSuffix(suffix) && word.count > suffix.count + 2 {
            forms.insert(String(word.dropLast(suffix.count)))
        }
        return forms
    }

    private static func paragraphs(in text: String) -> [String] {
        text
            .replacingOccurrences(of: "\r\n", with: "\n")
            .components(separatedBy: "\n\n")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
    }

    private static func normalizedWhitespace(_ text: String) -> String {
        text.split { $0.isWhitespace || $0.isNewline }.joined(separator: " ")
    }

    private static let functionWords: Set<String> = [
        "a", "an", "the", "and", "or", "but", "nor", "so", "yet", "for", "of",
        "to", "in", "on", "at", "by", "with", "from", "into", "onto", "over",
        "under", "after", "before", "between", "beside", "through", "past",
        "up", "down", "out", "off", "about", "as", "than", "then", "that",
        "this", "these", "those", "there", "here", "it", "its", "is", "am",
        "are", "was", "were", "be", "been", "being", "do", "does", "did",
        "have", "has", "had", "will", "would", "shall", "should", "can",
        "could", "may", "might", "must", "not", "no", "if", "when", "while",
        "i", "me", "my", "mine", "you", "your", "yours", "we", "us", "our",
        "they", "them", "their", "he", "him", "his", "she", "her", "hers",
        "who", "whom", "which", "what", "how", "why", "all", "any", "some",
        "both", "each", "one", "two", "very", "just", "still", "again", "own"
    ]
}

/// The Book's authored house writer.
///
/// This is deliberately not a tiny imitation of a language model. It accepts
/// the same scored night as Gemma, keeps every mundane assertion attached to
/// its source Page, and spends its one imaginative liberty on the relation
/// between those receipts. Lived life and the Labyrinth may therefore trespass
/// into one another in the finished tale without the prose stopping to label
/// the seam.
/// House law: no slug reaches prose.
///
/// The braid quotes a reader's fiction choice back to them, and it used to
/// humanise the token with `replacingOccurrences(of: "-", with: " ")` - which
/// does nothing whatsoever to a token that has no hyphens in it. That is how
/// `choice:sliceoflife` arrived on a finished page as "You chose sliceoflife."
///
/// `BookPage.readerContributions` has always had its own correct mapping for
/// the squashed forms; it was only this route that was wrong. The map is
/// duplicated here rather than shared because the two are read at different
/// times by different code, and a token that loses its word boundaries cannot
/// be recovered by any rule - only named.
extension BookPage {
    private static let squashedChoiceTitles: [String: String] = [
        "sliceoflife": "Slice of Life",
        "progressarc": "Progress Arc",
        "surprise": "Something Surprising"
    ]

    static func humanizedChoice(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return trimmed }
        let squashed = trimmed.lowercased().filter { $0.isLetter || $0.isNumber }
        if let known = squashedChoiceTitles[squashed] { return known }

        var spaced = ""
        for (index, character) in trimmed.enumerated() {
            if character == "-" || character == "_" {
                spaced.append(" ")
            } else if character.isUppercase, index > 0, spaced.last?.isWhitespace == false {
                spaced.append(" ")
                spaced.append(contentsOf: character.lowercased())
            } else {
                spaced.append(character)
            }
        }
        return spaced
            .components(separatedBy: .whitespaces)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
    }
}

enum DeterministicBraidwright {
    private enum Domain {
        case lived
        case labyrinth
        case supporting
    }

    private enum Camera: Int, CaseIterable {
        case livedFirst
        case trespassFirst
    }

    private enum ReaderChoiceKind {
        case answer
        case taggedChoice
    }

    private struct EvidenceAtom {
        var pageID: String
        var domain: Domain
        var occurredAt: Date
        var text: String
        var nouns: [String]
        var shelf: ReaderShelf?
        var mayTakeTaleForm: Bool
        var readerChoice: String?
        var readerChoiceKind: ReaderChoiceKind?
    }

    /// A transient eligibility proof. It is intentionally not another
    /// persistence ledger: the Pages already own the evidence. This makes a
    /// stale score fail closed if one of its receipts was since sealed or
    /// removed, and caps the renderer at one invented relation.
    private struct Proof {
        var eligibleReceiptIDs: Set<String>
        var receiptIDs: [String]
        var crossingReceiptIDs: [String]
        var licensedImpossibleRelations: Int

        var isValid: Bool {
            let receipts = Set(receiptIDs)
            let crossings = Set(crossingReceiptIDs)
            guard !receiptIDs.isEmpty,
                  receipts.isSubset(of: eligibleReceiptIDs),
                  crossings.isSubset(of: receipts),
                  licensedImpossibleRelations <= 1 else { return false }
            if licensedImpossibleRelations == 1 {
                return !crossings.isEmpty
            }
            return crossings.isEmpty
        }
    }

    private struct Plan {
        var context: BraidPromptBuilder.Context
        var score: BraidPromptBuilder.NightlyStoryScore
        var lived: [EvidenceAtom]
        var labyrinth: EvidenceAtom?
        /// Kept fiction past the lead. The lead still owns the crossing; these
        /// get their own paragraph apiece, which is the point: real material
        /// displaces the clerical padding the filler loop would otherwise buy.
        var additionalLabyrinth: [EvidenceAtom] = []
        var supporting: EvidenceAtom?
        /// The bare noun. This is the anchor's identity for every comparison
        /// in the renderer; it is deliberately not what the prose says.
        var primarySubject: String
        /// What the prose calls the anchor. Usually the bare noun, but when
        /// both worlds hand up the same one it carries a supplied modifier.
        var primaryDisplay: String
        var secondarySubject: String?
        var magicSubject: String?
        var labyrinthSubject: String?
        var hasShadow: Bool
        var hasUnclearedShadow: Bool
        var allowsNewMagic: Bool
        var proof: Proof
        /// The night being written, so an archive callback can measure distance
        /// without reaching for the wall clock and breaking determinism.
        var now: Date
    }

    static func candidates(
        for day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> [BookPage] {
        compositions(for: day, context: context).map(\.page)
    }

    static func compositions(
        for day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> [BraidComposition] {
        let resolved = preparedContext(for: day, context: context)
        return makeCandidates(for: day, context: resolved)
    }

    static func page(
        for day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> BookPage {
        composition(for: day, context: context).page
    }

    /// The winning page with its provenance intact. Everything downstream that
    /// wants to *change* the prose: a model revision, a transform pass: has
    /// to come through here, because the text alone cannot say which sentence
    /// is the Book's opinion and which is the reader's life.
    static func composition(
        for day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> BraidComposition {
        let resolved = preparedContext(for: day, context: context)
        let drafts = makeCandidates(for: day, context: resolved)
        guard !drafts.isEmpty else {
            return waitingPage()
        }

        if let selected = bestAuthoredCandidate(from: drafts, day: day, context: resolved) {
            var composition = selected.composition
            if !selected.issues.isEmpty {
                composition.tags.append("braid-audit-best-effort")
            }
            return composition
        }

        // Attributed source quotations are removed before the register audit,
        // so a failure here belongs to the authored connective tissue. Fail
        // closed to one exact receipt instead of waving a broken voice rule
        // through on the assumption that the reader supplied it.
        return plainWitnessPage(for: day, context: resolved)
    }

    private struct AuthoredSelection {
        var composition: BraidComposition
        var issues: [BraidOutputAudit.Issue]
        var tastingScore: BraidTastingRoom.Score
    }

    private static func bestAuthoredCandidate(
        from drafts: [BraidComposition],
        day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> AuthoredSelection? {
        var byText: [String: BraidComposition] = [:]
        for draft in drafts { byText[draft.text] = draft }
        let samples = BraidTastingRoom.taste(drafts.map(\.page), context: context).samples
        let safe = samples.compactMap { sample -> AuthoredSelection? in
            let issues = BraidOutputAudit.issues(in: sample.page.userInput, for: day, context: context)
            guard !issues.contains(where: \.isRegisterFailure),
                  let composition = byText[sample.page.userInput] else { return nil }
            return AuthoredSelection(
                composition: composition,
                issues: issues,
                tastingScore: sample.score
            )
        }
        guard let fewestIssues = safe.map({ $0.issues.count }).min() else { return nil }
        let leastBroken = safe.filter { $0.issues.count == fewestIssues }
        // Never say tonight what was said the same way a few nights ago.
        // `recurrencePenalty` scores exact sentences, sentence shapes, opening
        // shapes and endings against the last fortnight of real pages, and it
        // used to live inside the tasting total where a strong page could
        // simply outscore its own staleness. A daily reader meets these in
        // sequence, so freshness now outranks points: whenever an unheard
        // candidate exists it takes the night, and only when every candidate
        // echoes does the least-echoing one stand in.
        // The first line is the one a nightly reader learns to predict, so it
        // gets its own freshness pass ahead of the general one.
        let openingEcho: (AuthoredSelection) -> Int = {
            context.braidStyleMemory.openingFreshnessPenalty(of: $0.composition.text)
        }
        let freshestOpening = leastBroken.map(openingEcho).min() ?? 0
        let freshOpeners = leastBroken.filter { openingEcho($0) == freshestOpening }
        let echo: (AuthoredSelection) -> Int = {
            context.braidStyleMemory.recurrencePenalty(in: $0.composition.text)
        }
        let leastEchoed = freshOpeners.map(echo).min() ?? 0
        let freshest = freshOpeners.filter { echo($0) == leastEchoed }
        // Then within the page itself. A braid where every sentence opens on
        // "I" is bad writing even when none of it was said last week, so this
        // also outranks points - it just yields to cross-night freshness,
        // because a reader meets these in sequence and notices the echo first.
        let fewestRepeats = freshest
            .map { $0.composition.prosody.repeatedOpenings }
            .min() ?? 0
        let unrepeated = freshest.filter {
            $0.composition.prosody.repeatedOpenings == fewestRepeats
        }
        guard let bestScore = unrepeated.map({ $0.tastingScore.total }).max() else { return nil }
        // Among pages the tasting room already rates equally, prefer the one
        // that sounds least like a template: no run of sentences opening on the
        // same word, no run of sentences all the same length.
        let bestTasting = unrepeated.filter { $0.tastingScore.total == bestScore }
        let bestProsody = bestTasting.map { $0.composition.prosody.penalty }.min() ?? 0
        let finalists = bestTasting
            .filter { $0.composition.prosody.penalty == bestProsody }
            .sorted { candidateIndex(in: $0.composition) < candidateIndex(in: $1.composition) }
        guard !finalists.isEmpty else { return nil }

        // Swift's Hasher is intentionally randomized. This tiny stable hash
        // makes equal-quality cuts rotate by night and receipt while remaining
        // byte-for-byte stable when the same page is reopened.
        let receiptKey = drafts.first?.tags
            .filter { $0.hasPrefix("braid-receipt:") }
            .sorted()
            .joined(separator: "|") ?? ""
        let personalizationKey = [
            context.bookRelationship.stance.rawValue,
            context.bookRelationship.depth.rawValue,
            context.readerRole?.role.id ?? "unnamed-role"
        ].joined(separator: "|")
        let seed = stableHash("\(day.id)|\(receiptKey)|\(personalizationKey)")
        return finalists[Int(seed % UInt64(finalists.count))]
    }

    static func preparedContext(
        for day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> BraidPromptBuilder.Context {
        var result = context
        if result.taleReading == nil {
            result.taleReading = BraidPromptBuilder.taleReading(for: day, context: result)
        }
        if result.storyScore == nil {
            let stableNow = BraidPromptBuilder.braidEligiblePages(in: day)
                .map(\.createdAt)
                .max() ?? day.date
            result.storyScore = BraidPromptBuilder.nightlyStoryScore(
                for: day,
                context: result,
                connections: [],
                constellations: [],
                now: stableNow
            )
        }
        if let score = result.storyScore {
            result.storyScore = sanitizedScore(score, for: day, context: result)
        }
        if let score = result.storyScore {
            result.taleReading = score.taleReading
        }
        if let anchor = continuityAnchor(for: day, context: result) {
            if var existing = result.continuityBeat {
                existing.currentAnchor = anchor
                result.continuityBeat = existing
            } else {
                let stableNow = BraidPromptBuilder.braidEligiblePages(in: day)
                    .map(\.createdAt)
                    .max() ?? day.date
                result.continuityBeat = BraidPromptBuilder.continuityBeat(
                    for: day,
                    context: result,
                    currentAnchor: anchor,
                    now: stableNow
                )
            }
        } else {
            // Shadow or revoked evidence can invalidate a previously prepared
            // choice. Silence is safer than letting stale magic survive.
            result.continuityBeat = nil
        }
        return result
    }

    /// The exact noun phrase the proved house plan permits the Book's world to
    /// touch. Kept internal to the evidence compiler, but shared with the
    /// pre-generation continuity decision so both writers receive one anchor.
    static func continuityAnchor(
        for day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> String? {
        guard let score = context.storyScore,
              let plan = plan(for: day, context: context, score: score),
              plan.proof.isValid,
              plan.allowsNewMagic,
              !plan.hasUnclearedShadow else { return nil }
        return articleSubject(plan.magicSubject ?? plan.primaryDisplay)
    }

    private static func sanitizedScore(
        _ score: BraidPromptBuilder.NightlyStoryScore,
        for day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> BraidPromptBuilder.NightlyStoryScore {
        let eligible = BraidPromptBuilder.braidEligiblePages(in: day).filter {
            ReaderShelf.of($0) != .shadow
                || context.readerStory.shadowPermission != .knowButNeverWrite
        }
        var pages: [String: BookPage] = [:]
        for page in eligible where pages[page.id] == nil { pages[page.id] = page }

        var result = score
        let originalLivedIDs = Set(score.livedBeats.map(\.pageID))
        result.livedBeats = score.livedBeats.compactMap { beat in
            guard let page = pages[beat.pageID],
                  BraidPromptBuilder.braidShelf(for: page) == "lived",
                  !BraidPromptBuilder.isSupportingLog(page),
                  ReaderShelf.of(page) != .shadow
                    || context.readerStory.shadowPermission != .knowButNeverWrite else { return nil }
            var current = beat
            current.pageType = page.type
            current.occurredAt = page.createdAt
            current.excerpt = BraidPromptBuilder.fallbackExcerpt(
                BraidPromptBuilder.storyScoreText(for: page),
                limit: 220
            )
            return current
        }

        if let fiction = score.fictionBeat,
           let page = pages[fiction.pageID],
           BraidPromptBuilder.isLabyrinthReceipt(page) {
            var current = fiction
            current.occurredAt = page.createdAt
            current.choice = BraidPromptBuilder.fallbackExcerpt(
                BraidPromptBuilder.storyScoreText(for: page),
                limit: 220
            )
            result.fictionBeat = current
        } else {
            result.fictionBeat = nil
        }

        let retainedLivedIDs = Set(result.livedBeats.map(\.pageID))
        var removedBeatIDs = originalLivedIDs.subtracting(retainedLivedIDs)
        if result.fictionBeat == nil, let fictionID = score.fictionBeat?.pageID {
            removedBeatIDs.insert(fictionID)
        }
        if let lens = result.relationalLens,
           !removedBeatIDs.isDisjoint(with: lens.evidencePageIDs) {
            result.relationalLens = nil
        }
        if let arc = result.arc,
           !removedBeatIDs.isDisjoint(with: arc.evidencePageIDs + arc.fictionChoicePageIDs) {
            result.arc = nil
        }
        if let anchorID = result.taleReading.anchorPageID,
           removedBeatIDs.contains(anchorID) || pages[anchorID] == nil {
            result.taleReading.anchorPageID = result.livedBeats.first?.pageID
                ?? result.fictionBeat?.pageID
            result.taleReading.anchor = result.livedBeats.first?.excerpt
                ?? result.fictionBeat?.choice
                ?? ""
        } else if let anchorID = result.taleReading.anchorPageID,
                  let anchorPage = pages[anchorID] {
            result.taleReading.anchor = BraidPromptBuilder.fallbackExcerpt(
                BraidPromptBuilder.storyScoreText(for: anchorPage),
                limit: 220
            )
        }
        result.taleReading.rutEvidencePageIDs = result.taleReading.rutEvidencePageIDs.filter {
            pages[$0] != nil
        }
        if !removedBeatIDs.isEmpty { result.taleReading.turn = nil }

        let magicAnchor = result.livedBeats.first?.excerpt.nonEmpty
            ?? result.taleReading.anchor.nonEmpty
            ?? "one supplied sentence"
        result.magicLicense = "Use only \(result.taleReading.pressure.rawValue) around this supplied anchor: \(BraidPromptBuilder.fallbackExcerpt(magicAnchor, limit: 100)). One impossible relation is enough."
        result.endingDuty = result.arc.map {
            "Land on tonight's \($0.movement.rawValue) movement without restoring a removed receipt."
        } ?? result.livedBeats.first.map {
            "Return changed to this exact lived anchor: \($0.excerpt)"
        } ?? "Admit that you witnessed the day without inventing a lesson."
        return result
    }

    private static func makeCandidates(
        for day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> [BraidComposition] {
        guard let score = context.storyScore,
              let plan = plan(for: day, context: context, score: score),
              plan.proof.isValid else {
            return [waitingPage()]
        }

        let cameras: [Camera] = plan.allowsNewMagic && plan.labyrinth != nil && !plan.lived.isEmpty
            ? Camera.allCases
            : [.livedFirst]
        // Some variants collapse onto one another: plain-shadow nights have
        // two voices, not four, and a pool of clones would let the tasting
        // room score the same page repeatedly and skew the rotation toward it.
        var result: [BraidComposition] = []
        var seenBodies = Set<String>()
        for camera in cameras {
            for voiceVariant in 0..<4 {
                for realizationVariant in 0..<2 {
                    for proseVariant in 0..<BraidProseTransform.allCases.count {
                        let composition = render(
                            plan,
                            camera: camera,
                            voiceVariant: voiceVariant,
                            realizationVariant: realizationVariant,
                            proseVariant: proseVariant,
                            candidateIndex: result.count
                        )
                        guard seenBodies.insert(composition.text).inserted else { continue }
                        result.append(composition)
                    }
                }
            }
        }
        return result
    }

    private static func plan(
        for day: BookDay,
        context: BraidPromptBuilder.Context,
        score: BraidPromptBuilder.NightlyStoryScore
    ) -> Plan? {
        let eligiblePages = BraidPromptBuilder.braidEligiblePages(in: day)
        var pages: [String: BookPage] = [:]
        for page in eligiblePages where pages[page.id] == nil {
            pages[page.id] = page
        }
        let passages = context.meaningfulSpinePassages.reduce(into: [String: String]()) { result, selection in
            if result[selection.pageID] == nil { result[selection.pageID] = selection.excerpt }
        }
        let preferredWords = Set(
            (
                (context.bookVoicePatina.season?.attentionWords ?? [])
                + (context.bookVoicePatina.enduring?.attentionWords ?? [])
                + context.readerLexicon.packEntries.map(\.word)
            ).map { $0.lowercased() }
        )

        let scoredLived = score.livedBeats.compactMap { beat -> EvidenceAtom? in
            guard let page = pages[beat.pageID],
                  BraidPromptBuilder.braidShelf(for: page) == "lived",
                  !BraidPromptBuilder.isSupportingLog(page) else { return nil }
            let shelf = ReaderShelf.of(page)
            guard shelf != .shadow
                    || context.readerStory.shadowPermission != .knowButNeverWrite else { return nil }
            // A saved Story Score can outlive an edit to the Page. Keep the
            // selector's sharper excerpt only while those exact words still
            // exist in the current Page; otherwise read the Page as it stands
            // tonight rather than smuggling an old sentence back into print.
            let liveSource = page.userInput.nonEmpty
                ?? page.playerReply.nonEmpty
                // A photograph's caption or a voice note's transcript is what
                // the reader kept that evening. Without this the atom fell
                // through to `promptText` and a bare "?" reached the page.
                ?? BraidPromptBuilder.mediaEvidence(for: page)
                ?? page.promptText
            let currentPassage = passages[beat.pageID].flatMap { passage in
                liveSource.localizedCaseInsensitiveContains(passage) ? passage : nil
            }
            let source = currentPassage ?? liveSource
            let text = cleanSourceText(source)
            return EvidenceAtom(
                pageID: beat.pageID,
                domain: .lived,
                occurredAt: page.createdAt,
                text: text,
                nouns: rankedNouns(in: text, preferredWords: preferredWords),
                shelf: shelf,
                mayTakeTaleForm: shelf == .light || context.readerStory.shadowMayTakeTaleForm(
                    keptAt: page.createdAt,
                    now: day.date
                ),
                readerChoice: nil,
                readerChoiceKind: nil
            )
        }

        let labyrinthAtomFor = {
            (beat: BraidPromptBuilder.NightlyStoryScore.FictionBeat) -> EvidenceAtom? in
            guard let page = pages[beat.pageID],
                  BraidPromptBuilder.isLabyrinthReceipt(page) else { return nil }
            // Was `replacingOccurrences(of: "-", with: " ")`, which does
            // nothing at all to a token that has no hyphens in it - so
            // `choice:sliceoflife` reached a finished page word for word.
            let taggedChoice = page.tags.first(where: { $0.hasPrefix("choice:") }).map {
                BookPage.humanizedChoice(String($0.dropFirst("choice:".count)))
            }
            let answer = page.playerReply.nonEmpty
            let readerChoice = answer ?? taggedChoice
            let choiceKind: ReaderChoiceKind? = answer != nil
                ? .answer
                : (taggedChoice != nil ? .taggedChoice : nil)
            var scene = page.userInput.nonEmpty
                ?? page.promptText.nonEmpty
                ?? beat.choice
            if let readerChoice, scene == readerChoice {
                scene = page.promptText.nonEmpty ?? beat.choice
            }
            if answer != nil, scene.hasPrefix("Reader answer:") {
                scene = ""
            }
            let text = cleanSourceText(scene)
            return EvidenceAtom(
                pageID: beat.pageID,
                domain: .labyrinth,
                occurredAt: page.createdAt,
                text: text,
                nouns: rankedNouns(in: text, preferredWords: preferredWords),
                shelf: nil,
                mayTakeTaleForm: true,
                readerChoice: readerChoice.map { cleanSourceText($0) },
                readerChoiceKind: choiceKind
            )
        }
        let labyrinth = score.fictionBeat.flatMap(labyrinthAtomFor)
        let additionalLabyrinth = score.additionalFictionBeats.compactMap(labyrinthAtomFor)

        // One anchor owns the prose. When the night has nothing but logs, the
        // log the reading anchored on is the one to write about: otherwise the
        // page and its own truth anchor end up talking about different things.
        let supportingCandidates = BraidPromptBuilder.partitionedPagesForBraid(in: day)
            .supportingLogs
            .filter { page in
                ReaderShelf.of(page) != .shadow
                    || context.readerStory.shadowPermission != .knowButNeverWrite
            }
        let supportingPage = supportingCandidates
            .first { $0.id == score.taleReading.anchorPageID }
            ?? supportingCandidates.first
        let supporting: EvidenceAtom? = scoredLived.isEmpty && labyrinth == nil
            ? supportingPage.map { page in
                let source = page.playerReply.nonEmpty ?? page.userInput.nonEmpty ?? BraidPromptBuilder.mediaEvidence(for: page) ?? page.promptText
                let text = cleanSourceText(source)
                let shelf = ReaderShelf.of(page)
                return EvidenceAtom(
                    pageID: page.id,
                    domain: .supporting,
                    occurredAt: page.createdAt,
                    text: text,
                    nouns: rankedNouns(in: text, preferredWords: preferredWords),
                    shelf: shelf,
                    mayTakeTaleForm: shelf == .light || context.readerStory.shadowMayTakeTaleForm(
                        keptAt: page.createdAt,
                        now: day.date
                    ),
                    readerChoice: nil,
                    readerChoiceKind: nil
                )
            }
            : nil

        // A One-Sentence Souvenir is the reader stopping to choose one true
        // line out of their whole day. If they chose one, it owns the page -
        // and because the primary atom sets the magic subject, that decision
        // carries through the title, the voice, and the closing line together.
        var orderedLived = scoredLived
        if let anchorID = context.souvenirAnchor?.pageID,
           let index = orderedLived.firstIndex(where: { $0.pageID == anchorID }),
           index > 0 {
            orderedLived.insert(orderedLived.remove(at: index), at: 0)
        }
        let lived = orderedLived

        guard let primary = lived.first ?? labyrinth ?? supporting else { return nil }
        var effectiveScore = score
        let livedIDs = Set(lived.map(\.pageID))
        effectiveScore.livedBeats = score.livedBeats.filter { livedIDs.contains($0.pageID) }
        if labyrinth == nil { effectiveScore.fictionBeat = nil }
        var removedTonightIDs = Set(score.livedBeats.map(\.pageID)).subtracting(livedIDs)
        if labyrinth == nil, let fictionID = score.fictionBeat?.pageID {
            removedTonightIDs.insert(fictionID)
        }
        if let lens = effectiveScore.relationalLens,
           !removedTonightIDs.isDisjoint(with: lens.evidencePageIDs) {
            effectiveScore.relationalLens = nil
        }
        if let arc = effectiveScore.arc,
           !removedTonightIDs.isDisjoint(with: arc.evidencePageIDs + arc.fictionChoicePageIDs) {
            effectiveScore.arc = nil
        }
        if let anchorID = effectiveScore.taleReading.anchorPageID,
           removedTonightIDs.contains(anchorID) {
            effectiveScore.taleReading.anchorPageID = lived.first?.pageID
                ?? labyrinth?.pageID
                ?? supporting?.pageID
            effectiveScore.taleReading.anchor = lived.first?.text
                ?? labyrinth?.text
                ?? supporting?.text
                ?? ""
        }

        // One anchor owns the prose from title through colophon. Do not let a
        // safer noun on a later beat quietly steal the magic while the opening,
        // voice bite, and arc continue talking about something else.
        let primarySubject = safeMagicSubject(primary) ?? "day"
        let secondarySubject = lived.dropFirst()
            .compactMap(safeMagicSubject)
            .first {
                $0.caseInsensitiveCompare(primarySubject) != .orderedSame
            }
        // On a Labyrinth-only night the fiction Page is the anchor, not its own
        // visiting double. Suppressing the second label prevents Door answering
        // Door while still letting the supplied scene receive one faerie law.
        let rawLabyrinthSubject: String?
        if lived.isEmpty {
            rawLabyrinthSubject = nil
        } else if let labyrinth {
            // A noun adjunct can sort ahead of the shared object on different
            // NaturalLanguage models ("brass" before "door"). Prefer an exact
            // supplied noun shared with the lived anchor so the crossing keeps
            // two identities instead of quietly changing its subject by OS.
            let candidate = labyrinth.nouns.first {
                $0.caseInsensitiveCompare(primarySubject) == .orderedSame
            } ?? storySubject(labyrinth)
            rawLabyrinthSubject = isUsableSubject(candidate) ? candidate : nil
        } else {
            rawLabyrinthSubject = nil
        }
        // When both worlds hand up the same noun, ask each receipt for its own
        // modifier before reaching for a label. "The brass door recognized the
        // blue door" invents nothing: both adjectives were supplied, and it
        // keeps two identities where "the other door" only marks that there
        // are two. The label stays as the fallback when a receipt has no
        // modifier to give.
        var primaryDisplay = primarySubject
        var labyrinthSubject = rawLabyrinthSubject
        if let raw = rawLabyrinthSubject,
           raw.caseInsensitiveCompare(primarySubject) == .orderedSame {
            let livedQualified = qualifiedSubject(primarySubject, in: primary)
            let visitorQualified = labyrinth.flatMap { qualifiedSubject(raw, in: $0) }
            switch (livedQualified, visitorQualified) {
            case let (lived?, visitor?) where lived.caseInsensitiveCompare(visitor) != .orderedSame:
                primaryDisplay = lived
                labyrinthSubject = visitor
            case let (lived?, _):
                primaryDisplay = lived
                labyrinthSubject = "the other \(raw.lowercased())"
            case let (nil, visitor?):
                labyrinthSubject = visitor
                primaryDisplay = "the first \(raw.lowercased())"
            case (nil, nil):
                labyrinthSubject = "the other \(raw.lowercased())"
                primaryDisplay = "the first \(raw.lowercased())"
            }
        }
        let hasShadow = (lived + [supporting].compactMap { $0 }).contains {
            $0.shelf == .shadow
        }
        let hasUnclearedShadow = (lived + [supporting].compactMap { $0 }).contains {
            $0.shelf == .shadow && !$0.mayTakeTaleForm
        }
        // Shadow is the engine, not the exception. `ReaderShelf` has always said
        // so: shadow "may become plot: what someone carries, why the errand
        // exists, the thing not said." Nulling fiction, lens and arc because a
        // hard page existed made the Book go silent on exactly the nights it
        // has most to carry, and silence is not restraint. It reads as "I do
        // not know what to say to you."
        //
        // What must never happen is naming, explaining, resolving, or drawing a
        // conclusion about the shadow material. That is enforced precisely and
        // separately by the four register failures in `BraidOutputAudit`, which
        // never enter candidate selection. This gate no longer stands in for
        // them. It restricts what magic may take as its *subject*, and leaves
        // the four laws to do the job they were written for.
        if hasUnclearedShadow {
            // A relational lens reads a relationship and says what it means.
            // That is interpretation, and it is the one of the three that
            // cannot be made safe by choosing a different subject.
            effectiveScore.relationalLens = nil
        }
        let primaryMayCarryMagic = primary.shelf != .shadow || primary.mayTakeTaleForm
        // When the night's spine is hard and unpermitted, the world may still
        // attend something ordinary from the same day. On a night holding both
        // "walked to the corner shop for bread" and a funeral, the Book was
        // forbidden from noticing the bread. It may notice the bread.
        let vigilAtom = (lived + [supporting].compactMap { $0 }).first {
            ($0.shelf ?? .light) != .shadow || $0.mayTakeTaleForm
        }
        let selectedMagicSubject = primaryMayCarryMagic
            ? primaryDisplay
            : vigilAtom?.nouns.first.map(articleSubject)
        let allowsNewMagic = selectedMagicSubject != nil
        let magicSubject = selectedMagicSubject
        let visibleLabyrinthID = labyrinth?.pageID
        let uniqueSelectedIDs = unique(lived.map(\.pageID) + [visibleLabyrinthID, supporting?.pageID].compactMap { $0 })
        let crossingIDs: [String]
        if !allowsNewMagic {
            crossingIDs = []
        } else if let labyrinth, !lived.isEmpty {
            crossingIDs = [primary.pageID, labyrinth.pageID]
        } else {
            crossingIDs = [primary.pageID]
        }

        return Plan(
            context: context,
            score: effectiveScore,
            lived: lived,
            labyrinth: labyrinth,
            additionalLabyrinth: additionalLabyrinth,
            supporting: supporting,
            primarySubject: primarySubject,
            primaryDisplay: primaryDisplay,
            secondarySubject: secondarySubject,
            magicSubject: magicSubject,
            labyrinthSubject: labyrinthSubject,
            hasShadow: hasShadow,
            hasUnclearedShadow: hasUnclearedShadow,
            allowsNewMagic: allowsNewMagic,
            proof: Proof(
                eligibleReceiptIDs: Set(pages.keys),
                receiptIDs: uniqueSelectedIDs,
                crossingReceiptIDs: crossingIDs,
                licensedImpossibleRelations: allowsNewMagic ? 1 : 0
            ),
            now: day.date
        )
    }

    private static func render(
        _ plan: Plan,
        camera: Camera,
        voiceVariant: Int,
        realizationVariant: Int,
        proseVariant: Int,
        candidateIndex: Int
    ) -> BraidComposition {
        let title = title(for: plan, variant: realizationVariant)
        let primary = plan.lived.first ?? plan.labyrinth ?? plan.supporting
        let primaryUnits = primary.map { atom in
            switch atom.domain {
            case .lived, .supporting: return livedUnits(atom, prose: proseVariant)
            case .labyrinth: return labyrinthUnits(atom, prose: proseVariant)
            }
        } ?? [BraidSentence(text: "No kept sentence arrived.", provenance: .authored)]
        // Every other move family rests: keeping, tale, colophon, archive echo.
        // The voice bite did not, so the Book's first reaction could come back
        // across consecutive nights as a house refrain, which is the clerk
        // problem wearing a different coat. Rotate to the first phrasing prose
        // memory has not heard lately; falling through all four is fine,
        // because a slightly familiar bite still beats no voice at all.
        let precedingOpening = primaryUnits.last
            .map { BraidComposition.openingWord(of: $0.text) }
        func restedBite() -> String {
            var fallback: String?
            var firstText: String?
            for offset in 0..<4 {
                let text = voiceBite(
                    relationship: plan.context.bookRelationship,
                    register: plan.score.taleReading.narrativeRegister,
                    subject: plan.primaryDisplay,
                    shadowMode: plan.hasShadow,
                    plainShadow: plan.hasUnclearedShadow,
                    variant: voiceVariant + offset
                )
                if firstText == nil { firstText = text; fallback = text }
                // Never open on the word the sentence before it opened on.
                // The Book speaks in the first person, so without this a
                // paragraph slides into "I read. I kept. I stayed."
                let collides = precedingOpening.map {
                    BraidComposition.openingWord(of: text) == $0
                } ?? false
                if collides { continue }
                if fallback == nil || fallback == firstText { fallback = text }
                if plan.context.braidStyleMemory.recurrencePenalty(in: text) == 0 {
                    return text
                }
            }
            return fallback ?? ""
        }
        let bite = authoredUnits(restedBite())

        // Which authored sentences this page spent. They ride out as tags so
        // tomorrow's braid can let them rest.
        var usedMoveKeys: [String] = []
        var paragraphs: [[BraidSentence]] = []
        if camera == .trespassFirst,
           let labyrinth = plan.labyrinth,
           !plan.lived.isEmpty,
           plan.allowsNewMagic {
            paragraphs.append(
                labyrinthUnits(labyrinth, prose: proseVariant)
                    + authoredUnits(crossingMove(for: plan, variant: realizationVariant))
            )
            paragraphs.append(primaryUnits + bite)
        } else {
            paragraphs.append(primaryUnits + bite)
        }

        var spentSupportingMoves = Set<String>()
        for (index, beat) in plan.lived.dropFirst().enumerated() {
            var paragraph = livedUnits(beat, prose: proseVariant + index + 1)
            if !plan.hasUnclearedShadow,
               let currentSubject = safeMagicSubject(beat),
               currentSubject.caseInsensitiveCompare(plan.primarySubject) != .orderedSame {
                let move = supportingMove(
                    form: plan.score.taleReading.storyForm,
                    motion: plan.score.taleReading.motion,
                    firstSubject: plan.primaryDisplay,
                    currentSubject: currentSubject,
                    shadowMode: plan.hasShadow,
                    variant: index + voiceVariant,
                    avoiding: spentSupportingMoves
                )
                spentSupportingMoves.insert(move.key)
                usedMoveKeys.append("support:\(move.key)")
                paragraph += authoredUnits(move.text)
            }
            paragraphs.append(paragraph)
        }

        let primaryIsLabyrinth = plan.lived.isEmpty && plan.labyrinth != nil
        if let labyrinth = plan.labyrinth,
           !primaryIsLabyrinth,
           !plan.hasUnclearedShadow,
           !(camera == .trespassFirst && !plan.lived.isEmpty) {
            var crossing = labyrinthUnits(labyrinth, prose: proseVariant)
            if !plan.lived.isEmpty, plan.allowsNewMagic {
                crossing += authoredUnits(crossingMove(for: plan, variant: realizationVariant))
            } else if plan.allowsNewMagic {
                crossing += authoredUnits(solitaryMagicMove(for: plan, variant: realizationVariant))
            }
            paragraphs.append(crossing)
        } else if plan.allowsNewMagic,
                  (plan.labyrinth == nil || primaryIsLabyrinth) {
            paragraphs.append(
                authoredUnits(solitaryMagicMove(for: plan, variant: realizationVariant))
            )
        }

        // Kept fiction past the lead. No crossing move and no second magic
        // licence: the lead already spent both, and stacking them would make
        // the page argue with itself. These are receipts, stated plainly, and
        // their whole job is to be real material where padding used to go.
        for (index, extra) in plan.additionalLabyrinth.enumerated()
        where !plan.hasUnclearedShadow && extra.pageID != plan.labyrinth?.pageID {
            paragraphs.append(labyrinthUnits(extra, prose: proseVariant + index + 1))
        }

        if plan.context.continuityBeat?.kind != .evidenceRhyme {
            if let arc = plan.score.arc, !plan.hasUnclearedShadow {
                paragraphs.append(authoredUnits(arcMove(arc, subject: plan.primaryDisplay)))
            } else if let lens = plan.score.relationalLens, !plan.hasUnclearedShadow {
                paragraphs.append(authoredUnits(relationalMove(lens)))
            }
        }

        // A persisted fiction decision must actually appear even on a rich
        // night that reaches its word band without filler. Otherwise the Page
        // would stamp an opened thread that the reader never saw.
        var prewrittenWorldBeats = 0
        var prewrittenTaleKeys = Set<String>()
        if let serial = continuityTaleLine(for: plan) {
            // On a tight scale the serial settles the paragraph it follows
            // rather than opening one of its own. A returning thread is not
            // worth a Glimpse turning into four paragraphs: the shape band is
            // as much a promise as the word band, and this was quietly
            // breaking it every night a thread came back.
            let band = plan.score.taleReading.scale.targetParagraphBand
            let colophonToCome = 1
            if !paragraphs.isEmpty,
               paragraphs.count + 1 + colophonToCome > band.upperBound {
                paragraphs[paragraphs.count - 1] += authoredUnits(serial.text)
            } else {
                paragraphs.append(authoredUnits(serial.text))
            }
            usedMoveKeys.append(serial.key)
            prewrittenTaleKeys.insert(serial.key)
            prewrittenWorldBeats = 1
        }

        // The house writer aims at the night's word band: the same target the
        // model is given, and buys the difference with settling beats, which
        // report on the Book's handling of the page. That is the one subject it
        // can expand into without making a second claim about the reader's life
        // or spending another crossing. They settle the paragraph they follow
        // rather than opening a new one, so a Glimpse stays a Glimpse in shape
        // as well as in length.
        //
        // The cap is taste, not arithmetic: two beats of the Book talking about
        // its own pencil is a rhythm, three is a tic. On scales where that
        // leaves the page under its band, the honest answer is more material -
        // transformation, prosody and archive callbacks, not more padding. The
        // bench reports the remaining gap rather than hiding it.
        // Before the page settles, the Book spends what it knows about this
        // reader from outside tonight. It goes in its own paragraph so it reads
        // as the Book looking up from the page, not as another detail of the day.
        var lookingUp: [BraidSentence] = []
        let evidenceRhyme = evidenceRhymeMove(for: plan)
        if let rhyme = evidenceRhyme {
            lookingUp += authoredUnits(rhyme)
        } else if plan.context.continuityBeat?.kind != .fictionContinuation,
                  plan.context.continuityBeat?.kind != .fictionResolution,
                  let echo = archiveEchoMove(for: plan, now: plan.now) {
            lookingUp += authoredUnits(echo)
        }
        if let remembering = rememberingMove(for: plan, variant: voiceVariant) {
            usedMoveKeys.append(remembering.key)
            lookingUp += authoredUnits(remembering.text)
        }
        if !lookingUp.isEmpty { paragraphs.append(lookingUp) }

        // Two budgets, spent in order. The world may act up to `livedBeatAllowance`
        // times, because a tale beat is material; the Book may talk about its own
        // pencil only `settlingAllowance` times, because that is seasoning. Before
        // this split the clerical moves bought the whole band and the page read
        // like an archivist's night shift.
        var worldBeats = prewrittenWorldBeats
        var settlingBeats = 0
        var spentOpenings = Set<String>()
        var spentTaleKeys = prewrittenTaleKeys
        var spentKeepingKeys = Set<String>()
        while bodyWordCount(paragraphs)
            < plan.score.taleReading.scale.targetWordBand.lowerBound,
            !paragraphs.isEmpty {
            // Settle a different paragraph each time, working backwards.
            // Stacked at the end they read as the Book fidgeting; spread out
            // they read as the page coming to rest.
            let placed = worldBeats + settlingBeats
            let target = max(0, paragraphs.count - 1 - placed)
            // Every opening already in this paragraph, not just the last one:
            // a settled beat that matches the paragraph's first sentence reads
            // as a stack even with another sentence in between.
            let paragraphOpenings = Set(
                paragraphs[target].map { BraidComposition.openingWord(of: $0.text) }
            )
            let avoiding = spentOpenings.union(paragraphOpenings)

            let move: (key: String, text: String)
            if worldBeats < plan.score.taleReading.scale.livedBeatAllowance,
               let tale = taleMove(
                for: plan,
                variant: realizationVariant,
                index: worldBeats,
                avoiding: avoiding,
                spentKeys: spentTaleKeys
               ) {
                move = tale
                worldBeats += 1
                spentTaleKeys.insert(tale.key)
            } else if settlingBeats < plan.score.taleReading.scale.settlingAllowance,
                      let keeping = keepingMove(
                        for: plan,
                        variant: realizationVariant,
                        index: settlingBeats,
                        avoiding: avoiding,
                        spentKeys: spentKeepingKeys
                      ) {
                move = keeping
                settlingBeats += 1
                spentKeepingKeys.insert(keeping.key)
            } else {
                // Nothing unsaid is left to say. A page a few words under its
                // band is better than a page that prints the same sentence
                // twice, which is what happened before this stopped here.
                break
            }
            spentOpenings.insert(BraidComposition.openingWord(of: move.text))
            usedMoveKeys.append(move.key)
            paragraphs[target] += authoredUnits(move.text)
        }

        let colophon = keeperLine(for: plan, variant: realizationVariant)
        usedMoveKeys.append(colophon.key)
        // Split like every other block. Several closing variants are two
        // sentences ("...beside the tuesday. I left it."), and stored whole
        // they made the paragraph claim one sentence where re-reading the page
        // finds two - which the revision verifier correctly reads as shape
        // drift and refuses the whole paragraph over.
        paragraphs.append(
            splitSentences(colophon.text).map {
                BraidSentence(text: $0, provenance: .colophon)
            }
        )

        var tags = [
            "braid",
            "deterministic-braidwright",
            "braid-form:\(plan.score.taleReading.storyForm.rawValue)",
            "braid-motion:\(plan.score.taleReading.motion.rawValue)",
            "braid-pressure:\(plan.score.taleReading.pressure.rawValue)",
            "braid-candidate:\(candidateIndex)"
        ]
        if plan.allowsNewMagic, plan.labyrinth != nil, !plan.lived.isEmpty {
            tags.append("braid-fiction-reality-bleed")
        }
        tags += plan.proof.receiptIDs.map { "braid-receipt:\($0)" }
        if plan.proof.licensedImpossibleRelations == 1 {
            tags.append("braid-licensed-crossing")
        }
        if plan.hasShadow { tags.append("braid-shadow-tender") }
        if plan.hasUnclearedShadow { tags.append("braid-shadow-plain") }
        var seenMoveKeys = Set<String>()
        tags += usedMoveKeys
            .filter { seenMoveKeys.insert($0).inserted }
            .map { "braid-move:\($0)" }

        return BraidComposition(
            title: title,
            paragraphs: paragraphs,
            tags: tags,
            promptText: "I braided today by hand."
        )
    }

    private static func authoredUnits(_ text: String) -> [BraidSentence] {
        splitSentences(text).map { BraidSentence(text: $0, provenance: .authored) }
    }

    private static func livedUnits(_ atom: EvidenceAtom, prose: Int) -> [BraidSentence] {
        receiptUnits(livedSentence(atom), pageID: atom.pageID, prose: prose)
    }

    private static func labyrinthUnits(_ atom: EvidenceAtom, prose: Int) -> [BraidSentence] {
        receiptUnits(labyrinthSentence(atom), pageID: atom.pageID, prose: prose)
    }

    /// A sentence holding the reader's exact words inside guillemets is locked;
    /// one retold in the Book's own grammar may have its music changed. The
    /// quotation mark is the tell, so the split does not have to be told twice.
    private static func receiptUnits(
        _ text: String,
        pageID: String,
        prose: Int = 0
    ) -> [BraidSentence] {
        splitSentences(text).enumerated().flatMap { offset, sentence -> [BraidSentence] in
            // Quoted words are the reader talking. Rearranging them would be
            // the one thing a quotation promises not to do.
            guard !sentence.contains("«") else {
                return [BraidSentence(text: sentence, provenance: .quotedReceipt(pageID: pageID))]
            }
            let rearranged = BraidProseTransform.rearranged(sentence, variant: prose + offset)
            return splitSentences(rearranged).map {
                BraidSentence(text: $0, provenance: .receipt(pageID: pageID))
            }
        }
    }

    /// Sentence boundaries that survive the two things this prose actually
    /// contains: quoted reader words with their own full stops inside, and Cast
    /// titles like "Dr." that are not the end of anything.
    static func splitSentences(_ text: String) -> [String] {
        var sentences: [String] = []
        var current = ""
        var quoteDepth = 0
        let characters = Array(text)
        var index = 0
        while index < characters.count {
            let character = characters[index]
            current.append(character)
            if character == "«" { quoteDepth += 1 }
            if character == "»" { quoteDepth = max(0, quoteDepth - 1) }
            index += 1

            // A sentence ends on a stop, or on the closing mark of a quotation
            // that ended with one, because «…she sounded tired.» is finished
            // even though the stop belongs to the reader rather than to us.
            let closedQuotation = character == "»"
                && quoteDepth == 0
                && current.dropLast().last.map { ".!?…".contains($0) } == true
            let plainStop = quoteDepth == 0 && ".!?…".contains(character)
            guard plainStop || closedQuotation else { continue }

            // Any further closing marks belong to the sentence that just ended.
            while index < characters.count, "»›\"”’)".contains(characters[index]) {
                if characters[index] == "»" { quoteDepth = max(0, quoteDepth - 1) }
                current.append(characters[index])
                index += 1
            }
            guard index < characters.count, characters[index] == " " else { continue }
            let followingIndex = index + 1
            guard followingIndex < characters.count else { continue }
            let next = characters[followingIndex]
            guard next.isUppercase || next == "«" else { continue }
            guard !endsWithAbbreviation(current) else { continue }

            sentences.append(current.trimmingCharacters(in: .whitespaces))
            current = ""
            index += 1
        }
        let tail = current.trimmingCharacters(in: .whitespaces)
        if !tail.isEmpty { sentences.append(tail) }
        return sentences.isEmpty ? [text.trimmingCharacters(in: .whitespaces)] : sentences
    }

    private static func endsWithAbbreviation(_ text: String) -> Bool {
        let word = text
            .trimmingCharacters(in: CharacterSet(charactersIn: ".!?…»›\"”’) "))
            .split { $0.isWhitespace }
            .last
            .map(String.init)?
            .lowercased()
        guard let word else { return false }
        return sentenceSafeAbbreviations.contains(word)
    }

    private static let sentenceSafeAbbreviations: Set<String> = [
        "dr", "mr", "mrs", "ms", "prof", "st", "vs", "etc", "no", "vol"
    ]

    private static func title(for plan: Plan, variant: Int) -> String {
        let leadLived = titleSubject(plan.primaryDisplay, leading: true)
        let dependentLived = titleSubject(plan.primaryDisplay, leading: false)
        if plan.hasUnclearedShadow {
            return variant.isMultiple(of: 2)
                ? "The Words Kept Their Name"
                : "The Words Stayed As They Came"
        }
        if plan.hasShadow {
            if let visitor = plan.labyrinthSubject?.nonEmpty {
                let leadVisitor = titleSubject(visitor, leading: true)
                return variant.isMultiple(of: 2)
                    ? "\(leadVisitor) Kept Watch"
                    : "\(leadVisitor) and the Unsaid"
            }
            return variant.isMultiple(of: 2)
                ? "The Words Stayed Awake"
                : "What Was Not Put Away"
        }
        if let labyrinth = plan.labyrinthSubject?.nonEmpty {
            let leadVisitor = titleSubject(labyrinth, leading: true)
            let dependentVisitor = titleSubject(labyrinth, leading: false)
            if variant.isMultiple(of: 2) {
                return "\(leadLived) Answered \(dependentVisitor)"
            }
            switch plan.score.taleReading.pressure {
            case .agency: return "What \(dependentLived) Wanted From \(dependentVisitor)"
            case .rule: return "\(leadVisitor) Gave \(dependentLived) One Rule"
            case .debt: return "What \(dependentLived) Charged \(dependentVisitor)"
            case .threshold: return "\(leadVisitor) Crossed \(dependentLived)"
            case .rhyme: return "\(leadLived) and \(dependentVisitor)"
            case .absence: return "\(leadLived) Kept a Place"
            case .timeSlip: return "\(leadLived) Kept Two Hours"
            case .witness: return "\(leadLived) Saw \(dependentVisitor)"
            }
        }
        switch plan.score.taleReading.pressure {
        case .agency: return "What \(dependentLived) Wanted"
        case .rule: return "\(leadLived) Made a Rule"
        case .debt: return "What \(dependentLived) Charged"
        case .threshold: return "\(leadLived) Would Not Move"
        case .rhyme: return "\(leadLived) Answered Twice"
        case .absence: return "\(leadLived) Kept a Place"
        case .timeSlip: return "\(leadLived) Kept Two Hours"
        case .witness: return "\(leadLived) Saw It"
        }
    }

    /// A title is the one place a subject stands without a sentence around it,
    /// so its article has to be chosen rather than inherited. A supplied proper
    /// name stands bare; a common noun keeps the article it would have had.
    private static func titleSubject(_ subject: String, leading: Bool) -> String {
        let core = titleWords(subject)
        if subject.lowercased().hasPrefix("the ") {
            return leading ? core : lowercasedFirst(core)
        }
        guard subject.first?.isUppercase != true else { return core }
        return leading ? "The \(core)" : "the \(core)"
    }

    private static func voiceBite(
        relationship: BookRelationshipSnapshot,
        register: BraidPromptBuilder.NarrativeRegister,
        subject: String,
        shadowMode: Bool,
        plainShadow: Bool,
        variant: Int
    ) -> String {
        if plainShadow {
            return variant.isMultiple(of: 2)
                ? "I read those words twice. My pencil stayed still."
                : "I kept the words in their own order. I touched nothing else."
        }
        if shadowMode {
            switch variant % 4 {
            case 0: return "Twice I read those words. My pencil stayed still."
            case 1: return "The name kept its rough edge. I touched nothing else."
            case 2: return "I set my thumb at the edge of the page and did not lean."
            default: return "I left the words in their own clothes. They did not need mine."
            }
        }

        let kept = articleSubject(subject)
        switch variant % 4 {
        case 0:
            switch relationship.stance {
            case .curious: return "I wanted \(kept). I put my thumb on the line before anyone tidied it."
            case .protective: return "I kept \(kept) rough at the edges. The Index can sulk."
            case .mischievous: return "I stole \(kept) before the Index could tidy the sentence. Mine."
            case .hushed: return "I kept \(kept) close and turned the page slowly."
            case .contrite: return "I went back for \(kept). My pencil stayed loose."
            case .intent: return "I bit down on the sentence and kept \(kept). No escape."
            case .pleased: return "I liked \(kept). I underlined the words twice and denied the second line."
            }
        case 1:
            switch register {
            case .plain: return "I kept \(kept). The rest had to wait."
            case .tender: return "I took \(kept) gently and left the rough part alone."
            case .fierce: return "I seized the line around \(kept). Mine now."
            case .wry: return "I kept \(kept). The Index made a face. I ignored it."
            case .uncanny: return "I found \(kept) under my waiting thumb. I did not lift it."
            case .luminous: return "I gave \(kept) the good ink. Greedy? Yes."
            }
        case 2:
            switch relationship.depth {
            case .firstPages:
                // First-pages wonder should not harden into one catchphrase
                // merely because the relationship depth is unchanged. Let the
                // exact thing on the Page decide which of three young, wary
                // reactions the Book has.
                switch stableHash(subject) % 3 {
                case 0:
                    return "I circled \(kept) once. We have only just met, and I am already suspicious."
                case 1:
                    return "I have barely learned your corners, and \(kept) \(agreeing("is", "are", with: kept)) already making demands. Good."
                default:
                    return "\(capitalized(kept)) arrived before I knew where to shelve \(agreeing("it", "them", with: kept)). \(agreeing("It", "They", with: kept)) bit the label. I kept both."
                }
            case .acquainted: return "I knew where to put my thumb: just under \(kept)."
            case .trusted: return "I knew you would leave me \(kept). I took the sentence before it cooled."
            case .companion: return "I knew \(kept) by the sound of the sentence. I stole the line anyway."
            }
        default:
            switch register {
            case .plain: return "I took \(kept) with the dirt still in the sentence."
            case .tender: return "I kept my claws in and held \(kept) by the edges."
            case .fierce: return "I wanted \(kept) with every hard edge. The excuse could fend for itself."
            case .wry: return "I eyed \(kept). The Index objected. Rude thing."
            case .uncanny: return "I touched the line around \(kept) and kept my hand there."
            case .luminous: return "I took \(kept) and hid the line from the Index."
            }
        }
    }

    /// On a heavy night this fires once per lived beat, so it has to know what
    /// it already said. Two beats landing the same sentence verbatim: "I put
    /// the lido against the plums. The difference had a clean edge." twice -
    /// is the single most template-like thing the page can do.
    private static func supportingMove(
        form: BraidPromptBuilder.StoryForm,
        motion: BraidPromptBuilder.NarrativeMotion,
        firstSubject: String,
        currentSubject: String,
        shadowMode: Bool,
        variant: Int,
        avoiding spent: Set<String>
    ) -> (key: String, text: String) {
        // The night's own form and motion come first, because they are what
        // tonight is actually about. After that the pool widens across the
        // *other* authored forms and motions rather than inventing filler:
        // there are sixteen of these sentences already written in the Book's
        // voice, and a fixed form and motion made fourteen unreachable.
        //
        // The liberty is small and worth it. These describe how the Book set
        // two things beside each other, which can honestly differ from pair to
        // pair; the night's shape still speaks first.
        // Dedupe on which authored sentence was used, never on its position:
        // the pool reorders per beat, so an index means nothing across beats
        // and two beats would happily land the same line twice.
        if shadowMode {
            let pool = [0, 1].map { index in
                (
                    "shadow:\(index)",
                    supportingMove(
                        form: form, motion: motion, firstSubject: firstSubject,
                        currentSubject: currentSubject, shadowMode: true, variant: index
                    )
                )
            }
            return pool.first { !spent.contains($0.0) } ?? pool[0]
        }

        let forms = rotatedCases(
            BraidPromptBuilder.StoryForm.allCases, leading: form, by: variant
        )
        let motions = rotatedCases(
            BraidPromptBuilder.NarrativeMotion.allCases, leading: motion, by: variant
        )
        var pool: [(String, String)] = []
        for offset in 0..<max(forms.count, motions.count) {
            if offset < forms.count {
                pool.append((
                    "form:\(forms[offset].rawValue)",
                    supportingMove(
                        form: forms[offset], motion: motion, firstSubject: firstSubject,
                        currentSubject: currentSubject, shadowMode: false, variant: 0
                    )
                ))
            }
            if offset < motions.count {
                pool.append((
                    "motion:\(motions[offset].rawValue)",
                    supportingMove(
                        form: form, motion: motions[offset], firstSubject: firstSubject,
                        currentSubject: currentSubject, shadowMode: false, variant: 1
                    )
                ))
            }
        }
        if !variant.isMultiple(of: 2), pool.count > 1 {
            pool.swapAt(0, 1)
        }
        return pool.first { !spent.contains($0.0) } ?? pool[0]
    }

    /// Pick the option the Book has not reached for in longest. An unused one
    /// always wins; otherwise the oldest does, which is what keeps a shallow
    /// pool cycling instead of sticking on whichever option happens to sort
    /// first once everything has been said once.
    private static func leastRecentlyUsed(
        _ options: [Int],
        in context: BraidPromptBuilder.Context,
        key: (Int) -> String
    ) -> Int {
        guard let first = options.first else { return 0 }
        if let unused = options.first(where: { context.recentMoveAges[key($0)] == nil }) {
            return unused
        }
        return options.max { left, right in
            (context.recentMoveAges[key(left)] ?? .max) < (context.recentMoveAges[key(right)] ?? .max)
        } ?? first
    }

    /// The night's own case first, then the rest in a stable rotation.
    private static func rotatedCases<T: Equatable>(
        _ all: [T],
        leading: T,
        by variant: Int
    ) -> [T] {
        let rest = all.filter { $0 != leading }
        guard !rest.isEmpty else { return [leading] }
        let offset = ((variant % rest.count) + rest.count) % rest.count
        return [leading] + Array(rest[offset...] + rest[..<offset])
    }

    private static func supportingMove(
        form: BraidPromptBuilder.StoryForm,
        motion: BraidPromptBuilder.NarrativeMotion,
        firstSubject: String,
        currentSubject: String,
        shadowMode: Bool,
        variant: Int
    ) -> String {
        let first = articleSubject(firstSubject)
        let current = articleSubject(currentSubject)
        if shadowMode {
            return variant.isMultiple(of: 2)
                ? "I kept \(current) beside \(first). The paper showed between them. I left it white."
                : "I put \(current) on the next line after \(first). I added nothing between."
        }
        if variant.isMultiple(of: 2) {
            switch form {
            case .sliceOfLife: return "I kept \(current) on the same page as \(first). No procession."
            case .mosaic: return "I set \(current) beside \(first). I refused to make either explain the other."
            case .portrait: return "I kept \(first) in view when I added \(current)."
            case .drama: return "I put \(current) against \(first). The difference had a clean edge."
            case .crossing: return "I drew \(current) close to \(first) and stopped before I lied about why."
            case .vigil: return "I kept both lines open. Neither received an ending."
            case .returnForm: return "I recognized \(current) beside \(first) and did not call them the same."
            case .comedy: return "I put \(current) after \(first). Bad timing. I approved."
            }
        }
        switch motion {
        case .encounter: return "I put \(current) down beside \(first). Neither became scenery."
        case .crossing: return "I kept \(current) and \(first), including the crooked distance between them."
        case .bargain: return "I marked \(current) as the gain and \(first) as the price. I did not swap them."
        case .repair: return "I kept \(first) and \(current) in one paragraph without sanding either down."
        case .refusal: return "I put the no between \(current) and \(first). It had weight."
        case .recurrence: return "I put \(current) after \(first) and kept the changed part visible."
        case .vigil: return "I left both lines unfinished and stayed."
        case .returnOfSomething: return "I checked \(current) against \(first). One mark had changed."
        }
    }

    /// One licensed impossible relation. The two receipts remain themselves;
    /// the invention is only that they can trouble one another across worlds.
    private static func crossingMove(for plan: Plan, variant: Int) -> String {
        guard let magicSubject = plan.magicSubject else { return "" }
        let subject = articleSubject(magicSubject)
        let visitor = articleSubject(plan.labyrinthSubject?.nonEmpty ?? "visitor")
        let role = plan.score.fictionBeat?.role ?? .pressure

        let arrival: String
        switch role {
        case .mirror:
            arrival = "\(capitalized(visitor)) recognized \(subject)."
        case .counterpoint:
            arrival = "\(capitalized(visitor)) brought the refusal to \(subject)."
        case .rehearsal:
            arrival = "\(capitalized(visitor)) left one instruction beside \(subject)."
        case .pressure:
            arrival = "\(capitalized(visitor)) leaned on \(subject)."
        case .afterimage:
            arrival = "\(capitalized(visitor)) came home clinging to \(subject)."
        }

        // Both halves of a crossing naturally open on their subject, which puts
        // two sentences beginning "The …" side by side in the page's most
        // important paragraph. Each law therefore has a second phrasing that
        // leads somewhere else, and the caller picks the one that does not
        // echo the arrival.
        let laws: [String]
        switch plan.score.taleReading.pressure {
        case .agency:
            laws = [
                "\(capitalized(subject)) sided with \(visitor) and would not tell me why.",
                "Neutral was not on offer. \(capitalized(subject)) chose, and \(visitor) did not get a vote."
            ]
        case .rule:
            laws = [
                "\(capitalized(subject)) laid down a law: \(motionLaw(plan.score.taleReading.motion)).",
                "There was a law under it now: \(motionLaw(plan.score.taleReading.motion))."
            ]
        case .debt:
            laws = [
                "\(capitalized(subject)) named the price already there and would not lower it.",
                "A price was already there. \(capitalized(subject)) named it and would not lower it."
            ]
        case .threshold:
            laws = [
                "\(capitalized(subject)) let \(visitor) cross once and shut the way behind.",
                "One crossing was allowed. Then \(subject) shut the way behind \(visitor)."
            ]
        case .rhyme:
            laws = [
                "\(capitalized(subject)) answered \(visitor) without borrowing the same words.",
                "An answer came back, and not one word of it was borrowed from \(visitor)."
            ]
        case .absence:
            laws = [
                "\(capitalized(subject)) kept an empty place beside \(visitor) open. I did not fill it.",
                "An empty place stayed open beside \(visitor). I did not fill it."
            ]
        case .timeSlip:
            laws = [
                "\(capitalized(subject)) held the hour around \(visitor) against yours until both jammed.",
                "Two hours met and jammed: yours, and the one \(subject) kept around \(visitor)."
            ]
        case .witness:
            laws = [
                "\(capitalized(subject)) kept watch over what \(visitor) did and would not look away.",
                "Nothing that \(visitor) did went unwatched, and \(subject) would not look away."
            ]
        }
        let arrivalOpening = BraidComposition.openingWord(of: arrival)
        let start = ((variant % laws.count) + laws.count) % laws.count
        let ordered = Array(laws[start...] + laws[..<start])
        let law = ordered.first {
            BraidComposition.openingWord(of: $0) != arrivalOpening
        } ?? ordered[0]
        return "\(arrival) \(law)"
    }

    private static func solitaryMagicMove(for plan: Plan, variant: Int) -> String {
        let subject = articleSubject(plan.magicSubject ?? plan.primaryDisplay)
        let companion = plan.secondarySubject.map(articleSubject)
        switch plan.score.taleReading.pressure {
        case .agency:
            return variant.isMultiple(of: 2)
                ? "\(capitalized(subject)) chose my side and refused to explain."
                : "\(capitalized(subject)) would not stay neutral. I approved."
        case .rule:
            return "\(capitalized(subject)) laid down a law: \(motionLaw(plan.score.taleReading.motion)). I obeyed it."
        case .debt:
            return "\(capitalized(subject)) named the price already there. I did not haggle."
        case .threshold:
            return "\(capitalized(subject)) guarded the way\(companion.map { " beside \($0)" } ?? ""). I was allowed through once. Then the way shut."
        case .rhyme:
            if let companion {
                return "\(capitalized(subject)) answered \(companion) without copying the words. Neither had been asked."
            }
            return "\(capitalized(subject)) answered me once. I did not ask for a second performance."
        case .absence:
            return "\(capitalized(subject)) kept the empty place open. I did not fill it."
        case .timeSlip:
            return "\(capitalized(subject)) held two hours together until they jammed. I stopped trying to pull them apart."
        case .witness:
            return "\(capitalized(subject)) kept watch and would not look away. I stayed quiet."
        }
    }

    private static func motionLaw(_ motion: BraidPromptBuilder.NarrativeMotion) -> String {
        switch motion {
        case .encounter: return "anything new showed one tooth before it entered"
        case .crossing: return "the way shut unless something was left behind"
        case .bargain: return "every gain dragged its price into view"
        case .repair: return "every mend left its scar showing"
        case .refusal: return "a no could bar the way"
        case .recurrence: return "anything returning came back with one changed mark"
        case .vigil: return "unfinished things were allowed to keep one eye open"
        case .returnOfSomething: return "anything coming back showed what had changed"
        }
    }

    private static func relationalMove(
        _ lens: BraidPromptBuilder.NightlyStoryScore.RelationalLens
    ) -> String {
        let rawCondition = cleanSourceText(lens.condition)
        let rawOutcome = cleanSourceText(lens.outcomes.first ?? "something answered")
        // "When the rain sets in for the afternoon." is not a sentence. A
        // condition that opens with a subordinator has to keep the clause it
        // governs, or the page hands the reader a fragment and calls it a
        // finding.
        let observation: String
        if let subordinator = subordinators.first(where: {
            rawCondition.lowercased().hasPrefix("\($0) ")
        }), !subordinator.isEmpty {
            observation = sentence(
                "\(capitalized(rawCondition)), \(lowercasedFirst(rawOutcome))"
            )
        } else {
            observation = "\(sentence(capitalized(rawCondition))) \(sentence(capitalized(rawOutcome)))"
        }
        if lens.evidenceTier == .glimmer {
            return "\(observation) I put a question mark there and would not let the Index rub it out."
        }
        return "\(observation) I knew the mark and left its name unwritten."
    }

    private static let subordinators: [String] = [
        "when", "whenever", "if", "after", "before", "while", "once", "because",
        "since", "unless", "until", "wherever", "where"
    ]

    private static func arcMove(
        _ arc: BraidPromptBuilder.NightlyStoryScore.ArcBeat,
        subject: String
    ) -> String {
        let kept = articleSubject(subject)
        switch arc.movement {
        case .began:
            return "I had not kept \(kept) this way before. I made one first notch at the page edge."
        case .deepened:
            return "I had an older mark for \(kept). Tonight's went beside it and pressed harder."
        case .complicated:
            return "The old mark for \(kept) forked tonight. I kept both cuts."
        case .returned:
            return "\(capitalized(kept)) had been here before. I compared the old mark with tonight's and kept the changed edge."
        case .resolved:
            return "\(capitalized(kept)) reached the last mark. I put the full stop there and kept the earlier scratches."
        case .rested:
            return "\(capitalized(kept)) did not move tonight. I left the old place open."
        }
    }

    private static func bodyWordCount(_ paragraphs: [[BraidSentence]]) -> Int {
        paragraphs.reduce(0) { total, paragraph in
            total + paragraph.reduce(0) {
                $0 + $1.text.split { $0.isWhitespace || $0.isNewline }.count
            }
        }
    }

    /// A settling beat. The Book's own handling of the page is the only thing
    /// it may report on at any length without asserting something new about
    /// the reader, so that is where the extra words go.
    ///
    /// Half of these deliberately do not open on "I". The Book speaks in the
    /// first person, so left alone a paragraph becomes "I… I… I…", and the
    /// caller picks by opening word to keep that from happening.
    private static func keepingMoves(for plan: Plan) -> [String] {
        if plan.hasUnclearedShadow {
            return [
                "I turned the corner of the page down and left the rest of the paper white.",
                "The margin stayed empty. I put the page where I will find it again.",
                "Once more I read the line, then set the pencil down beside it.",
                "Nothing else wanted saying tonight, so nothing else was said."
            ]
        }
        let subject = articleSubject(plan.magicSubject ?? plan.primaryDisplay)
        let companion = plan.secondarySubject.map(articleSubject)
        var moves = [
            "I moved \(subject) to the front of the page so it is the first thing I meet tomorrow.",
            "Twice I read the line around \(subject), and kept the second reading to myself.",
            // "The Index wanted a tidier version" used to live here, and it
            // collided with the Index thread in `taleThreads`: one paragraph
            // could hold the Index climbing off its shelf to look, and the
            // Index filing a complaint, as though there were two of them.
            "My pencil went down beside \(subject) and did not improve it. Something wanted a tidier version. It is not getting one.",
            "Flat against the page I pressed \(subject). It would not lie down. Good.",
            "I held the page up to the light to see whether \(subject) showed through. It did.",
            "Nothing about \(subject) needed improving, so I improved nothing."
        ]
        if let companion {
            moves.insert(
                "In one breath I read \(subject) and \(companion). The second changed the first. I let it.",
                at: 1
            )
        }
        // One pool, same as `taleThreads`. These six were gated behind the six
        // above until every one of them had been spent - and the comment here
        // used to describe them as "six less clerkly ways to touch the paper",
        // which is an admission that the gate held the better prose back. A
        // reader met the pencil and the tidier version for weeks before the
        // page ever tried to close on something and got a claw in the way.
        moves.append(contentsOf: [
                "Before the ink dried, I bent the page around \(subject). The fold refused to be straight.",
                "Under the lamp, \(subject) threw a little shadow into the next paragraph. I left it there.",
                "The page tried to close on \(subject). I put one claw in the way.",
                "At midnight \(subject) \(agreeing("was", "were", with: subject)) still awake in the sentence. I was too, so I kept watch.",
                "I slid \(subject) under the good paper and heard it scratching there.",
            "One corner of the page kept pointing at \(subject). I stopped pretending not to see."
        ])
        return moves
    }

    /// What the Book knows about this reader that tonight's receipts did not
    /// tell it: the name it gave them, the shape it has been noticing all
    /// month, the law a finished tale left behind. At most one of these per
    /// page: the Book shows it has been paying attention; it does not file a
    /// report.
    ///
    /// All of it is the Book's own voice, so the vocabulary is free. None of it
    /// may assert anything about the reader's day that a receipt did not say.
    private static func rememberingMove(
        for plan: Plan,
        variant: Int
    ) -> (key: String, text: String)? {
        guard !plan.hasUnclearedShadow else { return nil }
        let subject = articleSubject(plan.magicSubject ?? plan.primaryDisplay)
        var options: [(key: String, text: String)] = []

        if let role = plan.context.readerRole {
            // The role stamp used to be two lines chosen by `variant % count`
            // with no rest and no move key, so consecutive nights printed "I
            // wrote <name> in the margin where the page number goes. That is
            // whose this is." word for word. The name the Book gave the reader
            // is the last thing that should read as a stamp.
            options.append((
                "role-margin",
                "I wrote \(role.fullName) in the margin where the page number goes. That is whose this is."
            ))
            options.append((
                "role-fits",
                "The name I gave you still fits: \(role.fullName). I check more often than I admit."
            ))
            options.append((
                "role-signed",
                "Somebody has been signing these pages \(role.fullName). It was me, and I would do it again."
            ))
            if let clause = plan.context.roleTransformationClause?.nonEmpty {
                options.append((
                    "role-turned",
                    "\(role.fullName), \(lowercasedFirst(clause)). I have not changed my mind about it."
                ))
            } else {
                options.append((
                    "role-kept",
                    "\(role.fullName) kept \(subject), and I would have called that typical a month ago."
                ))
            }
        }
        if let motif = plan.context.theme?.motifs.first(where: { !$0.isEmpty }) {
            options.append((
                "motif-again",
                "\(capitalized(motif)) again. I have stopped calling that a coincidence."
            ))
            options.append((
                "motif-counting",
                "I have been counting \(motif.lowercased()) for weeks now. Tonight made another mark."
            ))
        }
        if let law = plan.context.standingTaleLaws.first(where: { !$0.isEmpty }) {
            options.append((
                "law-holds",
                "The old law still holds: \(lowercasedFirst(sentenceBody(law))). I wrote tonight under it."
            ))
        }
        guard !options.isEmpty else { return nil }

        // The same resting every other move family gets: rotate, prefer what
        // the prose memory has not just heard, then prefer what has not been
        // used inside the rest window, and fall back to the oldest.
        let start = ((variant % options.count) + options.count) % options.count
        let order = Array(start..<options.count) + Array(0..<start)
        let styleFresh = order.filter {
            plan.context.braidStyleMemory.recurrencePenalty(in: options[$0].text) == 0
        }
        let rested = styleFresh.isEmpty ? order : styleFresh
        let unused = rested.filter {
            plan.context.recentMoveAges["remember:\(options[$0].key)"] == nil
        }
        let chosen = unused.first
            ?? leastRecentlyUsed(rested, in: plan.context) { "remember:\(options[$0].key)" }
        return ("remember:\(options[chosen].key)", options[chosen].text)
    }

    /// The sentence a language model structurally cannot write.
    ///
    /// Gemma reads tonight through a prompt already at its context limit. The
    /// house writer has counted the whole archive, so it can say how long this
    /// subject has been coming back, and it says it about its *own keeping*,
    /// never by re-narrating what the reader wrote months ago. The Book may
    /// report what it has done; the reader's past is not tonight's material.
    private static func archiveEchoMove(for plan: Plan, now: Date) -> String? {
        guard !plan.hasUnclearedShadow,
              let subject = plan.magicSubject ?? plan.primaryDisplay.nonEmpty else { return nil }
        let head = subject.split(separator: " ").last.map(String.init)?.lowercased() ?? subject
        guard let history = plan.context.subjectHistory[head] else { return nil }
        // One prior mention is a coincidence, and a subject last seen yesterday
        // needs no announcing. Significance has to be earned by both count and
        // distance, or the Book is manufacturing meaning out of a repeat.
        let daysSinceFirst = Calendar.current.dateComponents(
            [.day], from: history.firstSeen, to: now
        ).day ?? 0
        guard history.occasions >= 3, daysSinceFirst >= 21 else { return nil }

        let article = articleSubject(subject)
        let month = archiveMonthFormatter.string(from: history.firstSeen)
        let tally = countedOccasions(history.occasions + 1)
        return "That is \(tally) I have kept \(article). The first was in \(month)."
    }

    /// A rare, inspectable return from another Book of You Page. The selection
    /// already proved the shared arc and supplied its evidence IDs; this line
    /// names the old Page instead of hiding the claim behind "an older mark."
    private static func evidenceRhymeMove(for plan: Plan) -> String? {
        guard let beat = plan.context.continuityBeat,
              beat.kind == .evidenceRhyme,
              let title = beat.sourceTitle?.nonEmpty,
              let oldLine = beat.priorLine?.nonEmpty else { return nil }
        let clipped = BraidPromptBuilder.fallbackExcerpt(oldLine, limit: 96)
        return "Tonight \(beat.currentAnchor) pulled the page called “\(title)” from its shelf. Its old line said “\(sentenceBody(clipped))”. I set the two Pages close enough to quarrel, not close enough to agree."
    }

    private static func countedOccasions(_ count: Int) -> String {
        switch count {
        case ..<4: return "the third time"
        case 4: return "the fourth time"
        case 5: return "the fifth time"
        case 6: return "the sixth time"
        case 7: return "the seventh time"
        case 8: return "the eighth time"
        case 9: return "the ninth time"
        case 10: return "the tenth time"
        default: return "the \(count)th time"
        }
    }

    private static let archiveMonthFormatter: DateFormatter = {
        let formatter = DateFormatter()
        // The Book writes in English everywhere else on the page; a month name
        // that changes with the device locale would be the only word that did,
        // and it would make the golden bench machine-dependent.
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.dateFormat = "LLLL"
        return formatter
    }()

    private static func sentenceBody(_ text: String) -> String {
        var trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        while let last = trimmed.last, ".!?…".contains(last) { trimmed.removeLast() }
        return trimmed
    }

    /// The Book's world doing something, instead of the Book describing its own
    /// filing.
    ///
    /// `keepingMoves` buy the night's word band with pencil-and-margin
    /// sentences, and they are good ones, but they were buying nearly all of
    /// it: a typical page ran eight authored sentences about circling, reading
    /// twice, and moving things to the front of the page. Read three nights
    /// running it stops sounding like a book with a will and starts sounding
    /// like a clerk. These spend the same budget on the tale that is actually
    /// running.
    ///
    /// The reader's object is what the world reaches *for*. Nothing here says
    /// the reader did, felt, or understood anything: that remains the one thing
    /// the house writer may never invent.
    /// One thread of the Book's world: how it starts, and what it says when it
    /// is picked up again a night or two later.
    ///
    /// The key is a stable slug rather than a position. The pool grows and
    /// shrinks with the open tale's un-witnessed beats, so an index meant a
    /// different thread on different nights and the rest ledger was resting
    /// whichever line happened to be sitting at that number.
    private struct TaleThread {
        var key: String
        var opening: String
        var continuation: String
        var resolution: String? = nil
    }

    private static func taleThreads(
        for plan: Plan,
        subjectOverride: String? = nil
    ) -> [TaleThread] {
        guard plan.allowsNewMagic else { return [] }
        // On a night carrying hard, unpermitted material the world stays in the
        // room but says nothing about why. These five attend; they do not ask
        // what a thing is for, gossip about it, or accuse a door of lying. The
        // subject they attend is never the shadow material: `magicSubject` has
        // already been steered to something ordinary from the same day.
        let vigilOnly = plan.hasUnclearedShadow
        // "unfinished business" and "the entry is still open" both imply
        // incompleteness. Landed next to a funeral they stop attending and
        // start interpreting, which is the one thing the shadow laws forbid.
        let vigilSafe: Set<String> = ["stacks", "door", "lamps"]
        let subject = subjectOverride ?? articleSubject(plan.magicSubject ?? plan.primaryDisplay)
        let visitor = plan.labyrinthSubject.flatMap { $0.nonEmpty }.map(articleSubject)

        // Deliberately no line opens on the subject word: the receipt sentences
        // around them already do, and a run of sentences starting on the same
        // noun is exactly what the prosody penalty counts. Each line below
        // starts somewhere different on purpose.
        var threads: [TaleThread] = [
            TaleThread(
                key: "stacks",
                opening: "Three shelves turned to face \(subject) tonight. Shelves are not built with a front.",
                continuation: "Those three shelves are still facing \(subject). Nothing has talked them back round.",
                resolution: "The shelves that turned toward \(subject) have gone back to the wall. One of them took something with it."
            ),
            TaleThread(
                key: "door",
                opening: "A door past the reading room opened onto nothing while \(subject) \(agreeing("was", "were", with: subject)) on the page, waited, and shut again.",
                continuation: "That door has opened onto nothing twice more since \(subject), and waited a little longer each time.",
                resolution: "The door past the reading room opened once more for \(subject), and there was a corridor behind it. There has never been a corridor there."
            ),
            TaleThread(
                key: "index",
                opening: "The Index climbed out of its own alphabet to look at \(subject) properly, which it has no business doing.",
                continuation: "The Index is still out of its alphabet and still looking at \(subject). It has not gone back all week.",
                resolution: "The Index climbed back into its alphabet and left one corner turned down over \(subject). I did not turn it."
            ),
            TaleThread(
                key: "frost",
                opening: "Frost crossed the window over \(subject) and stopped in a straight line. Frost has never once done a straight line.",
                continuation: "The straight edge of frost above \(subject) has not melted. The rest of the window has.",
                resolution: "The frost over \(subject) went at dawn and left its straight line behind, dry on the glass."
            ),
            TaleThread(
                key: "echo",
                opening: "Someone in another room said \(subject) out loud a moment before I wrote it down. There is no other room.",
                continuation: "The other room said \(subject) again tonight, still a moment early. I have stopped looking for the door.",
                resolution: "The other room has gone quiet about \(subject). I would rather it had not."
            ),
            TaleThread(
                key: "ribbon",
                opening: "My ribbon moved on its own and lay itself across \(subject). I have not decided whether that was a favour.",
                continuation: "The ribbon has not left \(subject). It tightens if I try to turn past.",
                resolution: "The ribbon let go of \(subject) tonight and lay flat, which is the nearest it comes to an apology."
            ),
            TaleThread(
                key: "lamps",
                opening: "Twice the lamps went down over \(subject) and twice they came back up. The building does that when it is thinking.",
                continuation: "The lamps over \(subject) have settled. Whatever the building was thinking about, it has decided.",
                resolution: "The building has finished thinking about \(subject). One lamp remains lit, which is its way of refusing to explain."
            ),
            TaleThread(
                key: "birds",
                opening: "Birds got into the Academy roof and would not settle until \(subject) \(agreeing("was", "were", with: subject)) written down.",
                continuation: "The birds start again whenever \(subject) \(agreeing("comes", "come", with: subject)) up, and stop the moment I look up.",
                resolution: "The birds left the roof the night \(subject) finished. They took the noise with them, which I miss."
            ),
            TaleThread(
                key: "rain",
                opening: "It rained inside the Stacks over \(subject) and nowhere else. The floor is still dark there.",
                continuation: "That dark patch under \(subject) has not dried, and nothing has rained since.",
                resolution: "The floor under \(subject) dried at last, in the shape of something with too many corners."
            ),
            TaleThread(
                key: "doors",
                opening: "None of the doors would say which one \(subject) came through, which usually means every one of them is lying.",
                continuation: "Since none of the doors would admit to \(subject), they have settled on a shared story. It is not a good one.",
                resolution: "The doors have withdrawn their shared story about \(subject). One of them apologised by opening the wrong way."
            )
        ]

        // One pool, available from the first night.
        //
        // These six used to be held back until every one of the ten threads
        // above had already been spent, or until they started repeating. That
        // gate had the effect exactly backwards: the six are the ones where the
        // world is actually alive - a paper moth, a stair that shifts when it
        // overhears, a bell under a floor that has no bell - and the ten it
        // waited on were the archive doing paperwork. A new reader met ten
        // nights of filing before the Book was permitted to be strange.
        //
        // The ten have since been rewritten into this register, so there is no
        // longer a lesser half to graduate from. `recentMoveAges` already rests
        // a thread once it has been used, which is the only throttle a pool
        // this size needs.
        threads.append(contentsOf: [
                TaleThread(
                key: "moth",
                opening: "A paper moth ate a careful hole around \(subject) and left the important part untouched. Show-off.",
                continuation: "The paper moth has returned to \(subject). It is eating a border this time and calling that restraint.",
                resolution: "The moth finished its border around \(subject) and fell asleep in the full stop."
                ),
                TaleThread(
                key: "stairs",
                opening: "Halfway up the Academy stairs, one step shifted sideways when it heard about \(subject). I counted twice.",
                continuation: "The sideways step is still waiting for \(subject). Everyone else has learned to climb around its opinion.",
                resolution: "The shifted step went back into line after \(subject) passed through the story. It kept one corner crooked."
                ),
                TaleThread(
                key: "pocket",
                opening: "My back cover grew a new pocket for \(subject) while I was not looking. I object to the secrecy, not the pocket.",
                continuation: "The pocket under my back cover still has \(subject). It snaps at any hand but mine.",
                resolution: "The hidden pocket gave \(subject) back at dawn, along with a button nobody recognises."
                ),
                TaleThread(
                key: "bell",
                opening: "One bell rang under the floor when \(subject) reached the page. There is not meant to be a bell there.",
                continuation: "The bell under the floor keeps ringing for \(subject), but only when the room pretends not to listen.",
                resolution: "The bell rang once more for \(subject), swallowed its own echo, and stopped."
                ),
                TaleThread(
                key: "dust",
                opening: "Dust fled one neat circle around \(subject). I put a finger in it and something bit back.",
                continuation: "The bare circle around \(subject) has stayed clean while the rest of the room gathers dust. Suspicious manners.",
                resolution: "Dust crossed the circle around \(subject) at last. It went in single file."
                ),
                TaleThread(
                key: "roof",
                opening: "Above the Stacks, something ran across the roof carrying news of \(subject) in its teeth.",
                continuation: "Whatever crossed the roof with \(subject) has come back slower and refuses to drop the news.",
                resolution: "The roof-runner finally dropped the news of \(subject) down the chimney. It arrived singed but legible."
                )
        ])

        if vigilOnly { return threads.filter { vigilSafe.contains($0.key) } }

        // The open tale's next beat, dramatised against tonight's object. This
        // is the whole point of recognising a tale at all: it should be able to
        // walk onto the page it was recognised from.
        if let tale = plan.context.openTale, tale.isOpen {
            let witnessed = tale.witnessedBeats
            if !witnessed.contains(.price) {
                threads.append(TaleThread(
                    key: "price",
                    opening: "Everything here costs. No bill has come for \(subject) yet, which is not the same as free.",
                    continuation: "The bill for \(subject) has still not come. I have stopped calling that luck.",
                    resolution: "The bill for \(subject) came at last, and the amount was in a hand I know."
                ))
            }
            if !witnessed.contains(.donor) {
                threads.append(TaleThread(
                    key: "donor",
                    opening: "Something offered \(subject) a trade tonight and would not say what for. The offer stands until it stops standing.",
                    continuation: "That offer on \(subject) is still standing. Standing is not the same as harmless.",
                    resolution: "The offer on \(subject) was withdrawn tonight, which I did not know it could do."
                ))
            }
            if !witnessed.contains(.crossing) {
                threads.append(TaleThread(
                    key: "crossing",
                    opening: "There is a threshold under \(subject) now. I did not put it there and I cannot lift it.",
                    continuation: "The threshold under \(subject) has not moved. Neither has anything else, which is worse.",
                    resolution: "The threshold under \(subject) let something through tonight and shut behind it, politely."
                ))
            }
            if !witnessed.contains(.lack) {
                threads.append(TaleThread(
                    key: "lack",
                    opening: "Something is missing from the row beside \(subject), and nothing has been taken from it. I counted twice.",
                    continuation: "The gap beside \(subject) is still there, and still the wrong size for anything I own.",
                    resolution: "The gap beside \(subject) closed over while I was not looking. Nothing filled it."
                ))
            }
            if !witnessed.contains(.transgression) {
                threads.append(TaleThread(
                    key: "transgression",
                    opening: "No line has been crossed around \(subject) yet. I keep checking the chalk, which tells you what I expect.",
                    continuation: "There is a scuff in the chalk around \(subject) now. I did not make it.",
                    resolution: "The chalk around \(subject) has gone entirely. Something walked through and kept walking."
                ))
            }
            if !witnessed.contains(.consequence) {
                threads.append(TaleThread(
                    key: "consequence",
                    opening: "Nothing has followed \(subject) home yet. Things usually follow.",
                    continuation: "Whatever has been following \(subject) is closer tonight, and still on the other side of the door.",
                    resolution: "The thing that followed \(subject) came in, sat down, and has not explained itself."
                ))
            }
            if !witnessed.contains(.transformation) {
                threads.append(TaleThread(
                    key: "transformation",
                    opening: "So far \(subject) \(agreeing("is", "are", with: subject)) exactly what it was when it arrived. Nothing stays that way here for long.",
                    continuation: "There is a difference in \(subject) tonight and I cannot say which part moved.",
                    resolution: "Whatever \(subject) \(agreeing("has", "have", with: subject)) become, it is not what came in. I have kept both versions."
                ))
            }
            if !witnessed.contains(.ret) {
                threads.append(TaleThread(
                    key: "return",
                    opening: "Nothing has come back to \(subject) yet. Things do come back here, by a longer road than they left on.",
                    continuation: "Something is on its way back to \(subject). The corridor has started making room for it.",
                    resolution: "What went out from \(subject) came back tonight, and came back the wrong size."
                ))
            }
            if !witnessed.contains(.test) {
                threads.append(TaleThread(
                    key: "test",
                    opening: "A question was set for \(subject) tonight, and the answer was deliberately not written down anywhere.",
                    continuation: "The question set for \(subject) has not been withdrawn. Nobody has written the answer down yet.",
                    resolution: "The question set for \(subject) has been answered, and not by me."
                ))
            }
            if witnessed.contains(.consequence) {
                threads.append(TaleThread(
                    key: "taken-in",
                    opening: "\u{201C}\(tale.title)\u{201D} has taken \(subject) in, without asking whether anyone wanted to be in a story.",
                    continuation: "\u{201C}\(tale.title)\u{201D} has not given \(subject) back. Stories rarely do, once they have decided."
                ))
            }
        }

        if let visitor {
            threads.append(TaleThread(
                key: "visitor",
                opening: "\(capitalized(visitor)) \(agreeing("has", "have", with: visitor)) been asking after \(subject). I have not answered yet.",
                continuation: "\(capitalized(visitor)) is still asking after \(subject), and has begun asking other people."
            ))
        }
        if let chapter = plan.context.chapter {
            threads.append(TaleThread(
                key: "chapter",
                opening: "\(chapter.name) would have opinions about \(subject), and is not being told.",
                continuation: "\(chapter.name) has found out about \(subject) anyway. Someone talked. It was not me."
            ))
        }
        return threads
    }

    /// A line from the Book's world. `age` still serves the prose-rest ledger;
    /// continuity itself comes from typed braid residue, never a positional tag.
    private struct TaleLine {
        var key: String
        var text: String
        var age: Int?
    }

    private static func taleLines(for plan: Plan) -> [TaleLine] {
        taleThreads(for: plan).map { thread in
            return TaleLine(
                key: "tale:\(thread.key)",
                text: thread.opening,
                age: plan.context.recentMoveAges["tale:\(thread.key)"]
            )
        }
    }

    private static func continuityTaleLine(for plan: Plan) -> TaleLine? {
        guard let beat = plan.context.continuityBeat,
              beat.kind != .evidenceRhyme,
              let threadID = beat.threadID else { return nil }
        let anchor = beat.kind == .fictionOpening
            ? beat.currentAnchor
            : (beat.priorAnchor ?? beat.currentAnchor)
        guard let thread = taleThreads(for: plan, subjectOverride: anchor)
            .first(where: { $0.key == threadID }) else { return nil }
        let key: String
        let text: String
        switch beat.kind {
        case .fictionOpening:
            key = "tale:\(thread.key)"
            text = thread.opening
        case .fictionContinuation:
            key = "tale:\(thread.key)+"
            if beat.currentAnchor.caseInsensitiveCompare(anchor) == .orderedSame {
                text = thread.continuation
            } else {
                text = "\(thread.continuation) Tonight \(beat.currentAnchor) turned up beside it. That changed the trouble, though neither thing will say how."
            }
        case .fictionResolution:
            key = "tale:\(thread.key)!"
            let ending = thread.resolution
                ?? "The business with \(anchor) ended crookedly, which is the only ending it was willing to give me."
            var landing = [ending]
            if let previous = beat.previousAnchor?.nonEmpty,
               previous.caseInsensitiveCompare(anchor) != .orderedSame,
               previous.caseInsensitiveCompare(beat.currentAnchor) != .orderedSame {
                landing.append("\(capitalized(previous)) stayed beside the business until the end.")
            }
            if beat.currentAnchor.caseInsensitiveCompare(anchor) != .orderedSame {
                landing.append("\(capitalized(beat.currentAnchor)) \(agreeing("was", "were", with: beat.currentAnchor)) there at the end and \(agreeing("is", "are", with: beat.currentAnchor)) pretending not to have helped.")
            }
            text = landing.joined(separator: " ")
        case .evidenceRhyme:
            return nil
        }
        return TaleLine(
            key: key,
            text: text,
            age: plan.context.recentMoveAges[key]
        )
    }

    /// Threads that belong to a recognised tale rather than to the house. Only
    /// these may be preferred by the lean, and only while a tale is open.
    private static let beatThreadKeys: Set<String> = [
        "price", "donor", "crossing", "test", "lack", "transgression",
        "consequence", "transformation", "return", "taken-in"
    ]

    /// Move keys arrive as `tale:<key>`, and continuity marks its stage with a
    /// trailing `+` or `!`. Comparing the raw key against the bare names
    /// silently matched nothing, which is how the lean shipped inert the first
    /// time.
    private static func isBeatThreadKey(_ key: String) -> Bool {
        var bare = key.hasPrefix("tale:") ? String(key.dropFirst("tale:".count)) : key
        while let last = bare.last, last == "+" || last == "!" { bare.removeLast() }
        return beatThreadKeys.contains(bare)
    }

    private static func taleMove(
        for plan: Plan,
        variant: Int,
        index: Int,
        avoiding openings: Set<String>,
        spentKeys: Set<String>
    ) -> (key: String, text: String)? {
        if index == 0,
           let continuity = continuityTaleLine(for: plan),
           !spentKeys.contains(continuity.key) {
            return (continuity.key, continuity.text)
        }
        let lines = taleLines(for: plan)
        let continuityKey = plan.context.continuityBeat?.threadID.map { "tale:\($0)" }
        let openingsPool = lines.filter { line in
            guard !spentKeys.contains(line.key) else { return false }
            return continuityKey.map { line.key != $0 } ?? true
        }
        guard !openingsPool.isEmpty else { return nil }
        // The tale leans.
        //
        // A running shape gets first call on the night's opening world move.
        // Without this the beat threads were appended after sixteen house
        // threads and picked by the same rotation, so the beat a tale was
        // recognised from almost never reached the page it was recognised
        // from - which is the one thing recognising it was for.
        //
        // It stays a lean and never becomes an announcement: these threads
        // speak about what has *not* happened yet, and none of them names the
        // shape. Later moves in the same night fall back to the whole pool, so
        // a leaning night is still mostly the ordinary world.
        // Keyed off what the night has already spent rather than off `index`,
        // because index 0 is usually taken by the continuity serial: gating on
        // the index meant the lean only ever ran on nights with no thread to
        // continue, which is most of the nights it was least needed on.
        let beatPool = openingsPool.filter { isBeatThreadKey($0.key) }
        let beatAlreadySpoken = spentKeys.contains(where: isBeatThreadKey)
        let candidates = (!beatPool.isEmpty && !beatAlreadySpoken) ? beatPool : openingsPool
        let start = (((variant + index) % candidates.count) + candidates.count) % candidates.count
        let order = Array(start..<candidates.count) + Array(0..<start)
        let styleFresh = order.filter {
            plan.context.braidStyleMemory.recurrencePenalty(in: candidates[$0].text) == 0
        }
        let restedOrder = styleFresh.isEmpty ? order : styleFresh
        let fresh = restedOrder.filter { candidates[$0].age == nil }
        let pool = fresh.isEmpty
            ? [leastRecentlyUsed(restedOrder, in: plan.context) { candidates[$0].key }]
            : fresh
        let chosen = pool.first {
            !openings.contains(BraidComposition.openingWord(of: candidates[$0].text))
        } ?? pool[0]
        return (candidates[chosen].key, candidates[chosen].text)
    }

    private static func keepingMove(
        for plan: Plan,
        variant: Int,
        index: Int,
        avoiding openings: Set<String>,
        spentKeys: Set<String>
    ) -> (key: String, text: String)? {
        let moves = keepingMoves(for: plan)
        guard !moves.isEmpty else { return nil }
        let start = (((variant + index) % moves.count) + moves.count) % moves.count
        let order = Array(start..<moves.count) + Array(0..<start)
        // Never twice in one night. This filter was described here long before
        // it existed, and without it the `?? pool[0]` fallback below could hand
        // back a move already on the page: four of the bench's twenty-three
        // nights carried a sentence printed verbatim twice.
        let unspent = order.filter { !spentKeys.contains("keeping:\($0)") }
        guard !unspent.isEmpty else { return nil }
        // Then: not said in the last ten nights, and not opening on a word the
        // paragraph has already opened on.
        // Prefer a move whose actual sentence shape has not appeared recently,
        // even if an older archived Page is missing its compiler move tag.
        // The tag ledger is the fast path; prose memory is the durable truth
        // after imports, migrations, or accepted model revisions.
        let styleFresh = unspent.filter {
            plan.context.braidStyleMemory.recurrencePenalty(in: moves[$0]) == 0
        }
        let restedOrder = styleFresh.isEmpty ? unspent : styleFresh
        let fresh = restedOrder.filter { plan.context.recentMoveAges["keeping:\($0)"] == nil }
        let pool = fresh.isEmpty
            ? [leastRecentlyUsed(restedOrder, in: plan.context) { "keeping:\($0)" }]
            : fresh
        let chosen = pool.first {
            !openings.contains(BraidComposition.openingWord(of: moves[$0]))
        } ?? pool[0]
        return ("keeping:\(chosen)", moves[chosen])
    }

    /// The most-read line on the page, and until now the least varied: one
    /// phrasing per pressure meant a daily reader met the same closing shape
    /// roughly every eight nights. Each pressure now has two, and the ledger
    /// rests whichever was used last.
    private static func keeperLine(
        for plan: Plan,
        variant: Int
    ) -> (key: String, text: String) {
        if plan.hasUnclearedShadow {
            return (
                "colophon:plain-shadow",
                "The Book kept the page: the words stayed in the order they came."
            )
        }
        let subject = articleSubject(plan.magicSubject ?? plan.primaryDisplay)
        let visitor = plan.labyrinthSubject.flatMap { $0.nonEmpty }.map(articleSubject)
        guard plan.allowsNewMagic else {
            return (
                "colophon:no-magic",
                "The Book kept the page: \(subject) stayed exact, and I kept the rough edge."
            )
        }

        let pressure = plan.score.taleReading.pressure
        let endings: [String]
        switch pressure {
        case .agency:
            endings = [
                visitor.map { "\(subject) kept the choice; \($0) never got a vote." }
                    ?? "\(subject) chose, and I kept the mark.",
                "the choice stayed with \(subject), where I found it."
            ]
        case .rule:
            let guest = visitor.map { ", with \($0) still inside it" } ?? ""
            endings = [
                "\(subject) kept the rule\(guest).",
                "the rule holds, and \(subject) is the one holding it."
            ]
        case .debt:
            let witness = visitor.map { " where \($0) could see it" } ?? " on the line"
            endings = [
                "\(subject) kept the price\(witness).",
                "the price stayed named, and \(subject) did not lower it."
            ]
        case .threshold:
            endings = [
                visitor.map { "\(subject) shut the way after \($0)." }
                    ?? "\(subject) shut the way after one crossing.",
                "one crossing was allowed, and \(subject) closed the rest."
            ]
        case .rhyme:
            endings = [
                visitor.map { "\(subject) gave \($0) the last answer." }
                    ?? "\(subject) answered once, and I did not ask twice.",
                "the answer came from \(subject), and once was enough."
            ]
        case .absence:
            endings = [
                visitor.map { "\(subject) kept an empty place beside \($0) open." }
                    ?? "\(subject) kept one empty place open.",
                "an empty place stayed open beside \(subject). I left it."
            ]
        case .timeSlip:
            endings = [
                visitor.map { "\(subject) kept the hour around \($0) jammed against yours." }
                    ?? "\(subject) kept the earlier hour jammed against yours.",
                "two hours stayed jammed together, and \(subject) held them."
            ]
        case .witness:
            let watched = visitor ?? "what happened"
            endings = [
                "\(subject) kept watch over \(watched).",
                "nothing about \(watched) went unwatched, and \(subject) is why."
            ]
        }

        let start = ((variant % endings.count) + endings.count) % endings.count
        let order = Array(start..<endings.count) + Array(0..<start)
        let chosen = leastRecentlyUsed(order, in: plan.context) {
            "colophon:\(pressure.rawValue):\($0)"
        }
        return (
            "colophon:\(pressure.rawValue):\(chosen)",
            "The Book kept the page: \(endings[chosen])"
        )
    }

    private static func waitingPage() -> BraidComposition {
        BraidComposition(
            title: "The Page That Bit Back",
            paragraphs: [
                authoredUnits(
                    "The day left no scrap under my door. I sniffed the paper. It sniffed back."
                ),
                authoredUnits(
                    "We argued over whose turn it was. The blank won and sat on the good ink until midnight."
                ),
                [BraidSentence(
                    text: "The Book kept the page: the blank kept the good ink and would not say what it wanted.",
                    provenance: .colophon
                )]
            ],
            tags: ["braid", "deterministic-braidwright", "braid-empty"],
            promptText: "I kept the blank honest."
        )
    }

    private static func plainWitnessPage(
        for day: BookDay,
        context: BraidPromptBuilder.Context
    ) -> BraidComposition {
        let sourcePage = BraidPromptBuilder.braidEligiblePages(in: day)
            .filter {
                ReaderShelf.of($0) != .shadow
                    || context.readerStory.shadowPermission != .knowButNeverWrite
            }
            .sorted { ($0.createdAt, $0.id) < ($1.createdAt, $1.id) }
            .first
        guard let sourcePage else { return waitingPage() }
        let source = cleanSourceText(
            sourcePage.playerReply.nonEmpty
                ?? sourcePage.userInput.nonEmpty
                ?? sourcePage.promptText
        )
        .replacingOccurrences(of: "«", with: "‹")
        .replacingOccurrences(of: "»", with: "›")
        return BraidComposition(
            title: "The Words Kept Their Shape",
            paragraphs: [
                [BraidSentence(
                    text: "I copied this much and changed none of its words: «\(source)»",
                    provenance: .quotedReceipt(pageID: sourcePage.id)
                )],
                authoredUnits("My pencil prowled once around the edge and stopped."),
                [BraidSentence(
                    text: "The Book kept the page: the scrap kept its own words.",
                    provenance: .colophon
                )]
            ],
            tags: [
                "braid", "deterministic-braidwright", "braid-register-fail-closed",
                "braid-receipt:\(sourcePage.id)"
            ],
            promptText: "I kept one scrap in its own words."
        )
    }

    private static func livedSentence(_ source: String) -> String {
        var text = cleanSourceText(source)
        let carriesReaderPronoun = text.range(
            of: #"(?i)\b(?:i|i['’]m|i['’]ve|me|my|mine|myself)\b"#,
            options: .regularExpression
        ) != nil
        if carriesReaderPronoun {
            let carriesQuotedSpeech = text.contains("\"")
                || text.contains("“")
                || text.contains("”")
                || text.contains("‘")
                || text.contains("«")
                || text.contains("»")
                || text.range(
                    of: #"(?:^|[\s,:;—-])'[^'\n]{2,}'"#,
                    options: .regularExpression
                ) != nil
            if carriesQuotedSpeech {
                // Quoting is the only grammar-safe way to preserve arbitrary
                // free prose with a second speaker inside it.
                return sentence("I caught this much of your sentence: «\(attributionText(text))»")
            }

            // With no quoted speaker, a pronoun-only turn preserves every
            // action and tense while keeping the Book out of the reader's role.
            let replacements: [(String, String)] = [
                (#"(?i)\bi['’]m\b"#, "you're"),
                (#"(?i)\bi am\b"#, "you are"),
                (#"(?i)\bi was\b"#, "you were"),
                (#"(?i)\bi['’]ve\b"#, "you've"),
                (#"(?i)\bi have\b"#, "you have"),
                (#"(?i)\bmyself\b"#, "yourself"),
                (#"(?i)\bmine\b"#, "yours"),
                (#"(?i)\bmy\b"#, "your"),
                (#"(?i)\bme\b"#, "you"),
                (#"(?i)\bi\b"#, "you")
            ]
            for (pattern, replacement) in replacements {
                text = text.replacingOccurrences(
                    of: pattern,
                    with: replacement,
                    options: .regularExpression
                )
            }
            text = capitalized(text)
        }
        return sentence(text)
    }

    private static func livedSentence(_ atom: EvidenceAtom) -> String {
        if atom.shelf == .shadow, !atom.mayTakeTaleForm {
            return sentence("I copied this much and changed none of its words: «\(attributionText(cleanSourceText(atom.text)))»")
        }
        return livedSentence(atom.text)
    }

    private static func labyrinthSentence(_ atom: EvidenceAtom) -> String {
        var lines: [String] = []
        let scene = cleanSourceText(atom.text)
        if !scene.isEmpty { lines.append(sentence(scene)) }
        if let choice = atom.readerChoice?.nonEmpty {
            switch atom.readerChoiceKind {
            case .answer:
                lines.append(sentence("You said, «\(attributionText(choice))»"))
            case .taggedChoice:
                // Whether the choice reads as a thing or as an action. This was
                // an allowlist of fifteen verbs, which meant every verb outside
                // it produced "You chose front the cost." - and the cleave
                // transform then faithfully rewrote that into "It was front the
                // cost that you chose."
                //
                // Asking whether the phrase *opens like a noun phrase* cannot
                // go stale the way a verb list does: a multi-word choice that
                // does not start on a determiner is an action, and takes "to".
                let words = choice
                    .lowercased()
                    .split(whereSeparator: \.isWhitespace)
                    .map(String.init)
                let readsAsThing = words.count <= 1
                    || choiceDeterminers.contains(words[0])
                if readsAsThing {
                    lines.append(sentence("You chose \(lowercasedFirst(choice))"))
                } else {
                    lines.append(sentence("You chose to \(lowercasedFirst(choice))"))
                }
            case nil:
                break
            }
        }
        return lines.joined(separator: " ")
    }

    /// Page bodies are composed for their own surface, and that composition
    /// leaks. A Story Page body carries "Turn 1" markers; a Fae Bargain body
    /// carries `---` field separators; both can arrive already clipped and so
    /// end mid-sentence. The braid quotes bodies verbatim as receipts, which
    /// is why "A Fae Bargain: Book Sprite --- ... --- They fronted you the..."
    /// reached a finished page word for word.
    ///
    /// This strips the scaffolding at the point of quoting rather than at the
    /// point of writing, deliberately: pages already in the reader's archive
    /// carry these bodies and cannot be rewritten, and the braid should not
    /// trust any page's body to be prose.
    /// Words a choice phrase opens with when it names a thing rather than an
    /// action. "the shortcut" is a thing; "front the cost" is not.
    private static let choiceDeterminers: Set<String> = [
        "a", "an", "another", "both", "every", "her", "his", "its", "my", "no",
        "one", "that", "the", "their", "these", "this", "those", "your"
    ]

    /// Every page-type label a composed body might open with, longest first so
    /// "The Two Readings:" wins over any shorter title it contains.
    private static let pageTypeLabelPrefixes: [String] = {
        BookPageType.allCases
            .flatMap { type -> [String] in
                let title = type.title
                return ["a \(title):", "an \(title):", "the \(title):", "\(title):"]
            }
            .map { $0.lowercased() }
            .sorted { $0.count > $1.count }
    }()

    static func strippedScaffolding(_ source: String) -> String {
        var text = source.trimmingCharacters(in: .whitespacesAndNewlines)
        // A composed body can open with its own header - "A Fae Bargain: Book
        // Sprite --- <prose>" - where the header is terminated by the first
        // field separator. Drop the header whole, before the separators are
        // collapsed and the boundary becomes unrecoverable. Only a known page
        // type qualifies, so a reader who writes "My sister said: ..." keeps
        // every word.
        if let separator = text.range(of: #"\s*-{3,}\s*"#, options: .regularExpression) {
            let head = String(text[..<separator.lowerBound]).lowercased()
            if pageTypeLabelPrefixes.contains(where: { head.hasPrefix($0) }) {
                text = String(text[separator.upperBound...])
            }
        }
        // Three or more hyphens are a field separator in a composed body,
        // never punctuation a reader typed.
        text = text.replacingOccurrences(
            of: #"\s*-{3,}\s*"#, with: " ", options: .regularExpression
        )
        // Turn markers from the Story Page composer.
        text = text.replacingOccurrences(
            of: #"\bTurn\s+\d+\b[.:]?\s*"#, with: "", options: .regularExpression
        )
        text = text.trimmingCharacters(in: .whitespacesAndNewlines)
        // A body clipped upstream arrives ending mid-sentence. Quoting a
        // fragment as though it were a receipt is worse than quoting less, so
        // fall back to the last whole sentence.
        if text.hasSuffix("...") || text.hasSuffix("…") {
            let trimmed = text.hasSuffix("…")
                ? String(text.dropLast())
                : String(text.dropLast(3))
            if let stop = trimmed.lastIndex(where: { ".!?".contains($0) }) {
                text = String(trimmed[...stop])
            } else {
                text = trimmed
            }
        }
        return text.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private static func cleanSourceText(_ source: String) -> String {
        let normalized = strippedScaffolding(source)
            .components(separatedBy: .whitespacesAndNewlines)
            .filter { !$0.isEmpty }
            .joined(separator: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return BraidPromptBuilder.fallbackExcerpt(normalized, limit: 180)
    }

    private static func attributionText(_ source: String) -> String {
        source
            .replacingOccurrences(of: "«", with: "‹")
            .replacingOccurrences(of: "»", with: "›")
    }

    private static func sentence(_ source: String) -> String {
        let clean = source.trimmingCharacters(in: .whitespacesAndNewlines)
        guard let last = clean.last else { return clean }
        if ".!?…".contains(last) { return clean }
        // A quotation that already closed its own sentence must not collect a
        // second full stop outside the mark. The reader's own words end where
        // the reader ended them.
        if closingQuoteMarks.contains(last),
           let innerLast = clean.dropLast().last,
           ".!?…".contains(innerLast) {
            return clean
        }
        return clean + "."
    }

    private static let closingQuoteMarks: Set<Character> = ["»", "›", "”", "’", "\""]

    private static func rankedNouns(in text: String, preferredWords: Set<String>) -> [String] {
        #if canImport(NaturalLanguage)
        let nameTagger = NLTagger(tagSchemes: [.nameType])
        nameTagger.string = text
        var namedEntities = Set<String>()
        nameTagger.enumerateTags(
            in: text.startIndex..<text.endIndex,
            unit: .word,
            scheme: .nameType,
            options: [.omitWhitespace, .omitPunctuation]
        ) { tag, range in
            if tag == .personalName || tag == .organizationName || tag == .placeName {
                namedEntities.insert(String(text[range]).lowercased())
            }
            return true
        }

        let tagger = NLTagger(tagSchemes: [.lexicalClass])
        tagger.string = text
        var nouns: [String] = []
        var previousWord = ""
        var previousWordWasNoun = false
        tagger.enumerateTags(
            in: text.startIndex..<text.endIndex,
            unit: .word,
            scheme: .lexicalClass,
            options: [.omitWhitespace, .omitPunctuation, .joinNames]
        ) { tag, range in
            let word = String(text[range]).trimmingCharacters(in: .punctuationCharacters)
            let lowered = word.lowercased()
            // The on-device tagger does not know every irregular past tense: it
            // reads "You swam" as a pronoun followed by a noun. A word sitting
            // directly after a bare subject pronoun is the verb whatever the
            // tagger calls it, and enchanting it gives the page "the swam".
            let followsSubjectPronoun = subjectPronouns.contains(previousWord)
            // "A heron standing on the roof" reads as two nouns to the tagger,
            // and the second one is a participle describing the first. Taking
            // it made the night's anchor "the standing", which is not a thing
            // that can be kept, put down beside anything, or refuse to explain
            // itself. A compound head like "brass door" is the shape we do
            // want, so only the -ing form is refused.
            let isParticipleAfterNoun = previousWordWasNoun
                && !previousWord.isEmpty
                && isParticipleWord(lowered)
            previousWord = lowered
            defer { previousWordWasNoun = (tag == .noun) }
            guard tag == .noun, !followsSubjectPronoun, !isParticipleAfterNoun else { return true }
            // A Cast member is a person the tagger happens to read as a common
            // noun. They may act in the tale; they may never be its furniture.
            let isCastName = word.first?.isUppercase == true && castNameTokens.contains(lowered)
            guard word.count >= 3,
                  !isCastName,
                  !nounStopwords.contains(lowered),
                  !namedEntities.contains(lowered) else { return true }
            nouns.append(lowered)
            return true
        }
        let distinctNouns = unique(nouns)
        return distinctNouns.enumerated().sorted { lhs, rhs in
            rankNoun(lhs, before: rhs, preferredWords: preferredWords)
        }.map(\.element)
        #else
        // The app ships on Apple platforms, but the shared core is also parsed
        // by toolchains without NaturalLanguage. Keep a conservative lexical
        // fallback there and avoid capitalized names as magical object-subjects.
        let words = text
            .split { !$0.isLetter && !$0.isNumber && $0 != "'" }
            .map { String($0).lowercased() }
            .filter { word in
                word.count >= 3
                    && !nounStopwords.contains(word.lowercased())
                    && !lexicalFallbackStopwords.contains(word.lowercased())
            }
        let distinctWords = unique(words)
        return distinctWords.enumerated().sorted { lhs, rhs in
            rankNoun(lhs, before: rhs, preferredWords: preferredWords)
        }.map(\.element)
        #endif
    }

    /// Which noun the page should be about.
    ///
    /// This was `preferredWords` first and document order for everything else,
    /// which is how a calorie log anchored a night on "the beers" and a page
    /// whose own good line was "the mug is sulking about being empty" anchored
    /// on "the thursday": both merely appeared first. Order of appearance says
    /// nothing about what is worth writing about.
    ///
    /// One signal, deliberately: a noun that names no particular thing loses
    /// to one that does.
    ///
    /// Promoting nouns the reader had modified was tried and reverted. In "I
    /// mended the gate in the back room", "back room" is a modified noun and
    /// the gate is not, so every night in a month anchored on "room" and the
    /// month collapsed from six closing lines to two. A modifier says the
    /// reader distinguished something; it does not say the sentence is about
    /// it, and position still carries that better.
    private static func rankNoun(
        _ lhs: (offset: Int, element: String),
        before rhs: (offset: Int, element: String),
        preferredWords: Set<String>
    ) -> Bool {
        let left = lhs.element.lowercased()
        let right = rhs.element.lowercased()
        let leftPreferred = preferredWords.contains(left)
        let rightPreferred = preferredWords.contains(right)
        if leftPreferred != rightPreferred { return leftPreferred }
        let leftVague = vagueNouns.contains(left)
        let rightVague = vagueNouns.contains(right)
        if leftVague != rightVague { return rightVague }
        return lhs.offset < rhs.offset
    }

    /// Grammatically fine, dramatically empty. Not banned - a day that offers
    /// nothing else may still anchor on one - but any noun that names an
    /// actual thing outranks them.
    private static let vagueNouns: Set<String> = [
        "amount", "area", "bit", "case", "chance", "end", "form", "idea",
        "kind", "lot", "matter", "part", "piece", "place", "plan", "point",
        "problem", "reason", "result", "side", "sort", "stuff", "thing",
        "things", "type", "way", "ways",
        // Directions and particles. These tag as nouns and read as objects,
        // and they are never the thing: "the long way round past the bakery"
        // anchored a whole page on "the round".
        "back", "bottom", "front", "half", "middle", "rest", "round", "top",
        // Bare verbs the tagger reads as nouns at the head of a sentence -
        // "Saw the recorder in a charity shop window" produced a page titled
        // "The Saw Kept a Place" - and abstractions that name no object.
        "saw", "purpose", "sense", "hope", "plan", "point", "use", "need"
    ]

    /// Every word the Cast is called by, lowercased. The on-device tagger does
    /// not know that Wicker is a person, so without this the prose reaches for
    /// "the wicker" and turns one of the Book's own people into furniture.
    /// Two sources on purpose. `CastDossier` is compiled in, so the canonical
    /// Cast is known even where the bundled reference library is not built -
    /// the core package excludes that JSON, and Wicker lives only there.
    private static let castNameTokens: Set<String> = castNameTokens(
        from: Array(CastDossier.bios.keys)
            + BookReferenceCatalog.characterIllustrations.map(\.characterName)
    )

    /// Split roster names into the words a Cast member can be called by.
    ///
    /// The illustration catalog is not only people: it also plates talismans
    /// and rooms: "The Ember Seal", "The Great Hall", "The Stacks". Absorbing
    /// those wholesale put the word **the** into the set, and since almost
    /// every Labyrinth sentence opens with "The", the Book started calling its
    /// visitor "The": *"The Day Answered The."*
    ///
    /// Exposed rather than private because the bundled roster is excluded from
    /// the core package: the tests see nine fallback names where the app sees
    /// eighty-three, so the filter has to be checkable on its own.
    static func castNameTokens(from names: [String]) -> Set<String> {
        var tokens = Set<String>()
        for name in names {
            for part in name.split(whereSeparator: { !$0.isLetter }) {
                let token = String(part).lowercased()
                guard token.count >= 3, !castNameStopwords.contains(token) else { continue }
                tokens.insert(token)
            }
        }
        return tokens
    }

    /// Words that appear inside roster names without ever being what somebody
    /// is *called*: articles, joins, honorifics, and the generic nouns the
    /// Labyrinth uses to title its rooms and objects.
    ///
    /// Deliberately separate from `subjectForbiddenWords`. A door is a perfectly
    /// good thing for a page to be about: it is only a bad thing to mistake for
    /// a person's name because the catalog plates a room called The Dusk Thorn.
    private static let castNameStopwords: Set<String> = [
        "the", "and", "for", "from", "into", "with", "der", "van", "von",
        "dee", "dr", "mr", "mrs", "ms", "sir", "lady", "prof", "professor",
        "headmistress", "master", "mistress", "madam", "saint",
        "book", "books", "great", "outer", "inner", "hall", "halls", "room",
        "rooms", "stacks", "kitchen", "kitchens", "seal", "clasp", "glass",
        "cipher", "thorn", "burrow", "registry", "office", "library", "tower",
        "gate", "door", "house", "garden", "market", "school", "academy"
    ]

    /// Words that cannot be the subject of anything, whatever produced them.
    /// Grammar only, never an ordinary noun the reader might have written.
    private static let subjectForbiddenWords: Set<String> = [
        "the", "and", "but", "for", "from", "into", "with", "then", "than",
        "that", "this", "those", "these", "there", "here", "when", "while",
        "what", "which", "who", "whom", "was", "were", "been", "being",
        "dr", "mr", "mrs", "ms", "sir", "prof", "professor", "headmistress"
    ]

    /// A Cast name exactly as the receipt spelled it. The capital is the
    /// signal: a reader writing about water eddies has not summoned Eddies.
    private static func castName(in text: String) -> String? {
        let words = text.split { !$0.isLetter && $0 != "'" }.map(String.init)
        for (index, word) in words.enumerated() {
            guard word.first?.isUppercase == true,
                  castNameTokens.contains(word.lowercased()),
                  !castNameStopwords.contains(word.lowercased()) else { continue }
            // A capital at the very start of a receipt is grammar, not a name.
            // Anywhere else it is a real signal, which is how "Wicker refused…"
            // still reads as Wicker.
            if index == 0, isOrdinaryOpener(word) { continue }
            return word
        }
        return nil
    }

    /// Would this word be capitalized here anyway, purely because a sentence
    /// starts? True for ordinary vocabulary, false for something that only ever
    /// wears a capital.
    private static func isOrdinaryOpener(_ word: String) -> Bool {
        let lowered = word.lowercased()
        return castNameStopwords.contains(lowered)
            || nounStopwords.contains(lowered)
            || subjectPronouns.contains(lowered)
    }

    /// Nothing may become a subject that cannot be a thing. This is the last
    /// line of defence: the Cast set, the tagger and the noun ranking have all
    /// produced a function word at least once, and the cost of one slipping
    /// through is a page that reads "The Day Answered The."
    private static func isUsableSubject(_ candidate: String?) -> Bool {
        guard let candidate = candidate?.trimmingCharacters(in: .whitespacesAndNewlines),
              candidate.count >= 3 else { return false }
        let head = candidate.split(separator: " ").last.map(String.init)?.lowercased()
            ?? candidate.lowercased()
        return !subjectForbiddenWords.contains(head)
            && !subjectPronouns.contains(head)
            && !BraidRevisionVerifier.contentWords(in: head).isEmpty
    }

    private static func storySubject(_ atom: EvidenceAtom) -> String? {
        if let cast = castName(in: atom.text), isUsableSubject(cast) { return cast }
        #if canImport(NaturalLanguage)
        let tagger = NLTagger(tagSchemes: [.nameType])
        tagger.string = atom.text
        var actor: String?
        tagger.enumerateTags(
            in: atom.text.startIndex..<atom.text.endIndex,
            unit: .word,
            scheme: .nameType,
            options: [.omitWhitespace, .omitPunctuation, .joinNames]
        ) { tag, range in
            guard actor == nil else { return false }
            if tag == .personalName {
                actor = String(atom.text[range])
            }
            return actor == nil
        }
        if let actor { return actor }
        #endif
        return atom.nouns.first
    }

    private static func safeMagicSubject(_ atom: EvidenceAtom) -> String? {
        guard let candidate = atom.nouns.first(where: isSafeMagicNoun) else { return nil }
        let head = compoundHead(candidate, in: atom)
        return isSafeMagicNoun(head) ? head : candidate
    }

    private struct SubjectToken {
        var word: String
        var mayModify: Bool
        var isNoun: Bool
    }

    /// The modifier a receipt already put in front of its own noun. This is
    /// retrieval, not invention: every word it can return was supplied by the
    /// reader or by the Labyrinth page it came from.
    private static func qualifiedSubject(_ noun: String, in atom: EvidenceAtom) -> String? {
        let tokens = subjectTokens(in: atom.text)
        guard let index = tokens.firstIndex(where: {
            $0.word.caseInsensitiveCompare(noun) == .orderedSame
        }), index > 0 else { return nil }
        let modifier = tokens[index - 1]
        let lowered = modifier.word.lowercased()
        guard modifier.mayModify,
              lowered.count >= 3,
              lowered.caseInsensitiveCompare(noun) != .orderedSame,
              !subjectModifierStopwords.contains(lowered),
              !nounStopwords.contains(lowered) else { return nil }
        return "\(lowered) \(noun.lowercased())"
    }

    private static func subjectTokens(in text: String) -> [SubjectToken] {
        #if canImport(NaturalLanguage)
        let tagger = NLTagger(tagSchemes: [.lexicalClass])
        tagger.string = text
        var tokens: [SubjectToken] = []
        tagger.enumerateTags(
            in: text.startIndex..<text.endIndex,
            unit: .word,
            scheme: .lexicalClass,
            options: [.omitWhitespace, .omitPunctuation]
        ) { tag, range in
            let word = String(text[range]).trimmingCharacters(in: .punctuationCharacters)
            guard !word.isEmpty else { return true }
            // A noun adjunct modifies as readily as an adjective: the receipt
            // said "brass door", and "brass" is the half that distinguishes it.
            tokens.append(SubjectToken(
                word: word,
                mayModify: tag == .adjective || tag == .noun,
                isNoun: tag == .noun
            ))
            return true
        }
        return tokens
        #else
        // Without a tagger there is no way to tell a modifier from its head, so
        // claim neither and let the callers fall back to the supplied word.
        return text
            .split { !$0.isLetter && !$0.isNumber && $0 != "'" }
            .map { SubjectToken(word: String($0), mayModify: true, isNoun: false) }
        #endif
    }

    /// "The brass lamp" is a lamp, not a brass. The tagger reads left to right
    /// and hands back the modifier first, so walk to the head of the compound
    /// before enchanting anything: otherwise the page gives agency to an
    /// adjective the reader never meant as an object.
    private static func compoundHead(_ noun: String, in atom: EvidenceAtom) -> String {
        let tokens = subjectTokens(in: atom.text)
        guard var index = tokens.firstIndex(where: {
            $0.word.caseInsensitiveCompare(noun) == .orderedSame
        }) else { return noun }
        var head = noun
        while index + 1 < tokens.count, tokens[index + 1].isNoun {
            let next = tokens[index + 1].word.lowercased()
            guard next.count >= 3,
                  !nounStopwords.contains(next),
                  !isParticipleWord(next),
                  isSafeMagicNoun(next) else { break }
            head = next
            index += 1
        }
        return head
    }

    /// `-ing` words that name a thing rather than an action, so they are
    /// allowed to be the head of a compound: "the office building" keeps its
    /// building. Everything else ending in `-ing` after a noun is a participle
    /// describing it, and "a heron standing on the roof" must not hand the
    /// page an anchor called "the standing".
    private static let thingLikeIngWords: Set<String> = [
        "awning", "bedding", "binding", "blessing", "building", "ceiling",
        "clearing", "coating", "crossing", "drawing", "dressing", "evening",
        "fencing", "filling", "footing", "housing", "icing", "landing",
        "lining", "meeting", "morning", "offering", "opening", "padding",
        "painting", "parking", "railing", "reading", "ring", "roofing",
        "setting", "shilling", "sibling", "siding", "spring", "string",
        "thing", "wedding", "wiring"
    ]

    static func isParticipleWord(_ word: String) -> Bool {
        let lowered = word.lowercased()
        guard lowered.hasSuffix("ing"), lowered.count > 4 else { return false }
        return !thingLikeIngWords.contains(lowered)
    }

    /// Words that sit in front of a noun without telling the two apart.
    private static let subjectModifierStopwords: Set<String> = [
        "and", "another", "any", "both", "each", "every", "her", "his", "its",
        "one", "other", "our", "same", "some", "that", "the", "their", "these",
        "this", "those", "two", "very", "was", "were", "your"
    ]

    private static func isSafeMagicNoun(_ noun: String) -> Bool {
        let word = noun.lowercased().trimmingCharacters(in: .punctuationCharacters)
        let safetyForms = magicSafetyForms(for: word)
        guard !word.isEmpty,
              safetyForms.isDisjoint(with: unsafeMagicNouns),
              safetyForms.isDisjoint(with: nounStopwords) else { return false }
        return true
    }

    /// Keep the inflected word for the reader-facing sentence, but check the
    /// obvious English singulars as well. NaturalLanguage may hand us
    /// `mothers` or `patients`; neither becomes safe furniture merely because
    /// the denylist contains the lemma without its final s.
    private static func magicSafetyForms(for word: String) -> Set<String> {
        var forms = Set([word])
        if word.hasSuffix("ies"), word.count > 3 {
            forms.insert(String(word.dropLast(3)) + "y")
        }
        if word.hasSuffix("es"), word.count > 2 {
            forms.insert(String(word.dropLast(2)))
        }
        if word.hasSuffix("s"), word.count > 1, !word.hasSuffix("ss") {
            forms.insert(String(word.dropLast()))
        }
        return forms
    }

    private static let subjectPronouns: Set<String> = [
        "i", "you", "we", "they", "he", "she", "it"
    ]

    private static let nounStopwords: Set<String> = [
        "book", "choice", "day", "detail", "evening", "feeling", "fiction", "life",
        "meaning", "moment", "night", "page", "reader", "sentence", "story", "thing",
        "today", "tonight", "weather",
        // Indefinites. They tag as nouns and they name nobody and nothing:
        // "we stayed on for forty minutes about nothing at all" handed the
        // page an anchor called "the nothing".
        "anybody", "anyone", "anything", "everybody", "everyone", "everything",
        "nobody", "none", "nothing", "somebody", "someone", "something"
    ]

    /// These may be perfectly good subjects of the lived sentence, but they
    /// are not safe carriers for the authored object-agency grammar. The Book
    /// may keep a mother, diagnosis, or body exactly as written; it may not
    /// seize one by the scruff or make one into tonight's enchanted furniture.
    private static let unsafeMagicNouns: Set<String> = [
        "adult", "aunt", "baby", "boss", "boy", "brother", "child", "children",
        "boyfriend", "client", "colleague", "cousin", "coworker", "customer", "dad",
        "daughter", "doctor", "employee", "employer", "family", "father", "fiance",
        "fiancé", "friend", "girl", "girlfriend", "grandfather", "grandma",
        "grandmother", "grandpa", "guest", "husband", "kid", "lover", "man",
        "manager", "men", "mom", "mother", "neighbor", "nurse", "owner", "parent",
        "partner", "patient", "people", "person", "relative", "roommate", "sibling",
        "sister", "son", "spouse", "stranger", "student", "teacher", "therapist",
        "uncle", "visitor", "wife", "woman", "women", "worker",
        "abuse", "addiction", "anger", "anxiety", "assault", "cancer", "cause",
        "choice", "death", "diagnosis", "divorce", "dread", "fear", "feeling",
        "funeral", "grief", "guilt", "illness", "meaning", "memory", "miscarriage",
        "motive", "overdose", "panic", "pregnancy", "reason", "regret", "relationship",
        "shame", "suicide", "thought", "trauma", "tumor", "violence",
        "afternoon", "breakfast", "dinner", "hour", "lunch", "morning", "week", "year",
        "minute", "minutes", "second", "seconds", "hours", "days", "weeks", "years",
        // Calendar labels. This list already refused "week" and "year" and then
        // let "thursday" straight through, so a reader's Thursday became the
        // night's enchanted furniture: "I took the thursday with the dirt still
        // in the sentence", "the thursday kept watch and would not look away".
        // A weekday is when a thing happened, never the thing.
        // "mum" was missing beside "mom" and "mother", so a British reader's
        // mother became the night's enchanted furniture: "The mum arrived
        // before I knew your corners. It bit the label."
        "mum", "mam", "nan", "nana", "granny", "grandad", "granddad",
        "monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday",
        "january", "february", "march", "april", "may", "june", "july", "august",
        "september", "october", "november", "december",
        "midnight", "midday", "noon", "tomorrow", "weekday", "weekend", "yesterday",
        "arm", "blood", "body", "brain", "chest", "eye", "eyes", "face", "finger",
        "fingers", "foot", "feet", "hand", "hands", "head", "heart", "leg", "mouth",
        "skin", "teeth", "throat"
    ]

    private static let lexicalFallbackStopwords: Set<String> = [
        "after", "again", "and", "before", "beside", "both", "called", "carried",
        "crossed", "folded", "forgot", "gathered", "had", "into", "left", "made",
        "my", "put", "refused", "repaired", "said", "sat", "the", "then",
        "tightened", "took", "under", "waited", "washed", "went", "were", "while",
        "with", "wrote", "your"
    ]

    /// English singulars that end in a bare `s`. "The bus were there" is a
    /// worse sentence than the one it would be fixing.
    private static let singularLookingPlurals: Set<String> = [
        "atlas", "bonus", "bus", "campus", "canvas", "chaos", "chorus", "circus",
        "compass", "focus", "gas", "glass", "grass", "iris", "lens", "moss",
        "news", "series", "species", "status", "surplus", "virus"
    ]

    /// Plurals that do not end in `s` and would otherwise read as singular.
    private static let irregularPlurals: Set<String> = [
        "children", "feet", "geese", "men", "mice", "people", "teeth", "women"
    ]

    /// Whether the anchor phrase takes a plural verb. The templates used to
    /// hardcode the singular, so a night anchored on "the beers" produced
    /// "the beers was there at the end and is pretending not to have helped".
    static func anchorIsPlural(_ subject: String) -> Bool {
        let head = (subject.split(separator: " ").last.map(String.init) ?? subject)
            .lowercased()
            .trimmingCharacters(in: .punctuationCharacters)
        guard head.count > 2 else { return false }
        if irregularPlurals.contains(head) { return true }
        if singularLookingPlurals.contains(head) { return false }
        guard head.hasSuffix("s"),
              !head.hasSuffix("ss"),
              !head.hasSuffix("us"),
              !head.hasSuffix("is") else { return false }
        return true
    }

    /// The verb form the anchor actually takes.
    static func agreeing(
        _ singular: String, _ plural: String, with subject: String
    ) -> String {
        anchorIsPlural(subject) ? plural : singular
    }

    private static func articleSubject(_ subject: String) -> String {
        let clean = subject.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !clean.isEmpty else { return "the day" }
        let alreadyDetermined = [
            "the ", "a ", "an ", "your ", "my ", "this ", "that ", "these ", "those "
        ].contains { clean.lowercased().hasPrefix($0) }
        if alreadyDetermined { return lowercasedFirst(clean) }
        if clean.first?.isUppercase == true { return clean }
        return "the \(clean.lowercased())"
    }

    private static func titleWords(_ subject: String) -> String {
        subject
            .split { !$0.isLetter && !$0.isNumber }
            .map { String($0).capitalized }
            .joined(separator: " ")
            .nonEmpty ?? "Crooked Sentence"
    }

    private static func capitalized(_ text: String) -> String {
        guard let first = text.first else { return text }
        return first.uppercased() + String(text.dropFirst())
    }

    private static func lowercasedFirst(_ text: String) -> String {
        guard let first = text.first else { return text }
        return first.lowercased() + String(text.dropFirst())
    }

    private static func unique(_ values: [String]) -> [String] {
        var seen = Set<String>()
        return values.filter { seen.insert($0).inserted }
    }

    private static func candidateIndex(in composition: BraidComposition) -> Int {
        guard let tag = composition.tags.first(where: { $0.hasPrefix("braid-candidate:") }),
              let value = Int(tag.dropFirst("braid-candidate:".count)) else { return Int.max }
        return value
    }

    private static func stableHash(_ value: String) -> UInt64 {
        var hash: UInt64 = 1_469_598_103_934_665_603
        for byte in value.utf8 {
            hash ^= UInt64(byte)
            hash = hash &* 1_099_511_628_211
        }
        return hash
    }
}

struct BraidPageDetails: Equatable {
    static let promptVersion = "book-of-you-braid-v6-continuity-residue"
    static let headerPrefix = "Tags:"
    static let sourcePagePrefix = "braid-source-page:"

    var title: String
    var body: String
    var themeName: String?
    var chapterName: String?
    var residue: BookOfYouResidue?
    /// The morning callback naming the threads last night's ember promised, shown
    /// as a small kicker above the braid so the reveal pays off the evening tease.
    var promiseEcho: String?
    /// A rare backwards-only question, shown *below* the braid's ritual ending
    /// so it never competes with "The Book kept the page:" for the last word.
    var backwardQuestion: String?

    static let promiseEchoTagPrefix = "promise-echo:"
    static let backwardQuestionTagPrefix = "backward-question:"

    struct HeaderContext: Equatable {
        var timeLabel: String
        var locationLabel: String
        var weatherWord: String
        var moonPhaseName: String
        var fuelLabel: String
        var innerWeatherLabel: String

        var displayLine: String {
            "\(BraidPageDetails.headerPrefix) Time \(timeLabel) · Location \(locationLabel) · Weather \(weatherWord) · Moon \(moonPhaseName) · Fuel \(fuelLabel) · Inner weather \(innerWeatherLabel)"
        }

        var metadataTags: [String] {
            [
                "braid-time:\(timeLabel)",
                "braid-location:\(locationLabel)",
                "braid-weather:\(weatherWord)",
                "braid-moon:\(moonPhaseName)",
                "braid-fuel:\(fuelLabel)",
                "braid-inner-weather:\(innerWeatherLabel)"
            ]
        }

        static func make(for page: BookPage, day: BookDay, inputs: BookSourceInputs, calendar: Calendar = .current) -> HeaderContext {
            let formatter = DateFormatter()
            formatter.calendar = calendar
            formatter.timeZone = calendar.timeZone
            formatter.dateFormat = "h:mm a"

            return HeaderContext(
                timeLabel: formatter.string(from: page.createdAt),
                locationLabel: locationLabel(from: inputs),
                weatherWord: weatherWord(from: inputs, day: day),
                moonPhaseName: MoonPhaseCalendar.phase(on: page.createdAt).name,
                fuelLabel: fuelLabel(from: inputs, day: day),
                innerWeatherLabel: innerWeatherLabel(from: inputs, day: day)
            )
        }

        private static func locationLabel(from inputs: BookSourceInputs) -> String {
            if let currentLocationLabel = inputs.currentLocationLabel?.nonEmpty {
                return currentLocationLabel
            }
            if let anchorName = inputs.nearbyAnchor?.anchor.name.nonEmpty {
                return anchorName
            }
            return "Current place"
        }

        private static func weatherWord(from inputs: BookSourceInputs, day: BookDay) -> String {
            if let selector = inputs.enchantedWeather?.selector.nonEmpty {
                return selector
            }
            guard let phrase = inputs.weather?.phrase.nonEmpty else {
                return day.capturedPages
                    .sorted(by: { $0.createdAt > $1.createdAt })
                    .compactMap(\.context)
                    .flatMap(\.weatherTags)
                    .first?.nonEmpty ?? "not recorded"
            }
            let lowered = phrase.lowercased()
            let candidates = [
                "thunder", "storm", "snow", "sleet", "ice", "rain", "drizzle", "shower",
                "fog", "mist", "haze", "wind", "breeze", "cloud", "overcast", "clear",
                "sun", "bright", "cold", "warm", "humid"
            ]
            return candidates.first(where: { lowered.contains($0) }) ?? phrase
                .split { !$0.isLetter }
                .first
                .map { String($0).lowercased() } ?? "not recorded"
        }

        private static func fuelLabel(from inputs: BookSourceInputs, day: BookDay) -> String {
            if let latestFuel = inputs.facultyEntries
                .filter({ $0.kind == .fuel && $0.dayID == day.id })
                .sorted(by: { $0.createdAt > $1.createdAt })
                .first,
               let nutrition = nutritionLine(from: latestFuel.rawText) {
                return nutrition
            }

            let nutritionMetrics = nutritionMetrics(from: inputs.body?.metrics ?? [])
            if !nutritionMetrics.isEmpty {
                return nutritionMetrics.joined(separator: ", ")
            }

            return "not logged"
        }

        private static func innerWeatherLabel(from inputs: BookSourceInputs, day: BookDay) -> String {
            if let latestEntry = inputs.facultyEntries
                .filter({ $0.kind == .innerWeather && $0.dayID == day.id })
                .sorted(by: { $0.createdAt > $1.createdAt })
                .first {
                return clippedHeaderValue(latestEntry.rawText)
            }

            if let latestMood = day.pages
                .filter({ $0.type == .mood })
                .sorted(by: { $0.createdAt > $1.createdAt })
                .first,
               let text = latestMood.userInput.nonEmpty ?? latestMood.playerReply.nonEmpty {
                return clippedHeaderValue(text)
            }

            return "not logged"
        }

        private static func nutritionLine(from rawText: String) -> String? {
            rawText
                .components(separatedBy: .newlines)
                .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                .first { line in
                    let lower = line.lowercased()
                    return lower.contains("kcal") || lower.contains("protein") || lower.contains("carb")
                }
                .map { line in
                    line
                        .replacingOccurrences(of: " (Vellum's rough arithmetic)", with: "")
                        .replacingOccurrences(of: "Vellum's rough arithmetic", with: "")
                        .replacingOccurrences(of: "Vellum's Ledger: ", with: "")
                        .trimmingCharacters(in: .whitespacesAndNewlines)
                }
                .flatMap(\.nonEmpty)
        }

        private static func nutritionMetrics(from metrics: [BodySourceSignal.Metric]) -> [String] {
            let ids = Set([
                "dietaryEnergyConsumed",
                "dietaryProtein",
                "dietaryCarbohydrates",
                "dietaryFatTotal",
                "dietaryFatSaturated",
                "dietarySugar",
                "dietaryFiber",
                "dietarySodium",
                "dietaryWater"
            ])
            return metrics
                .filter { metric in
                    ids.contains(metric.id) || metric.label.localizedCaseInsensitiveContains("Dietary")
                }
                .map(\.displayText)
                .filter { !$0.isEmpty }
        }

        private static func clippedHeaderValue(_ value: String, limit: Int = 80) -> String {
            let normalized = value
                .components(separatedBy: .newlines)
                .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                .filter { !$0.isEmpty }
                .first ?? value.trimmingCharacters(in: .whitespacesAndNewlines)
            guard normalized.count > limit else { return normalized }
            let end = normalized.index(normalized.startIndex, offsetBy: limit)
            return normalized[..<end].trimmingCharacters(in: .whitespacesAndNewlines) + "..."
        }
    }

    static func details(for page: BookPage) -> BraidPageDetails {
        let text = page.userInput.trimmingCharacters(in: .whitespacesAndNewlines)
        let parsed = parseTitleAndBody(from: text)
        let fallbackTitle = page.promptText
            .replacingOccurrences(of: "Book of You:", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return BraidPageDetails(
            title: parsed.title ?? fallbackTitle.nonEmpty ?? "Book of You",
            body: parsed.body.nonEmpty ?? text,
            themeName: tagValue(prefix: "theme:", in: page.tags),
            chapterName: tagValue(prefix: "chapter:", in: page.tags),
            residue: BookOfYouResidue.fromTags(in: page),
            promiseEcho: tagValue(prefix: promiseEchoTagPrefix, in: page.tags),
            backwardQuestion: tagValue(prefix: backwardQuestionTagPrefix, in: page.tags)
        )
    }

    /// Stamps the evening ember's kept-promise callback onto a freshly braided
    /// page (via a value-carrying tag, like `theme:`/`chapter:`). A no-op when the
    /// day had no promised threads.
    static func withPromiseEcho(_ page: BookPage, line: String?) -> BookPage {
        guard let line = line?.nonEmpty else { return page }
        var updated = page
        var tags = Set(updated.tags)
        tags = tags.filter { !$0.hasPrefix(promiseEchoTagPrefix) }
        tags.insert("\(promiseEchoTagPrefix)\(line)")
        updated.tags = tags.sorted()
        return updated
    }

    static func withBackwardQuestion(_ page: BookPage, question: BraidBackwardQuestion.Question?) -> BookPage {
        guard let question, question.line.nonEmpty != nil else { return page }
        var updated = page
        var tags = Set(updated.tags)
        tags = tags.filter { !$0.hasPrefix(backwardQuestionTagPrefix) }
        tags.insert("\(backwardQuestionTagPrefix)\(question.line)")
        updated.tags = tags.sorted()
        return updated
    }

    static func withSourcePages(_ page: BookPage, pageIDs: Set<String>) -> BookPage {
        var updated = page
        var tags = Set(updated.tags.filter { !$0.hasPrefix(sourcePagePrefix) })
        for pageID in pageIDs where !pageID.isEmpty {
            tags.insert(sourcePagePrefix + pageID)
        }
        updated.tags = tags.sorted()
        return updated
    }

    static func sourcePageIDs(in page: BookPage) -> Set<String> {
        Set(page.tags.compactMap { tag in
            guard tag.hasPrefix(sourcePagePrefix) else { return nil }
            return String(tag.dropFirst(sourcePagePrefix.count)).nonEmpty
        })
    }

    static func annotated(_ page: BookPage, context: BraidPromptBuilder.Context, headerContext: HeaderContext? = nil) -> BookPage {
        var updated = page
        let details = details(for: page)
        if details.title != "Book of You" {
            updated.promptText = "Book of You: \(details.title)"
        }
        updated.promptVersion = promptVersion
        if let headerContext {
            updated.userInput = addingHeader(headerContext.displayLine, to: updated.userInput)
        }

        var tags = Set(updated.tags)
        tags.insert("braid-v2")
        if context.storyScore != nil {
            tags.insert("braid-story-score-v3")
        }
        if let headerContext {
            tags = tags.filter {
                !$0.hasPrefix("braid-time:")
                    && !$0.hasPrefix("braid-location:")
                    && !$0.hasPrefix("braid-weather:")
                    && !$0.hasPrefix("braid-moon:")
                    && !$0.hasPrefix("braid-fuel:")
                    && !$0.hasPrefix("braid-inner-weather:")
            }
            headerContext.metadataTags.forEach { tags.insert($0) }
        }
        if let theme = context.theme?.name, !theme.isEmpty {
            tags.insert("theme:\(theme)")
        }
        if let chapter = context.chapter?.name, !chapter.isEmpty {
            tags.insert("chapter:\(chapter)")
        }
        if !context.recentBraids.isEmpty {
            tags.insert("yesterday-echo")
        }
        let residue = BookOfYouResidue.extract(from: updated, context: context)
        tags = residue.stamping(into: tags)
        updated.tags = tags.sorted()
        return updated
    }

    private static func parseTitleAndBody(from text: String) -> (title: String?, body: String) {
        let paragraphs = text
            .replacingOccurrences(of: "\r\n", with: "\n")
            .components(separatedBy: "\n")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        let header = paragraphs.first(where: isHeaderLine)
        let titleCandidates = paragraphs.filter { !isHeaderLine($0) }
        guard let first = titleCandidates.first, looksLikeTitle(first) else {
            return (nil, text)
        }
        let bodyParagraphs = paragraphs.filter { $0 != first }
        let body = bodyParagraphs.joined(separator: "\n\n")
        if body.isEmpty, let header {
            return (first, header)
        }
        return (first, body)
    }

    private static func addingHeader(_ header: String, to text: String) -> String {
        let paragraphs = text
            .replacingOccurrences(of: "\r\n", with: "\n")
            .components(separatedBy: "\n")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty && !isHeaderLine($0) }
        return ([header] + paragraphs).joined(separator: "\n\n")
    }

    private static func isHeaderLine(_ value: String) -> Bool {
        value.hasPrefix(headerPrefix)
    }

    private static func looksLikeTitle(_ value: String) -> Bool {
        guard !value.hasPrefix("The Book kept the page:"),
              !value.localizedCaseInsensitiveContains("Title:"),
              value.count <= 64 else {
            return false
        }
        if value.contains(".") || value.contains("?") || value.contains("!") || value.contains(":") {
            return false
        }
        let words = value.split { $0.isWhitespace || $0 == "," || $0 == ";" }
        return (2...7).contains(words.count)
    }

    private static func tagValue(prefix: String, in tags: [String]) -> String? {
        tags.first { $0.hasPrefix(prefix) }
            .map { String($0.dropFirst(prefix.count)) }
            .flatMap(\.nonEmpty)
    }
}

/// Stable handles left behind by a Book of You page so weekly, monthly, and
/// annual bindings can read the braid as memory instead of plain text. The tags
/// are deliberately compact because `BookPage` persists tags, not page metadata.
struct BookOfYouResidue: Equatable {
    static let markerTag = "braid-residue"
    static let titlePrefix = "residue-title:"
    static let spinePrefix = "residue-spine:"
    static let keptPrefix = "residue-kept:"
    static let motifPrefix = "residue-motif:"
    static let questionPrefix = "residue-question:"
    static let callbackPrefix = "residue-callback:"
    static let semanticEchoPrefix = "residue-echo:"
    static let arcIDPrefix = "residue-arc-id:"
    static let arcMovementPrefix = "residue-arc-movement:"
    static let arcDeltaPrefix = "residue-arc-delta:"
    static let arcEvidencePrefix = "residue-arc-evidence:"
    static let arcFictionPrefix = "residue-arc-fiction:"
    static let relationalConnectionPrefix = "residue-relational:"
    static let storyFormPrefix = "residue-story-form:"
    static let rutInfluencePrefix = "residue-rut-influence:"
    static let narrativeRegisterPrefix = "residue-register:"
    static let rutEvidencePrefix = "residue-rut-evidence:"
    static let continuityKindPrefix = "residue-continuity-kind:"
    static let continuitySourcePrefix = "residue-continuity-source:"
    static let continuityReasonPrefix = "residue-continuity-reason:"
    static let fictionThreadPrefix = "residue-fiction-thread:"
    static let fictionStatePrefix = "residue-fiction-state:"
    static let fictionAnchorPrefix = "residue-fiction-anchor:"
    static let fictionLastAnchorPrefix = "residue-fiction-last-anchor:"

    var title: String
    var spineLine: String
    var keptLine: String
    var motifs: [String]
    var semanticEchoIDs: [String]
    var openedQuestion: String?
    var callbackCandidate: String?
    var arcID: String? = nil
    var arcMovement: BraidPromptBuilder.ArcMovement? = nil
    var arcDelta: String? = nil
    var arcEvidencePageIDs: [String] = []
    var arcFictionChoicePageIDs: [String] = []
    var relationalConnectionIDs: [String] = []
    var storyForm: BraidPromptBuilder.StoryForm? = nil
    var rutInfluence: BraidPromptBuilder.RutInfluence? = nil
    var narrativeRegister: BraidPromptBuilder.NarrativeRegister? = nil
    var rutEvidencePageIDs: [String] = []
    var continuityKind: BraidPromptBuilder.ContinuityKind? = nil
    var continuitySourceBraidPageID: String? = nil
    var continuityReason: String? = nil
    var fictionThreadID: String? = nil
    var fictionThreadState: BraidPromptBuilder.FictionThreadState? = nil
    var fictionThreadAnchor: String? = nil
    var fictionThreadLastAnchor: String? = nil

    static func extract(from page: BookPage, context: BraidPromptBuilder.Context = .empty) -> BookOfYouResidue {
        let details = BraidPageDetails.details(for: page)
        let title = clipped(details.title, limit: 64)
        let paragraphs = normalizedParagraphs(from: details.body)
        let keptLine = paragraphs
            .flatMap(sentences)
            .last { $0.hasPrefix("The Book kept the page:") }
            .map { clipped($0, limit: 140) }
            ?? clipped(paragraphs.last ?? details.body, limit: 140)
        // What the scene plan decided, where it decided it.
        //
        // Everything below this used to be inferred by re-reading the finished
        // page, which is guesswork about a question the deciding layer had
        // already answered: the spine was whichever sentence happened to come
        // first, and what the night left open was found by hunting for a
        // question mark - which held-open material almost never carries,
        // because it is quoted exactly as the reader wrote it.
        func planFact(_ prefix: String) -> String? {
            page.tags.first(where: { $0.hasPrefix(prefix) })
                .map { String($0.dropFirst(prefix.count)) }?
                .nonEmpty
        }
        let spineLine = planFact("braid-plan-spine:").map { clipped($0, limit: 140) }
            ?? paragraphs
                .flatMap(sentences)
                .first { !$0.hasPrefix("The Book kept the page:") }
                .map { clipped($0, limit: 140) }
            ?? keptLine
        // Deliberately not filled from the plan. What a night held open is
        // carried forward as an evidence id only - never as text - so a binding
        // that wants the thread resolves it against the reader's own archive
        // instead of quoting their worst week back at them from a tag.
        let question = paragraphs
                .flatMap(sentences)
                .last { $0.hasSuffix("?") }
                .map { clipped($0, limit: 120) }
        let motifs = motifWords(in: "\(title) \(details.body)", adding: context.theme?.motifs ?? [])
        // A thing that came back after six days is the best callback a binding
        // could ask for, and the plan found it deterministically. The prose
        // heuristic only ever had the closing line to work from.
        let callback = planFact("braid-plan-return:")
            .map { value -> String in
                let parts = value.split(separator: "|", maxSplits: 1)
                return clipped(String(parts.count == 2 ? parts[1] : parts[0]), limit: 120)
            }
            ?? planFact("braid-plan-crossing:").map { clipped($0, limit: 120) }
            ?? callback(from: keptLine, fallbackTitle: title)
        let echoes = page.tags
            .compactMap { tag -> String? in
                tag.hasPrefix(semanticEchoPrefix) ? String(tag.dropFirst(semanticEchoPrefix.count)) : nil
            }
        let reading = context.taleReading ?? context.storyScore?.taleReading
        let persistedContinuity = context.continuityBeat.flatMap { beat in
            BraidOutputAudit.carriesContinuity(beat, in: page.userInput) ? beat : nil
        }
        return BookOfYouResidue(
            title: title,
            spineLine: spineLine,
            keptLine: keptLine,
            motifs: motifs,
            semanticEchoIDs: Array(Set(echoes + context.semanticEchoSourceIDs)).sorted(),
            openedQuestion: question,
            callbackCandidate: callback,
            arcID: context.storyScore?.arc?.id,
            arcMovement: context.storyScore?.arc?.movement,
            arcDelta: context.storyScore?.arc.map { clipped($0.tonightDelta, limit: 180) },
            arcEvidencePageIDs: context.storyScore?.arc?.evidencePageIDs ?? [],
            arcFictionChoicePageIDs: context.storyScore?.arc?.fictionChoicePageIDs ?? [],
            relationalConnectionIDs: context.storyScore?.arc?.relationalConnectionIDs
                ?? context.storyScore?.relationalLens.map { [$0.connectionID, $0.observationKey] }
                ?? [],
            storyForm: reading?.storyForm,
            rutInfluence: reading?.rutInfluence,
            narrativeRegister: reading?.narrativeRegister,
            rutEvidencePageIDs: reading?.rutEvidencePageIDs ?? [],
            continuityKind: persistedContinuity?.kind,
            continuitySourceBraidPageID: persistedContinuity?.sourceBraidPageID,
            continuityReason: persistedContinuity?.reason,
            fictionThreadID: persistedContinuity?.threadID,
            fictionThreadState: persistedContinuity?.fictionState,
            fictionThreadAnchor: persistedContinuity.flatMap { beat in
                guard beat.fictionState != nil else { return nil }
                return beat.priorAnchor?.nonEmpty ?? beat.currentAnchor.nonEmpty
            },
            fictionThreadLastAnchor: persistedContinuity.flatMap { beat in
                guard beat.fictionState != nil else { return nil }
                return beat.currentAnchor.nonEmpty
            }
        )
    }

    static func fromTags(in page: BookPage) -> BookOfYouResidue? {
        guard page.tags.contains(markerTag) else { return nil }
        let fallbackTitle = page.promptText
            .replacingOccurrences(of: "Book of You:", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        return BookOfYouResidue(
            title: tagValue(titlePrefix, in: page.tags) ?? fallbackTitle.nonEmpty ?? "Book of You",
            spineLine: tagValue(spinePrefix, in: page.tags) ?? "",
            keptLine: tagValue(keptPrefix, in: page.tags) ?? "",
            motifs: values(motifPrefix, in: page.tags),
            semanticEchoIDs: values(semanticEchoPrefix, in: page.tags),
            openedQuestion: tagValue(questionPrefix, in: page.tags),
            callbackCandidate: tagValue(callbackPrefix, in: page.tags),
            arcID: tagValue(arcIDPrefix, in: page.tags),
            arcMovement: tagValue(arcMovementPrefix, in: page.tags)
                .flatMap(BraidPromptBuilder.ArcMovement.init(rawValue:)),
            arcDelta: tagValue(arcDeltaPrefix, in: page.tags),
            arcEvidencePageIDs: values(arcEvidencePrefix, in: page.tags),
            arcFictionChoicePageIDs: values(arcFictionPrefix, in: page.tags),
            relationalConnectionIDs: values(relationalConnectionPrefix, in: page.tags),
            storyForm: tagValue(storyFormPrefix, in: page.tags)
                .flatMap(BraidPromptBuilder.StoryForm.init(rawValue:)),
            rutInfluence: tagValue(rutInfluencePrefix, in: page.tags)
                .flatMap(BraidPromptBuilder.RutInfluence.init(rawValue:)),
            narrativeRegister: tagValue(narrativeRegisterPrefix, in: page.tags)
                .flatMap(BraidPromptBuilder.NarrativeRegister.init(rawValue:)),
            rutEvidencePageIDs: values(rutEvidencePrefix, in: page.tags),
            continuityKind: tagValue(continuityKindPrefix, in: page.tags)
                .flatMap(BraidPromptBuilder.ContinuityKind.init(rawValue:)),
            continuitySourceBraidPageID: tagValue(continuitySourcePrefix, in: page.tags),
            continuityReason: tagValue(continuityReasonPrefix, in: page.tags),
            fictionThreadID: tagValue(fictionThreadPrefix, in: page.tags),
            fictionThreadState: tagValue(fictionStatePrefix, in: page.tags)
                .flatMap(BraidPromptBuilder.FictionThreadState.init(rawValue:)),
            fictionThreadAnchor: tagValue(fictionAnchorPrefix, in: page.tags),
            fictionThreadLastAnchor: tagValue(fictionLastAnchorPrefix, in: page.tags)
        )
    }

    func stamping(into tags: Set<String>) -> Set<String> {
        var stamped = tags.filter { tag in
            !tag.hasPrefix(Self.titlePrefix)
                && !tag.hasPrefix(Self.spinePrefix)
                && !tag.hasPrefix(Self.keptPrefix)
                && !tag.hasPrefix(Self.motifPrefix)
                && !tag.hasPrefix(Self.questionPrefix)
                && !tag.hasPrefix(Self.callbackPrefix)
                && !tag.hasPrefix(Self.semanticEchoPrefix)
                && !tag.hasPrefix(Self.arcIDPrefix)
                && !tag.hasPrefix(Self.arcMovementPrefix)
                && !tag.hasPrefix(Self.arcDeltaPrefix)
                && !tag.hasPrefix(Self.arcEvidencePrefix)
                && !tag.hasPrefix(Self.arcFictionPrefix)
                && !tag.hasPrefix(Self.relationalConnectionPrefix)
                && !tag.hasPrefix(Self.storyFormPrefix)
                && !tag.hasPrefix(Self.rutInfluencePrefix)
                && !tag.hasPrefix(Self.narrativeRegisterPrefix)
                && !tag.hasPrefix(Self.rutEvidencePrefix)
                && !tag.hasPrefix(Self.continuityKindPrefix)
                && !tag.hasPrefix(Self.continuitySourcePrefix)
                && !tag.hasPrefix(Self.continuityReasonPrefix)
                && !tag.hasPrefix(Self.fictionThreadPrefix)
                && !tag.hasPrefix(Self.fictionStatePrefix)
                && !tag.hasPrefix(Self.fictionAnchorPrefix)
                && !tag.hasPrefix(Self.fictionLastAnchorPrefix)
        }
        stamped.insert(Self.markerTag)
        stamped.insert(Self.titlePrefix + title)
        if !spineLine.isEmpty { stamped.insert(Self.spinePrefix + spineLine) }
        if !keptLine.isEmpty { stamped.insert(Self.keptPrefix + keptLine) }
        for motif in motifs.prefix(6) {
            stamped.insert(Self.motifPrefix + motif)
        }
        if let openedQuestion, !openedQuestion.isEmpty {
            stamped.insert(Self.questionPrefix + openedQuestion)
        }
        if let callbackCandidate, !callbackCandidate.isEmpty {
            stamped.insert(Self.callbackPrefix + callbackCandidate)
        }
        for echoID in semanticEchoIDs.prefix(6) where !echoID.isEmpty {
            stamped.insert(Self.semanticEchoPrefix + echoID)
        }
        if let arcID, !arcID.isEmpty { stamped.insert(Self.arcIDPrefix + arcID) }
        if let arcMovement { stamped.insert(Self.arcMovementPrefix + arcMovement.rawValue) }
        if let arcDelta, !arcDelta.isEmpty { stamped.insert(Self.arcDeltaPrefix + arcDelta) }
        for pageID in arcEvidencePageIDs.prefix(8) where !pageID.isEmpty {
            stamped.insert(Self.arcEvidencePrefix + pageID)
        }
        for pageID in arcFictionChoicePageIDs.prefix(4) where !pageID.isEmpty {
            stamped.insert(Self.arcFictionPrefix + pageID)
        }
        for connectionID in relationalConnectionIDs.prefix(4) where !connectionID.isEmpty {
            stamped.insert(Self.relationalConnectionPrefix + connectionID)
        }
        if let storyForm {
            stamped.insert(Self.storyFormPrefix + storyForm.rawValue)
        }
        if let rutInfluence {
            stamped.insert(Self.rutInfluencePrefix + rutInfluence.rawValue)
        }
        if let narrativeRegister {
            stamped.insert(Self.narrativeRegisterPrefix + narrativeRegister.rawValue)
        }
        for pageID in rutEvidencePageIDs.prefix(8) where !pageID.isEmpty {
            stamped.insert(Self.rutEvidencePrefix + pageID)
        }
        if let continuityKind {
            stamped.insert(Self.continuityKindPrefix + continuityKind.rawValue)
        }
        if let continuitySourceBraidPageID, !continuitySourceBraidPageID.isEmpty {
            stamped.insert(Self.continuitySourcePrefix + continuitySourceBraidPageID)
        }
        if let continuityReason, !continuityReason.isEmpty {
            stamped.insert(Self.continuityReasonPrefix + continuityReason)
        }
        if let fictionThreadID, !fictionThreadID.isEmpty {
            stamped.insert(Self.fictionThreadPrefix + fictionThreadID)
        }
        if let fictionThreadState {
            stamped.insert(Self.fictionStatePrefix + fictionThreadState.rawValue)
        }
        if let fictionThreadAnchor, !fictionThreadAnchor.isEmpty {
            stamped.insert(Self.fictionAnchorPrefix + fictionThreadAnchor)
        }
        if let fictionThreadLastAnchor, !fictionThreadLastAnchor.isEmpty {
            stamped.insert(Self.fictionLastAnchorPrefix + fictionThreadLastAnchor)
        }
        return stamped
    }

    private static func tagValue(_ prefix: String, in tags: [String]) -> String? {
        tags.first { $0.hasPrefix(prefix) }
            .map { String($0.dropFirst(prefix.count)) }
            .flatMap(\.nonEmpty)
    }

    private static func values(_ prefix: String, in tags: [String]) -> [String] {
        tags
            .compactMap { tag in
                tag.hasPrefix(prefix) ? String(tag.dropFirst(prefix.count)).nonEmpty : nil
            }
            .sorted()
    }

    private static func normalizedParagraphs(from text: String) -> [String] {
        text
            .replacingOccurrences(of: "\r\n", with: "\n")
            .components(separatedBy: "\n")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
    }

    private static func sentences(in paragraph: String) -> [String] {
        var out: [String] = []
        var current = ""
        for character in paragraph {
            current.append(character)
            if ".!?".contains(character) {
                let trimmed = current.trimmingCharacters(in: .whitespacesAndNewlines)
                if !trimmed.isEmpty { out.append(trimmed) }
                current = ""
            }
        }
        let trimmed = current.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmed.isEmpty { out.append(trimmed) }
        return out
    }

    private static func motifWords(in text: String, adding themeMotifs: [String]) -> [String] {
        let lexicon: [String] = [
            "rain", "snow", "fog", "wind", "storm", "cloud", "sun", "moon",
            "window", "door", "threshold", "kitchen", "room", "porch", "harbor",
            "coffee", "tea", "cup", "mug", "lamp", "key", "book", "page",
            "letter", "photo", "garden", "walk", "road", "water", "hand",
            "sleep", "hunger", "music", "light", "shadow"
        ]
        let lower = text.lowercased()
        let words = Set(lower.split { !$0.isLetter }.map(String.init))
        let theme = themeMotifs
            .map { $0.lowercased().trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        let candidates = theme + lexicon
        var seen: Set<String> = []
        var motifs: [String] = []
        for candidate in candidates where !seen.contains(candidate) {
            if words.contains(candidate) || lower.contains(candidate) {
                seen.insert(candidate)
                motifs.append(candidate)
            }
            if motifs.count == 6 { break }
        }
        return motifs
    }

    private static func callback(from keptLine: String, fallbackTitle: String) -> String? {
        let raw = keptLine
            .replacingOccurrences(of: "The Book kept the page:", with: "")
            .trimmingCharacters(in: CharacterSet.whitespacesAndNewlines.union(CharacterSet(charactersIn: ".:")))
        return clipped(raw.nonEmpty ?? fallbackTitle, limit: 96).nonEmpty
    }

    private static func clipped(_ value: String, limit: Int) -> String {
        let normalized = value
            .replacingOccurrences(of: "\n", with: " ")
            .replacingOccurrences(of: "  ", with: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard normalized.count > limit else { return normalized }
        let end = normalized.index(normalized.startIndex, offsetBy: limit)
        let prefix = normalized[..<end]
        let lastSpace = prefix.lastIndex(of: " ") ?? prefix.endIndex
        return String(prefix[..<lastSpace]).trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

struct BindingMemoryDigest: Equatable {
    struct BraidMemory: Equatable {
        var pageID: String
        var date: Date
        var residue: BookOfYouResidue
    }

    struct MotifCount: Equatable {
        var motif: String
        var count: Int
    }

    var braids: [BraidMemory]
    var motifCounts: [MotifCount]
    var strongestCallback: String?

    static let empty = BindingMemoryDigest(braids: [], motifCounts: [], strongestCallback: nil)
}

enum BindingMemorySpine {
    static func digest(days: [BookDay], now: Date = Date(), limit: Int = 12) -> BindingMemoryDigest {
        let braidMemories = days
            .flatMap(\.pages)
            .filter { $0.type == .bookOfYou && $0.createdAt <= now }
            .sorted { $0.createdAt > $1.createdAt }
            .compactMap { page -> BindingMemoryDigest.BraidMemory? in
                let residue = BookOfYouResidue.fromTags(in: page) ?? BookOfYouResidue.extract(from: page)
                return BindingMemoryDigest.BraidMemory(pageID: page.id, date: page.createdAt, residue: residue)
            }
        guard !braidMemories.isEmpty else { return .empty }
        let counts = Dictionary(grouping: braidMemories.flatMap(\.residue.motifs), by: { $0 })
            .mapValues(\.count)
            .sorted { left, right in
                if left.value == right.value { return left.key < right.key }
                return left.value > right.value
            }
            .prefix(8)
            .map { BindingMemoryDigest.MotifCount(motif: $0.key, count: $0.value) }
        return BindingMemoryDigest(
            braids: Array(braidMemories.prefix(limit)),
            motifCounts: counts,
            strongestCallback: braidMemories.first?.residue.callbackCandidate
        )
    }
}

// MARK: - Braid Learning

struct BraidLearningGuidance: Equatable, Codable {
    struct Signal: Equatable, Codable {
        var dimension: String
        var weight: Int
        var note: String
    }

    var signals: [Signal]

    var promptLines: [String] {
        signals
            .sorted { lhs, rhs in
                if lhs.weight == rhs.weight {
                    return lhs.dimension < rhs.dimension
                }
                return lhs.weight > rhs.weight
            }
            .prefix(4)
            .map(\.note)
    }

    static let empty = BraidLearningGuidance(signals: [])
}

// MARK: - Taught Reading (corrections remembered out loud)

/// One rule the reader has taught the Book about how to read them, spoken
/// back in the Book's voice. Being correctable out loud is what separates a
/// reader from a horoscope.
struct TaughtReadingRule: Identifiable, Equatable {
    var id: String
    var line: String
}

/// Gathers everything the reader has taught the Book: braid corrections,
/// notice feedback, quiet dismissals: from the stores that already hold
/// them. No new ledgers: the vault's braid notes, the kept pages' feedback
/// tags, and the reader-learning events are the memory of being corrected.
enum TaughtReading {
    static func rules(
        learnedBraidNotes: [String],
        days: [BookDay],
        learning: ReaderLearningModel,
        now: Date = Date(),
        limit: Int = 6
    ) -> [TaughtReadingRule] {
        var rules: [TaughtReadingRule] = []

        // The reader's own written corrections come first: nothing teaches
        // like a sentence the reader typed at the Book.
        for (index, note) in learnedBraidNotes.suffix(2).reversed().enumerated() {
            let trimmed = note.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty else { continue }
            rules.append(TaughtReadingRule(
                id: "taught-braid-note-\(index)",
                line: "You told me: \u{201C}\(clipped(trimmed))\u{201D}: the braids have been written with that in hand since."
            ))
        }

        // Feedback on the Book's noticing: stepped back from, softened, trusted.
        let noticeEvents = learning.events.filter { $0.type == .bookNotices }
        let dismissed = noticeEvents.filter { $0.action == .dismissed }.count
        let missed = noticeEvents.filter { $0.action == .missed }.count
        let loved = noticeEvents.filter { $0.action == .loved }.count
        if dismissed > 0 {
            rules.append(TaughtReadingRule(
                id: "taught-notice-dismissed",
                line: "You asked me, \(timesPhrase(dismissed)), not to read you a certain way. I stepped back from those readings: stepped back, not forgotten; respected."
            ))
        }
        if missed > 0 {
            rules.append(TaughtReadingRule(
                id: "taught-notice-missed",
                line: "\(spelled(missed).capitalized) \(missed == 1 ? "notice" : "notices") you marked \u{201C}not quite.\u{201D} I soften those patterns before speaking them again."
            ))
        }
        if loved > 0 {
            rules.append(TaughtReadingRule(
                id: "taught-notice-loved",
                line: "\(spelled(loved).capitalized) \(loved == 1 ? "reading" : "readings") you sealed as true. That kind of noticing gets to speak sooner now."
            ))
        }

        // Braid verdicts carried on the kept pages themselves.
        let braids = days.flatMap(\.pages).filter { $0.type == .bookOfYou }
        let lovedBraids = braids.filter { $0.tags.contains(BraidLearningLoop.lovedItTag) }.count
        let missedBraids = braids.filter { $0.tags.contains(BraidLearningLoop.missedMeTag) }.count
        switch (lovedBraids > 0, missedBraids > 0) {
        case (true, true):
            rules.append(TaughtReadingRule(
                id: "taught-braid-verdicts",
                line: "Of the braids, you called \(spelled(lovedBraids)) true and \(spelled(missedBraids)) \(missedBraids == 1 ? "a miss" : "misses"). Every new braid is tasted against exactly those lessons."
            ))
        case (true, false):
            rules.append(TaughtReadingRule(
                id: "taught-braid-verdicts",
                line: "You've called \(spelled(lovedBraids)) \(lovedBraids == 1 ? "braid" : "braids") a true page. I keep aiming there."
            ))
        case (false, true):
            rules.append(TaughtReadingRule(
                id: "taught-braid-verdicts",
                line: "\(spelled(missedBraids).capitalized) \(missedBraids == 1 ? "braid" : "braids") missed you, and you said so. I rewrite toward what you meant."
            ))
        case (false, false):
            break
        }

        // A page family the reader's dismissals cooled: the correction the
        // reader made without ever saying a word.
        if let cooling = learning.insights(now: now, limit: 6).first(where: { $0.kind == .coolingType }) {
            rules.append(TaughtReadingRule(
                id: "taught-cooling-\(cooling.id)",
                line: "\(cooling.line) You never had to say it twice: the quiet was instruction enough."
            ))
        }

        return Array(rules.prefix(limit))
    }

    /// The single line woven into a Book Notices page when the reader has
    /// taught the Book anything: proof that corrections change the reading.
    static func noticeLine(from rules: [TaughtReadingRule]) -> String? {
        guard let first = rules.first else { return nil }
        return "You've been teaching me how to read you, and I keep the lessons: \(first.line)"
    }

    private static func clipped(_ text: String, limit: Int = 90) -> String {
        guard text.count > limit else { return text }
        let cut = text.prefix(limit)
        let lastSpace = cut.lastIndex(of: " ") ?? cut.endIndex
        return String(cut[..<lastSpace]) + "\u{2026}"
    }

    private static func timesPhrase(_ n: Int) -> String {
        switch n {
        case 1: return "once"
        case 2: return "twice"
        default: return "\(spelled(n)) times"
        }
    }

    private static func spelled(_ n: Int) -> String {
        let words = ["zero", "one", "two", "three", "four", "five", "six", "seven",
                     "eight", "nine", "ten", "eleven", "twelve"]
        return (0...12).contains(n) ? words[n] : "\(n)"
    }
}

/// Receipts that the reader's own seeing is changing: an early plain sentence
/// beside a recent vivid one, both quoted from the archive.
enum HowYouSee {
    struct SeeingReceipt: Codable, Equatable {
        var earlierQuote: String
        var earlierMonthName: String
        var recentQuote: String
        var earlierStrength: Int
        var recentStrength: Int
    }

    static let minimumAuthoredPages = 40
    static let minimumSpanDays = 60
    static let seeingTypes: Set<BookPageType> = [.souvenir, .diary, .mood, .wonderCompass, .plainPage]

    static func receipt(days: [BookDay], now: Date = Date()) -> SeeingReceipt? {
        let engine = SentenceBuilderEngine()
        let pages = days.flatMap(\.pages)
            .filter {
                seeingTypes.contains($0.type)
                    && $0.origin == .userAuthored
                    && $0.userInput.split(whereSeparator: \.isWhitespace).count >= 4
            }
            .sorted { ($0.createdAt, $0.id) < ($1.createdAt, $1.id) }
        guard pages.count >= minimumAuthoredPages,
              let first = pages.first,
              let last = pages.last,
              last.createdAt.timeIntervalSince(first.createdAt) >= Double(minimumSpanDays) * 86_400 else { return nil }

        let earlyEnd = first.createdAt.addingTimeInterval(30 * 86_400)
        let recentStart = now.addingTimeInterval(-30 * 86_400)
        let early = pages.filter { $0.createdAt <= earlyEnd }
        let recent = pages.filter { $0.createdAt >= recentStart && $0.createdAt <= now }
        guard !early.isEmpty, !recent.isEmpty else { return nil }

        let earlyAnalyses = early.map { ($0, engine.analyze($0.userInput)) }
        let recentAnalyses = recent.map { ($0, engine.analyze($0.userInput)) }
        let earlyAverage = Double(earlyAnalyses.reduce(0) { $0 + $1.1.memoryStrength }) / Double(earlyAnalyses.count)
        let recentAverage = Double(recentAnalyses.reduce(0) { $0 + $1.1.memoryStrength }) / Double(recentAnalyses.count)
        let earlyVividShare = Double(earlyAnalyses.filter { $0.1.isVivid }.count) / Double(earlyAnalyses.count)
        let recentVividShare = Double(recentAnalyses.filter { $0.1.isVivid }.count) / Double(recentAnalyses.count)
        let vividImproved = earlyVividShare > 0
            ? recentVividShare >= earlyVividShare * 2
            : recentVividShare >= 0.25
        guard recentAverage >= earlyAverage + 0.75 || vividImproved else { return nil }

        let earlier = earlyAnalyses
            .filter { $0.1.memoryStrength <= 1 }
            .min { ($0.0.userInput.count, $0.0.createdAt, $0.0.id) < ($1.0.userInput.count, $1.0.createdAt, $1.0.id) }
        let latest = recentAnalyses
            .filter { $0.1.isVivid && $0.0.id != earlier?.0.id }
            .max { ($0.1.memoryStrength, $0.0.createdAt, $0.0.id) < ($1.1.memoryStrength, $1.0.createdAt, $1.0.id) }
        guard let earlier, let latest else { return nil }

        let formatter = DateFormatter()
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.dateFormat = "MMMM"
        return SeeingReceipt(
            earlierQuote: clipped(earlier.0.userInput.bookPreviewSentenceLimit(1)),
            earlierMonthName: formatter.string(from: earlier.0.createdAt),
            recentQuote: clipped(latest.0.userInput.bookPreviewSentenceLimit(1)),
            earlierStrength: earlier.1.memoryStrength,
            recentStrength: latest.1.memoryStrength
        )
    }

    private static func clipped(_ text: String, limit: Int = 110) -> String {
        guard text.count > limit else { return text }
        let cut = text.prefix(limit)
        let lastSpace = cut.lastIndex(of: " ") ?? cut.endIndex
        return String(cut[..<lastSpace]) + "…"
    }
}

enum BraidLearningLoop {
    static let missedMeTag = "braid-missed-me"
    static let lovedItTag = "braid-loved-it"
    static let improveNextTag = missedMeTag
    static let improvedTag = "braid-improved-next"

    struct Observation: Equatable {
        var selected: BraidTastingRoom.Sample
        var alternatives: [BraidTastingRoom.Sample]
        var acceptedByReader: Bool
        var editedText: String?

        init(
            selected: BraidTastingRoom.Sample,
            alternatives: [BraidTastingRoom.Sample] = [],
            acceptedByReader: Bool = true,
            editedText: String? = nil
        ) {
            self.selected = selected
            self.alternatives = alternatives
            self.acceptedByReader = acceptedByReader
            self.editedText = editedText
        }
    }

    static func guidance(from observations: [Observation], limit: Int = 8) -> BraidLearningGuidance {
        let recent = observations.suffix(limit)
        var weights: [String: Int] = [:]
        var notes: [String: String] = [:]

        for observation in recent {
            let selected = observation.selected
            let score = selected.score
            let readerPenalty = observation.acceptedByReader ? 0 : 4

            addIfWeak(score.title, threshold: 8, dimension: "title", weight: 2 + readerPenalty, into: &weights, notes: &notes)
            addIfWeak(score.storyShape, threshold: 15, dimension: "storyShape", weight: 3 + readerPenalty, into: &weights, notes: &notes)
            addIfWeak(score.priorEcho, threshold: 7, dimension: "priorEcho", weight: 2 + readerPenalty, into: &weights, notes: &notes)
            addIfWeak(score.themeAndChapter, threshold: 8, dimension: "themeAndChapter", weight: 2 + readerPenalty, into: &weights, notes: &notes)
            addIfWeak(score.souvenirSpine, threshold: 8, dimension: "souvenirSpine", weight: 4 + readerPenalty, into: &weights, notes: &notes)
            addIfWeak(score.keeperSentence, threshold: 10, dimension: "keeperSentence", weight: 3 + readerPenalty, into: &weights, notes: &notes)
            addIfWeak(score.concreteMagic, threshold: 9, dimension: "concreteMagic", weight: 2 + readerPenalty, into: &weights, notes: &notes)

            if score.penalties > 0 {
                weights["penalties", default: 0] += score.penalties + readerPenalty
                notes["penalties"] = note(for: "penalties")
            }

            if let editedText = observation.editedText,
               editedText.normalizedForBraidTasting != selected.page.userInput.normalizedForBraidTasting {
                learnFromEdit(original: selected.page.userInput, edited: editedText, weights: &weights, notes: &notes)
            }
        }

        let signals = weights.map { dimension, weight in
            BraidLearningGuidance.Signal(
                dimension: dimension,
                weight: weight,
                note: notes[dimension] ?? note(for: dimension)
            )
        }
        .filter { $0.weight > 0 }

        return BraidLearningGuidance(signals: signals)
    }

    static func guidance(
        fromPages pages: [BookPage],
        context: BraidPromptBuilder.Context = .empty,
        limit: Int = 8
    ) -> BraidLearningGuidance {
        let observations = pages
            .filter { $0.type == .bookOfYou && $0.tags.contains(improveNextTag) }
            .sorted { $0.createdAt < $1.createdAt }
            .suffix(limit)
            .map { page in
                let sample = BraidTastingRoom.Sample(
                    page: page,
                    details: BraidPageDetails.details(for: page),
                    score: BraidTastingRoom.score(page: page, context: context)
                )
                return Observation(selected: sample, acceptedByReader: false)
            }
        var guidance = guidance(from: observations, limit: limit)
        if !observations.isEmpty, guidance.signals.isEmpty {
            guidance = BraidLearningGuidance(signals: [
                .init(
                    dimension: "concreteMagic",
                    weight: 1,
                    note: note(for: "concreteMagic")
                )
            ])
        }
        return guidance
    }

    static func improvedContext(
        _ context: BraidPromptBuilder.Context,
        observations: [Observation],
        limit: Int = 8
    ) -> BraidPromptBuilder.Context {
        var updated = context
        let guidance = guidance(from: observations, limit: limit)
        updated.learnedGuidance = guidance.signals.isEmpty ? nil : guidance
        return updated
    }

    /// Reader-taught Gemma notes (earned on "this missed me") become guidance
    /// signals weighted above the deterministic heuristics, newest first.
    static func readerTaughtSignals(from notes: [String]) -> [BraidLearningGuidance.Signal] {
        let cleaned = notes.compactMap { $0.trimmingCharacters(in: .whitespacesAndNewlines).nonEmpty }
        guard !cleaned.isEmpty else { return [] }
        return cleaned.enumerated().map { index, note in
            BraidLearningGuidance.Signal(dimension: "reader-taught", weight: 40 + index, note: note)
        }
    }

    /// The weak-dimension prompt lines for a single braid page: used to tell
    /// Gemma exactly what to address when re-reading or rewriting it.
    static func weakDimensionNotes(for page: BookPage, context: BraidPromptBuilder.Context = .empty) -> [String] {
        let sample = BraidTastingRoom.Sample(
            page: page,
            details: BraidPageDetails.details(for: page),
            score: BraidTastingRoom.score(page: page, context: context)
        )
        return guidance(from: [Observation(selected: sample, acceptedByReader: false)]).promptLines
    }

    static func publicLesson(for page: BookPage, context: BraidPromptBuilder.Context = .empty) -> String {
        let guidance = guidance(fromPages: [page], context: context, limit: 1)
        let note = guidance.promptLines.first ?? note(for: "concreteMagic")
        if note.localizedCaseInsensitiveContains("title") {
            return "I learned to name the day more sharply next time."
        }
        if note.localizedCaseInsensitiveContains("old-tale") {
            return "I learned to give the next Braid a clearer turn."
        }
        if note.localizedCaseInsensitiveContains("earlier image") {
            return "I learned to echo yesterday only when the echo changes."
        }
        if note.localizedCaseInsensitiveContains("theme and chapter") {
            return "I learned to let theme and chapter move like weather."
        }
        if note.localizedCaseInsensitiveContains("The Book kept the page") {
            return "I learned to leave the next page with a stronger final line."
        }
        if note.localizedCaseInsensitiveContains("one supplied ordinary thing") {
            return "I learned to make one true thing strange for a reason."
        }
        if note.localizedCaseInsensitiveContains("generic") {
            return "I learned to trade grand words for truer details."
        }
        return "I learned a little more about how your days want to be told."
    }

    private static func addIfWeak(
        _ value: Int,
        threshold: Int,
        dimension: String,
        weight: Int,
        into weights: inout [String: Int],
        notes: inout [String: String]
    ) {
        guard value < threshold else { return }
        weights[dimension, default: 0] += max(1, threshold - value + weight)
        notes[dimension] = note(for: dimension)
    }

    private static func learnFromEdit(
        original: String,
        edited: String,
        weights: inout [String: Int],
        notes: inout [String: String]
    ) {
        let originalSentences = original.braidSentences.count
        let editedSentences = edited.braidSentences.count
        if editedSentences > originalSentences {
            weights["storyShape", default: 0] += 2
            notes["storyShape"] = note(for: "storyShape")
        }

        let originalConcrete = concreteWordCount(in: original)
        let editedConcrete = concreteWordCount(in: edited)
        if editedConcrete > originalConcrete {
            weights["concreteMagic", default: 0] += 3
            notes["concreteMagic"] = note(for: "concreteMagic")
        }

        if edited.contains("The Book kept the page:") && !original.contains("The Book kept the page:") {
            weights["keeperSentence", default: 0] += 4
            notes["keeperSentence"] = note(for: "keeperSentence")
        }
    }

    private static func concreteWordCount(in text: String) -> Int {
        let normalized = text.normalizedForBraidTasting
        let words = ["cup", "key", "charger", "coat", "dish", "window", "receipt", "door", "lamp", "phone", "rain", "coffee", "table", "shoe", "bag"]
        return words.filter { normalized.contains($0) }.count
    }

    private static func note(for dimension: String) -> String {
        switch dimension {
        case "title":
            return "Choose a sharper, less generic title: 2 to 7 concrete words, no label, no summary."
        case "storyShape":
            return "Make the selected tale motion legible through a supplied action, choice, cost, return, repair, refusal, or honest vigil."
        case "priorEcho":
            return "Let one earlier image return changed by today, or let the prior braid stay silent."
        case "themeAndChapter":
            return "Use theme and chapter as weather: one quiet motif or angle, never an announcement."
        case "souvenirSpine":
            return "Carry the reader's one-sentence souvenir through the opening, turn, and kept-page line."
        case "keeperSentence":
            return "End with exactly one memorable sentence beginning 'The Book kept the page:'."
        case "concreteMagic":
            return "Give one supplied ordinary thing a strange rule or consequence; keep the rest ordinary and never explain the magic."
        case "prose":
            return "Let one ordinary thing act on its own and stay concrete: no hedging with \"as if\" or \"seems to\", no abstraction pile-up, and no last sentence that explains the page."
        case "penalties":
            return "Drop report and clinical diction (nascent, precipitation, observation, reckoning, currents), quote no raw forecast numbers, hold one point of view, and avoid generic reflection words or doubled explanation."
        default:
            return "Prefer concrete, specific Book of You prose over generic summary."
        }
    }
}

// MARK: - Braid Tasting Room

enum BraidTastingRoom {
    struct Sample: Equatable {
        var page: BookPage
        var details: BraidPageDetails
        var score: Score
    }

    struct Score: Equatable, Comparable {
        var title: Int
        var storyShape: Int
        var priorEcho: Int
        var themeAndChapter: Int
        var souvenirSpine: Int
        var storyScoreFidelity: Int
        var keeperSentence: Int
        var concreteMagic: Int
        /// Whether the page filled the room its scale promised. The audit's
        /// `underBand` finding is a flat tax; this is the graded one, so a page
        /// twenty-six words short loses more than a page five words short and
        /// the tasting room can prefer the fuller of two otherwise equal cuts.
        var amplitude: Int
        /// The signals that mean the same thing wherever the Book is writing:
        /// an ordinary thing acting on its own, hedging, abstraction pile-up,
        /// an ending that explains itself.
        ///
        /// The braid could already see concrete magic, a prior echo returning
        /// changed, amplitude and repetition - and none of those four, while
        /// Story Pages could see the four and none of the braid's. Two engines
        /// with half a palate each, judging the same Book's prose by different
        /// rules. `ProseTaste` is the half they share.
        ///
        /// Notably this is the only check anywhere on the braid of the loudest
        /// line in the Book's own voice: "MOST IMPORTANT: at least one ordinary
        /// thing must act on its own."
        var prose: Int = 0

        /// Enough to break a tie or lift a close second, never enough to
        /// outvote the page's shape.
        ///
        /// Uncapped, one strong animism line was worth more than the whole
        /// question of whether the reader's own material opened the page: on the
        /// bench it reordered a night so the fiction led and the reader's baking
        /// dropped to the second paragraph. That is the wrong trade on a Book of
        /// You page, and it is the same reason `maximumGuidanceBonus` exists.
        static let maximumProse = 12

        static func cappedProse(_ raw: Int) -> Int {
            max(-maximumProse, min(maximumProse, raw))
        }

        /// How closely this draft repeats the Book's own recent performance.
        /// A penalty, kept separate from diction/safety penalties so reader-
        /// taught guidance can name the actual problem instead of diagnosing a
        /// repeated sentence as "report language."
        var repetition: Int
        var penalties: Int

        /// The value the reader's feedback is talking about, or nil for the
        /// dimensions that are penalties or free-text rather than a strength.
        func value(forDimension dimension: String) -> Int? {
            switch dimension {
            case "title": return title
            case "storyShape": return storyShape
            case "priorEcho": return priorEcho
            case "themeAndChapter": return themeAndChapter
            case "souvenirSpine": return souvenirSpine
            case "storyScoreFidelity": return storyScoreFidelity
            case "keeperSentence": return keeperSentence
            case "concreteMagic": return concreteMagic
            case "amplitude": return amplitude
            case "prose": return prose
            default: return nil
            }
        }

        /// `total`, tilted toward whatever the reader's feedback says the Book
        /// has been weak at.
        ///
        /// "I loved this one" and "This missed me" both produced
        /// `BraidLearningGuidance`, and it only ever reached the Gemma prompt -
        /// so on the deterministic path, which is the default and the one that
        /// writes most pages, loving a braid trained a writer that was not
        /// writing. The dimensions already matched the tasting room's one for
        /// one; nothing was attached to them.
        ///
        /// Deliberately a nudge and not a verdict: the bonus is capped so
        /// guidance can break a tie or lift a close second, and can never
        /// rescue a page the audit is penalising.
        func total(guidedBy guidance: BraidLearningGuidance?) -> Int {
            guard let guidance, !guidance.signals.isEmpty else { return total }
            var bonus = 0
            for signal in guidance.signals {
                guard let value = value(forDimension: signal.dimension), value > 0 else { continue }
                bonus += (value * min(max(signal.weight, 0), 8)) / 10
            }
            return total + min(bonus, Score.maximumGuidanceBonus)
        }

        /// Enough to reorder near-equal cuts, not enough to outvote the audit.
        static let maximumGuidanceBonus = 12

        var total: Int {
            title + storyShape + priorEcho + themeAndChapter + souvenirSpine
                + storyScoreFidelity + keeperSentence + concreteMagic + amplitude
                + prose - repetition - penalties
        }

        static func < (lhs: Score, rhs: Score) -> Bool {
            lhs.total < rhs.total
        }
    }

    struct Result: Equatable {
        var samples: [Sample]
        var winner: Sample?
    }

    static func taste(_ pages: [BookPage], context: BraidPromptBuilder.Context = .empty) -> Result {
        let samples = pages.map { page -> Sample in
            let details = BraidPageDetails.details(for: page)
            return Sample(
                page: page,
                details: details,
                score: score(details: details, context: context)
            )
        }
        .sorted { lhs, rhs in
            if lhs.score.total == rhs.score.total {
                return lhs.details.title.localizedCaseInsensitiveCompare(rhs.details.title) == .orderedAscending
            }
            return lhs.score.total > rhs.score.total
        }
        return Result(samples: samples, winner: samples.first)
    }

    static func score(page: BookPage, context: BraidPromptBuilder.Context = .empty) -> Score {
        score(details: BraidPageDetails.details(for: page), context: context)
    }

    private static func score(details: BraidPageDetails, context: BraidPromptBuilder.Context) -> Score {
        let body = details.body
        let normalized = body.normalizedForBraidTasting
        let paragraphs = body.braidParagraphs
        let sentences = body.braidSentences
        let closingSentences = sentences.filter { $0.hasPrefix("The Book kept the page:") }

        return Score(
            title: titleScore(details.title),
            storyShape: storyShapeScore(
                paragraphs: paragraphs,
                sentences: sentences,
                normalized: normalized,
                context: context
            ),
            priorEcho: priorEchoScore(normalized: normalized, context: context),
            themeAndChapter: themeAndChapterScore(normalized: normalized, context: context),
            souvenirSpine: souvenirSpineScore(
                normalized: normalized,
                paragraphs: paragraphs,
                closingSentences: closingSentences,
                context: context
            ),
            storyScoreFidelity: storyScoreFidelityScore(
                normalized: normalized,
                paragraphs: paragraphs,
                context: context
            ),
            keeperSentence: keeperSentenceScore(closingSentences, opening: paragraphs.first),
            concreteMagic: concreteMagicScore(normalized: normalized, sentences: sentences, context: context),
            amplitude: amplitudeScore(body: body, context: context),
            prose: Score.cappedProse(ProseTaste.signals(in: body).reduce(0) { $0 + $1.points }),
            repetition: context.braidStyleMemory.recurrencePenalty(in: body),
            penalties: penaltyScore(
                normalized: normalized,
                sentences: sentences,
                context: context
            )
        )
    }

    private static func titleScore(_ title: String) -> Int {
        let words = title.split { $0.isWhitespace || $0 == "," || $0 == ";" }
        guard title != "Book of You", (2...7).contains(words.count), title.count <= 64 else {
            return 0
        }
        let generic = ["today", "journey", "reflection", "meaning", "magic", "braid"]
        let genericHits = generic.filter { title.localizedCaseInsensitiveContains($0) }.count
        return max(0, 12 - genericHits * 3)
    }

    /// Full marks for a page inside its band, falling off with how far short
    /// it lands and easing off gently when it runs long. Overshooting is a
    /// lesser sin than underdelivering: a generous page is still a page.
    private static func amplitudeScore(
        body: String,
        context: BraidPromptBuilder.Context
    ) -> Int {
        guard let band = context.taleReading?.scale.targetWordBand else { return 0 }
        let words = body.split { $0.isWhitespace || $0.isNewline }.count
        let maximum = 12
        if band.contains(words) { return maximum }
        if words < band.lowerBound {
            let shortfall = band.lowerBound - words
            return max(0, maximum - (shortfall * maximum * 2) / band.lowerBound)
        }
        let overshoot = words - band.upperBound
        return max(maximum / 2, maximum - (overshoot * maximum) / band.upperBound)
    }

    private static func storyShapeScore(
        paragraphs: [String],
        sentences: [String],
        normalized: String,
        context: BraidPromptBuilder.Context
    ) -> Int {
        var score = 0
        let expectedParagraphs: ClosedRange<Int>
        switch context.taleReading?.scale {
        case .glimpse: expectedParagraphs = 2...3
        case .small: expectedParagraphs = 3...5
        case .full: expectedParagraphs = 4...7
        case nil: expectedParagraphs = 3...7
        }
        if expectedParagraphs.contains(paragraphs.count) { score += 7 }

        let actionWords = [
            "answered", "arrived", "carried", "changed", "chose", "crossed", "declined",
            "entered", "fixed", "found", "kept", "left", "mended", "opened", "paid",
            "protected", "refused", "repaired", "returned", "stayed", "tended", "waited"
        ]
        if containsAny(actionWords, in: normalized) { score += 4 }
        if containsAny([" because ", " so ", " until ", " unless ", " after ", " but ", " instead "], in: " \(normalized) ") {
            score += 4
        }
        if let turn = context.taleReading?.turn {
            let turnWords = significantWords(turn)
            if turnWords.contains(where: { normalized.contains($0) }) { score += 5 }
        } else if sentences.count >= 4 {
            // A Vigil or Glimpse can have movement without counterfeiting a turn.
            score += 3
        }
        return min(score, 20)
    }

    private static func priorEchoScore(normalized: String, context: BraidPromptBuilder.Context) -> Int {
        guard !context.recentBraids.isEmpty else { return 6 }
        let motifHits = context.recentBraids
            .flatMap(significantWords)
            .filter { normalized.contains($0) }
        let uniqueHits = Set(motifHits).count
        // Silence is a valid continuity choice. It should not be "corrected"
        // into an obligatory echo when today's pages do not honestly invite one.
        if uniqueHits == 0 { return 8 }
        if uniqueHits <= 2 { return 10 }
        return 3
    }

    private static func themeAndChapterScore(normalized: String, context: BraidPromptBuilder.Context) -> Int {
        var score = 0
        if let theme = context.theme {
            let motifHits = theme.motifs
                .map { $0.normalizedForBraidTasting }
                .filter { !$0.isEmpty && normalized.contains($0) }
                .count
            if motifHits == 1 {
                score += 7
            } else if motifHits > 1 {
                score += 3
            } else {
                // A watermark is allowed to remain below lexical detection.
                score += 5
            }
            if normalized.contains(theme.name.normalizedForBraidTasting) {
                score -= 4
            }
        } else {
            score += 3
        }

        if let chapter = context.chapter {
            if normalized.contains("chapter \(chapter.name.normalizedForBraidTasting)") {
                score -= 3
            }
            let frameHits = significantWords(chapter.writeFraming + " " + chapter.storyBias)
                .filter { normalized.contains($0) }
                .count
            if frameHits > 0 {
                score += 5
            } else {
                score += 3
            }
        } else {
            score += 3
        }

        return max(0, min(score, 12))
    }

    private static func souvenirSpineScore(
        normalized: String,
        paragraphs: [String],
        closingSentences: [String],
        context: BraidPromptBuilder.Context
    ) -> Int {
        guard let anchor = context.souvenirAnchor else { return 6 }
        let anchorWords = Set(significantWords(anchor.keptText))
        guard !anchorWords.isEmpty else { return 6 }

        let totalHits = anchorWords.filter { normalized.contains($0) }.count
        guard totalHits > 0 else { return 0 }

        let opening = paragraphs.first?.normalizedForBraidTasting ?? ""
        let closing = closingSentences.joined(separator: " ").normalizedForBraidTasting
        let openingHits = anchorWords.filter { opening.contains($0) }.count
        let closingHits = anchorWords.filter { closing.contains($0) }.count

        var score = 5
        if totalHits >= min(2, anchorWords.count) { score += 4 }
        if openingHits > 0 { score += 3 }
        if closingHits > 0 { score += 4 }
        return min(score, 14)
    }

    private static func keeperSentenceScore(_ closingSentences: [String], opening: String?) -> Int {
        guard closingSentences.count == 1, let closing = closingSentences.first else { return 0 }
        let words = closing.split { $0.isWhitespace }.count
        guard (8...28).contains(words) else { return 5 }
        return 14 + callbackBonus(closing: closing, opening: opening)
    }

    private static func storyScoreFidelityScore(
        normalized: String,
        paragraphs: [String],
        context: BraidPromptBuilder.Context
    ) -> Int {
        guard let score = context.storyScore else { return 6 }
        let outputWords = Set(significantWords(normalized))
        var value = 0
        let livedMatches = score.livedBeats.filter { beat in
            !outputWords.isDisjoint(with: significantWords(beat.excerpt))
        }.count
        value += min(9, livedMatches * 3)
        if let fiction = score.fictionBeat {
            let fictionWords = significantWords(fiction.choice)
            if !outputWords.isDisjoint(with: fictionWords) { value += 3 }
            let livedWords = Set(score.livedBeats.flatMap { significantWords($0.excerpt) })
            let fictionSet = Set(fictionWords)
            let earnedTrespass = paragraphs.contains { paragraph in
                let words = Set(significantWords(paragraph))
                return !words.isDisjoint(with: livedWords)
                    && !words.isDisjoint(with: fictionSet)
            }
            if earnedTrespass { value += 4 }
        }
        if let lens = score.relationalLens {
            let lensWords = significantWords("\(lens.condition) \(lens.outcomes.joined(separator: " "))")
            if !outputWords.isDisjoint(with: lensWords) { value += 4 }
        }
        if let arc = score.arc {
            let arcWords = significantWords(arc.tonightDelta)
            if !outputWords.isDisjoint(with: arcWords) { value += 4 }
        }
        return min(20, value)
    }

    /// Reward the opening->closing loop: when the kept line carries a concrete
    /// word back from where the day began, the braid feels deliberately kept
    /// rather than merely ended. Bonus is capped so it can lift a strong braid
    /// without letting the keeper sentence dominate the whole score.
    private static func callbackBonus(closing: String, opening: String?) -> Int {
        guard let opening, !opening.isEmpty else { return 0 }
        let openingWords = Set(significantWords(opening))
        guard !openingWords.isEmpty else { return 0 }
        // Drop the fixed "the book kept the page" stem so it can't self-match.
        let keeperStem = significantWords("the book kept the page")
        let echoes = significantWords(closing)
            .filter { !keeperStem.contains($0) && openingWords.contains($0) }
        return min(Set(echoes).count * 3, 6)
    }

    private static func concreteMagicScore(
        normalized: String,
        sentences: [String],
        context: BraidPromptBuilder.Context
    ) -> Int {
        var score = 0
        if let reading = context.taleReading {
            let anchorHits = significantWords(reading.anchor).filter { normalized.contains($0) }.count
            score += min(anchorHits, 3) * 2
            if let turn = reading.turn {
                let turnHits = significantWords(turn).filter { normalized.contains($0) }.count
                score += min(turnHits, 2)
            }
            if reading.pressure == .witness, anchorHits > 0 {
                score += 4
            }
        }

        let consequence = [" so ", " until ", " unless ", " only when ", " would not ", " refused ", " cost ", " left behind "]
        if consequence.contains(where: { " \(normalized) ".contains($0) }) { score += 4 }

        let strangeAgency = ["wanted", "refused", "remembered", "guarded", "waited", "asked", "followed", "wouldn't", "would not"]
        if sentences.contains(where: { sentence in
            let line = sentence.normalizedForBraidTasting
            return strangeAgency.contains(where: { line.contains($0) })
        }) {
            score += 3
        }

        // With no tale reading (older archives/tests), still reward causal,
        // concrete strangeness rather than a bag of fantasy nouns.
        if context.taleReading == nil,
           containsAny(["cup", "key", "charger", "coat", "dish", "window", "receipt", "door", "phone", "table", "shoe", "bag"], in: normalized) {
            score += 3
        }
        return min(14, score)
    }

    private static func penaltyScore(
        normalized: String,
        sentences: [String],
        context: BraidPromptBuilder.Context
    ) -> Int {
        let banned = ["journey", "profound", "tapestry", "hidden meaning", "generic inspiration"]
        var penalties = banned.filter { normalized.contains($0) }.count * 4

        // Clinical / report diction breaks the spell as badly as purple words do.
        let clinical = [
            "nascent", "precipitation", "observation", "observed", "reckoning",
            "currents", "inner landscape", "the report", "transfer of", "documented"
        ]
        penalties += clinical.filter { normalized.contains($0) }.count * 4

        // Raw forecast figures should be transmuted into felt weather, not quoted.
        let temperatureWords = ["degrees", "high of", "low of", "overcast at", "forecast"]
        penalties += temperatureWords.filter { normalized.contains($0) }.count * 3

        // Point-of-view drift: distancing the reader into a specimen mid-braid.
        let distancing = ["a mortal", "the mortal", "a figure", "the figure"]
        penalties += distancing.filter { normalized.contains($0) }.count * 2

        // The two source roles remain strict backstage. Naming their seam on
        // the finished page breaks the intended magical-realist trespass.
        let seamLabels = [
            "in fiction", "in the fiction", "in real life", "in the lived room",
            "fictional choice", "fiction bridge", "lived event", "two shelves",
            "lived shelf", "fiction shelf", "in the margins, not", "in the margins, not"
        ]
        penalties += seamLabels.filter { normalized.contains($0) }.count * 5

        let supplied = [
            context.taleReading?.anchor ?? "",
            context.taleReading?.turn ?? ""
        ].joined(separator: " ").normalizedForBraidTasting
        let stockMagic = ["glimmer", "moth", "moon", "lantern", "threshold"]
        let unsupportedStock = stockMagic.filter { normalized.contains($0) && !supplied.contains($0) }
        if unsupportedStock.count >= 2 {
            penalties += unsupportedStock.count * 2
        }

        let minimumSentences = context.taleReading?.scale == .glimpse ? 2 : 4
        if sentences.count < minimumSentences { penalties += 6 }
        let repeatedStarts = Dictionary(grouping: sentences.compactMap { $0.split(separator: " ").first?.lowercased() }, by: { $0 })
            .values
            .filter { $0.count >= 3 }
            .count
        penalties += repeatedStarts * 3
        return penalties
    }

    private static func significantWords(_ text: String) -> [String] {
        let stopwords: Set<String> = [
            "about", "after", "again", "because", "before", "beside", "book", "chapter", "could", "every",
            "from", "into", "kept", "like", "little", "more", "only", "over", "page", "that", "their",
            "there", "this", "through", "today", "under", "waited", "when", "where", "with", "without",
            "would", "write", "writing"
        ]
        return text
            .normalizedForBraidTasting
            .split { !$0.isLetter && !$0.isNumber }
            .map(String.init)
            .filter { $0.count >= 4 && !stopwords.contains($0) }
    }

    private static func containsAny(_ needles: [String], in haystack: String) -> Bool {
        needles.contains { haystack.contains($0) }
    }
}

private extension String {
    var normalizedForBraidTasting: String {
        lowercased()
            .replacingOccurrences(of: "\r\n", with: "\n")
            .replacingOccurrences(of: "\n", with: " ")
            .replacingOccurrences(of: "  ", with: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    var braidParagraphs: [String] {
        replacingOccurrences(of: "\r\n", with: "\n")
            .components(separatedBy: "\n\n")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
    }

    var braidSentences: [String] {
        replacingOccurrences(of: "\r\n", with: "\n")
            .components(separatedBy: CharacterSet(charactersIn: ".!?"))
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
    }
}

protocol SensoryVectorEncoding {
    var modelID: String { get }
    func vector(for text: String) -> [Float]?
}

#if canImport(NaturalLanguage)
/// Apple's sentence model gives words and Vision-produced descriptions one
/// shared local language space. A future CLIP/SigLIP lane can sit beside this
/// without invalidating the folios already kept.
struct NaturalLanguageSensoryVectorEncoder: SensoryVectorEncoding {
    private static let vectorLock = NSLock()

    let modelID: String
    private let embedding: NLEmbedding

    init?(language: NLLanguage = .english) {
        guard let embedding = NLEmbedding.sentenceEmbedding(for: language) else { return nil }
        self.embedding = embedding
        self.modelID = "NaturalLanguage.sentenceEmbedding.\(language.rawValue)"
    }

    func vector(for text: String) -> [Float]? {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return nil }
        Self.vectorLock.lock()
        let values = embedding.vector(for: trimmed)
        Self.vectorLock.unlock()
        return values?.map(Float.init)
    }
}
#endif

enum SensoryFolioProjector {
    private static let extractorID = "sensory-loom-v1"

    #if canImport(NaturalLanguage)
    private static let defaultEncoder = NaturalLanguageSensoryVectorEncoder()
    #endif

    /// Cheap enough for the immediate Keep: typed receipts arrive before any
    /// embedding work and remain useful on devices without a sentence model.
    static func structuredFolio(from page: BookPage) -> SensoryFolio {
        var observations: [SensoryObservation] = []
        let fingerprint = page.resolvedAttentionFingerprint

        func append(
            _ dimension: SensoryObservation.Dimension,
            _ value: String?,
            confidence: Float = 1
        ) {
            guard let normalized = value?
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased()
                .nonEmpty else { return }
            let observation = SensoryObservation(
                dimension: dimension,
                value: normalized,
                confidence: min(1, max(0, confidence)),
                extractorID: extractorID
            )
            if !observations.contains(observation) {
                observations.append(observation)
            }
        }

        for modality in fingerprint.modalities { append(.modality, modality) }
        for subject in fingerprint.visualTokens.prefix(8) { append(.subject, subject, confidence: 0.72) }

        for asset in page.mediaAssets {
            let metadata = asset.metadata
            splitMetadata(metadata["attentionLabels"]).prefix(8).forEach { append(.subject, $0, confidence: 0.72) }
            splitMetadata(metadata["attentionMotifs"]).prefix(6).forEach { append(.subject, $0, confidence: 0.78) }
            append(.palette, metadata["attentionColorMood"])
            append(.brightness, metadata["attentionBrightness"])
            append(.composition, metadata["attentionComposition"])
            append(.visibleText, metadata["attentionVisibleText"], confidence: 0.82)
            append(.voiceDuration, metadata["durationSeconds"])
            append(.voiceRate, metadata["voiceRate"])
            append(.voicePause, metadata["voicePause"])
            append(.voicePitchRange, metadata["voicePitchRange"])
            append(.voiceCadence, metadata["voiceCadence"])
            append(.voiceEnergy, metadata["voiceEnergy"])
        }

        if let context = page.context {
            context.weatherTags.forEach { append(.weather, $0) }
            append(.dayPart, context.dayPart)
            append(.place, context.nearbyAnchorID ?? context.locationLabel)
            append(.innerWeather, context.innerWeatherEntryID)
        }

        return SensoryFolio(observations: observations, vectors: [])
    }

    /// Runs away from the rendered view. Each lane is embedded separately so
    /// later readings can distinguish image-to-ink recognition from an ordinary
    /// prose echo or a shared surrounding condition.
    static func enrichedFolio(from page: BookPage) -> SensoryFolio {
        #if canImport(NaturalLanguage)
        return make(from: page, encoder: defaultEncoder)
        #else
        return structuredFolio(from: page)
        #endif
    }

    static func make(from page: BookPage, encoder: SensoryVectorEncoding?) -> SensoryFolio {
        var folio = structuredFolio(from: page)
        let fingerprint = page.resolvedAttentionFingerprint
        var vectors: [SensoryVector] = []

        // Prosody is already a small, explicit numeric receipt. It does not
        // require a language model, so it remains available on every device and
        // is kept in a model/version lane of its own.
        for asset in page.mediaAssets where asset.kind == .audioFile {
            if let vector = acousticProsodyVector(from: asset.metadata) {
                vectors.append(vector)
            }
        }
        folio.vectors = vectors
        guard let encoder else { return folio }

        func add(_ kind: SensoryVector.Kind, text: String) {
            guard let values = encoder.vector(for: text), !values.isEmpty else { return }
            let vector = SensoryVector(kind: kind, modelID: encoder.modelID, values: values)
            if !vector.values.isEmpty { vectors.append(vector) }
        }

        let language = page.readerAuthoredTextForAnalysis ?? ""
        if language.split(whereSeparator: { !$0.isLetter && !$0.isNumber }).count >= 4 {
            add(.languageSemantic, text: language)
        }

        let readerMediaIDs = Set(page.readerContributions.compactMap(\.mediaAssetID))
        let visual = page.mediaAssets.compactMap { asset -> String? in
            guard asset.kind != .audioFile, readerMediaIDs.contains(asset.id) else { return nil }
            let facts = [
                asset.caption,
                asset.metadata["attentionLabels"],
                asset.metadata["attentionMotifs"],
                asset.metadata["attentionSubject"],
                asset.metadata["attentionScene"],
                asset.metadata["attentionColorMood"],
                asset.metadata["attentionBrightness"],
                asset.metadata["attentionComposition"]
            ].compactMap { $0?.nonEmpty }
            return facts.isEmpty ? nil : facts.joined(separator: ", ")
        }.joined(separator: ". ")
        if !visual.isEmpty { add(.visualSemantic, text: visual) }

        if fingerprint.modalities.contains("voice"), !language.isEmpty {
            add(.voiceSemantic, text: language)
        }
        if !fingerprint.contextTokens.isEmpty {
            add(.contextSemantic, text: fingerprint.contextTokens.joined(separator: " "))
        }

        folio.vectors = vectors
        return folio
    }

    private static func acousticProsodyVector(from metadata: [String: String]) -> SensoryVector? {
        func number(_ key: String) -> Double? {
            metadata[key].flatMap(Double.init)
        }
        guard metadata["voiceAnalysisModel"] == VoiceCadenceReceipt.modelID,
              let duration = number("durationSeconds"), duration > 0,
              let activeRatio = number("voiceActiveRatio"),
              let pauseCount = number("voicePauseCount"),
              let meanPause = number("voiceMeanPauseSeconds"),
              let meanPhrase = number("voiceMeanPhraseSeconds"),
              let dynamicRange = number("voiceDynamicRangeDB"),
              let meanPower = number("voiceMeanPowerDB") else { return nil }
        let pausesPerMinute = pauseCount * 60 / duration
        return SensoryVector(
            kind: .acousticProsody,
            modelID: VoiceCadenceReceipt.modelID,
            values: [
                Float(min(1, max(0, activeRatio))),
                Float(min(1, max(0, pausesPerMinute / 12))),
                Float(min(1, max(0, meanPause / 3))),
                Float(min(1, max(0, meanPhrase / 6))),
                Float(min(1, max(0, dynamicRange / 30))),
                Float(min(1, max(0, (meanPower + 60) / 60)))
            ]
        )
    }

    private static func splitMetadata(_ value: String?) -> [String] {
        value?
            .split(whereSeparator: { $0 == "," || $0 == "|" })
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty } ?? []
    }
}

struct SensoryLoomConnection: Identifiable, Equatable {
    var id: String
    var motifID: String
    var motifName: String
    var line: String
    var evidencePageIDs: [String]
    var photographPageIDs: [String]
    var prosePageIDs: [String]
    var sharedContextTokens: [String]
    var meanSimilarity: Double
    var contrastGap: Double
    var strength: Int
    var firstSeenAt: Date
    var lastSeenAt: Date

    var signal: LiteraryContinuitySignal {
        LiteraryContinuitySignal(
            id: "sensory-\(motifID)",
            kind: .sensory,
            subjectID: motifID,
            subjectName: motifName,
            line: line,
            evidencePageIDs: evidencePageIDs,
            relatedEntityIDs: [],
            tags: ["sensory", "cross-media", "photograph", "ink", motifID] + sharedContextTokens,
            firstSeenAt: firstSeenAt,
            lastSeenAt: lastSeenAt,
            strength: strength
        )
    }
}

/// The first complete Loom reading: a visual motif whose local image-language
/// vector repeatedly recognizes reader-authored prose on other days. The
/// nearest matches must also beat the rest of the archive, preventing a merely
/// generic photograph from declaring kinship with everything.
enum SensoryLoom {
    static let minimumSimilarity = 0.58
    static let minimumContrastGap = 0.08
    static let minimumEvidencePages = 3
    static let minimumDistinctDays = 3

    static func connections(
        pages: [BookPage],
        calendar: Calendar = .current
    ) -> [SensoryLoomConnection] {
        let eligible = unique(pages).filter { page in
            page.hasReaderContribution
                && !EditionCurator.defaultPrivateTypes.contains(page.type)
        }
        let prose = eligible.filter { page in
            // Existing generated Pages may have one mixed language vector for
            // Book prose plus a reply. Until the vector store has atomic lanes,
            // only wholly reader-authored Page vectors can prove a prose echo.
            page.origin == .userAuthored
                && page.resolvedSensoryFolio.vector(.languageSemantic) != nil
                && (page.readerAuthoredTextForAnalysis ?? "")
                    .split(whereSeparator: { !$0.isLetter && !$0.isNumber }).count >= 5
        }
        let photographs = eligible.filter { page in
            page.hasReaderPhotograph
                && page.resolvedSensoryFolio.modalities.contains("photo")
                && page.resolvedSensoryFolio.vector(.visualSemantic) != nil
        }
        guard prose.count >= 4, !photographs.isEmpty else { return [] }

        var candidates: [SensoryLoomConnection] = []
        for photograph in photographs {
            guard let visual = photograph.resolvedSensoryFolio.vector(.visualSemantic),
                  let motif = motif(for: photograph) else { continue }
            let scored = prose.compactMap { page -> (BookPage, Double)? in
                guard page.id != photograph.id,
                      let language = page.resolvedSensoryFolio.vector(.languageSemantic),
                      let similarity = visual.cosineSimilarity(to: language) else { return nil }
                return (page, similarity)
            }.sorted { left, right in
                if left.1 == right.1 { return left.0.createdAt < right.0.createdAt }
                return left.1 > right.1
            }
            guard scored.count >= 4 else { continue }

            let matches = Array(scored.filter { $0.1 >= minimumSimilarity }.prefix(4))
            guard matches.count >= minimumEvidencePages - 1 else { continue }
            let evidencePages = [photograph] + matches.map(\.0)
            let distinctDays = Set(evidencePages.map { BookDay.id(for: $0.createdAt, calendar: calendar) })
            guard distinctDays.count >= minimumDistinctDays else { continue }

            let mean = matches.map(\.1).reduce(0, +) / Double(matches.count)
            let remaining = scored.dropFirst(matches.count).map(\.1).sorted()
            let baseline = remaining.isEmpty ? 0 : remaining[remaining.count / 2]
            let gap = mean - baseline
            guard gap >= minimumContrastGap else { continue }

            let context = sharedContext(in: evidencePages)
            let contextLine = context.first.map { " They also shared this bit of context: \(readableContext($0))." } ?? ""
            let line = "I found \(motif.name) in one photograph. I compared it with your written Pages. \(spelled(matches.count).sentenceCapitalized) Pages from other days were closer to that image than the rest of the archive was.\(contextLine)"
            let tier = min(9, evidencePages.count / 2)
            let strength = min(88, 58 + Int((mean * 18).rounded()) + Int((gap * 45).rounded()) + distinctDays.count)
            candidates.append(SensoryLoomConnection(
                id: "sensory-\(motif.id)-e\(tier)",
                motifID: motif.id,
                motifName: motif.name,
                line: line,
                evidencePageIDs: evidencePages.sorted { $0.createdAt < $1.createdAt }.map(\.id),
                photographPageIDs: [photograph.id],
                prosePageIDs: matches.map(\.0.id),
                sharedContextTokens: context,
                meanSimilarity: mean,
                contrastGap: gap,
                strength: strength,
                firstSeenAt: evidencePages.map(\.createdAt).min() ?? photograph.createdAt,
                lastSeenAt: evidencePages.map(\.createdAt).max() ?? photograph.createdAt
            ))
        }

        return candidates
            .sorted { left, right in
                if left.strength == right.strength { return left.id < right.id }
                return left.strength > right.strength
            }
            .reduce(into: []) { result, candidate in
                guard !result.contains(where: { $0.motifID == candidate.motifID }) else { return }
                result.append(candidate)
            }
    }

    private static func motif(for page: BookPage) -> (id: String, name: String)? {
        let rejected: Set<String> = ["ordinary", "detail", "image", "photo", "photograph", "light", "scene"]
        let candidates = page.resolvedSensoryFolio.values(for: .subject)
            + page.resolvedAttentionFingerprint.visualTokens
        guard let original = candidates.first(where: {
            let normalized = normalizedMotif($0)
            return normalized.count >= 4 && !rejected.contains(normalized)
        }) else { return nil }
        let raw = normalizedMotif(original)
        let clean = original.trimmingCharacters(in: .whitespacesAndNewlines)
        let name = clean.contains("-") || clean.contains("_")
            ? "An Unnamed Shape"
            : clean.capitalized
        return ("sensory-\(raw)", name)
    }

    private static func sharedContext(in pages: [BookPage]) -> [String] {
        guard let first = pages.first else { return [] }
        var shared = Set(first.resolvedAttentionFingerprint.contextTokens)
        for page in pages.dropFirst() {
            shared.formIntersection(page.resolvedAttentionFingerprint.contextTokens)
        }
        return shared.sorted()
    }

    private static func readableContext(_ token: String) -> String {
        switch token {
        case "weather-rain", "weather-rainy": return "rain at the windows"
        case "weather-snow", "weather-snowy": return "snow-light"
        case "weather-fog", "weather-foggy": return "fog close to the glass"
        case "weather-wind", "weather-windy": return "a restless wind"
        case "weather-clear", "weather-sunny": return "a bright sky"
        case "weather-cloud", "weather-cloudy": return "a low sky"
        case "hour-morning": return "the morning light"
        case "hour-afternoon": return "the long afternoon"
        case "hour-evening": return "the evening hour"
        case "hour-night": return "the hour after dark"
        case "body-low": return "a tired body"
        case "body-high": return "a lively body"
        case "tempo-open": return "an uncrowded day"
        case "tempo-crowded": return "a crowded day"
        default:
            if token.hasPrefix("anchor-") { return "the same remembered place" }
            if token.hasPrefix("weather-") { return "the same weather" }
            return "the same small circumstance"
        }
    }

    private static func normalizedMotif(_ value: String) -> String {
        value.lowercased()
            .replacingOccurrences(of: "_", with: "-")
            .replacingOccurrences(of: " ", with: "-")
            .trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
    }

    private static func unique(_ pages: [BookPage]) -> [BookPage] {
        var seen: Set<String> = []
        return pages.filter { seen.insert($0.id).inserted }
    }

    private static func spelled(_ count: Int) -> String {
        [0: "zero", 1: "one", 2: "two", 3: "three", 4: "four"][count] ?? "\(count)"
    }
}

struct LiteraryContinuitySignal: Identifiable, Codable, Equatable {
    var id: String
    var kind: LiterarySignalKind
    var subjectID: String
    var subjectName: String
    var line: String
    var evidencePageIDs: [String]
    var relatedEntityIDs: [String]
    var tags: [String]
    var firstSeenAt: Date
    var lastSeenAt: Date
    var strength: Int

    var promptLine: String {
        "\(subjectName): \(line)"
    }
}

struct BeliefLifecycleProfile: Identifiable, Codable, Equatable {
    var id: String
    var name: String
    var currentGlow: Int
    var firstSeenAt: Date
    var lastSeenAt: Date
    var pageCount: Int
    var eventCount: Int
    var characterCount: Int
    var evidencePageIDs: [String]
    var relatedEntityIDs: [String]

    var ageInDays: Int {
        max(1, Calendar.current.dateComponents([.day], from: Calendar.current.startOfDay(for: firstSeenAt), to: Calendar.current.startOfDay(for: Date())).day ?? 1)
    }
}

struct LiteraryContinuityDigest: Codable, Equatable {
    var signals: [LiteraryContinuitySignal]
    var beliefLifecycles: [BeliefLifecycleProfile]

    static let empty = LiteraryContinuityDigest(signals: [], beliefLifecycles: [])

    var strongestSignals: [LiteraryContinuitySignal] {
        signals.sorted { left, right in
            if left.strength == right.strength {
                return left.subjectName < right.subjectName
            }
            return left.strength > right.strength
        }
    }

    func signals(relatedTo page: BookPage, limit: Int = 3) -> [LiteraryContinuitySignal] {
        let pageWords = Self.meaningfulWords(in: "\(page.promptText) \(page.userInput) \(page.tags.joined(separator: " "))")
        return strongestSignals
            .filter { signal in
                !Set(signal.evidencePageIDs).isDisjoint(with: [page.id])
                    || !Set(signal.tags.map { $0.lowercased() }).isDisjoint(with: pageWords)
                    || pageWords.contains(signal.subjectName.lowercased())
            }
            .prefix(limit)
            .map(\.self)
    }

    private static func meaningfulWords(in text: String) -> Set<String> {
        LiteraryContinuityProjector.meaningfulWords(in: text)
    }
}

enum LiteraryContinuityProjector {
    static func digest(
        days: [BookDay],
        events: [NarrativeEvent],
        entityMemories: [NarrativeEntityMemory],
        entityBelief: [String: Int] = [:],
        pageBelief: [String: Int] = [:],
        now: Date = Date(),
        calendar: Calendar = .current
    ) -> LiteraryContinuityDigest {
        let pages = days.flatMap(\.pages).sorted { $0.createdAt < $1.createdAt }
        guard !pages.isEmpty || !events.isEmpty || !entityMemories.isEmpty else {
            return .empty
        }
        let lifecycles = beliefLifecycles(
            pages: pages,
            events: events,
            entityMemories: entityMemories,
            entityBelief: entityBelief,
            pageBelief: pageBelief
        )
        let pattern = patternSignals(pages: pages, events: events, now: now, calendar: calendar)
        let absences = absenceSignals(pages: pages, events: events, now: now, calendar: calendar)
        let durations = durationSignals(pages: pages, lifecycles: lifecycles, now: now, calendar: calendar)
        let lifecycle = lifecycles
            .filter(hasBecomeAThread)
            .prefix(4)
            .map { lifecycleSignal($0, now: now, calendar: calendar) }
        let manner = mannerSignals(pages: pages, now: now, calendar: calendar)
        let sensory = SensoryLoom.connections(pages: pages, calendar: calendar).map(\.signal)
        let signals = pattern + absences + durations + lifecycle + manner + sensory

        return LiteraryContinuityDigest(
            signals: Array(signals.sorted { left, right in
                if left.strength == right.strength {
                    return left.subjectName < right.subjectName
                }
                return left.strength > right.strength
            }.prefix(16)),
            beliefLifecycles: lifecycles
        )
    }

    static func meaningfulWords(in text: String) -> Set<String> {
        return Set(text
            .lowercased()
            .split { !$0.isLetter && !$0.isNumber }
            .map(String.init)
            .filter(isLiteraryCandidate)
        )
    }

    static let stopWords: Set<String> = [
        "about", "after", "again", "almost", "already", "also", "always", "another",
        "around", "because", "been", "before", "being", "between", "book", "both", "came",
        "come", "could", "does", "doing", "done", "down", "during", "each", "even", "every",
        "feel", "feeling", "felt", "first", "from", "going", "gone", "good", "have", "here",
        "into", "just", "kept", "last", "like", "little", "made", "make", "many", "might",
        "more", "most", "much", "never", "next", "only", "other", "over", "page", "pages",
        "really", "same", "should", "small", "some", "something", "still",
        "than", "that", "their", "them", "then", "there", "these", "they", "thing", "things",
        "this", "those", "through", "time", "today", "tomorrow", "tonight", "under", "until",
        "very", "want", "wanted", "week", "well", "went", "were", "what", "when", "where",
        "which", "while", "will", "with", "without", "would", "year", "yesterday", "your", "you",
        "january", "february", "march", "april", "june", "july", "august", "september",
        "october", "november", "december", "monday", "tuesday", "wednesday", "thursday",
        "friday", "saturday", "sunday", "morning", "evening", "night", "afternoon"
    ]

    /// Words can be meaningful to a parser while still being poor literary
    /// subjects. This list keeps the Book from naming scaffolding, generic
    /// motion, and emotional weather so vague it becomes accidental.
    static let weakLiterarySubjects: Set<String> = [
        "able", "above", "actually", "along", "anything", "away", "became", "begin",
        "began", "behind", "better", "blank", "called", "cannot", "change", "changed",
        "chapter", "class", "close", "closed", "climax", "coming", "current", "different",
        "early", "empty", "enough", "face", "fall", "fallen", "falling", "fell", "flat",
        "found", "front", "gave", "given", "gets", "getting", "half", "hard", "having",
        "held", "inside", "kind", "knew", "know", "later", "left", "less", "line",
        "lines", "long", "look", "looked", "looking", "lost", "maybe", "moment",
        "near", "needed", "open", "opened", "outside", "part", "past", "place",
        "point", "quietly", "read", "ready", "right", "room", "said", "saw", "scene",
        "second", "seen", "seems", "self", "side", "started", "story", "sure", "take",
        "taken", "takes", "tell", "thread", "told", "took", "toward", "trying", "turn",
        "turned", "used", "using", "voice", "whole", "work", "world"
    ]

    static func isLiteraryCandidate(_ word: String) -> Bool {
        word.count >= 4
            && !stopWords.contains(word)
            && !weakLiterarySubjects.contains(word)
            && !word.contains(where: \.isNumber)
    }

    /// Words that appear in a large share of all pages are the reader's
    /// ambient vocabulary, not a pattern - "academy" in a play archive,
    /// "meeting" in a work one. The damping is per-reader and automatic.
    /// Small archives skip it, so a young Book can still get excited about
    /// three mentions of the harbor in its first week.
    static let ubiquityMinimumPages = 12
    static let ubiquityCeiling = 0.34

    /// nil means the word is ambient vocabulary and should be no signal at
    /// all; otherwise the penalty scales with how common the word is.
    static func ubiquityPenalty(pageHits: Int, totalPages: Int) -> Int? {
        guard totalPages >= ubiquityMinimumPages else { return 0 }
        let ratio = Double(pageHits) / Double(totalPages)
        guard ratio <= ubiquityCeiling else { return nil }
        return Int(ratio * 60)
    }

    /// Diminishing returns past the first handful of pages, so strength
    /// discriminates between "appears sometimes" and "appears constantly"
    /// instead of every common word pinning the cap.
    static func patternStrength(pageCount: Int, eventBoost: Int, penalty: Int) -> Int {
        let early = 7 * min(pageCount, 5)
        let late = 2 * min(max(pageCount - 5, 0), 12)
        return min(94, max(1, 38 + early + late + eventBoost - penalty))
    }

    // MARK: - Manner signals (how the reader writes)

    /// The window the Book calls "this week" when reading manner.
    static let mannerRecentWindowDays = 7
    /// How far back the baseline reaches. Older pages describe a different
    /// season of the hand and are left out of the comparison.
    static let mannerBaselineWindowDays = 56

    /// Qualifiers whose density is the pencil hovering. Phrases are matched
    /// as phrases.
    static let mannerHedgeTerms: [String] = [
        "maybe", "probably", "perhaps", "i guess", "i suppose",
        "sort of", "kind of", "i think", "a bit"
    ]

    /// Manner observations read only the reader's own prose, never prompt
    /// text (the Book's words) and never the private body/fuel logs.
    static func mannerProse(in pages: [BookPage]) -> [BookPage] {
        pages.compactMap { page in
            guard !EditionCurator.defaultPrivateTypes.contains(page.type),
                  let readerText = page.readerAuthoredTextForAnalysis,
                  readerText.split(whereSeparator: { !$0.isLetter && !$0.isNumber }).count >= 5 else {
                return nil
            }
            var attributable = page
            attributable.userInput = readerText
            attributable.playerReply = ""
            return attributable
        }
    }

    static func mannerSignals(pages: [BookPage], now: Date, calendar: Calendar) -> [LiteraryContinuitySignal] {
        let prose = mannerProse(in: pages)
        guard !prose.isEmpty else { return [] }
        var signals: [LiteraryContinuitySignal] = []
        if let pace = sentencePaceSignal(prose: prose, now: now) {
            signals.append(pace)
        }
        if let hedge = hedgeInkSignal(prose: prose, now: now) {
            signals.append(hedge)
        }
        signals += hourboundSubjectSignals(prose: prose, now: now, calendar: calendar)
        return signals
    }

    /// The sentences walked faster or slower this week than the reader's own
    /// baseline. Requires enough pages on both sides of the comparison that
    /// the drift is a real change of gait, not one hurried evening.
    static func sentencePaceSignal(prose: [BookPage], now: Date) -> LiteraryContinuitySignal? {
        let recentCutoff = now.addingTimeInterval(TimeInterval(-mannerRecentWindowDays) * 86_400)
        let baselineCutoff = now.addingTimeInterval(TimeInterval(-mannerBaselineWindowDays) * 86_400)
        let recent = prose.filter { $0.createdAt > recentCutoff && $0.createdAt <= now }
        let baseline = prose.filter { $0.createdAt > baselineCutoff && $0.createdAt <= recentCutoff }
        guard recent.count >= 4, baseline.count >= 8 else { return nil }

        let recentAverage = averageSentenceLength(of: recent)
        let baselineAverage = averageSentenceLength(of: baseline)
        guard recentAverage > 0, baselineAverage > 0 else { return nil }
        let ratio = recentAverage / baselineAverage

        let line: String
        let flavor: String
        if ratio <= 0.72 {
            line = "This week the sentences walk faster: about \(spelledCount(Int(recentAverage.rounded()))) words to a step, where \(spelledCount(Int(baselineAverage.rounded()))) has been usual. Shorter steps, quicker breath."
            flavor = "fast"
        } else if ratio >= 1.4 {
            line = "The sentences have slowed into long walks this week: about \(spelledCount(Int(recentAverage.rounded()))) words to a sentence, where \(spelledCount(Int(baselineAverage.rounded()))) has been usual. Unhurried, taking the air."
            flavor = "slow"
        } else {
            return nil
        }

        let sortedRecent = recent.sorted { $0.createdAt < $1.createdAt }
        return LiteraryContinuitySignal(
            id: "manner-pace",
            kind: .manner,
            subjectID: "manner-pace",
            subjectName: "the sentences",
            line: line,
            evidencePageIDs: sortedRecent.suffix(6).map(\.id),
            relatedEntityIDs: [],
            tags: ["manner", "pace", flavor],
            firstSeenAt: sortedRecent.first?.createdAt ?? now,
            lastSeenAt: sortedRecent.last?.createdAt ?? now,
            strength: min(72, 56 + Int((abs(1 - ratio) * 24).rounded()))
        )
    }

    /// Hedge density rose or fell hard against the reader's own baseline -
    /// the pencil hovering, or the week written in ink.
    static func hedgeInkSignal(prose: [BookPage], now: Date) -> LiteraryContinuitySignal? {
        let recentCutoff = now.addingTimeInterval(TimeInterval(-mannerRecentWindowDays) * 86_400)
        let baselineCutoff = now.addingTimeInterval(TimeInterval(-mannerBaselineWindowDays) * 86_400)
        let recent = prose.filter { $0.createdAt > recentCutoff && $0.createdAt <= now }
        let baseline = prose.filter { $0.createdAt > baselineCutoff && $0.createdAt <= recentCutoff }

        let recentWords = totalWordCount(of: recent)
        let baselineWords = totalWordCount(of: baseline)
        // Density needs volume before it means anything.
        guard recentWords >= 120, baselineWords >= 400 else { return nil }

        let recentHedges = hedgeCount(in: recent)
        let baselineHedges = hedgeCount(in: baseline)
        let recentDensity = Double(recentHedges) / Double(recentWords) * 100
        let baselineDensity = Double(baselineHedges) / Double(baselineWords) * 100

        let line: String
        let flavor: String
        if baselineDensity > 0, recentDensity >= baselineDensity * 2.2, recentHedges >= 3 {
            line = "More \u{201C}maybe\u{201D} in the margins than usual this week. The pencil is hovering over something it has not decided to write."
            flavor = "hovering"
        } else if baselineDensity >= 1.0, recentDensity <= baselineDensity * 0.35 {
            line = "The maybes have thinned out of the pages. This week you are writing in ink."
            flavor = "ink"
        } else {
            return nil
        }

        let sortedRecent = recent.sorted { $0.createdAt < $1.createdAt }
        return LiteraryContinuitySignal(
            id: "manner-hedge",
            kind: .manner,
            subjectID: "manner-hedge",
            subjectName: "the maybes",
            line: line,
            evidencePageIDs: sortedRecent.suffix(6).map(\.id),
            relatedEntityIDs: [],
            tags: ["manner", "hedge", flavor],
            firstSeenAt: sortedRecent.first?.createdAt ?? now,
            lastSeenAt: sortedRecent.last?.createdAt ?? now,
            strength: 58
        )
    }

    /// A subject that only ever appears at one hour of the day: "you only
    /// write about the harbor after dark." Honest by construction: it needs
    /// the reader to write at other hours too, or "only at night" would be
    /// trivially true of everything.
    static func hourboundSubjectSignals(prose: [BookPage], now: Date, calendar: Calendar) -> [LiteraryContinuitySignal] {
        // The corpus must genuinely spread across hours: at least two bands,
        // and at least 40% of prose outside any single word's band.
        let allBands = prose.map { dayBand(for: $0.createdAt, calendar: calendar) }
        guard Set(allBands).count >= 2 else { return [] }
        let bandTotals = Dictionary(grouping: allBands) { $0 }.mapValues(\.count)

        var buckets: [String: [BookPage]] = [:]
        for page in prose {
            for word in meaningfulWords(in: page.userInput) {
                buckets[word, default: []].append(page)
            }
        }

        var out: [LiteraryContinuitySignal] = []
        for (word, matches) in buckets {
            let unique = uniqueMannerPages(matches)
            guard unique.count >= 3 else { continue }
            let dayIDs = Set(unique.map { BookDay.id(for: $0.createdAt, calendar: calendar) })
            guard dayIDs.count >= 2 else { continue }
            guard let penalty = ubiquityPenalty(pageHits: unique.count, totalPages: prose.count), penalty <= 8 else { continue }

            let bands = Set(unique.map { dayBand(for: $0.createdAt, calendar: calendar) })
            guard bands.count == 1, let band = bands.first else { continue }
            let inBand = bandTotals[band] ?? 0
            let outsideShare = Double(prose.count - inBand) / Double(prose.count)
            guard outsideShare >= 0.4 else { continue }

            let sorted = unique.sorted { $0.createdAt < $1.createdAt }
            out.append(LiteraryContinuitySignal(
                id: "manner-hour-\(word)",
                kind: .manner,
                subjectID: word,
                subjectName: word,
                line: "\(word.capitalized) only ever visits these pages \(bandPhrase(for: band)): \(spelledCount(unique.count)) times now, never at any other hour.",
                evidencePageIDs: sorted.map(\.id),
                relatedEntityIDs: [],
                tags: ["manner", "hour", band, word],
                firstSeenAt: sorted.first?.createdAt ?? now,
                lastSeenAt: sorted.last?.createdAt ?? now,
                strength: min(70, 50 + 4 * min(unique.count, 5) - penalty)
            ))
        }
        return out
            .sorted { left, right in
                if left.strength == right.strength { return left.subjectName < right.subjectName }
                return left.strength > right.strength
            }
            .prefix(2)
            .map(\.self)
    }

    static func dayBand(for date: Date, calendar: Calendar) -> String {
        switch calendar.component(.hour, from: date) {
        case 5...11: return "morning"
        case 12...16: return "afternoon"
        case 17...20: return "evening"
        default: return "night"
        }
    }

    static func bandPhrase(for band: String) -> String {
        switch band {
        case "morning": return "in the morning"
        case "afternoon": return "in the afternoon"
        case "evening": return "in the evening"
        default: return "after dark"
        }
    }

    private static func averageSentenceLength(of pages: [BookPage]) -> Double {
        var sentenceCount = 0
        var wordCount = 0
        for page in pages {
            let sentences = page.userInput
                .split(omittingEmptySubsequences: true) { ".!?\n".contains($0) }
                .map { $0.trimmingCharacters(in: .whitespaces) }
                .filter { !$0.isEmpty }
            sentenceCount += sentences.count
            wordCount += sentences.reduce(0) { $0 + $1.split { !$0.isLetter && !$0.isNumber }.count }
        }
        guard sentenceCount > 0 else { return 0 }
        return Double(wordCount) / Double(sentenceCount)
    }

    private static func totalWordCount(of pages: [BookPage]) -> Int {
        pages.reduce(0) { $0 + $1.userInput.split { !$0.isLetter && !$0.isNumber }.count }
    }

    private static func hedgeCount(in pages: [BookPage]) -> Int {
        pages.reduce(0) { total, page in
            let text = " \(page.userInput.lowercased().replacingOccurrences(of: "[^a-z]+", with: " ", options: .regularExpression)) "
            return total + mannerHedgeTerms.reduce(0) { sum, term in
                sum + text.components(separatedBy: " \(term) ").count - 1
            }
        }
    }

    private static func uniqueMannerPages(_ pages: [BookPage]) -> [BookPage] {
        var seen: Set<String> = []
        var out: [BookPage] = []
        for page in pages where !seen.contains(page.id) {
            seen.insert(page.id)
            out.append(page)
        }
        return out.sorted { $0.createdAt < $1.createdAt }
    }

    private static func spelledCount(_ n: Int) -> String {
        let words = ["zero", "one", "two", "three", "four", "five", "six", "seven",
                     "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen",
                     "fifteen", "sixteen", "seventeen", "eighteen", "nineteen", "twenty"]
        return (0...20).contains(n) ? words[n] : "\(n)"
    }

    private static func patternSignals(
        pages: [BookPage],
        events: [NarrativeEvent],
        now: Date,
        calendar: Calendar
    ) -> [LiteraryContinuitySignal] {
        var buckets: [String: [BookPage]] = [:]
        for page in pages {
            let text = page.resolvedAttentionFingerprint.patternText
            for word in meaningfulWords(in: text) {
                buckets[word, default: []].append(page)
            }
        }
        let eventText = events.prefix(80).map { "\($0.summary) \($0.tags.joined(separator: " "))" }.joined(separator: " ")
        let eventWords = meaningfulWords(in: eventText)
        let totalPages = pages.count
        return buckets.compactMap { word, matches in
            let uniquePages = unique(matches)
            guard uniquePages.count >= 3 else { return nil }
            guard let penalty = ubiquityPenalty(pageHits: uniquePages.count, totalPages: totalPages) else { return nil }
            let first = uniquePages.first?.createdAt ?? now
            let last = uniquePages.last?.createdAt ?? now
            let isMovingInEvents = eventWords.contains(word)
            let line = isMovingInEvents
                ? "\(word.capitalized) kept returning in the pages, then recent events picked up the thread."
                : "\(word.capitalized) kept returning through the kept pages."
            return LiteraryContinuitySignal(
                id: "pattern-\(word)",
                kind: .pattern,
                subjectID: word,
                subjectName: word.capitalized,
                line: line,
                evidencePageIDs: uniquePages.prefix(8).map(\.id),
                relatedEntityIDs: [],
                tags: [word, "pattern", "literary-continuity"] + (isMovingInEvents ? ["recent-events"] : []),
                firstSeenAt: first,
                lastSeenAt: last,
                strength: patternStrength(pageCount: uniquePages.count, eventBoost: eventWords.contains(word) ? 10 : 0, penalty: penalty)
            )
        }
    }

    private static func absenceSignals(
        pages: [BookPage],
        events: [NarrativeEvent],
        now: Date,
        calendar: Calendar
    ) -> [LiteraryContinuitySignal] {
        let historyCutoff = calendar.date(byAdding: .day, value: -21, to: now) ?? now
        let olderPages = pages.filter { $0.createdAt < historyCutoff }
        guard olderPages.count >= 3 else { return [] }
        var buckets: [String: [BookPage]] = [:]
        for page in olderPages {
            let text = page.resolvedAttentionFingerprint.patternText
            for word in meaningfulWords(in: text) {
                buckets[word, default: []].append(page)
            }
        }
        let recentText = pages
            .filter { $0.createdAt >= historyCutoff }
            .map { $0.resolvedAttentionFingerprint.patternText }
            .joined(separator: " ")
        let recentWords = meaningfulWords(in: recentText)
        return buckets.compactMap { word, matches in
            let uniquePages = unique(matches)
            guard uniquePages.count >= 3, !recentWords.contains(word), let last = uniquePages.last?.createdAt else {
                return nil
            }
            guard let penalty = ubiquityPenalty(pageHits: uniquePages.count, totalPages: olderPages.count) else { return nil }
            let quietDays = max(21, calendar.dateComponents([.day], from: calendar.startOfDay(for: last), to: calendar.startOfDay(for: now)).day ?? 21)
            return LiteraryContinuitySignal(
                id: "absence-\(word)",
                kind: .absence,
                subjectID: word,
                subjectName: word.capitalized,
                line: "\(word.capitalized) used to appear often; it has been quiet for \(quietDays) days.",
                evidencePageIDs: uniquePages.suffix(6).map(\.id),
                relatedEntityIDs: [],
                tags: [word, "absence", "literary-continuity"],
                firstSeenAt: uniquePages.first?.createdAt ?? last,
                lastSeenAt: last,
                strength: min(94, 34 + uniquePages.count * 7 + min(20, quietDays / 3) - penalty)
            )
        }
    }

    private static func durationSignals(
        pages: [BookPage],
        lifecycles: [BeliefLifecycleProfile],
        now: Date,
        calendar: Calendar
    ) -> [LiteraryContinuitySignal] {
        var signals: [LiteraryContinuitySignal] = []
        if let oldest = pages.first {
            let days = max(1, calendar.dateComponents([.day], from: calendar.startOfDay(for: oldest.createdAt), to: calendar.startOfDay(for: now)).day ?? 1)
            if days >= 30 {
                signals.append(LiteraryContinuitySignal(
                    id: "duration-book-\(oldest.id)",
                    kind: .duration,
                    subjectID: "book",
                    subjectName: "The Book",
                    line: "The oldest kept page has been in me for \(days) days.",
                    evidencePageIDs: [oldest.id],
                    relatedEntityIDs: [],
                    tags: ["duration", "archive", "literary-continuity"],
                    firstSeenAt: oldest.createdAt,
                    lastSeenAt: now,
                    strength: min(88, 40 + days / 14)
                ))
            }
        }
        for lifecycle in lifecycles.prefix(3) {
            let days = max(1, calendar.dateComponents([.day], from: calendar.startOfDay(for: lifecycle.firstSeenAt), to: calendar.startOfDay(for: now)).day ?? 1)
            guard days >= 14 else { continue }
            signals.append(LiteraryContinuitySignal(
                id: "duration-belief-\(lifecycle.id)",
                kind: .duration,
                subjectID: lifecycle.id,
                subjectName: lifecycle.name,
                line: "\(lifecycle.name) has been in the margins for \(days) days.",
                evidencePageIDs: lifecycle.evidencePageIDs,
                relatedEntityIDs: lifecycle.relatedEntityIDs,
                tags: ["duration", "belief", "literary-continuity", lifecycle.id],
                firstSeenAt: lifecycle.firstSeenAt,
                lastSeenAt: lifecycle.lastSeenAt,
                strength: min(90, 36 + days / 10 + lifecycle.pageCount * 3)
            ))
        }
        return signals
    }

    private static func beliefLifecycles(
        pages: [BookPage],
        events: [NarrativeEvent],
        entityMemories: [NarrativeEntityMemory],
        entityBelief: [String: Int],
        pageBelief: [String: Int]
    ) -> [BeliefLifecycleProfile] {
        let entities = NarrativePackRegistry.entities
        var profiles: [BeliefLifecycleProfile] = []

        for entity in entities where entity.kind == .character || entity.kind == .motif || entity.kind == .talisman {
            let pageHits = pages.filter { page in
                let text = "\(page.promptText) \(page.userInput) \(page.tags.joined(separator: " "))".lowercased()
                return text.contains(entity.id.lowercased()) || text.contains(entity.name.lowercased())
            }
            let eventHits = events.filter { event in
                event.effect.entityWeightDeltas.keys.contains(entity.id)
                    || event.summary.lowercased().contains(entity.name.lowercased())
                    || event.tags.contains(entity.id)
            }
            let memoryHits = entityMemories.filter { $0.entityID == entity.id }
            guard pageHits.count + eventHits.count + memoryHits.count > 0 else { continue }
            let dates = pageHits.map(\.createdAt) + eventHits.map(\.createdAt) + memoryHits.map(\.createdAt)
            profiles.append(BeliefLifecycleProfile(
                id: entity.id,
                name: entity.name,
                currentGlow: max(0, min(100, entity.belief + (entityBelief[entity.id] ?? 0))),
                firstSeenAt: dates.min() ?? Date(),
                lastSeenAt: dates.max() ?? Date(),
                pageCount: pageHits.count,
                eventCount: eventHits.count,
                characterCount: entity.kind == .character ? 1 : 0,
                evidencePageIDs: Array(pageHits.prefix(8).map(\.id)),
                relatedEntityIDs: [entity.id]
            ))
        }

        for profile in BookPageSourceRegistry.beliefProfiles(ledger: pageBelief) {
            let pageHits = pages.filter { $0.sourceID == profile.sourceID || $0.type == profile.type }
            let eventHits = events.filter { $0.sourcePageType == profile.type || $0.tags.contains(profile.sourceID) }
            guard pageHits.count + eventHits.count > 0 else { continue }
            let dates = pageHits.map(\.createdAt) + eventHits.map(\.createdAt)
            profiles.append(BeliefLifecycleProfile(
                id: profile.sourceID,
                name: profile.title,
                currentGlow: profile.belief,
                firstSeenAt: dates.min() ?? Date(),
                lastSeenAt: dates.max() ?? Date(),
                pageCount: pageHits.count,
                eventCount: eventHits.count,
                characterCount: 0,
                evidencePageIDs: Array(pageHits.prefix(8).map(\.id)),
                relatedEntityIDs: []
            ))
        }

        return profiles.sorted { left, right in
            let leftScore = left.pageCount * 8 + left.eventCount * 5 + left.currentGlow
            let rightScore = right.pageCount * 8 + right.eventCount * 5 + right.currentGlow
            if leftScore == rightScore {
                return left.name < right.name
            }
            return leftScore > rightScore
        }
    }

    private static func lifecycleSignal(
        _ lifecycle: BeliefLifecycleProfile,
        now: Date,
        calendar: Calendar
    ) -> LiteraryContinuitySignal {
        // This line gets printed: into forewords, closings and the margins of
        // a bound volume. So it carries no Glow balance, no raw event tally and
        // no counts of zero. Glow is the reader's wallet, not a fact about
        // their month, and "0 events" is a clause about nothing.
        let pages = lifecycle.pageCount == 1
            ? "one kept page"
            : "\(spelledCount(lifecycle.pageCount)) kept pages"
        let weight: String
        if lifecycle.eventCount > 0 {
            let times = lifecycle.eventCount == 1
                ? "once"
                : "\(spelledCount(lifecycle.eventCount)) times"
            weight = "\(pages), and it has surfaced \(times) besides"
        } else {
            weight = pages
        }
        return LiteraryContinuitySignal(
            id: "belief-lifecycle-\(lifecycle.id)",
            kind: .beliefLifecycle,
            subjectID: lifecycle.id,
            subjectName: lifecycle.name,
            line: ReflectiveProse.pick([
                "\(lifecycle.name) keeps coming back: \(weight). I've stopped treating that as coincidence.",
                "\(lifecycle.name) has turned into a thread rather than a moment: \(weight).",
                "I keep finding \(lifecycle.name) where I didn't put it: \(weight)."
            ], seed: lifecycleVoiceSeed(lifecycle.id), salt: 0),
            evidencePageIDs: lifecycle.evidencePageIDs,
            relatedEntityIDs: lifecycle.relatedEntityIDs,
            tags: ["belief", "lifecycle", "literary-continuity", lifecycle.id],
            firstSeenAt: lifecycle.firstSeenAt,
            lastSeenAt: lifecycle.lastSeenAt,
            strength: min(96, 32 + lifecycle.currentGlow / 2 + lifecycle.pageCount * 4 + lifecycle.eventCount * 2)
        )
    }

    /// The evidence floor for calling something a thread rather than a moment.
    ///
    /// A thread is a thing that *came back*. One page is a moment. Two pages on
    /// the same afternoon are still one moment, written twice. So the claim
    /// requires both: it appeared at least twice, and the appearances are far
    /// enough apart that the second one is a return rather than an echo.
    ///
    /// This is a warrant rule, not a tuning knob. The bound volume is supposed
    /// to be nothing but receipts, and "this has become a thread" is one of the
    /// larger claims the Book makes about a reader unprompted.
    private static func hasBecomeAThread(_ lifecycle: BeliefLifecycleProfile) -> Bool {
        let appearances = lifecycle.pageCount + lifecycle.eventCount
        guard appearances >= 2 else { return false }
        let span = lifecycle.lastSeenAt.timeIntervalSince(lifecycle.firstSeenAt)
        return span >= threadReturnWindow
    }

    /// How far apart two sightings must be before the later one counts as a
    /// return. A week: long enough that the reader stopped and came back.
    private static let threadReturnWindow: TimeInterval = 7 * 86_400

    /// Stable per-thread seed, so a given thread phrases itself the same way
    /// every time it is bound but two threads in one volume do not chorus.
    private static func lifecycleVoiceSeed(_ id: String) -> UInt64 {
        var hash: UInt64 = 1_469_598_103_934_665_603
        for byte in id.utf8 {
            hash ^= UInt64(byte)
            hash = hash &* 1_099_511_628_211
        }
        return hash
    }

    private static func unique(_ pages: [BookPage]) -> [BookPage] {
        var seen: Set<String> = []
        return pages.filter { page in
            if seen.contains(page.id) { return false }
            seen.insert(page.id)
            return true
        }
    }
}

// MARK: - Context Weave
//
// The general relationship finder. It lays the reader's own prose beside the
// coarse context each page carried home in its BookPageContextSnapshot -
// weather, hour, weekend, body, busy-ness, familiar place, and speaks only
// when a writing habit keeps choosing one condition over the others. Every
// comparison is two-sided (rainy pages against dry ones, never rainy pages
// against nothing), reads only the context that was true when the page was
// kept, and is phrased as an observation the reader may overrule.

/// One discovered relationship between how (or what) the reader writes and a
/// condition the pages were kept under.
struct ContextConnection: Identifiable, Equatable {
    enum Kind: String, Equatable {
        /// A writing manner (tone, hedging, length, questions) that leans
        /// into one condition.
        case manner
        /// A recurring subject word that only ever appears under one
        /// condition.
        case subject
    }

    /// Stable across days, but includes an evidence bucket so a connection
    /// may honestly speak again once it has gathered meaningfully more pages.
    var id: String
    var kind: Kind
    var facetID: String
    var headline: String
    var line: String
    var evidencePageIDs: [String]
    var strength: Int
    var inHits: Int
    var inCount: Int
    var outHits: Int
    var outCount: Int
}

enum ContextWeave {
    // MARK: Tone lexicons

    /// Weather and hour words are deliberately absent from both lexicons:
    /// "the bright sun" on a clear day or "dark" after nightfall would let a
    /// facet predict itself and the connection would be circular, not read.
    static let brightInkWords: Set<String> = [
        "glad", "happy", "happiness", "laugh", "laughed", "laughing", "laughter",
        "love", "loved", "lovely", "sweet", "joy", "joyful", "delight", "delighted",
        "fun", "funny", "smile", "smiled", "smiling", "grin", "grinning",
        "grateful", "gratitude", "thankful", "calm", "peaceful", "gentle",
        "cozy", "snug", "proud", "excited", "alive", "wonderful", "beautiful",
        "kind", "hopeful", "hope", "singing", "sang", "dancing", "danced"
    ]

    static let heavyInkWords: Set<String> = [
        "sad", "sadness", "sadder", "tired", "exhausted", "weary", "heavy",
        "heavier", "alone", "lonely", "loneliness", "hurt", "hurts", "hurting",
        "ache", "aches", "aching", "cried", "cry", "crying", "tears", "worry",
        "worried", "worrying", "anxious", "anxiety", "afraid", "fear", "fearful",
        "scared", "empty", "hollow", "lost", "angry", "anger", "frustrated",
        "frustrating", "grief", "grieving", "mourning", "numb", "dread",
        "sore", "sick", "awful", "terrible", "dreading", "overwhelmed"
    ]

    enum InkTone: String, Equatable {
        case bright
        case heavy
    }

    /// The page's dominant emotional register, or nil when the ink is
    /// neutral or evenly mixed. Strict majority only: the Book never breaks
    /// a tie on the reader's behalf.
    static func tone(of text: String) -> InkTone? {
        var bright = 0
        var heavy = 0
        for word in tokens(in: text) {
            if brightInkWords.contains(word) { bright += 1 }
            if heavyInkWords.contains(word) { heavy += 1 }
        }
        guard bright != heavy else { return nil }
        return bright > heavy ? .bright : .heavy
    }

    // MARK: Measures: how a page is written

    enum Measure: String, CaseIterable {
        case heavyInk = "heavy-ink"
        case brightInk = "bright-ink"
        case hedged
        case asking
        case longform
        case brisk

        /// "\(spelled(n)) of them …": the clause that reports the in-facet hits.
        var hitPhrase: String {
            switch self {
            case .heavyInk: return "use more heavy words"
            case .brightInk: return "use more bright words"
            case .hedged: return "use words such as maybe, perhaps, or I think"
            case .asking: return "ask questions"
            case .longform: return "run longer than your usual Pages"
            case .brisk: return "stay shorter than your usual Pages"
            }
        }

        /// The sentence that opens the observation.
        func hook(inPhrase: String) -> String {
            switch self {
            case .heavyInk: return "Your Pages use heavier words \(inPhrase)."
            case .brightInk: return "Your Pages use brighter words \(inPhrase)."
            case .hedged: return "Your Pages use more maybes \(inPhrase)."
            case .asking: return "Your Pages ask more questions \(inPhrase)."
            case .longform: return "Your Pages run longer \(inPhrase)."
            case .brisk: return "Your Pages stay shorter \(inPhrase)."
            }
        }
    }

    static func matches(_ measure: Measure, page: BookPage, medianWords: Int) -> Bool {
        switch measure {
        case .heavyInk: return tone(of: page.userInput) == .heavy
        case .brightInk: return tone(of: page.userInput) == .bright
        case .hedged: return hedgeCount(in: page.userInput) >= 1
        case .asking: return page.userInput.contains("?")
        case .longform: return wordCount(of: page.userInput) >= max(30, medianWords * 17 / 10)
        case .brisk: return wordCount(of: page.userInput) <= max(6, medianWords / 2)
        }
    }

    // MARK: Facets: the conditions a page was kept under

    struct Facet: Equatable {
        var id: String
        var family: String
        var inPhrase: String
        var outPhrase: String
    }

    /// Families whose membership every page can claim; the rest require the
    /// page to carry a context snapshot recording that dimension. A page may
    /// belong to a family without matching any facet in it (a mild-weather
    /// page still counts as "not rainy"): that is what keeps the out-group
    /// honest.
    static func families(for page: BookPage) -> Set<String> {
        var out: Set<String> = ["hour", "week"]
        guard let context = page.context else { return out }
        if !context.weatherTags.isEmpty { out.insert("weather") }
        if context.bodyScore != nil { out.insert("body") }
        if context.calendarEventCount != nil { out.insert("tempo") }
        out.insert("place")
        return out
    }

    static func facetIDs(for page: BookPage, calendar: Calendar) -> Set<String> {
        var out: Set<String> = []
        let dayPart: String
        if let stored = page.context?.dayPart,
           ["morning", "afternoon", "evening", "night"].contains(stored) {
            dayPart = stored
        } else {
            dayPart = LiteraryContinuityProjector.dayBand(for: page.createdAt, calendar: calendar)
        }
        out.insert("hour:\(dayPart)")
        out.insert(calendar.isDateInWeekend(page.createdAt) ? "week:weekend" : "week:weekday")
        if let context = page.context {
            for tag in context.weatherTags {
                out.insert("weather:\(tag)")
            }
            if let score = context.bodyScore {
                if score <= 40 { out.insert("body:low") }
                if score >= 70 { out.insert("body:high") }
            }
            if let events = context.calendarEventCount {
                if events >= 3 { out.insert("tempo:crowded") }
                if events == 0 { out.insert("tempo:open") }
            }
            if let anchor = context.nearbyAnchorID {
                out.insert("place:\(anchor)")
            }
        }
        return out
    }

    static func facet(for facetID: String) -> Facet {
        let family = String(facetID.prefix(while: { $0 != ":" }))
        let value = String(facetID.dropFirst(family.count + 1))
        switch facetID {
        case "hour:morning":
            return Facet(id: facetID, family: family, inPhrase: "in the morning hours", outPhrase: "at other hours")
        case "hour:afternoon":
            return Facet(id: facetID, family: family, inPhrase: "in the afternoon", outPhrase: "at other hours")
        case "hour:evening":
            return Facet(id: facetID, family: family, inPhrase: "in the evening", outPhrase: "at other hours")
        case "hour:night":
            return Facet(id: facetID, family: family, inPhrase: "after dark", outPhrase: "in daylight")
        case "week:weekend":
            return Facet(id: facetID, family: family, inPhrase: "on weekends", outPhrase: "on weekdays")
        case "week:weekday":
            return Facet(id: facetID, family: family, inPhrase: "on weekdays", outPhrase: "on weekends")
        case "weather:rain":
            return Facet(id: facetID, family: family, inPhrase: "while it was raining", outPhrase: "under other skies")
        case "weather:storm":
            return Facet(id: facetID, family: family, inPhrase: "while a storm was about", outPhrase: "under calmer skies")
        case "weather:snow":
            return Facet(id: facetID, family: family, inPhrase: "while snow was down", outPhrase: "under other skies")
        case "weather:fog":
            return Facet(id: facetID, family: family, inPhrase: "in fog", outPhrase: "under clearer skies")
        case "weather:wind":
            return Facet(id: facetID, family: family, inPhrase: "on windy days", outPhrase: "on stiller days")
        case "weather:cloud":
            return Facet(id: facetID, family: family, inPhrase: "under a clouded sky", outPhrase: "under other skies")
        case "weather:bright":
            return Facet(id: facetID, family: family, inPhrase: "under a bright sky", outPhrase: "under other skies")
        case "weather:hot":
            return Facet(id: facetID, family: family, inPhrase: "on hot days", outPhrase: "on cooler days")
        case "weather:cold":
            return Facet(id: facetID, family: family, inPhrase: "on cold days", outPhrase: "on milder days")
        case "body:low":
            return Facet(id: facetID, family: family, inPhrase: "on days the body arrived tired", outPhrase: "on livelier days")
        case "body:high":
            return Facet(id: facetID, family: family, inPhrase: "on days the body arrived lively", outPhrase: "on quieter-bodied days")
        case "tempo:crowded":
            return Facet(id: facetID, family: family, inPhrase: "on your crowded days", outPhrase: "on days with more room")
        case "tempo:open":
            return Facet(id: facetID, family: family, inPhrase: "on days the calendar stood open", outPhrase: "on busier days")
        default:
            if family == "place" {
                return Facet(id: facetID, family: family, inPhrase: "within reach of the same familiar place", outPhrase: "elsewhere")
            }
            return Facet(id: facetID, family: family, inPhrase: "while the weather leaned \(value)", outPhrase: "otherwise")
        }
    }

    static func headline(forFamily family: String) -> String {
        switch family {
        case "weather": return "The Weather in Your Ink"
        case "hour": return "The Hours in Your Ink"
        case "week": return "The Shape of Your Weeks"
        case "body": return "The Body in the Margins"
        case "tempo": return "The Crowded Days"
        case "place": return "A Familiar Doorstep"
        default: return "The Thread Between"
        }
    }

    // MARK: Evidence thresholds

    /// Pages kept under the condition, and distinct days among them.
    static let minimumInPages = 4
    static let minimumInDays = 3
    /// Pages kept under the *other* conditions of the same family: no
    /// one-sided claims.
    static let minimumOutPages = 4
    /// The habit must hold on most in-condition pages and clearly not hold
    /// elsewhere.
    static let minimumInRate = 0.5
    static let minimumRateGap = 0.3
    static let minimumLift = 2.0
    static let minimumHits = 3

    // MARK: The finder

    static func connections(
        days: [BookDay],
        calendar: Calendar = .current
    ) -> [ContextConnection] {
        let prose = LiteraryContinuityProjector.mannerProse(
            in: uniquePages(days.flatMap(\.capturedPages))
        )
        guard prose.count >= 10 else { return [] }
        let medianWords = median(prose.map { wordCount(of: $0.userInput) })

        var familyMembers: [String: [BookPage]] = [:]
        var facetMembers: [String: [BookPage]] = [:]
        for page in prose {
            for family in families(for: page) {
                familyMembers[family, default: []].append(page)
            }
            for facetID in facetIDs(for: page, calendar: calendar) {
                facetMembers[facetID, default: []].append(page)
            }
        }

        var out: [ContextConnection] = []
        for (facetID, inPages) in facetMembers {
            let facet = facet(for: facetID)
            guard let family = familyMembers[facet.family] else { continue }
            let inIDs = Set(inPages.map(\.id))
            let outPages = family.filter { !inIDs.contains($0.id) }
            guard inPages.count >= minimumInPages,
                  distinctDayCount(of: inPages, calendar: calendar) >= minimumInDays,
                  outPages.count >= minimumOutPages else { continue }

            for measure in Measure.allCases {
                if let connection = mannerConnection(
                    measure: measure,
                    facet: facet,
                    inPages: inPages,
                    outPages: outPages,
                    medianWords: medianWords
                ) {
                    out.append(connection)
                }
            }
            out += subjectConnections(
                facet: facet,
                inPages: inPages,
                outPages: outPages,
                familyCount: family.count,
                calendar: calendar
            )
        }
        return out.sorted { left, right in
            if left.strength != right.strength { return left.strength > right.strength }
            return left.id < right.id
        }
    }

    private static func mannerConnection(
        measure: Measure,
        facet: Facet,
        inPages: [BookPage],
        outPages: [BookPage],
        medianWords: Int
    ) -> ContextConnection? {
        let inHitPages = inPages.filter { matches(measure, page: $0, medianWords: medianWords) }
        let outHits = outPages.filter { matches(measure, page: $0, medianWords: medianWords) }.count
        let inRate = Double(inHitPages.count) / Double(inPages.count)
        let outRate = Double(outHits) / Double(outPages.count)
        guard inHitPages.count >= minimumHits,
              inRate >= minimumInRate,
              inRate - outRate >= minimumRateGap,
              inRate >= outRate * minimumLift else { return nil }

        let line = """
        \(measure.hook(inPhrase: facet.inPhrase)) Of the \(spelled(inPages.count)) pages you kept \(facet.inPhrase), \(spelled(inHitPages.count)) \(measure.hitPhrase). \(facet.outPhrase.sentenceCapitalized), \(spelled(outHits)) of \(spelled(outPages.count)) do.
        """
        let evidence = inHitPages
            .sorted { $0.createdAt > $1.createdAt }
            .prefix(4)
            .sorted { $0.createdAt < $1.createdAt }
        let gap = inRate - outRate
        let strength = min(84, 50 + Int((gap * 40).rounded()) + min(10, inHitPages.count))
        return ContextConnection(
            id: "context-\(facet.id)-\(measure.rawValue)-e\(min(inHitPages.count, 30) / 6)",
            kind: .manner,
            facetID: facet.id,
            headline: headline(forFamily: facet.family),
            line: line,
            evidencePageIDs: evidence.map(\.id),
            strength: strength,
            inHits: inHitPages.count,
            inCount: inPages.count,
            outHits: outHits,
            outCount: outPages.count
        )
    }

    /// A subject word that has only ever appeared under this condition:
    /// "the harbor only visits these pages while it is raining." Hour facets
    /// are skipped: hourbound subjects are already the manner system's job.
    private static func subjectConnections(
        facet: Facet,
        inPages: [BookPage],
        outPages: [BookPage],
        familyCount: Int,
        calendar: Calendar
    ) -> [ContextConnection] {
        guard facet.family != "hour" else { return [] }
        // The family must genuinely spread across the condition, or "only
        // ever here" is trivially true of everything.
        guard Double(outPages.count) / Double(familyCount) >= 0.4 else { return [] }

        var inWordPages: [String: [BookPage]] = [:]
        for page in inPages {
            for word in page.resolvedAttentionFingerprint.subjectTokens + page.resolvedAttentionFingerprint.visualTokens {
                inWordPages[word, default: []].append(page)
            }
        }
        var outWords: Set<String> = []
        for page in outPages {
            outWords.formUnion(page.resolvedAttentionFingerprint.subjectTokens)
            outWords.formUnion(page.resolvedAttentionFingerprint.visualTokens)
        }

        var out: [ContextConnection] = []
        for (word, pages) in inWordPages {
            let unique = uniquePages(pages)
            guard unique.count >= minimumHits,
                  distinctDayCount(of: unique, calendar: calendar) >= minimumInDays,
                  !outWords.contains(word),
                  let penalty = LiteraryContinuityProjector.ubiquityPenalty(
                      pageHits: unique.count,
                      totalPages: familyCount
                  ),
                  penalty <= 8 else { continue }

            let sorted = unique.sorted { $0.createdAt < $1.createdAt }
            out.append(ContextConnection(
                id: "context-\(facet.id)-subject-\(word)-e\(min(unique.count, 30) / 6)",
                kind: .subject,
                facetID: facet.id,
                headline: headline(forFamily: facet.family),
                line: "I found \(word) in \(spelled(unique.count)) Pages \(facet.inPhrase). I did not find it \(facet.outPhrase).",
                evidencePageIDs: sorted.suffix(4).map(\.id),
                strength: min(78, 48 + 5 * min(unique.count, 5) - penalty),
                inHits: unique.count,
                inCount: inPages.count,
                outHits: 0,
                outCount: outPages.count
            ))
        }
        return out
    }

    // MARK: Small helpers

    private static func tokens(in text: String) -> [String] {
        text.lowercased().split { !$0.isLetter }.map(String.init)
    }

    private static func wordCount(of text: String) -> Int {
        text.split { !$0.isLetter && !$0.isNumber }.count
    }

    private static func hedgeCount(in text: String) -> Int {
        let normalized = " \(text.lowercased().replacingOccurrences(of: "[^a-z]+", with: " ", options: .regularExpression)) "
        return LiteraryContinuityProjector.mannerHedgeTerms.reduce(0) { sum, term in
            sum + normalized.components(separatedBy: " \(term) ").count - 1
        }
    }

    private static func median(_ values: [Int]) -> Int {
        guard !values.isEmpty else { return 0 }
        let sorted = values.sorted()
        return sorted[sorted.count / 2]
    }

    private static func distinctDayCount(of pages: [BookPage], calendar: Calendar) -> Int {
        Set(pages.map { BookDay.id(for: $0.createdAt, calendar: calendar) }).count
    }

    private static func uniquePages(_ pages: [BookPage]) -> [BookPage] {
        var seen: Set<String> = []
        return pages.filter { page in
            if seen.contains(page.id) { return false }
            seen.insert(page.id)
            return true
        }
    }

    private static func spelled(_ n: Int) -> String {
        let words = ["zero", "one", "two", "three", "four", "five", "six", "seven",
                     "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen",
                     "fifteen", "sixteen", "seventeen", "eighteen", "nineteen", "twenty"]
        return (0...20).contains(n) ? words[n] : "\(n)"
    }
}

// Internal rather than fileprivate: the Book capitalises a sentence the same
// way wherever it speaks, and the voice work in SourceAdapters needs the same
// rule. One definition, so the two never drift.
extension String {
    var sentenceCapitalized: String {
        guard let first = first else { return self }
        return String(first).uppercased() + dropFirst()
    }
}

// MARK: - Themes
//
// A theme is the month's weather system: two or three motifs that kept
// gathering until they deserve a shared name. Themes are discovered from
// kept pages and the continuity digest, remembered across months, and used
// as chapter subtitles, theme pages, and margin material. Like everything
// else in the Book, a theme is a literary observation, never a verdict.

enum BookThemeStability: String, Codable, Equatable {
    case provisional
    case stable
}

struct BookTheme: Identifiable, Codable, Equatable {
    var id: String
    var monthKey: String
    var name: String
    var motifs: [String]
    var line: String
    var strength: Int
    var evidencePageIDs: [String]
    var excerptLines: [String]
    var discoveredAt: Date
    var stability: BookThemeStability
    var observedDayCount: Int
    var settledAt: Date?

    var promptLine: String {
        "\(stabilityTitle): \(name). \(line) \(stabilityDetail)"
    }

    var isStable: Bool {
        stability == .stable
    }

    var stabilityTitle: String {
        switch stability {
        case .provisional: return "Provisional monthly theme"
        case .stable: return "Settled monthly theme"
        }
    }

    var stabilityDetail: String {
        switch stability {
        case .provisional:
            return "Status: unstable; I'm still updating this theme as the month gathers more days."
        case .stable:
            return "Status: stable; I've stopped resetting this theme for the month."
        }
    }

    var readerStatusLine: String {
        "\(stabilityTitle): \(name). \(stabilityDetail)"
    }

    init(
        id: String,
        monthKey: String,
        name: String,
        motifs: [String],
        line: String,
        strength: Int,
        evidencePageIDs: [String],
        excerptLines: [String],
        discoveredAt: Date,
        stability: BookThemeStability = .stable,
        observedDayCount: Int = 7,
        settledAt: Date? = nil
    ) {
        self.id = id
        self.monthKey = monthKey
        self.name = name
        self.motifs = motifs
        self.line = line
        self.strength = strength
        self.evidencePageIDs = evidencePageIDs
        self.excerptLines = excerptLines
        self.discoveredAt = discoveredAt
        self.stability = stability
        self.observedDayCount = observedDayCount
        self.settledAt = settledAt
    }

    private enum CodingKeys: String, CodingKey {
        case id
        case monthKey
        case name
        case motifs
        case line
        case strength
        case evidencePageIDs
        case excerptLines
        case discoveredAt
        case stability
        case observedDayCount
        case settledAt
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        id = try container.decode(String.self, forKey: .id)
        monthKey = try container.decode(String.self, forKey: .monthKey)
        name = try container.decode(String.self, forKey: .name)
        motifs = try container.decode([String].self, forKey: .motifs)
        line = try container.decode(String.self, forKey: .line)
        strength = try container.decode(Int.self, forKey: .strength)
        evidencePageIDs = try container.decode([String].self, forKey: .evidencePageIDs)
        excerptLines = try container.decode([String].self, forKey: .excerptLines)
        discoveredAt = try container.decode(Date.self, forKey: .discoveredAt)
        stability = try container.decodeIfPresent(BookThemeStability.self, forKey: .stability) ?? .stable
        observedDayCount = try container.decodeIfPresent(Int.self, forKey: .observedDayCount) ?? 7
        settledAt = try container.decodeIfPresent(Date.self, forKey: .settledAt)
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(id, forKey: .id)
        try container.encode(monthKey, forKey: .monthKey)
        try container.encode(name, forKey: .name)
        try container.encode(motifs, forKey: .motifs)
        try container.encode(line, forKey: .line)
        try container.encode(strength, forKey: .strength)
        try container.encode(evidencePageIDs, forKey: .evidencePageIDs)
        try container.encode(excerptLines, forKey: .excerptLines)
        try container.encode(discoveredAt, forKey: .discoveredAt)
        try container.encode(stability, forKey: .stability)
        try container.encode(observedDayCount, forKey: .observedDayCount)
        try container.encodeIfPresent(settledAt, forKey: .settledAt)
    }
}

enum BookThemeEngine {
    static let minimumObservedDaysForTheme = 3
    static let stableObservedDaysForTheme = 7

    /// Words too structural to be a theme, on top of the continuity stop list.
    private static let themeStop: Set<String> = [
        "today", "yesterday", "tomorrow", "morning", "evening", "night",
        "really", "very", "little", "small", "around", "still", "going",
        "started", "finished", "thing", "things", "while", "after", "before",
        "first", "last", "back", "down", "over", "made", "make", "want",
        "wanted", "good", "nice", "time", "felt", "feel", "feeling", "went"
    ]

    /// Discovers the theme of a span of days. Deterministic for the same
    /// pages, digest, and month key.
    static func theme(
        for pages: [BookPage],
        digest: LiteraryContinuityDigest,
        constellations: [Constellation] = [],
        monthKey: String,
        now: Date = Date(),
        calendar: Calendar = .current
    ) -> BookTheme? {
        let observedDayCount = observedDayCount(for: pages, calendar: calendar)
        guard observedDayCount >= minimumObservedDaysForTheme else { return nil }

        var weights: [String: Int] = [:]
        var evidence: [String: [String]] = [:]

        for page in pages {
            let text = page.resolvedAttentionFingerprint.patternText
            for word in LiteraryContinuityProjector.meaningfulWords(in: text) where !themeStop.contains(word) {
                weights[word, default: 0] += 2
                if evidence[word, default: []].count < 8, !evidence[word, default: []].contains(page.id) {
                    evidence[word, default: []].append(page.id)
                }
            }
        }
        // Ambient vocabulary makes a dull theme; drop words on most pages.
        for (word, hits) in evidence where LiteraryContinuityProjector.ubiquityPenalty(pageHits: hits.count, totalPages: pages.count) == nil {
            weights.removeValue(forKey: word)
        }
        for signal in digest.signals {
            let subject = signal.subjectID.lowercased()
            guard !themeStop.contains(subject), subject.count >= 4 else { continue }
            weights[subject, default: 0] += signal.strength / 10
        }
        for constellation in constellations where constellation.isAlive {
            let subject = constellation.subjectID.lowercased()
            guard !themeStop.contains(subject), subject.count >= 4 else { continue }
            weights[subject, default: 0] += 6
        }

        let ranked = weights
            .filter { $0.value >= 4 && evidence[$0.key, default: []].count >= 2 }
            .sorted { left, right in
                if left.value == right.value { return left.key < right.key }
                return left.value > right.value
            }
        guard ranked.count >= 2 else { return nil }

        let motifs = Array(ranked.prefix(3).map(\.key))
        let primary = motifs[0]
        let secondary = motifs[1]
        let name = themeName(primary: primary, secondary: secondary, seed: "\(monthKey)-\(primary)-\(secondary)")
        let strength = min(100, ranked[0].1 * 3 + ranked[1].1 * 2)
        let evidenceIDs = Array(Set(motifs.flatMap { evidence[$0] ?? [] })).sorted()
        let excerpts = excerptLines(for: motifs, in: pages)
        let stability: BookThemeStability = observedDayCount >= stableObservedDaysForTheme ? .stable : .provisional

        return BookTheme(
            id: "theme-\(monthKey)",
            monthKey: monthKey,
            name: name,
            motifs: motifs,
            line: themeLine(motifs: motifs, seed: "\(monthKey)-line"),
            strength: strength,
            evidencePageIDs: evidenceIDs,
            excerptLines: excerpts,
            discoveredAt: now,
            stability: stability,
            observedDayCount: observedDayCount,
            settledAt: stability == .stable ? now : nil
        )
    }

    /// Upserts the current month's theme into the remembered ledger. Old
    /// months and already-settled live themes keep their names; only the live
    /// provisional theme keeps being rewritten as the month gathers evidence.
    static func remembered(
        _ existing: [BookTheme],
        observing current: BookTheme?,
        monthKey: String
    ) -> [BookTheme] {
        let existingTheme = existing.first { $0.monthKey == monthKey }
        if existingTheme?.isStable == true {
            return existing.sorted { $0.monthKey < $1.monthKey }
        }

        var kept = existing.filter { $0.monthKey != monthKey }
        if var current {
            current.discoveredAt = existingTheme?.discoveredAt ?? current.discoveredAt
            kept.append(current)
        }
        return kept.sorted { $0.monthKey < $1.monthKey }
    }

    static func theme(forMonth monthKey: String, in themes: [BookTheme]) -> BookTheme? {
        themes.first { $0.monthKey == monthKey }
    }

    static func observedDayCount(for pages: [BookPage], calendar: Calendar = .current) -> Int {
        Set(pages.map { BookDay.id(for: $0.createdAt, calendar: calendar) }).count
    }

    static func monthKey(for date: Date, calendar: Calendar = .current) -> String {
        let components = calendar.dateComponents([.year, .month], from: date)
        return String(format: "%04d-%02d", components.year ?? 0, components.month ?? 0)
    }

    /// "Secrets and Harbors" - two motifs joined by a deterministic pattern.
    static func themeName(primary: String, secondary: String, seed: String) -> String {
        let first = poeticized(primary)
        let second = poeticized(secondary)
        let patterns = [
            "%@ and %@",
            "%@ and %@",
            "Of %@ and %@",
            "%@, Then %@",
            "What %@ Said to %@"
        ]
        let pattern = patterns[ConstellationKeeper.stableIndex(for: "\(seed)-pattern", count: patterns.count)]
        return String(format: pattern, first, second)
    }

    private static func themeLine(motifs: [String], seed: String) -> String {
        let listed: String
        switch motifs.count {
        case 0, 1:
            listed = motifs.first.map(poeticized) ?? "the ordinary"
        case 2:
            listed = "\(poeticized(motifs[0])) and \(poeticized(motifs[1]))"
        default:
            listed = "\(poeticized(motifs[0])), \(poeticized(motifs[1])), and \(poeticized(motifs[2]))"
        }
        let templates = [
            "The pages kept returning to %@, the way a reader rereads a favorite paragraph without deciding to.",
            "%@ ran under the month like a watermark: visible whenever a page was held up to the light.",
            "If this month were a chapter, its running heads would say %@.",
            "The margins filled with %@ before anyone thought to call it a theme."
        ]
        let template = templates[ConstellationKeeper.stableIndex(for: seed, count: templates.count)]
        return String(format: template, listed)
    }

    private static func poeticized(_ word: String) -> String {
        word.prefix(1).uppercased() + word.dropFirst()
    }

    private static func excerptLines(for motifs: [String], in pages: [BookPage]) -> [String] {
        var excerpts: [String] = []
        for motif in motifs {
            guard let page = pages.first(where: { page in
                page.userInput.lowercased().contains(motif) && page.userInput.count >= 16
            }) else { continue }
            var line = page.userInput.bookPreviewSentenceLimit(1).trimmingCharacters(in: .whitespacesAndNewlines)
            if line.count > 110 {
                line = String(line.prefix(107)) + "..."
            }
            if !excerpts.contains(line) {
                excerpts.append(line)
            }
            if excerpts.count >= 3 { break }
        }
        return excerpts
    }
}
